  ('core-exxet', 'categorias', 'Novel', '{"categoria":"Novel","turno":5,"PV":5,"costeMultiploPV":20,"conocimientoMarcial":20,"limiteCombate":0.6000000000000001,"limiteMagia":0.6000000000000001,"limitePsi":0.6000000000000001,"nvPorCV":2,"bonoZeon":10,"costeHA":2,"costeHP":2,"costeHE":2,"costeLlevarArmadura":2,"costeKi":2,"costeAcumKi":20,"costeZeon":2,"costeACT":60,"costeProyeccionMagica":2,"costeConvocar":2,"costeControlar":2,"costeAtar":2,"costeDesconvocar":2,"costeCV":20,"costeProyeccionPsiquica":2,"costeAtleticas":2,"costeSociales":2,"costePerceptivas":2,"costeIntelectuales":2,"costeVigor":2,"costeSubterfugio":2,"costeCreativas":2,"costePFuerza":3,"costeResDolor":3,"costeFrialdad":3,"costeTramperia":3,"costeHerbolaria":3,"costeAnimales":3,"costeMedicina":3,"costeTasacion":3,"costeSigilo":3,"costeMemorizar":3,"costeVMagica":3,"costeTManos":3,"costePersuasion":3,"costeOcultismo":3,"arquetipo1":"Sin","arquetipo2":"Sin","arquetipo":"SinSin"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear luz', '{"conjuro":"Crear luz","via":"Luz","nivel":2,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":20,"zeonIntermedio":50,"zeonAvanzado":100,"zeonArcano":200,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":15,"efectoBase":"5 metros de zona iluminada","efectoIntermedio":"25 metros de zona iluminada","efectoAvanzado":"100 metros de zona iluminada","efectoArcano":"500 metros de zona iluminada","efecto":"Crea una fuente de luz en un punto u objeto determinado por el hechicero","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Imbuir calma', '{"conjuro":"Imbuir calma","via":"Luz","nivel":6,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":11,"intRArcano":14,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 80 / 10 metros de radio","efectoIntermedio":"RM o RP 100 / 25 metros de radio.","efectoAvanzado":"RM o RP 120 / 50 metros de radio","efectoArcano":"RM o RP 150 / 100 metros de radio","efecto":"Tranquiliza a los individuos perturbados por un sentimiento de temor u odio que se encuentren alrededor del lanzador. Hace desaparecer cualquier estado de Miedo, Terror o Ira en el que estén sumidos, incluso si es de origen sobrenatural. De cualquier modo, no eliminará acciones violentas si estas se realizan a sangre fría o premeditadamente.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Flash cegador', '{"conjuro":"Flash cegador","via":"Luz","nivel":8,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":14,"zeonBase":50,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":200,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"10 metros de radio / 140 RF","efectoIntermedio":"25 metros de radio / 140 RF.","efectoAvanzado":"50 metros de radio / 140 RF.","efectoArcano":"100 metros de radio / 160 RF","efecto":"Causa un repentino flash de luz en un radio alrededor del brujo que ciega a cualquiera que lo mire durante tantos asaltos como número de decenas por las que no supere la RF del conjuro. No es posible designar blancos específicos en el interior del flash, afectando automáticamente a todos por igual salvo al lanzador. Si alguien se está cubriendo los ojos o prevé de algún modo el resplandor, podrá aplicar un +40 a su RF.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo de luz', '{"conjuro":"Escudo de luz","via":"Luz","nivel":10,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":14,"zeonBase":50,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":250,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"El escudo tiene 300 puntos de Resistencia","efectoIntermedio":"El escudo tiene 1.000 puntos de Resistencia","efectoAvanzado":"El escudo tiene 1.800 puntos de Resistencia","efectoArcano":"El escudo tiene 3.000 puntos de Resistencia","efecto":"Forma una barrera de energía, que protege frente a cualquier fuente de ataque. El escudo sólo puede ser dañado por ataques de naturaleza sobrenatural, aunque los impactos basados en oscuridad causarán doble daño sobre él.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Percibir', '{"conjuro":"Percibir","via":"Luz","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":14,"zeonBase":50,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"+50 Advertir, Buscar y Valoración mágica.","efectoIntermedio":"+150 Advertir, Buscar y Valoración mágica","efectoAvanzado":"+200 Advertir, Buscar y Valoración mágica","efectoArcano":"+250 Advertir, Buscar y Valoración mágica","efecto":"Este conjuro aumenta la percepción del hechicero acrecentando sus habilidades secundarias de Advertir y Buscar, así como su Valoración mágica en el caso de que pretenda medir o detectar el potencial mágico de algo o alguien (nunca para ocultarlo) así como para analizar la naturaleza de otros conjuros","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Armadura de luz', '{"conjuro":"Armadura de luz","via":"Luz","nivel":16,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"TA 2 en Energía y TA 1 en el resto","efectoIntermedio":"TA 5 en Energía y TA 2 en el resto","efectoAvanzado":"TA 8 en Energía y TA 4 en el resto.","efectoArcano":"TA 12 en Energía y TA 6 en el resto.","efecto":"Forma una coraza mística que otorga TA a su usuario contra todo tipo de ataque, en especial contra los basados en energía. Aunque cuenta como una armadura, no se aplican penalizadores al turno por emplear capas de protección adicionales.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción de sombras', '{"conjuro":"Destrucción de sombras","via":"Luz","nivel":18,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":250,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":25,"efectoBase":"10 metros de radio / 140 RM.","efectoIntermedio":"100 metros de radio / 180 RM","efectoAvanzado":"250 metros de radio / 220 RM.","efectoArcano":"500 metros de radio / 280 RM","efecto":"Destruye las sombras existentes alrededor del hechicero. Si se lanza sobre seres basados naturalmente en oscuridad, estos deberán superar una RM o perderán una cantidad equivalente al doble de su nivel de fracaso en puntos de vida (por diez, si poseen acumulación de daño). Mientras se mantenga el conjuro, las entidades afectadas deberán realizar un nuevo control de RM cada asalto","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detectar lo negativo', '{"conjuro":"Detectar lo negativo","via":"Luz","nivel":20,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":100,"zeonAvanzado":160,"zeonArcano":280,"mantBase":5,"mantIntermedio":10,"mantAvanzado":20,"mantArcano":30,"efectoBase":"25 metros de radio / 80 RM para resistirse.","efectoIntermedio":"150 metros de radio / 140 RM para resistirse","efectoAvanzado":"500 metros de radio / 160 RM para resistirse.","efectoArcano":"1 kilómetro de radio / 200 RM para resistirse","efecto":"Detecta cualquier sentimiento negativo, como odio, miedo o ira, que se encuentre un radio alrededor del lanzador, que no sea capaz de resistir la RM del conjuro. De igual forma, el mago también percibe las criaturas elementales basadas en dichas emociones.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descarga de luz', '{"conjuro":"Descarga de luz","via":"Luz","nivel":22,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 60.","efectoIntermedio":"Daño 90.","efectoAvanzado":"Daño 120.","efectoArcano":"Daño 150.","efecto":"Proyecta una descarga de energía mágica basada en luz. El ataque se realiza en la TA de Energía","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Holograma', '{"conjuro":"Holograma","via":"Luz","nivel":26,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":40,"zeonIntermedio":150,"zeonAvanzado":250,"zeonArcano":350,"mantBase":5,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"La imagen tiene un tamaño máximo de un metro cuadrados","efectoIntermedio":"La imagen tiene un tamaño máximo de 15 metros cuadrados","efectoAvanzado":"La imagen tiene un tamaño máximo de 50 metros cuadrados","efectoArcano":"máximo 100 metros² y dificultad de Advertir (IMP) y Buscar (ABS).","efecto":"Crea forma luminosa inmaterial, el mago elige apariencia y movimiento. Si crea una criatura, podrá hacer acciones inhumanas, pero imita las habilidades físicas del mago. Si se utiliza para simular que se va a atacar, utiliza la habilidad de combate del mago. El holograma no puede tocar ni ser tocado. Si recibe daño basado en energía, desaparece. Para percibir que se trata de una imagen, superar control de Advertir (Casi Imposible), o Buscar (Muy Difícil).","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Lazos de luz', '{"conjuro":"Lazos de luz","via":"Luz","nivel":28,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":180,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Disponen de una Fuerza base 8 para los controles","efectoIntermedio":"Disponen de una Fuerza base 12 para los controles","efectoAvanzado":"Disponen de una Fuerza base 15 para los controles y tienen Entereza 30","efectoArcano":"Disponen de una Fuerza base 18 para los controles y tienen Entereza 35","efecto":"Forma unos lazos de luz que sujetan al blanco designado. Para ello el lanzador emplea las reglas de Presa, aunque sin penalizador alguno a su habilidad. Los lazos de luz no pueden romperse por el sujeto al que sujetan, pero si un tercero intenta romperlos, estos se consideran un arma de energía con Entereza 25.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Dominio lumínico', '{"conjuro":"Dominio lumínico","via":"Luz","nivel":30,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":150,"zeonAvanzado":250,"zeonArcano":250,"mantBase":5,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Radio de 20 metros / RM 80","efectoIntermedio":"Radio de 150 metros / RM 140","efectoAvanzado":"Radio de 300 metros y RM 180.","efectoArcano":"Radio de 500 metros / RM 220","efecto":"Modifica y controla la forma, color o intensidad de la luz de un ambiente. Si se lanza sobre seres basados naturalmente en este elemento serán dominados por el hechicero si no superan una RM determinada por el grado del conjuro. La criatura sólo puede repetir el control si recibe una orden que sea opuesta a su naturaleza.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detectar vida', '{"conjuro":"Detectar vida","via":"Luz","nivel":32,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":30,"efectoBase":"Radio de 25 metros / RM 140","efectoIntermedio":"Radio de 50 metros / RM 180","efectoAvanzado":"Radio de 150 metros / RM 220","efectoArcano":"Radio de 500 metros / RM 280.","efecto":"Detecta cualquier fuente de vida. El conjuro no dará más información que el número de seres vivos y el lugar exacto donde se encuentran con respecto al lanzador","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Espía de luz', '{"conjuro":"Espía de luz","via":"Luz","nivel":36,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":20,"mantIntermedio":40,"mantAvanzado":60,"mantArcano":80,"efectoBase":"100 en Advertir y Buscar / 1 Kilómetro de distancia máxima","efectoIntermedio":"150 en Advertir y Buscar / 10 Kilómetros de distancia máxima.","efectoAvanzado":"200 en Advertir y Buscar / 50 Kilómetros de distancia máxima.","efectoArcano":"250 en Advertir y Buscar / 500 Kilómetros de distancia máxima","efecto":"Crea pequeña luz con un Tipo de vuelo 14. A través de ella el mago puede ver y escuchar , pero al hacerlo((elegir cada turno si hacerlo), sólo podrá percibir  a través del espía. El espía emplea sus habilidades de Advertir y Buscar, y serán estas las que utilice el mago. El espía esquiva usando la Proyección Mágica del mago. Sólo es dañado con ataques sobrenaturales. distancia máxima de sepación espía-hechicero es determinada por el grado del conjuro.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Éxtasis', '{"conjuro":"Éxtasis","via":"Luz","nivel":38,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 80 / 10 metros de radio","efectoIntermedio":"RM 100 / 50 metros de radio.","efectoAvanzado":"RM 120 / 100 metros de radio.","efectoArcano":"RM 160 / 250 metros de radio","efecto":"Crea un sentimiento de completo éxtasis, en aquel o aquellos sujetos que estén alrededor del mago y fallen la RM. La sensación de placer será tan intensa que sus sentidos se nublarán por completo, aplicando un –20 a toda acción mientras dure su poder. Los hechizados olvidarán completamente cualquier sentimiento de dolor y pesadumbre, e ignorarán todos los otros penalizadores que puedan aplicárseles, salvo aquellos provocados por incapacidades físicas.","_seccion":"LUZ"}'::jsonb)
insert into public.catalogo (paquete_id, coleccion, clave, datos) values
  ('core-exxet', 'conjuros', 'Dest. sentimientos negativos', '{"conjuro":"Dest. sentimientos negativos","via":"Luz","nivel":40,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 100 / 100 metros de radio","efectoIntermedio":"RM o RP 150 / 500 metros de radio","efectoAvanzado":"RM o RP 180 / 1 kilómetro de radio","efectoArcano":"RM o RP 220 / 5 Kilómetros de radio","efecto":"Destruye temporalmente cualquier sentimiento negativo, como odio, miedo o ira, de aquellos individuos que se encuentren alrededor del hechicero y no superen la RM del conjuro.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Luz sanadora', '{"conjuro":"Luz sanadora","via":"Luz","nivel":42,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":70,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":200,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"40 Puntos de Vida.","efectoIntermedio":"80 Puntos de Vida","efectoAvanzado":"120 Puntos de Vida","efectoArcano":"250 Puntos de Vida","efecto":"Hace recuperar puntos de vida al sujeto sobre el que se lance. Este conjuro no permite restaurar miembros cercenados o pérdidas permanentes, ni tampoco elimina los penalizadores causados por los críticos","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Esfera buscadora', '{"conjuro":"Esfera buscadora","via":"Luz","nivel":46,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Daño Base 100 / Proyección Mágica 150","efectoIntermedio":"Daño Base de 120 / Proyección Mágica 180","efectoAvanzado":"Daño Base de 160 / Proyección Mágica 210","efectoArcano":"Daño Base de 200 / Proyección Mágica 240","efecto":"Crea una esfera de luz que ataca en TA de ENE. Se controla con la Proyección Mágica del mago hasta impactar, por lo que si un blanco esquiva, podrá seguir atacando en el turno siguiente. Únicamente cuando causa daño o es parada, la esfera desaparece. Si el mago abandona el control directo sobre ella, la esfera se moverá por si misma, atacando todos los asaltos al último blanco prefijado con su propia Proyección Mágica independiente de la del mago.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Zona de detección', '{"conjuro":"Zona de detección","via":"Luz","nivel":48,"diario":"Si","tipo":"Detección","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":280,"zeonArcano":360,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 180 / 20 metros de radio","efectoIntermedio":"RM 240 / 80 metros de radio","efectoAvanzado":"RM 280 / 150 metros de radio","efectoArcano":"RM 340 / 250 metros de rad","efecto":"El brujo percibe a seres que entren dentro del área si no superan una RM. La Zona de Detección no dará más información que el número de individuos que haya dentro y su localización. También percibirá otros hechizos de Detección que traten de entrar en ella, siempre que el mago que los lanza no supere la RM de la Zona (sin importar dónde se encuentre). Este conjuro permanece estático en el lugar donde fue lanzado","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Introducirse en los sueños', '{"conjuro":"Introducirse en los sueños","via":"Luz","nivel":50,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM o RP 140 / 10 metros de distancia","efectoIntermedio":"RM o RP 160 / 80 metros de distancia","efectoAvanzado":"RM o RP 200 / 140 metros de distancia","efectoArcano":"RM o RP 240 / 200 metros de distancia","efecto":"El mago entra físicamente en los Sueños de alguien. No tendrá control del mundo onírico del soñador, todo lo que pase será real para él. El blanco deberá tener Sueños tranquilos como requisito, si se convierte en pesadilla, despierta o muere, el mago abandona el mundo onírico y vuelve al real. Un conjuro de Esencia hecho al durmiente afecta también al mago. Una vez en los Sueños, el brujo puede saltar al subconsciente de otro soñador que se defiende con su RM.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cuerpo a luz', '{"conjuro":"Cuerpo a luz","via":"Luz","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"+50 en Advertir y Buscar / +20 a sus Resistencias","efectoIntermedio":"+60 en Advertir y Buscar / +30 a sus Resistencias","efectoAvanzado":"el bono será  contra todo efecto sobrenatural que no sea oscuridad","efectoArcano":"Como arriba, pero no sufre doble daño por ataques basado en oscuridad","efecto":"El cuerpo designado por el hechicero se transformará en pura energía luminosa, volviéndose intangible ante todas las materias y ataques no basados en energía. Mientras se encuentre en este estado, el sujeto ganará un bono en sus habilidades secundarias de Advertir y Buscar, así como a sus Resistencias contra efectos basados en Luz. En este estado, cualquier daño causado por Oscuridad se doblará","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Bendición', '{"conjuro":"Bendición","via":"Luz","nivel":56,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"+10 a toda acción / +10 resistencias / Radio de 5 metros","efectoIntermedio":"+20 a toda acción / +20 resistencias / Radio de 25 metros","efectoAvanzado":"+20 a toda acción / +30 resistencias / Radio de 50 metros","efectoArcano":"+30 a toda acción / +30 resistencias / Radio de 150 metros","efecto":"La bendición imbuye de una increíble energía sobrenatural a quienes se encuentren alrededor del hechicero. Aquellos que se encuentren bajo su influencia recibirán un bonificador a todas sus acciones y Resistencias. Los beneficios de este conjuro no se superponen, por lo que un personaje no obtendría el doble de bonos por encontrarse en el área de dos conjuros de Bendición.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear sentimientos positivos', '{"conjuro":"Crear sentimientos positivos","via":"Luz","nivel":58,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Radio de 20 metros / RM o RP 120.","efectoIntermedio":"Radio de 100 metros / RM o RP 160","efectoAvanzado":"Radio de 250 metros / RM o RP 180.","efectoArcano":"Radio de 500 metros / RM o RP 220","efecto":"Introduce algún tipo de sentimiento positivo, como amor, placer o amistad, en los individuos designados por el hechicero que fallen la RM del conjuro. El afectado puede repetir el control una vez al día","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ver realmente', '{"conjuro":"Ver realmente","via":"Luz","nivel":60,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":250,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":25,"efectoBase":"Verá magia, matrices psíquicas y seres invisibles / +50 RM contra Ilusiónes.","efectoIntermedio":"Como en Base, pero permite ver también seres espirituales","efectoAvanzado":"Como en Intermedio, pero obtiene un +75 RM contra Ilusiónes.","efectoArcano":"Como avanzado, pero obtiene un +100 RM contra Ilusiónes","efecto":"Permite al afectado por el conjuro percibir las fuerzas sobrenaturales que son invisibles para el ojo humano; podrá ver magia, matrices psíquicas y seres invisibles o espirituales. Aunque no funciona contra conjuros ilusorios, ya que afectan a la mente y no a la vista, cualquiera que utilice Ver Realmente contra Ilusiónes visuales podrá aplicar un bono a su RM, puesto que le resulta más fácil darse cuenta de su falsedad.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudar contra lo negativo', '{"conjuro":"Escudar contra lo negativo","via":"Luz","nivel":62,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120 / radio de 20 metros","efectoIntermedio":"RM 140 / radio de 100 metros","efectoAvanzado":"RM 160 / radio de 250 metros","efectoArcano":"RM 180 / radio de 500 metros","efecto":"Encanta una zona, haciéndola impenetrable para seres basados naturalmente en sentimientos negativos u oscuridad. Cualquiera de estas criaturas que entre en la zona , debe realizar cada asalto una RM o perder tantos puntos de vida como el nivel de fracaso. Adicionalmente, de fallar el control, el ser recibirá de inmediato un penalizador a toda acción de -40 mientras siga en su interior. La zona afectada permanece estática en el lugar donde fue lanzada.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Encontrar', '{"conjuro":"Encontrar","via":"Luz","nivel":66,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":160,"zeonIntermedio":200,"zeonAvanzado":260,"zeonArcano":320,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 140.","efectoIntermedio":"RM 180","efectoAvanzado":"RM 220.","efectoArcano":"RM 260.","efecto":"Permite localizar una persona, objeto o lugar, y saber su ubicación exacta en ese momento sin importar la distancia. Podrá buscar cualquier cosa, concreta o genérica, o simplemente algo que reúna una condición. Podría localizar una ciudad, un ladron (al cual no conoce) o incluso a la doncella de sangre real más cercana. Los blancos deberán hacer una tirada de RM para evitar ser localizados. Los lugares de gran tamaño aplican un –40 a dicha tirada.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Restituir', '{"conjuro":"Restituir","via":"Luz","nivel":68,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Elimina un -40 a toda acción y restituye 2 puntos de Cansancio","efectoIntermedio":"Elimina un -80 a toda acción y restituye 5 puntos de Cansancio","efectoAvanzado":"Elimina un -120 a toda acción y restituye 10 puntos de Cansancio","efectoArcano":"Restituye cualquier penalizador y cantidad de Puntos de Cansancio","efecto":"Este conjuro restituye los penalizadores que se apliquen sobre un individuo determinado. Los negativos restituidos podrán haber sido causados por cansancio, hambre, daños físicos o incluso conjuros, aunque no por carencias físicas, como la pérdida de un miembro u otra parte del cuerpo. La restitución recuperará, además, cierta cantidad de de puntos de Cansancio gastados.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Esquema hipnótico', '{"conjuro":"Esquema hipnótico","via":"Luz","nivel":70,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":280,"zeonArcano":360,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Visible en 1 kilómetro de radio / RM o RP 120","efectoIntermedio":"Visible en 5 kilómetros de radio / RM o RP 150","efectoAvanzado":"Visible en 15 kilómetros de radio / RM o RP 180.","efectoArcano":"Visible en 25 kilómetros de radio / RM o RP 220","efecto":"Forma una marca o un espectáculo de luces que fascina y atonta a los que lo vean. Quien lo mire y falle la Resistencia no podrá hacer sino seguir contemplándolo absorto, y mientras se encuentren afectados por el conjuro, sólo podrán realizar acciones pasivas. Cada vez que reciban un ataque tendrán una nueva oportunidad de superar la Resistencia. La condición para ser afectado es mirar directamente al esquema hipnótico.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Luz catastrófica', '{"conjuro":"Luz catastrófica","via":"Luz","nivel":72,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 120 / 25 metros de radio","efectoIntermedio":"Daño 150 / 100 metros de radio","efectoAvanzado":"Daño 200 / 150 metros de radio","efectoArcano":"Daño 250 / 250 metros de radio.","efecto":"Proyecta una descarga basada en luz. Ataca en la TA de Energía","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Objetos luminosos materiales', '{"conjuro":"Objetos luminosos materiales","via":"Luz","nivel":76,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Presencia 60 / Calidad +5","efectoIntermedio":"Presencia 100 / Calidad +10","efectoAvanzado":"Presencia 140 / Calidad +10","efectoArcano":"Presencia 180 / Calidad +15","efecto":"Forma un objeto físico de energía lumínica. Pese a estar hecho de luz, tiene consistencia física. La presencia máxima de dicho objeto y la calidad del mismo viene determinada por el grado del conjuro.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Transmisión por luz', '{"conjuro":"Transmisión por luz","via":"Luz","nivel":78,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":360,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"100 kilómetros / 250 de presencia / RM 120","efectoIntermedio":"1.000 kilómetros / 500 de presencia / RM 140","efectoAvanzado":"5.000 kilómetros / 1.000 de presencia / RM 180","efectoArcano":"15.000 kilómetros / 2.000 de presencia / RM contra 200","efecto":"Transporta instantáneamente a los individuos u objetos designados por el brujo, desde una fuente de luz hasta otra. Si desea resistirse, hay que superar la RM del conjuro. Tanto la distancia máxima como la máxima presencia afectable son determinadas por el grado del conjuro","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Señor de los sueños', '{"conjuro":"Señor de los sueños","via":"Luz","nivel":80,"diario":"No","tipo":"Animíco","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":300,"zeonIntermedio":400,"zeonAvanzado":500,"zeonArcano":750,"mantBase":60,"mantIntermedio":65,"mantAvanzado":70,"mantArcano":80,"efectoBase":"RM 140.","efectoIntermedio":"RM 150 / En Vigilia, obtiene Gnosis 40. En zona neutra, 30.","efectoAvanzado":"RM 160 / como intermedio, pero el Gnosis en zonas neutras es de 35.","efectoArcano":"RM 180 / Como Avanzado, sin límites espacial.","efecto":"Permite dominar cualquier  Sueños del objetivo que no pase RM. El mago podra controlar el mundo onírico de un durmiente, modificándolo como si tuviera Gnosis 45. En el caso de que el Sueños se torne una pesadilla, su Gnosis será de 30. Los conjuros que el brujo lance gracias a dicho Gnosis (como por ejemplo, magia divina), no tienen efecto fuera de los límites espaciales del conjuro y sus efectos desaparecen en cuanto el mago sale del Sueños o de la Vigilia.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Creación de luz', '{"conjuro":"Creación de luz","via":"Luz","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":50,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":140,"efectoBase":"Nivel 1.","efectoIntermedio":"Nivel 3","efectoAvanzado":"Nivel 6.","efectoArcano":"Nivel 10.","efecto":"Crea un ser luminoso con apariencia de vida, bajo el control absoluto del hechicero. El ente será desarrollado como un Ser Entre Mundos, usando los poderes y limitaciones de los elementales de Luz del Capítulo 26. Para calcular su nivel máximo se emplean las mismas reglas que en el conjuro Crear Ser, de la vía de Creación","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Prisma reflectante', '{"conjuro":"Prisma reflectante","via":"Luz","nivel":86,"diario":"Si","tipo":"Defensa","accion":"Pasiva","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":160,"zeonIntermedio":250,"zeonAvanzado":300,"zeonArcano":400,"mantBase":20,"mantIntermedio":25,"mantAvanzado":30,"mantArcano":40,"efectoBase":"100 contra choques / Tiene 800 puntos de Resistencia","efectoIntermedio":"120 contra choques / Tiene 1.500 puntos de Resistencia","efectoAvanzado":"140 contra choques / Tiene 3.000 puntos de Resistencia","efectoArcano":"180 contra choques / Tiene 6.000 puntos de Resistencia","efecto":"Crea un cuerpo de luz que reflecta todo hechizo ofensivo, poder psíquico de ataque o técnica de Ki a distancia que sea contra el. Deberá logar una defensa con éxito y ganar un control de choque contra un equivalente de daño determinado por el Grado del conjuro, para devolverla. Si es un Ataque en área, seguirá afectando a todo el área, salvo al mago. No se devuelven efectos Anímicos o Esotéricos. Se puede usar Proyección Mágica para redirigir el ataque.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Omnisciencia radial', '{"conjuro":"Omnisciencia radial","via":"Luz","nivel":88,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":200,"zeonIntermedio":250,"zeonAvanzado":400,"zeonArcano":800,"mantBase":40,"mantIntermedio":50,"mantAvanzado":60,"mantArcano":65,"efectoBase":"500 metros de radio / presencia máxima 60.","efectoIntermedio":"2 kilómetros de radio / presencia máxima 80","efectoAvanzado":"10 kilómetros de radio / presencia máxima 100","efectoArcano":"50 kilómetros de radio / presencia máxima 120","efecto":"Permite al lanzador ser omnisciente respecto a cualquier suceso o pensamiento que acontezca a su alrededor. Sólo afecta a individuos que no tengan más Gnosis que el personaje y cuya presencia no sea superior a lo permitido por el Grado del conjuro. El brujo sabrá, de manera automática, todo lo que está pasado dentro de este radio y qué piensan las personas. No hay control de Resistencia posible.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Predecir', '{"conjuro":"Predecir","via":"Luz","nivel":90,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Un año","efectoIntermedio":"Cinco años","efectoAvanzado":"Cincuenta años / Si ocurrirá en menos de un día, será muy exacta","efectoArcano":"Un siglo / Si ocurrirá en menos de un año, será bastante exacta.","efecto":"Permite vislumbrar acontecimientos futuros que se desarrollarán alrededor de una persona, objeto o lugar. Muestra lo más probable que ocurra, dándo información detallada. El tiempo no puede ser superior al Grado del conjuro. El DJ debe explicar al mago cuáles serán los sucesos que acontecerán probablemente, aunque estos pueden ser modificados por fuerzas mayores o individuos con Gnosis muy superior a su Natura.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Prisión de luz', '{"conjuro":"Prisión de luz","via":"Luz","nivel":92,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":200,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":800,"mantBase":40,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":160,"efectoBase":"RM 140 / La prisión posee 10.000 puntos de resistencia","efectoIntermedio":"RM 180 / La prisión posee 250.000 puntos de resistencia","efectoAvanzado":"RM 220 / La prisión posee 500.000 puntos de resistencia","efectoArcano":"RM 240 / no puede romperse desde adentro, 500.000 puntos de resistencia.","efecto":"Encierra algo en luz, no podrá interactuar con el exterior, ni éste con lo encerrado. No se sabe lo que ocurre fuera, ni viceversa. Para forzar la prisión desde el interior, se considera un ser de acumulación con TA 10 y resistencia dada por el grado del conjuro. El daño desde fuera se dobla. Tiene Regeneración 19. Si el blanco falla la RM, deberá romper la prisión para salir de la prisión, sin derecho a otra RM. El mago no puede encerrarse.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Esencia de luz', '{"conjuro":"Esencia de luz","via":"Luz","nivel":96,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":200,"zeonIntermedio":400,"zeonAvanzado":600,"zeonArcano":800,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Un día","efectoIntermedio":"Una semana","efectoAvanzado":"Un mes","efectoArcano":"Un año","efecto":"Permite al lanzador o el objetivo designado por este entrar en completo letargo, mientras su cuerpo se hace uno con la luz. La entidad abandona el mundo y asciende a la red de almas para nutrirse de sus energías. Apartado y desconocedor de todo lo que sucede en el exterior, multiplica por 10 su regeneración zeónica y cura sus heridas con Regeneración 16. Cuanto tiempo puede permanecer apartado del mundo es determinado por el grado del conjuro.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ascensión', '{"conjuro":"Ascensión","via":"Luz","nivel":98,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":500,"zeonIntermedio":1000,"zeonAvanzado":2000,"zeonArcano":5000,"mantBase":30,"mantIntermedio":40,"mantAvanzado":45,"mantArcano":50,"efectoBase":"Gnosis máximo 30","efectoIntermedio":"Gnosis máximo 35","efectoAvanzado":"Gnosis máximo 40","efectoArcano":"Gnosis máximo 45.","efecto":"El conjuro intercambia la esencia del lanzador por energía divina, modificando su espíritu por puro poder sobrenatural. Al hacerlo, el lanzador o el individuo designado por éste aumenta su Gnosis hasta una cantidad máxima determinada por el grado del conjuro","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Holocausto de luz', '{"conjuro":"Holocausto de luz","via":"Luz","nivel":100,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":600,"zeonIntermedio":1000,"zeonAvanzado":2500,"zeonArcano":10000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 350 / 100 metros de radio","efectoIntermedio":"Daño 500 / 100 kilómetros de radio","efectoAvanzado":"Daño 800 / 10.000 kilómetros de radio","efectoArcano":"Daño 1.000 / 1 ua de radio","efecto":"Este poder arrasa todo, tanto en el mundo material como espiritual. Incluso las criaturas elementales de luz son asimiladas. Una gran cúpula lumínica que ataca en la TA de energía. Cualquier ser que reciba daño, por mínimo que sea, debe superar una RM de 160 o es unificado con la luz y destruido en cuerpo y alma. No es posible designar blancos en el radio del conjuro, y afecta a todos por igual salvo al lanzador.","_seccion":"LUZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear oscuridad', '{"conjuro":"Crear oscuridad","via":"Oscuridad","nivel":2,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":20,"zeonIntermedio":50,"zeonAvanzado":100,"zeonArcano":200,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":15,"efectoBase":"5 metros de radio","efectoIntermedio":"25 metros de radio","efectoAvanzado":"100 metros de radio","efectoArcano":"500 metros de radio","efecto":"Oscurece completamente una zona. Todo lo que hay en su interior se percibe como en una noche cerrada y sin luna","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Imbuir miedo', '{"conjuro":"Imbuir miedo","via":"Oscuridad","nivel":6,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":140,"zeonArcano":180,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 80 / 10 metros de radio.","efectoIntermedio":"RM o RP 100 / 50 metros de radio","efectoAvanzado":"RM o RP 120 / 100 metros de radio","efectoArcano":"RM o RP 140 / 250 metros de radio","efecto":"Provoca, temporalmente, el estado de Miedo a todos los sujetos que se encuentren alrededor del lanzador. El hechicero decidirá cuál es la fuente que origina el miedo a los afectados","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ver en la oscuridad', '{"conjuro":"Ver en la oscuridad","via":"Oscuridad","nivel":8,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Presencia máxima 80","efectoIntermedio":"Presencia máxima 100","efectoAvanzado":"Presencia máxima 120.","efectoArcano":"Presencia máxima 140 / Permite ver en la oscuridad sobrenatural","efecto":"Permite al hechicero, o a quienes este seleccione, ver perfectamente en la oscuridad natural, siempre que la suma de sus presencias no supere el valor determinado por el grado del conjuro","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo oscuro', '{"conjuro":"Escudo oscuro","via":"Oscuridad","nivel":10,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":14,"zeonBase":50,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":250,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"El escudo tiene 300 puntos de Resistencia","efectoIntermedio":"El escudo tiene 1.000 puntos de Resistencia","efectoAvanzado":"El escudo tiene 1.800 puntos de Resistencia","efectoArcano":"El escudo tiene 3.000 puntos de Resistencia","efecto":"Forma una barrera de energía, que protege frente a cualquier fuente de ataque. El escudo sólo puede ser dañado por ataques de naturaleza sobrenatural, aunque los impactos basados en luz causarán doble daño sobre él","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sombra', '{"conjuro":"Sombra","via":"Oscuridad","nivel":12,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":5,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":14,"zeonBase":50,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":240,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"+50 en Sigilo, Ocultarse y Valoración Mágica","efectoIntermedio":"+150 en Sigilo, Ocultarse y Valoración Mágica","efectoAvanzado":"+200 en Sigilo, Ocultarse y Valoración Mágica","efectoArcano":"+250 en Sigilo, Ocultarse y Valoración Mágica","efecto":"Este conjuro aumenta la capacidad de ocultación del hechicero, acrecentando sus habilidades secundarias de Sigilo y Ocultarse, así como su Valoración mágica en la misma cantidad, aunque sólo en el caso de que pretenda ocultar el potencial mágico de algo o alguien (nunca para detectarlo).","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Armadura oscura', '{"conjuro":"Armadura oscura","via":"Oscuridad","nivel":16,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"TA 2 en Energía y TA 1 en el resto","efectoIntermedio":"TA 5 en Energía y TA 2 en el resto","efectoAvanzado":"TA 8 en Energía y TA 4 en el resto","efectoArcano":"TA 12 en Energía y TA 6 en el resto","efecto":"Forma una coraza mística que otorga TA a su usuario contra todo tipo de ataque, en especial contra los basados en energía. Aunque cuenta como una armadura, no se aplican penalizadores al turno por emplear capas de protección adicionales","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción de luz', '{"conjuro":"Destrucción de luz","via":"Oscuridad","nivel":18,"diario":"No","tipo":"Efecto Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":250,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"10 metros de radio / 140 RM.","efectoIntermedio":"100 metros de radio / 180 RM.","efectoAvanzado":"250 metros de radio / 220 RM","efectoArcano":"500 metros de radio / 280 RM","efecto":"Destruye la luminosidad ambiental alrededor del hechicero. Si se lanza sobre seres basados naturalmente en luz, estos deberán superar una RM o perderán una cantidad equivalente al doble de su nivel de fracaso en puntos de vida (por diez, si poseen acumulación de daño). Mientras se mantenga el conjuro, la entidad, deberá realizar un nuevo control de RM cada asalto que permanezca en el interior del radio del conjuro","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ocultación de magia', '{"conjuro":"Ocultación de magia","via":"Oscuridad","nivel":20,"diario":"Si","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":5,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"–100 a Valoración Mágica","efectoIntermedio":"–180 a Valoración Mágica","efectoAvanzado":"–240 a Valoración Mágica","efectoArcano":"–320 a Valoración Mágica","efecto":"Oculta un conjuro, o las propiedades místicas de un objeto, ante cualquier tipo de detección mágica. A efectos de juego, produce un penalizador a la Valoración mágica de quien intente detectar o medir el conjuro u objeto oculto (así como al propio hechizo de Ocultación de Magia).","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descarga oscura', '{"conjuro":"Descarga oscura","via":"Oscuridad","nivel":22,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 60.","efectoIntermedio":"Daño 90.","efectoAvanzado":"Daño 120","efectoArcano":"Daño 150","efecto":"Proyecta una descarga mágica basada en oscuridad. El ataque se realiza en la TA de Energía","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Oscuridad ambiental', '{"conjuro":"Oscuridad ambiental","via":"Oscuridad","nivel":26,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Radio de 20 metros","efectoIntermedio":"Radio de 250 metros","efectoAvanzado":"Radio de 500 metros","efectoArcano":"Radio de 1 kilómetro","efecto":"Crea un ambiente místico que nubla los sentidos de cualquiera que se encuentre en su interior. La Oscuridad Ambiental aumenta en dos grados el nivel de dificultad de cualquier control perceptivo que se realice dentro, incluyendo detección por Ki o medios mágicos. No se puede designar blancos en su interior, y la zona permanece inmóvil en el mismo lugar en el que fue lanzada. No tiene control de RM posible.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Lazos oscuros', '{"conjuro":"Lazos oscuros","via":"Oscuridad","nivel":28,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":180,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Disponen de una Fuerza base 8 para los controles","efectoIntermedio":"Disponen de una Fuerza base 12 para los controles","efectoAvanzado":"Disponen de una Fuerza base 15 para los controles y tienen Entereza 30","efectoArcano":"Disponen de una Fuerza base 18 para los controles y tienen Entereza 35","efecto":"Forma unos lazos de oscuridad que sujetan al blanco designado. Para ello el lanzador emplea las reglas de Presa, aunque sin penalizador alguno a su habilidad. Los lazos de oscuridad no pueden romperse por el sujeto al que sujetan, pero si un tercero intenta romperlos, estos se consideran un arma de energía con Entereza 25.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Dominio oscuro', '{"conjuro":"Dominio oscuro","via":"Oscuridad","nivel":30,"diario":"No","tipo":"Efecto Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":16,"zeonBase":50,"zeonIntermedio":150,"zeonAvanzado":250,"zeonArcano":350,"mantBase":5,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Radio de 20 metros / RM 80","efectoIntermedio":"Radio de 150 metros / RM 140","efectoAvanzado":"Radio de 300 metros y RM 180","efectoArcano":"Radio de 500 metros / RM 220","efecto":"Este conjuro modifica y controla la forma e intensidad de la oscuridad y sombras que rodean al hechicero. Si se lanza sobre seres basados naturalmente en este elemento serán dominados por el hechicero si no superan una RM determinada por el grado del conjuro. La criatura sólo puede repetir el control si recibe una orden que sea opuesta a su naturaleza.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ocultación', '{"conjuro":"Ocultación","via":"Oscuridad","nivel":32,"diario":"Si","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"+50 a la RM o RP / +50 Ocultación del Ki","efectoIntermedio":"+140 a la RM o RP / +150 Ocultación del Ki","efectoAvanzado":"+220 a la RM o RP / +200 Ocultación del Ki","efectoArcano":"+280 a la RM o RP / +250 Ocultación del Ki","efecto":"Oculta la presencia del hechicero o del blanco designado por éste ante cualquier tipo de detección. A efectos de juego, aumenta en las Resistencias contra detecciones sobrenaturales, ya sean místicas o psíquicas. Esta habilidad también aumenta la Ocultación del Ki del personaje (aunque este aumento no se contabiliza a la hora de determinar los bonos aplicables a la RM), permitiéndole esconder su energía incluso si no ha desarrollado dicha habilidad","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ofuscar', '{"conjuro":"Ofuscar","via":"Oscuridad","nivel":36,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":20,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"Base de 100 en Sigilo, Ocultarse y Ocultación del Ki","efectoIntermedio":"Base de 150 en Sigilo, Ocultarse y Ocultación del Ki","efectoAvanzado":"Base de 200 en Sigilo, Ocultarse y Ocultación del Ki","efectoArcano":"Base de 250 en Sigilo, Ocultarse y Ocultación del Ki","efecto":"Modifica el cuerpo de un individuo, fundiéndolo con su entorno y permitiéndole ocultarse naturalmente. Mientras el conjuro de Ofuscar se mantenga activo, el personaje podrá intercambiar su habilidad de Sigilo y Ocultarse por un valor base. También proporciona la misma cantidad a su Ocultación del Ki, incluso si no ha desarrollado dicha habilidad.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Rabia', '{"conjuro":"Rabia","via":"Oscuridad","nivel":38,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":150,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"5 metros de radio / RM 80","efectoIntermedio":"20 metros de radio / RM 100","efectoAvanzado":"50 metros de radio / RM 120","efectoArcano":"100 metros de radio / RM 140","efecto":"Provoca el estado de Ira sobre los objetivos del conjuro, haciendo que estos no controlen sus acciones y ataquen al individuo más cercano a ellos. Mientras alguien se vea influido por sus efectos, aplicará un bono de +10 a su habilidad ofensiva y un –30 al resto de sus controles.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir sentimientos positivos', '{"conjuro":"Destruir sentimientos positivos","via":"Oscuridad","nivel":40,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 100 / 100 metros de radio","efectoIntermedio":"RM o RP 150 / 500 metros de radio","efectoAvanzado":"RM o RP 180 / 1 kilómetro de radio","efectoArcano":"RM o RP 220 / 5 Kilómetros de radio","efecto":"Destruye temporalmente cualquier sentimiento positivo, como paz interior, calma o alegría, que se encuentre en un radio respecto al hechicero. Si desea resistirse, ha de superarse una RM o RP.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Noche', '{"conjuro":"Noche","via":"Oscuridad","nivel":42,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Radio 25 metros","efectoIntermedio":"Radio 250 metros","efectoAvanzado":"Radio 500 metros/ La oscuridad se considera sobrenatural","efectoArcano":"Radio 1 kilómetro / La oscuridad se considera sobrenatural","efecto":"Forma una cúpula de oscuridad absoluta. Todo aquel que se encuentre en su interior, excepto el hechicero, se verá sometido a las reglas de Ceguera. Para poder ver a través de esta oscuridad, ya sea desde dentro o fuera de la cúpula, es necesario superar una dificultad de Imposible en Advertir o de Absurdo en Buscar. No se puede designar blancos en el interior del área","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Esfera oscura', '{"conjuro":"Esfera oscura","via":"Oscuridad","nivel":46,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Daño Base 100 / Proyección Mágica 150.","efectoIntermedio":"Daño Base de 120 / Proyección Mágica 180","efectoAvanzado":"Daño Base de 160 / Proyección Mágica 210","efectoArcano":"Daño Base de 200 / Proyección Mágica 240","efecto":"Crea una esfera de oscuridad que ataca en TA de ENE. Se controla con la Proyección Mágica del mago hasta impactar, por lo que si un blanco esquiva, podrá seguir atacando en el turno siguiente. Únicamente cuando causa daño o es parada, la esfera desaparece. Si el mago abandona el control directo sobre ella, la esfera se moverá por si misma, atacando todos los asaltos al último blanco prefijado con su propia Proyección Mágica independiente de la del mago.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Zona de ocultación', '{"conjuro":"Zona de ocultación","via":"Oscuridad","nivel":48,"diario":"Si","tipo":"Detección","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"20 metros de radio, RM +100, -140 a Habilidades de detección.","efectoIntermedio":"50 metros de radio, RM +150, -180 a Habilidades de detección.","efectoAvanzado":"250 metros de radio, RM +200, -240 a Habilidades de detección","efectoArcano":"500 metros de radio, RM +300, -320 a Habilidades de detección","efecto":"Al lanzar este conjuro sobre una zona, el hechicero crea un área mística que impide que se pueda detectar nada de lo que se encuentra en el interior. Todo lo que hay dentro de la zona incrementa su RM contra detecciones y cualquier habilidad de Detección del Ki, Valoración mágica o habilidad psíquica de detección que se utilice en ella, sufre un penalizador a su resultado final. La zona afectada permanece estática en el lugar donde fue lanzada","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Introducirse en las pesadillas', '{"conjuro":"Introducirse en las pesadillas","via":"Oscuridad","nivel":50,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM o RP 140 / 10 metros de distancia","efectoIntermedio":"RM o RP 160 / 80 metros de distancia","efectoAvanzado":"RM o RP 200 / 140 metros de distancia","efectoArcano":"RM o RP 240 / 200 metros de distancia","efecto":"El mago entra físicamente en las pesadillas de alguien. No tendrá control del mundo onírico del soñador, todo lo que pase será real para él. El blanco deberá tener pesadillas como requisito, si se torna  buen Sueños, despierta o muere, el mago abandona el mundo onírico y vuelve al real. Un conjuro de Esencia hecho al durmiente afecta también al mago. Una vez en las pesadillas, el brujo puede saltar al subconsciente de otro soñador que se defiende con su RM.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cuerpo a oscuridad', '{"conjuro":"Cuerpo a oscuridad","via":"Oscuridad","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"+50 en Ocultarse y Sigilo / +20 a sus Resistencias","efectoIntermedio":"+60 en Ocultarse y Sigilo / +30 a sus Resistencias","efectoAvanzado":"Como arriba y el bono sirve contra todo efecto sobrenatural que no sea luz.","efectoArcano":"Como el Avanzado, pero no sufre doble daño por ataques basados en Luz.","efecto":"El cuerpo designado por el hechicero se transformará en pura energía oscura, volviéndose intangible ante todas las materias y ataques no basados en energía. Mientras se encuentre en este estado, el sujeto ganará un bono en sus habilidades secundarias de Advertir y Buscar, así como a sus Resistencias contra efectos basados en Luz. En este estado, cualquier daño causado por luz se doblará","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Perdición', '{"conjuro":"Perdición","via":"Oscuridad","nivel":56,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120 / Radio de 5 metros.","efectoIntermedio":"RM 160 / 25 metros de radio","efectoAvanzado":"RM 180 / 50 metros de radio / -40 a toda acción","efectoArcano":"RM 200 / 150 metros de radio / -50 a toda acción","efecto":"Disminuyendo capacidades y poderes de alguien. Los que este en la zona deberán superar RM, o recibir penalizador a toda acción y Resistencias de –30. El conjuro afecta en un radio alrededor del mago, afectando automáticamente a cualquiera que este desee de cuantos se encuentren en el interior. Los penalizadores de la Perdición no se superponen, por lo que un personaje no sufriría el doble de negativos por encontrarse bajo la influencia de dos perdiciones","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear sentimientos negativos', '{"conjuro":"Crear sentimientos negativos","via":"Oscuridad","nivel":58,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Radio de 20 metros / RM o RP 120","efectoIntermedio":"Radio de 100 metros / RM o RP 160","efectoAvanzado":"Radio de 250 metros / RM o RP 180","efectoArcano":"Radio de 500 metros / RM o RP 220","efecto":"Introduce algún tipo de sentimiento negativo, como odio, miedo o ira, en los individuos designados por el hechicero. El afectado puede repetir el control una vez al día.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Eliminar residuos', '{"conjuro":"Eliminar residuos","via":"Oscuridad","nivel":60,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"50 metros de radio.","efectoIntermedio":"250 metros de radio","efectoAvanzado":"1 km de radio / Borra acciones de alguien al ver el pasado de objetos o lugares.","efectoArcano":"5 km de radio / Como Avanzado y puede borrar todo rastro del pasado del lugar.","efecto":"El hechicero puede borrar el rastro de que ha estado en un sitio determinado. De hecho, cualquier residuo de su paso por ese lugar desaparece completamente, ya sea ante habilidades de carácter natural, como Rastrear, o detecciones sobrenaturales.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudar contra lo positivo', '{"conjuro":"Escudar contra lo positivo","via":"Oscuridad","nivel":62,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120 / radio de 20 metros","efectoIntermedio":"RM 140 / radio de 100 metros","efectoAvanzado":"RM 160 / radio de 250 metros","efectoArcano":"RM 180 / radio de 500 metros","efecto":"Encanta una zona, haciéndola impenetrable para los seres basados naturalmente en sentimientos positivos o luz. Cualquiera de estas criaturas que entre en la zona , debe realizar cada asalto una RM o perder tantos puntos de vida como el nivel de fracaso. Adicionalmente, de fallar el control, el ser recibirá de inmediato un penalizador a toda acción de -40 mientras siga en su interior. La zona afectada permanece estática en el lugar donde fue lanzada.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Oscuridad devoradora', '{"conjuro":"Oscuridad devoradora","via":"Oscuridad","nivel":66,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Daño del choque 80 y 600 puntos de Resistencia","efectoIntermedio":"Daño del choque 110 y 1200 puntos de Resistencia","efectoAvanzado":"Daño del choque 140 y 1800 puntos de Resistencia","efectoArcano":"Daño del choque 170 y 2200 puntos de Resistencia","efecto":"Crea un escudo sobrenatural sombrío que posee además la habilidad de tragarse cualquier hechizo de Ataque que reciba. Para que el conjuro sea absorbido, es necesario primero lograr una parada con éxito contra la descarga, y en segundo lugar ganar un control de choque. El vacío permite absorber la mitad del Zeon del conjuro devorado. Es posible incluso que se trague ataques en área.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrozar', '{"conjuro":"Destrozar","via":"Oscuridad","nivel":68,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120.","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"Provoca penalizadores mediante la acumulación de dolor, sufrimiento, desdicha y otros efectos místicos tenebrosos. El afectado deberá superar una RM, o sufrir un penalizador a toda acción y a sus Resistencias equivalente al nivel de fracaso del control. Si no supera la RM, el blanco del conjuro no tendrá derecho a una nueva tirada mientras el hechizo se mantenga","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Marca del miedo', '{"conjuro":"Marca del miedo","via":"Oscuridad","nivel":70,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":280,"zeonArcano":360,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Visible en 1 kilómetro de radio / RM o RP 120","efectoIntermedio":"Visible en 5 kilómetros de radio / RM o RP 150","efectoAvanzado":"Visible en 15 kilómetros de radio / RM o RP 180","efectoArcano":"Visible en 25 kilómetros de radio / RM o RP 220","efecto":"Forma una marca o un espectáculo de luces en un lugar determinado que aterroriza y llena de terror a quienes la observen. Todo aquel que lo mire y falle la Resistencia sufrirá de inmediato el estado de Terror. La condición para ser afectado consiste en mirar directamente la Marca del Miedo","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Oscuridad catastrófica', '{"conjuro":"Oscuridad catastrófica","via":"Oscuridad","nivel":72,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 120 / 25 metros de radio","efectoIntermedio":"Daño 150 / 100 metros de radio","efectoAvanzado":"Daño 200 / 150 metros de radio","efectoArcano":"Daño 250 / 250 metros de radio","efecto":"Proyecta una descarga de energía basada en oscuridad. Ataca en la TA de Energía.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Objetos oscuros', '{"conjuro":"Objetos oscuros","via":"Oscuridad","nivel":76,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Presencia 60 / Calidad +5.","efectoIntermedio":"Presencia 100 / Calidad +10","efectoAvanzado":"Presencia 140 / Calidad +10","efectoArcano":"Presencia 180 / Calidad +15","efecto":"Forma un objeto físico de energía lumínica, ya sea algo tan complejo como un reloj o tan simple como una espada. Pese a estar hecho de luz, tiene consistencia física. La presencia máxima de dicho objeto y la calidad del mismo viene determinada por el grado del conjuro","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Transmisión por sombras', '{"conjuro":"Transmisión por sombras","via":"Oscuridad","nivel":78,"diario":"No","tipo":"Efecto Anímico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":360,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"100 kilómetros / 250 de presencia / RM 120","efectoIntermedio":"1.000 kilómetros / 500 de presencia / RM 140","efectoAvanzado":"5.000 kilómetros / 1.000 de presencia / RM 180","efectoArcano":"15.000 kilómetros / 2.000 de presencia / RM contra 200","efecto":"Transporta instantáneamente a los individuos u objetos designados por el brujo, desde una sombra hasta otra. Si desea resistirse, hay que superar la RM del conjuro. Tanto la distancia máxima como la máxima presencia afectable son determinadas por el grado del conjuro","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Rey de pesadillas', '{"conjuro":"Rey de pesadillas","via":"Oscuridad","nivel":80,"diario":"No","tipo":"Efecto Anímico","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":300,"zeonIntermedio":400,"zeonAvanzado":500,"zeonArcano":750,"mantBase":60,"mantIntermedio":65,"mantAvanzado":70,"mantArcano":80,"efectoBase":"RM 140.","efectoIntermedio":"RM 150 / En la Vigilia, obtiene Gnosis 40. En zona neutra, 30.","efectoAvanzado":"RM 160 / Como Intermedio, pero el Gnosis del brujo en zonas neutras es de 35.","efectoArcano":"RM 180 / Como Avanzado, sin límites espacial.","efecto":"Permite dominar cualquier pesadilla de objetivo que no pase RM. El mago podra controlar el mundo onírico de un durmiente, modificándolo como si tuviera Gnosis 45. En el caso de que sea un buen Sueños, su Gnosis será sólo de 30. Los conjuros que el brujo lance únicamente gracias a dicho Gnosis (como por ejemplo, magia divina), no tienen efecto fuera de los límites espaciales del conjuro y sus efectos desaparecen en cuanto el mago sale del Sueños o de la Vigilia","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Creación oscura', '{"conjuro":"Creación oscura","via":"Oscuridad","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":50,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":140,"efectoBase":"Nivel 1.","efectoIntermedio":"Nivel 3.","efectoAvanzado":"Nivel 6.","efectoArcano":"Nivel 10.","efecto":"Crea un ser oscuro con apariencia de vida, bajo el control absoluto del hechicero. El ente será desarrollado como un Ser Entre Mundos, usando los poderes y limitaciones de los elementales oscuros del Capítulo 26. Para calcular su nivel máximo se emplean las mismas reglas que en el conjuro Crear Ser, de la vía de Creación","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ocultarse ante la magia', '{"conjuro":"Ocultarse ante la magia","via":"Oscuridad","nivel":86,"diario":"Si","tipo":"Efecto","accion":"Pasiva","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Afecta a conjuros Automáticos de Grado Base","efectoIntermedio":"Afecta a conjuros Automáticos de Grado Intermedio","efectoAvanzado":"Afecta a conjuros Automáticos de Grado Avanzado","efectoArcano":"Afecta a conjuros Automáticos de Grado Arcano","efecto":"Oculta la presencia de un individuo contra los conjuros de tipo Automático, haciendo que no sea afectado de manera directa por ellos. Al contrario de lo que indican las reglas generales, el hechicero que mantenga cualquier conjuro Automático deberá conseguir fijar con su Proyección Mágica al personaje, como si se tratase de un conjuro Anímico normal, a pesar de que este cumpla la condición para ser afectado","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Reino de tinieblas', '{"conjuro":"Reino de tinieblas","via":"Oscuridad","nivel":88,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":360,"zeonAvanzado":430,"zeonArcano":480,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":25,"efectoBase":"50 metros de radio","efectoIntermedio":"500 metros de radio","efectoAvanzado":"1 kilómetro de radio","efectoArcano":"1 kilómetros de radio / +30 al ACT al lanzar conjuros oscuros","efecto":"Crea zona de oscuridad. El cuerpo del brujo se funde con sombras, +20 su ACT en Oscuridad y +40 a Resistencias contra detecciones. Para localizarlo con sentidos naturales, control de Buscar Imposible, o Advertir Inhumano, con Detección del Ki (Zen). Mientras lo mantenga se podrá transportar una vez por asalto como acción activa hasta donde desee dentro del límite. Todo ser no elemental oscuro pierde 10 de Zeon por turno y un punto de Ki, dos, si es de luz","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Indetección', '{"conjuro":"Indetección","via":"Oscuridad","nivel":90,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":350,"zeonIntermedio":450,"zeonAvanzado":600,"zeonArcano":800,"mantBase":80,"mantIntermedio":90,"mantAvanzado":105,"mantArcano":115,"efectoBase":"El personaje se vuelve indetectable ante conjuros y habilidades psíquicas.","efectoIntermedio":"Como en grado Base, pero se vuelve indetectable ante habilidades del Ki.","efectoAvanzado":"También es indetectable ante todas las habilidades sobrenaturales.","efectoArcano":"Ignora cualquier detección que no sean los sentidos naturales","efecto":"El hechicero, o quien este designe, se vuelve completamente inmune ante ciertos tipos de detecciones sobrenaturales. Por ejemplo, un personaje que use este conjuro en grado Arcano sólo podría ser encontrado mediante los sentidos físicos, como la vista o el oído.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Prisión de oscuridad', '{"conjuro":"Prisión de oscuridad","via":"Oscuridad","nivel":92,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":200,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":800,"mantBase":40,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":160,"efectoBase":"RM 140 / La prisión posee 10.000 puntos de resistencia","efectoIntermedio":"RM 180 / La prisión posee 250.000 puntos de resistencia","efectoAvanzado":"RM 220 / La prisión posee 500.000 puntos de resistencia","efectoArcano":"RM 240 / no se rompe desde dentro, 500.000 puntos de resistencia.","efecto":"Encierra algo en oscuridad, no podrá interactuar con el exterior, ni éste con lo encerrado. No se sabe lo que ocurre fuera, ni viceversa. Para forzar la prisión desde el interior, se considera un ser de acumulación con TA 10 y resistencia dada por el grado del conjuro. El daño desde fuera se dobla. Tiene Regeneración 19. Si el blanco falla la RM, deberá romper la prisión para salir de la prisión, sin derecho a otra RM. El mago no puede encerrarse.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Esencia oscura', '{"conjuro":"Esencia oscura","via":"Oscuridad","nivel":96,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":200,"zeonIntermedio":400,"zeonAvanzado":600,"zeonArcano":800,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Un día","efectoIntermedio":"Una semana","efectoAvanzado":"Un mes","efectoArcano":"Un año","efecto":"Permite al lanzador o el objetivo designado por este entrar en completo letargo, mientras su cuerpo se hace uno con la oscuridad. La entidad abandona el mundo y asciende a la red de almas para nutrirse de sus energías. Apartado y desconocedor de todo lo que sucede en el exterior, multiplica por 10 su regeneración zeónica y cura sus heridas con Regeneración 16. Cuanto tiempo puede permanecer apartado del mundo es determinado por el grado del conjuro.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ascensión oscura', '{"conjuro":"Ascensión oscura","via":"Oscuridad","nivel":98,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":500,"zeonIntermedio":1000,"zeonAvanzado":2000,"zeonArcano":5000,"mantBase":30,"mantIntermedio":40,"mantAvanzado":45,"mantArcano":50,"efectoBase":"Gnosis máximo 30","efectoIntermedio":"Gnosis máximo 35","efectoAvanzado":"Gnosis máximo 40","efectoArcano":"Gnosis máximo 45.","efecto":"El conjuro intercambia la esencia del lanzador por energía divina, modificando su espíritu por puro poder sobrenatural. Al hacerlo, el lanzador o el individuo designado por éste aumenta su Gnosis hasta una cantidad máxima determinada por el grado del conjuro","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Holocausto de oscuridad', '{"conjuro":"Holocausto de oscuridad","via":"Oscuridad","nivel":100,"diario":"No","tipo":"Ataque Anímico","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":600,"zeonIntermedio":1000,"zeonAvanzado":2500,"zeonArcano":10000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 350 / 100 metros de radio","efectoIntermedio":"Daño 500 / 100 kilómetros de radio","efectoAvanzado":"Daño 800 / 10.000 kilómetros de radio","efectoArcano":"Daño 1.000 / 1 ua de radio","efecto":"Este poder arrasa todo, tanto en el mundo material como espiritual. Incluso las criaturas elementales de oscuridad son asimiladas. Una gran cúpula oscura que ataca en la TA de energía. Cualquier ser que reciba daño, por mínimo que sea, debe superar una RM de 160 o es unificado con la oscuridad y destruido en cuerpo y alma. No es posible designar blancos en el radio del conjuro, y afecta a todos por igual salvo al lanzador.","_seccion":"OSCURIDAD"}'::jsonb),
  ('core-exxet', 'conjuros', 'Creación menor', '{"conjuro":"Creación menor","via":"Creación","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"1 obj. / pres. max 25","efectoIntermedio":"5 obj. / pres. max 25","efectoAvanzado":"1 obj. / pres max. 30","efectoArcano":"5 obj. / pres. max 30","efecto":"Crea un objeto de naturaleza simple, cuya presencia no podrá ser mayor a 25","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Reconstruir', '{"conjuro":"Reconstruir","via":"Creación","nivel":6,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":280,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Pres. max. afectable 20","efectoIntermedio":"Pres. max. afectable 60","efectoAvanzado":"Pres. max. Afec. 100","efectoArcano":"Pres. max. Afect. 120","efecto":"Restaura un objeto inorgánico hasta su forma original, a partir de las piezas o componentes que queden de él. Nótese que es necesario tener todos sus fragmentos o la materia prima necesaria para que la reconstrucción sea completa o, en caso contrario, sólo se reparará parcialmente.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear energía', '{"conjuro":"Crear energía","via":"Creación","nivel":8,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"1 intensidad","efectoIntermedio":"5 intensidades","efectoAvanzado":"10 intensidades","efectoArcano":"20 intensidades","efecto":"Crea intensidades de uno de los tres tipos de energía existentes: frío, fuego o electricidad.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Regeneración', '{"conjuro":"Regeneración","via":"Creación","nivel":10,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":250,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":25,"efectoBase":"Regeneración 4","efectoIntermedio":"Regeneración 8","efectoAvanzado":"Regeneración 12","efectoArcano":"Regeneración 16","efecto":"Aumenta la capacidad de un cuerpo para sanar todo tipo de herida. Este conjuro otorga un nivel de Regeneración base a cualquier individuo designado por el mago, sustituyendo la que poseyera naturalmente.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Modificación inorgánica', '{"conjuro":"Modificación inorgánica","via":"Creación","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"Presencia máxima 20","efectoIntermedio":"Presencia máxima 30","efectoAvanzado":"Presencia máxima 40","efectoArcano":"Presencia máxima 50","efecto":"Mediante el control de la magia, el brujo puede alterar la forma y naturaleza de un objeto inorgánico, convirtiéndolo en otro completamente distinto pero de poder espiritual similar. De este modo, permite transformar algo en otra cosa que tenga una presencia igual o inferior.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aumentar resistencias', '{"conjuro":"Aumentar resistencias","via":"Creación","nivel":16,"diario":"Si","tipo":"Efecto","accion":"Pasiva","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":150,"zeonArcano":200,"mantBase":15,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"Mas 10 a Resistencias","efectoIntermedio":"Mas 20 a Resistencias","efectoAvanzado":"Mas 30 a Resistencias","efectoArcano":"Mas 40 a Resistencias","efecto":"Incrementa sobrenaturalmente todas las Resistencias de un individuo (RF, RV, RE, RM y RP). Los efectos de este conjuro no se superponen, y sólo se puede afectar con él una vez a cada sujeto.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo real', '{"conjuro":"Escudo real","via":"Creación","nivel":18,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":150,"zeonAvanzado":260,"zeonArcano":400,"mantBase":5,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"500 Puntos de Resistencia","efectoIntermedio":"3.000 Puntos de Resistencia","efectoAvanzado":"5.000 Puntos de Resistencia","efectoArcano":"10.000 Puntos de Resistencia","efecto":"Forma una barrera de energía que protege frente a cualquier fuente de ataque.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Curación', '{"conjuro":"Curación","via":"Creación","nivel":20,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":150,"zeonArcano":200,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"50 Puntos de vida.","efectoIntermedio":"150 Puntos de vida.","efectoAvanzado":"250 Puntos de vida.","efectoArcano":"350 Puntos de vida.","efecto":"Hace recuperar puntos de vida al sujeto sobre el que se lance. Este conjuro no permite recobrar miembros cercenados o pérdidas permanentes, pero sí elimina los penalizadores temporales causados por críticos, en una cantidad equivalente a la mitad de los puntos de vida devueltos.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Barrera de daño', '{"conjuro":"Barrera de daño","via":"Creación","nivel":22,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Barrera de Daño 30.","efectoIntermedio":"Barrera de Daño 50.","efectoAvanzado":"Barrera de Daño 80.","efectoArcano":"Barrera de Daño 100.","efecto":"Las energías sobrenaturales que maneja este hechizo se unen al cuerpo del individuo designado, otorgándole así cierta inmunidad al daño. A efectos de juego, obtendrá una barrera de daño (Ver capítulo 14).","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear homúnculo', '{"conjuro":"Crear homúnculo","via":"Creación","nivel":26,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":180,"zeonAvanzado":250,"zeonArcano":350,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":35,"efectoBase":"1 Homúnculo","efectoIntermedio":"10 Homúnculos","efectoAvanzado":"25 Homúnculos","efectoArcano":"100 Homúnculos","efecto":"Crea elementales de magia de nivel 0 para diversas funciones, bajo el completo control del mago, con las reglas del Capítulo 26. Son Seres Entre Mundos con Gnosis 5. El maximo en características es 5, sin Don, ni habilidad primaria o secundaria mayor a 50. Tienen un penalizador de –2 a tamaño y no pueden elegir Tamaño Innatural. Ninguna habilidad intelectual puede estar por encima de la de su creador. Pueden ser muy diferentes.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cambio menor', '{"conjuro":"Cambio menor","via":"Creación","nivel":28,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":150,"zeonArcano":250,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":25,"efectoBase":"RM 80 / Máxima Presencia 60","efectoIntermedio":"RM 100 / Máxima Presencia 90","efectoAvanzado":"RM 140 / Máxima Presencia 120","efectoArcano":"RM 180 / Máxima Presencia 180","efecto":"Altera la apariencia de un objeto o ser, modificando su forma. Modifica aspecto exterior, sin perder sus cualidades o naturaleza original. Una espada corta se podría tornar vieja y oxidada, pero no en un bastón. A los seres vivos, puede modificarse su aspecto físico sin variar más de dos puntos su Tamaño. Los objetos no repiten control de RM, las personas, una vez al día. Se puede afectar a varios objetivos, si la suma de sus presencias no es mayor a lo permitido.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Imitar', '{"conjuro":"Imitar","via":"Creación","nivel":30,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Presencia máxima 30","efectoIntermedio":"Presencia máxima 80","efectoAvanzado":"Presencia máxima 120","efectoArcano":"Presencia máxima 160","efecto":"Crea una copia exacta de un objeto inorgánico ya existente que se encuentre al alcance del brujo. Se forma una imitación perfecta del original que mantendrá todas sus cualidades, incluso las sobrenaturales, siempre y cuando no sean poderes de Nivel 4 o superior. No tiene efectos sobre criaturas animadas mágicamente, pero sí sobre construcciones mecánicas, en el caso de que no tengan alma.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inmunidad', '{"conjuro":"Inmunidad","via":"Creación","nivel":32,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"5 Intensidades","efectoIntermedio":"15 Intensidades","efectoAvanzado":"25 Intensidades","efectoArcano":"35 Intensidades","efecto":"Este conjuro permite al hechicero, o a aquellas personas designadas por él, ser inmune a intensidades de un tipo concreto de energía, ya sea fuego, electricidad o frío. En el caso de que se reciba un ataque basado en el elemento respecto del que se es inmune, cada intensidad disminuye 5 puntos el daño base y otorga un +5 a las Resistencias contra sus efectos.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Reducción de daño', '{"conjuro":"Reducción de daño","via":"Creación","nivel":36,"diario":"No","tipo":"Auto","accion":"Pasiva","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":240,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Menos 40 al daño del ataque","efectoIntermedio":"Menos 60 al daño del ataque","efectoAvanzado":"Menos 80 al daño del ataque","efectoArcano":"Menos 120 al daño del ataque","efecto":"La magia de este conjuro afecta a la potencia de una agresión, disminuyendo la fuerza de su impacto. Al ser lanzado, reduce el daño base de un ataque. Si esta decrece hasta 0, la agresión no produce ningún efecto. Si, por ejemplo, se utiliza en grado base contra un ataque de daño 60, cuando este vaya a golpear se calculará como si tuviera sólo 20. Dos conjuros de reducción de daño no se superponen frente a una misma fuente de ataque.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control físico', '{"conjuro":"Control físico","via":"Creación","nivel":38,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":24,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"RM 80","efectoIntermedio":"RM 120","efectoAvanzado":"RM 140","efectoArcano":"RM 180","efecto":"Permite controlar el cuerpo de un ser. Dado a que es solo dominio físico y no espiritual, el individuo sometido no está obligado a usar ninguna habilidad sobrenatural en contra de su voluntad, aunque sí sus habilidades marciales. Para resistir el control, hay que superar una RM. El afectado tendrá derecho a una nueva Resistencia por día, y en cada ocasión en la que las órdenes recibidas vayan completamente en contra de su comportamiento.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Adquirir habilidades', '{"conjuro":"Adquirir habilidades","via":"Creación","nivel":40,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":280,"zeonArcano":350,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Mas 50 al bonificador","efectoIntermedio":"Mas 150 al bonificador","efectoAvanzado":"Mas 250 al bonificador","efectoArcano":"Mas 400 al bonificador","efecto":"Este hechizo incrementa temporalmente las habilidades secundarias de un individuo, otorgándole un bonificador que podrá repartir libremente entre cualquier campo hasta un máximo de 320, salvo en aquellos que requieran conocimientos.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Fusionar', '{"conjuro":"Fusionar","via":"Creación","nivel":42,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Presencia máxima 80 / RM 80","efectoIntermedio":"Presencia máxima 100 / RM 120","efectoAvanzado":"Presencia máxima 150 / RM 140","efectoArcano":"Presencia máxima 200 / RM 180","efecto":"Une dos seres, creando otro con características y habilidades de ambos. El mago elige qué capacidades predominarán,de cada uno. El dominio del cuerpo es del que gane un control enfrentado de Voluntad, pero se mantiene algo de personalidad del otro. Los cuerpos vuelven como eran al finalizar el conjuro. La muerte de la entidad conlleva la muerte de ambos . La suma de la presencia no puede ser mayor al limite. Es posible fusionar seres con objetos.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear recuerdos', '{"conjuro":"Crear recuerdos","via":"Creación","nivel":46,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 100","efectoIntermedio":"RM o RP 120","efectoAvanzado":"RM o RP 160","efectoArcano":"RM o RP 200","efecto":"Permite crear recuerdos en la mente de alguien, sin borrar necesariamente con ello los anteriores. Salvo si se modifican memorias muy arraigadas, el personaje se siente confundido, pero cree que todos sus recuerdos son reales. El mago puede determinar la información a inducir, no importa complejidad o duración. Para evitarlo, RM o RP. Aunque no exige mantenimiento, el individuo tendrá derecho a una nueva tirada si ve o hace algo de lo que sospechar.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Recuperar', '{"conjuro":"Recuperar","via":"Creación","nivel":48,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":250,"zeonIntermedio":300,"zeonAvanzado":350,"zeonArcano":400,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"500 Puntos de vida","efectoIntermedio":"750 Puntos de vida","efectoAvanzado":"1.000 Puntos de vida","efectoArcano":"1.500 Puntos de vida","efecto":"Restaura completamente la condición física de un sujeto, sanando sus puntos de vida perdidos y haciendo desaparecer cualquier penalizador físico que tuviese, siempre que no sea por causa de miembros amputados o daños similares. Este hechizo no recupera puntos de Cansancio, ni deshace estados negativos provocados por medios sobrenaturales.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Adquirir poderes', '{"conjuro":"Adquirir poderes","via":"Creación","nivel":50,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":20,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"100 PD","efectoIntermedio":"200 PD","efectoAvanzado":"300 PD","efectoArcano":"400 PD / Gnosis 30","efecto":"Concede al mago, o a alguien, habilidades sobrenaturales. Otorga PD adicionales para obtener poderes detallados en el Capítulo 26, como si tuviera Gnosis 25. Esto afectará temporalmente a su forma física. Si obtiene Vuelo Natural, lo más lógico sería que estuviese dotado de unas enormes alas. Los beneficios de este conjuro no se superponen, y sólo puede afectar uno por sujeto.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear engendro', '{"conjuro":"Crear engendro","via":"Creación","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":250,"zeonArcano":500,"mantBase":10,"mantIntermedio":15,"mantAvanzado":25,"mantArcano":50,"efectoBase":"Nivel 2","efectoIntermedio":"Nivel 4","efectoAvanzado":"Nivel 8","efectoArcano":"Nivel 12","efecto":"Crea un ser mágico con apariencia de vida bajo control del mago. Se crea como un Ser Entre Mundos con las reglas del Capítulo 26. Tendrá Gnosis 20. Sin importar el Grado, no se puede crear criaturas de un nivel superior al del mago. Los engendros no tienen la capacidad de recibir un alma, por lo que no es posible darles vida independiente mediante el conjuro de Otorgar Alma, ni transmigrar un espíritu en ellos.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aura de protección', '{"conjuro":"Aura de protección","via":"Creación","nivel":56,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":10,"mantIntermedio":15,"mantAvanzado":25,"mantArcano":35,"efectoBase":"Mas 20 a las Resistencias / 100 metros de radio","efectoIntermedio":"Mas 50 a las Resistencias / 500 metros de radio","efectoAvanzado":"Mas 80 a las Resistencias / 1 kilometro de radio","efectoArcano":"Mas 120 a las Resistencias / 10 kilometros de radio","efecto":"Incrementa sobrenaturalmente todas las Resistencias de los individuos designados por el brujo en un área (RF, RV, RE, RM y RP). Los efectos de este conjuro no se superponen, y sólo se puede afectar con él una vez a cada sujeto.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Estancar esencia', '{"conjuro":"Estancar esencia","via":"Creación","nivel":58,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 100","efectoIntermedio":"RM 120","efectoAvanzado":"RM 140","efectoArcano":"RM 180","efecto":"El mago estanca el espíritu de alguien en el estado en que se encuentra en ese momento. A partir de ahi, el afectado no deberá realizar nuevos controles mágicos o psíquicos, y permanecerá inalterablemente en esa condición espiritual. No podrá ser influido por estados de ningún tipo, tanto buenos como malos. Si desea resistir el estancamiento, superar una RM. Alguien afectado por este sortilegio no puede realizar ningún control para librarse de él mientras se mantenga.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo perfecto', '{"conjuro":"Escudo perfecto","via":"Creación","nivel":60,"diario":"Si","tipo":"Defensa","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":15,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"Aguanta 100 puntos de daño","efectoIntermedio":"Aguanta 250 puntos de daño","efectoAvanzado":"Aguanta 500 puntos de daño","efectoArcano":"Aguanta 1.000 puntos de daño","efecto":"Forma una barrera de energía que protege frente a cualquier fuente de ataque. Si no es destruido al finalizar el asalto, recupera automáticamente todos sus puntos de vida perdidos.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vitalidad', '{"conjuro":"Vitalidad","via":"Creación","nivel":62,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":350,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":35,"efectoBase":"Mas 50 puntos de vida","efectoIntermedio":"Mas 75 puntos de vida","efectoAvanzado":"Mas 100 puntos de vida","efectoArcano":"Mas 150 puntos de vida","efecto":"La magia crea un estado de vitalidad sobrenatural en un individuo, aumenta el valor máximo de sus puntos de vida mientras este hechizo se mantenga. Sus efectos no se superponen, y sólo se puede afectar con él una vez a cada sujeto. Los seres con acumulación de daño multiplican por cinco esta cantidad.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Creación completa', '{"conjuro":"Creación completa","via":"Creación","nivel":66,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":15,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"Presencia máxima 50","efectoIntermedio":"Presencia máxima 80","efectoAvanzado":"Presencia máxima 120","efectoArcano":"Presencia máxima 150","efecto":"Forma un objeto con una presencia determinada por el grado del conjuro. La creación debe de encontrarse en una ubicación lógica, dependiendo de su naturaleza. No es posible, por ejemplo, hacer aparecer una pequeña montaña, situarla en el aire y dejarla caer. Como limitación, la presencia del objeto creado no puede ser superior al doble de la presencia base del brujo.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Potenciar magia', '{"conjuro":"Potenciar magia","via":"Creación","nivel":68,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":8,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":100,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":10,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"Afecta la los conjuros de Grado Base","efectoIntermedio":"Afecta la los conjuros de Grado Intermedio","efectoAvanzado":"Afecta la los conjuros de Grado Avanzado","efectoArcano":"Afecta la los conjuros de Grado Arcano","efecto":"Potencia otro hechizo al que se le vincule. Otorga al sortilegio las siguientes ventajas: +20 a su RM, +50% de daño / resistencia al daño adicional (redondeado hacia arriba en grupos de 5) y +20% a cualquier valor numérico de diferente naturaleza (Presencia, intensidades, distancia, radio de efecto, incrementos o elementos similares), salvo los valores relacionados con el Gnosis.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Transmutar', '{"conjuro":"Transmutar","via":"Creación","nivel":70,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":800,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120 / Presencia Máxima 50","efectoIntermedio":"RM 160 / Presencia Máxima 100","efectoAvanzado":"RM 220 / Presencia Máxima 150","efectoArcano":"RM 260 / Presencia Máxima 200","efecto":"El brujo transforma un objeto inorgánico convirtiéndolo en otro distinto, pero de poder anímico similar. De este modo modifica algo en otra cosa que tenga un valor de presencia igual o inferior. Si el objeto es sobrenatural o especialmente poderoso, puede resistirse pasando una RM.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Metamorfismo', '{"conjuro":"Metamorfismo","via":"Creación","nivel":72,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":350,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 100","efectoIntermedio":"RM 120","efectoAvanzado":"RM 160","efectoArcano":"RM 200","efecto":"El mago transmuta la sustancia y forma de un cuerpo, convirtiéndolo en otra cosa, siempre que la presencia no sea mayor que la original. Los seres vivos que cambian a inorgánico, siguen viviendo bajo la nueva forma. Al finalizar el conjuro, recupera su forma. No otorga poderes o habilidades esenciales, salvo las de seres vivos naturales con Gnosis 0. Para evitar ser polimorfizado, superar una RM. Sólo se puede repetir la Resistencia una vez al día.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Recrear', '{"conjuro":"Recrear","via":"Creación","nivel":76,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":300,"zeonIntermedio":500,"zeonAvanzado":750,"zeonArcano":1500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Presencia máxima 60","efectoIntermedio":"Presencia máxima 120","efectoAvanzado":"Presencia máxima 180","efectoArcano":"Presencia máxima 240","efecto":"Restaura pérdidas sufridas por  un individuo u objeto. Puede elegir qué partes recrea.Un ser herido o una construcción destrozada recupera todo daño o negativo. Tambien deshace efectos de habilidades sobrenaturales, restaura recuerdos, o PD. Afecta carencias sufridas de modo artificial, no una evolución natural o positiva. No tiene efecto en almas fallecidas. El daño hecho por ser de Gnosis 15 puntos mayor, reduce la presencia afectable a la mitad.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear ser', '{"conjuro":"Crear ser","via":"Creación","nivel":78,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":400,"zeonAvanzado":600,"zeonArcano":1000,"mantBase":50,"mantIntermedio":80,"mantAvanzado":120,"mantArcano":200,"efectoBase":"Nivel 1","efectoIntermedio":"Nivel 5","efectoAvanzado":"Nivel 9","efectoArcano":"Nivel 12","efecto":"Crea una criatura con apariencia de vida bajo el control del mago. Será un Ser Entre Mundos con Gnosis 25. Su existencia se encuentra atada al alma del mago y el número de seres que haya creado que dependan de él limitará su nivel máximo. Puede tener como tope el nivel de su creador, menos el número de entidades creadas. Si uno o varios seres tienen ya su nivel máximo y el brujo crea otro nuevo, los anteriores bajan un nivel.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Quimera', '{"conjuro":"Quimera","via":"Creación","nivel":80,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":500,"zeonAvanzado":1000,"zeonArcano":2500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Más 100 PD / hasta 100 PD opcionales en desventajas","efectoIntermedio":"Más 200 PD / hasta 100 PD opcionales en desventajas","efectoAvanzado":"Más 300 PD / hasta 200 PD opcionales en desventajas","efectoArcano":"Más 400 PD / hasta 200 PD opcionales en desventajas","efecto":"El mago, o el objetivo, se transforma en un Ser Entre Mundos con Gnosis 25, con todas sus ventajas y desventajas. Obtendrá PD extras usables para elegir entre Habilidades Esenciales y poderes de la Creación de Seres. También puede escoger PD en desventajas y penalizadores para más puntos. El exceso de PD aumenta el nivel. Sólo funciona en seres naturales. Todo lo que se obtiene depende de su forma física perdiendose si se trasmigra el alma.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Zona de salvaguardia', '{"conjuro":"Zona de salvaguardia","via":"Creación","nivel":82,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":12,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":18,"zeonBase":350,"zeonIntermedio":500,"zeonAvanzado":800,"zeonArcano":1500,"mantBase":35,"mantIntermedio":50,"mantAvanzado":80,"mantArcano":150,"efectoBase":"RM 140 / radio de 100 metros","efectoIntermedio":"RM 180 / radio de 500 metros","efectoAvanzado":"RM 220 / radio de 1 kilómetro","efectoArcano":"RM 250 / radio de 5 kilómetros","efecto":"Crea zona en cuyo interior nada ni nadie puede causar ningún tipo de daño a ninguna persona u objeto. Afecta a cualquiera que se encuentre en el área del sortilegio, incluyendo al propio brujo. La zona encantada permanece en el lugar donde es lanzada, sin que el hechicero pueda reubicarla posteriormente. Para superar sus efectos es necesario superar una RM. Sólo es posible repetir la Resistencia una vez al día, incluso si se sale de ella y se vuelve a entrar.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mantenimiento', '{"conjuro":"Mantenimiento","via":"Creación","nivel":86,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":500,"zeonAvanzado":900,"zeonArcano":1600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"500 Puntos de Zeon","efectoIntermedio":"2.000 Puntos de Zeon","efectoAvanzado":"5.000 Puntos de Zeon","efectoArcano":"10.000 Puntos de Zeon","efecto":"Afecta a otro hechizo activo, fijándolo de un modo más duradero al mundo. A efectos de juego, añade puntos de Zeon al mantenimiento de un conjuro determinado. Ten en cuenta que esta cantidad no se suma a su potencial, sino que los emplea tan sólo para pagar su conservación.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Otorgar alma', '{"conjuro":"Otorgar alma","via":"Creación","nivel":88,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":13,"intRIntermedio":14,"intRAvanzado":15,"intRArcano":16,"zeonBase":500,"zeonIntermedio":800,"zeonAvanzado":1200,"zeonArcano":2000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Presencia máxima 30","efectoIntermedio":"Presencia máxima 50","efectoAvanzado":"Presencia máxima 80","efectoArcano":"Presencia máxima 100","efecto":"El mago puede concebir un alma, dándole el soplo de la vida a un objeto o cuerpo capaz de contenerla. Si se la otorga a una criatura engendrada mágicamente, como las del conjuro Crear Ser o los de nivel 82 de las elementales, no es necesario mantener el hechizo y el ente cobra existencia independiente. Rompe cualquier lazo con su creador, obteniendo libre albedrío. No se puede emplear sobre algo que ya posea un alma viva.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Creación mayor', '{"conjuro":"Creación mayor","via":"Creación","nivel":90,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":400,"zeonIntermedio":800,"zeonAvanzado":1200,"zeonArcano":2000,"mantBase":20,"mantIntermedio":25,"mantAvanzado":25,"mantArcano":30,"efectoBase":"500 Puntos de Presencia / Presencia máxima 100","efectoIntermedio":"1.000 Puntos de Presencia / Presencia máxima 120","efectoAvanzado":"2.000 Puntos de Presencia / Presencia máxima 140","efectoArcano":"3.000 Puntos de Presencia / Presencia máxima 180","efecto":"Otorga al hechicero el don de crear a su antojo, concediéndole puntos de presencia para repartir libremente entre varios objetos o construcciones. Puede elaborar cualquier cosa inanimada que desee, desde castillos a montañas, siempre y cuando la presencia de sus Creaciónes no seasuperior a lo que permite el grado del conjuro.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Magia eterna', '{"conjuro":"Magia eterna","via":"Creación","nivel":92,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":600,"zeonIntermedio":1000,"zeonAvanzado":2500,"zeonArcano":5000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Afecta a un conjuro de Grado Base","efectoIntermedio":"Afecta a un conjuro de Grado Intermedio","efectoAvanzado":"Afecta a un conjuro de Grado Avanzado","efectoArcano":"Afecta a un conjuro de Grado Arcano","efecto":"Disminuye el coste del mantenimiento de otro conjuro o incluso lo hace desaparecer, dependiendo de si influye o no a un mantenimiento diario. Si es diario deja de ser necesario mantenerlo. El sortilegio sigue siendo controlado por su lanzador. Si el mantenimiento es por asalto, se convierte en Diario. Magia Eterna sólo influye en hechizos que tengan un nivel de vía inferior a 80.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'La barrera', '{"conjuro":"La barrera","via":"Creación","nivel":96,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":15,"intRIntermedio":16,"intRAvanzado":17,"intRArcano":19,"zeonBase":800,"zeonIntermedio":2500,"zeonAvanzado":5000,"zeonArcano":10000,"mantBase":40,"mantIntermedio":45,"mantAvanzado":45,"mantArcano":50,"efectoBase":"RM 120 / 100 kilómetros cuadrados o línea","efectoIntermedio":"RM 180 / 1.000 kilómetros cuadrados o línea","efectoAvanzado":"RM 240 / 100.000 kilómetros cuadrados o línea","efectoArcano":"RM 300 / Sin límite de espacio","efecto":"Crea una brecha en la realidad, capaz de separar el mundo en dos. Si se traspasa, se sale por otro punto de la barrera y el transporte se percibe con advertir(inhumano). Es capaz de adoptar cualquier apariencia. El mago puede elegir dejar abiertos pasajes, en una o ambas direcciones. Se puede pasar con Gnosis 25 o mas, y sabiendo su existencia y ubicación exacta a su vez que tirando una RM. Si fracasa, sólo puede repetir una vez al día.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear la vida', '{"conjuro":"Crear la vida","via":"Creación","nivel":98,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":16,"intRIntermedio":17,"intRAvanzado":18,"intRArcano":19,"zeonBase":800,"zeonIntermedio":2000,"zeonAvanzado":4000,"zeonArcano":8000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Nivel 1 y 50 PD en el caso de que se trate de un ser natural","efectoIntermedio":"Nivel 6 y 100 PD en el caso de que se trate de un ser natural","efectoAvanzado":"Nivel 11 y 150 PD en el caso de que se trate de un ser natural","efectoArcano":"Nivel 16 y 200 PD en el caso de que se trate de un ser natural","efecto":"Permite crear una nueva forma de vida. La creación puede ser de cualquier clase (Natural, Espiritual o Entre Mundos), y estar atada a un elemento. El nivel máximo no podrá ser superior a al creador. Este debe elegir el Gnosis de su obra, dándole como máximo diez puntos menos que el del. Si es Natural con Gnosis inferior a 20, obtendrá además PD para elegir poderes y habilidades especiales raciales, empleando las reglas del Capítulo 26.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear', '{"conjuro":"Crear","via":"Creación","nivel":100,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":17,"intRIntermedio":18,"intRAvanzado":19,"intRArcano":20,"zeonBase":1000,"zeonIntermedio":3000,"zeonAvanzado":6000,"zeonArcano":12000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"1.000 Puntos de presencia / Presencia máxima 180 / 1 regla existencial","efectoIntermedio":"10.000 Puntos de presencia / Presencia máxima 220 / 5 reglas existenciales","efectoAvanzado":"10..000 Puntos de presencia / Presencia máxima 260 / 10 reglas existenciales","efectoArcano":"100.000 de presencia / Presencia máxima 320 / Sin límite reglas existenciales.","efecto":"Otorga la capacidad de concebir cualquier cosa que desee: continentes, océanos o incluso mundos enteros. Otorga puntos de presencia para crear, mientras no supere un límite de presencia determinada por el grado del conjuro. Este hechizo también puede imponer nuevas reglas a la realidad; alterar la gravedad, modificar la velocidad con la que pasa el tiempo… Cualquiera con un Gnosis inferior a la mitad del que posee el lanzador, se verá sometido a ellas.","_seccion":"CREACION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Fragilidad', '{"conjuro":"Fragilidad","via":"Destrucción","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"-2 a su entereza / Presencia máxima afectable 30","efectoIntermedio":"-4 a su entereza / Presencia máxima afectable 60","efectoAvanzado":"-8 a su entereza / Presencia máxima afectable 90","efectoArcano":"-12 a su entereza / Presencia máxima afectable 120","efecto":"Altera la solidez de un objeto. Cualquier cuerpo afectado perderá automáticamente su barrera de daño y, en caso de ser un arma o una armadura, reducirá su entereza","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Desmantelar', '{"conjuro":"Desmantelar","via":"Destrucción","nivel":6,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Presencia máxima 20","efectoIntermedio":"Presencia máxima 40","efectoAvanzado":"Presencia máxima 60","efectoArcano":"Presencia máxima 80","efecto":"Desmantela un objeto que esté formado por varias partes. Sólo afecta a cosas inanimadas.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir intensidades', '{"conjuro":"Destruir intensidades","via":"Destrucción","nivel":8,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"1 intensidad / 100 RM","efectoIntermedio":"5 intensidades / 120 RM","efectoAvanzado":"10 intensidades / 140 RM","efectoArcano":"15 intensidades / 160 RM","efecto":"Destruye intensidades de uno de los tres tipos de energía existentes: fuego, frío o electricidad. Los seres formados por dichos elementos pierden cinco puntos de vida por cada intensidad disminuida, si no superan la RM adecuada.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción menor', '{"conjuro":"Destrucción menor","via":"Destrucción","nivel":10,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":140,"zeonArcano":180,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Presencia máxima 20","efectoIntermedio":"Presencia máxima 40","efectoAvanzado":"Presencia máxima 60","efectoArcano":"Presencia máxima 80","efecto":"Afecta a la esencia de un objeto sin vida, destruyéndolo completamente, siempre que su presencia no sea superior a lo permitido por el grado del conjuro","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Esfera de destrucción', '{"conjuro":"Esfera de destrucción","via":"Destrucción","nivel":12,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":13,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":100,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Un ataque","efectoIntermedio":"Tres ataques","efectoAvanzado":"Cinco ataques","efectoArcano":"Siete ataques","efecto":"Proyecta descargas menores de energía mágica. El ataque se realiza en la TA de Energía y tiene daño 30. Cada ataque puede ser dirigido a blancos diferentes, pero hay que determinar todos sus objetivos y distribución en el momento del lanzamiento.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Incrementar debilidad', '{"conjuro":"Incrementar debilidad","via":"Destrucción","nivel":16,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"120 RM","efectoIntermedio":"140 RM","efectoAvanzado":"160 RM","efectoArcano":"200 RM","efecto":"Incrrementa los puntos débiles de alguien. Dobla el penalizador que tenga por alguna vulnerabilidad. Un elemental débil ante la lúz recibiría x4 de daño contra ataques de luz, mientras que alguien vulnerable a los venenos reduciría su RV x4. Una vez afectado por la RM, el blanco del conjuro puede repetir la tirada cada vez que su debilidad le afecte.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción de magia', '{"conjuro":"Destrucción de magia","via":"Destrucción","nivel":18,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":16,"zeonBase":60,"zeonIntermedio":150,"zeonAvanzado":300,"zeonArcano":500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Valor zeónico 50","efectoIntermedio":"Valor zeónico 120","efectoAvanzado":"Valor zeónico 200","efectoArcano":"Valor zeónico 350","efecto":"Destruye un sortilegio hasta cierto valor de Zeon. Dado que es un conjuro pasivo, puede emplearse para anular cualquier hechizo que se lance en el mismo asalto.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Agravar daño', '{"conjuro":"Agravar daño","via":"Destrucción","nivel":20,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":220,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño +30","efectoIntermedio":"Daño +50","efectoAvanzado":"Daño +90","efectoArcano":"Daño +120","efecto":"Aumenta el daño base que produce una fuente de ataque de cualquier clase: físico o sobrenatural. Un luchador que acomete con un arma de daño base 60, empleando este conjuro en grado base, podrá incrementarlo hasta 90. A pesar de ser un sortilegio pasivo, debe ser ejecutado antes de que se lancen los dados para calcular el ataque y la defensa de los oponentes.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción de matrices', '{"conjuro":"Destrucción de matrices","via":"Destrucción","nivel":22,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":16,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":240,"zeonArcano":320,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Dificultad Media (80)","efectoIntermedio":"Dificultad Muy Difícil (140)","efectoAvanzado":"Dificultad Casi Imposible (240)","efectoArcano":"Dificultad Inhumana (320)","efecto":"Este hechizo deshace las energías matriciales de un poder psíquico. Dado que es pasivo, puede emplearse para anular cualquier poder lanzado en el mismo turno.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Herir', '{"conjuro":"Herir","via":"Destrucción","nivel":26,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"20% de Puntos de Vida / 120 RM","efectoIntermedio":"40% de Puntos de Vida / 140 RM","efectoAvanzado":"60% de Puntos de Vida / 160 RM","efectoArcano":"80% de Puntos de Vida / 200 RM","efecto":"Herir afecta a la condición física de un individuo, menoscabando su estado de salud en ese momento. Produce heridas y daños equivalentes a un porcentaje de sus puntos de vida actuales, no de su total. Para resistir este hechizo, debe de superase una RM.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción de ki', '{"conjuro":"Destrucción de ki","via":"Destrucción","nivel":28,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":220,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"140 RM","efectoIntermedio":"160 RM","efectoAvanzado":"180 RM","efectoArcano":"220 RM","efecto":"La magia que desencadena este conjuro se introduce en el alma de un individuo, deshaciendo la reserva de Ki que posea. El afectado deberá superar una RM o perderá una cantidad de puntos de Ki equivalente al nivel de fracaso.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Producir daño', '{"conjuro":"Producir daño","via":"Destrucción","nivel":30,"diario":"No","tipo":"Anímico","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"50 puntos de daño / 120 RM","efectoIntermedio":"100 puntos de daño / 140 RM","efectoAvanzado":"180 puntos de daño / 160 RM","efectoArcano":"250 puntos de daño / 200 RM","efecto":"Produce automáticamente una herida al objetivo. De no superar la RM, el individuo afectado recibe directamente el daño indicado. Las criaturas de acumulación multiplican esta cantidad por su múltiplo de acumulación.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción de sentidos', '{"conjuro":"Destrucción de sentidos","via":"Destrucción","nivel":32,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":280,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"100 RM","efectoIntermedio":"120 RM","efectoAvanzado":"140 RM","efectoArcano":"180 RM","efecto":"Arrebata los sentidos de un individuo que no supere la RM. El brujo es quien decide qué sentidos son afectados.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descarga', '{"conjuro":"Descarga","via":"Destrucción","nivel":36,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":220,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 100","efectoIntermedio":"Daño 150","efectoAvanzado":"Daño 200","efectoArcano":"Daño 250","efecto":"Proyecta una descarga mística, que ataca en la TA de Energía.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Desatar vínculos', '{"conjuro":"Desatar vínculos","via":"Destrucción","nivel":38,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"120 RM","efectoIntermedio":"140 RM","efectoAvanzado":"160 RM","efectoArcano":"200 RM","efecto":"Deshace los lazos que los convocadores tienen sobre sus criaturas. Puede usarse sobre el ser o sobre el convocador, pero siempre será el creador del vínculo el que deba superar el control de resistencia. De emplearse sobre el ser, sólo destruirá el lazo que le afecta a él. Pero si se lanza sobre el convocador, el hechizo romperá un vínculo de control o atadura adicional por cada diez puntos por los que no supere la RM. Los familiares aplican un +40 al control.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir resistencias', '{"conjuro":"Destruir resistencias","via":"Destrucción","nivel":40,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"120 RM","efectoIntermedio":"160 RM","efectoAvanzado":"200 RM","efectoArcano":"240 RM","efecto":"El afectado disminuirá todas sus resistencias en una cantidad equivalente a la cifra por la que no supere la RM del conjuro","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Deshacer estados', '{"conjuro":"Deshacer estados","via":"Destrucción","nivel":42,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"120 RM / Presencia máxima 120","efectoIntermedio":"140 RM / Presencia máxima 200","efectoAvanzado":"160 RM / Presencia máxima 300","efectoArcano":"200 RM / Presencia máxima 400","efecto":"Deshace inmediatamente cualquiera de los estados descritos en el Capítulo 14 del manual básico, u otros equivalentes. Podrá afectar a tantos individuos como se desee, siempre y cuando la suma de sus presencias no sea superior a la determinada por el conjuro. No puede deshacer los penalizadores a toda acción provocados por un crítico. Si desea resistirse, debe superarse la RM.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cúpula de destrucción', '{"conjuro":"Cúpula de destrucción","via":"Destrucción","nivel":46,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"10 metros de radio / Daño 80","efectoIntermedio":"50 metros de radio / Daño 120","efectoAvanzado":"100 metros de radio / Daño 160","efectoArcano":"150 metros de radio / Daño 200","efecto":"Desencadena una cúpula de energía sobrenatural, que estalla en un área. El ataque se realiza en la TA de Energía, y no es posible seleccionar blancos.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Área de decaimiento', '{"conjuro":"Área de decaimiento","via":"Destrucción","nivel":48,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"10 metros de radio / RM 100","efectoIntermedio":"30 metros de radio / RM 120","efectoAvanzado":"60 metros de radio / RM 160","efectoArcano":"100 metros de radio / RM 200","efecto":"Crea una zona estática, en la que toda forma de vida comienza a pudrirse y deshacerse de forma acelerada. Quien se encuentre dentro de ella, perderá una décima parte de sus puntos de vida totales si no es capaz de superar el control de RM. Cada asalto que permanezca dentro del área, debe realizar un nuevo control, sin importar si ha superado o no la resistencia anteriormente. La condición para ser afectado es encontrarse dentro del área.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aura de destrucción', '{"conjuro":"Aura de destrucción","via":"Destrucción","nivel":50,"diario":"Sí","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":350,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 80 / Presencia máxima 60 / 1 metro de diámetro","efectoIntermedio":"RM 100 / Presencia máxima 90 / 5 metros de diámetro","efectoAvanzado":"RM 120 / Presencia máxima 120 / 15 metros de diámetro","efectoArcano":"RM 150 / Presencia máxima 150 / 25 metros de diámetro","efecto":"Encanta un objeto o lugar, creando a su alrededor un aura de magia que destruye todo lo que se pone en contacto con ella. Cualquiera que la toque deberá superar una RM, o perderá una cantidad de puntos de vida equivalente a su nivel de fracaso. Los efectos del hechizo se aplican incluso sobre el lanzador.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir recuerdos', '{"conjuro":"Destruir recuerdos","via":"Destrucción","nivel":52,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 100","efectoIntermedio":"RM o RP 120","efectoAvanzado":"RM o RP 160","efectoArcano":"RM o RP 200","efecto":"Afecta a los recuerdos de un individuo, haciéndole olvidar todo lo que el hechicero desee. No influye en las habilidades, sólo en la memoria consciente.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Bloquear aprendizaje', '{"conjuro":"Bloquear aprendizaje","via":"Destrucción","nivel":56,"diario":"Sí","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":300,"zeonArcano":500,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"Este hechizo estanca la capacidad de aprendizaje de un individuo, impidiéndole evolucionar o adquirir nuevos conocimientos. Mientras se encuentre bajo los efectos de la magia, no podrá adquirir puntos de experiencia, ni desarrollar ninguna de sus habilidades o poderes. Sólo es posible repetir la RM una vez al día.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Negar', '{"conjuro":"Negar","via":"Destrucción","nivel":58,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":15,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"El hechicero veta una acción concreta para un sujeto, impidiendole intentar siquiera llevarla a cabo. Este conjuro sólo permite negar acciones activas. En el caso de que la acción negada sea muy amplia, como no atacar, o no moverse, el afectado puede aplicar entre un +10 y un +30 a su RM.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir poderes', '{"conjuro":"Destruir poderes","via":"Destrucción","nivel":60,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 180","efectoArcano":"RM 220","efecto":"Si un sujeto es afectado por este conjuro, pierde automáticamente la capacidad de utilizar sus habilidades sobrenaturales. Niega los poderes mágicos, psiquicos o dominios del Ki que posea. Los seres místicos también pierden todos sus poderes, aunque no sus habilidades sobrenaturales.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descarga mayor', '{"conjuro":"Descarga mayor","via":"Destrucción","nivel":62,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":150,"zeonIntermedio":300,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 150","efectoIntermedio":"Daño 300","efectoAvanzado":"Daño 450","efectoArcano":"Daño 500","efecto":"Proyecta una poderosa descarga mística. El ataque se realiza en la TA de Energía.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir la voluntad', '{"conjuro":"Destruir la voluntad","via":"Destrucción","nivel":66,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":160,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantBase":20,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120 / 10 metros de radio","efectoIntermedio":"RM 140 / 25 metros de radio","efectoAvanzado":"RM 160 / 50 metros de radio","efectoArcano":"RM 180 / 100 metros de radio","efecto":"Este conjuro afecta a un área dentro de la cual, todo individuo que no supere una RM perderá automáticamente la capacidad de tomar decisiones. Mientras una persona esté bajo los efectos de este sortilegio, no podrá emprender ninguna acción activa, salvo caso de necesidad institntiva.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Zona de debilidad', '{"conjuro":"Zona de debilidad","via":"Destrucción","nivel":68,"diario":"Sí","tipo":"Auto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":20,"mantIntermedio":30,"mantAvanzado":40,"mantArcano":50,"efectoBase":"25 metros de radio / RM 140","efectoIntermedio":"100 metros de radio / RM 160","efectoAvanzado":"250 metros de radio / RM 180","efectoArcano":"500 metros de radio / RM 200","efecto":"Todo en el área se vuelve frágil y quebradizo. Todo daño se dobla y los personajes reciben críticos como si todo su cuerpo fuera un punto vulnerable. Las estructuras perderán su barrera de daño, y los objetos con entereza, sufren un penalizador de -5. El área permanece fija, y la condición para verse afectado es simplemente entrar en su interior. Sólo es posible repetir la RM una vez al día, aunque los efectos desaparecen al abandonar el lugar afectado.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Esencia de destrucción', '{"conjuro":"Esencia de destrucción","via":"Destrucción","nivel":70,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Daño equivalnente al nivel de fracaso","efectoIntermedio":"Daño y negativo a toda acción equivalentes al nivel de fracaso","efectoAvanzado":"Daño x 2 de nivel de fracaso / Negativo a acción igual a nivel de fracaso","efectoArcano":"Daño y negativo a toda acción equivalentes al doble del nivel de fracaso","efecto":"El brujo altera la materia de su cuerpo, transformándolo en una forma de pura energía destructiva, capaz de devorar todo lo que se ponga en contacto con ella. Mientras se encuentre en ese estado, sólo podrá ser dañado por ataques capaces de dañar energía, y cualquiera que se ponga en contacto con él deberá superar una RM contra el doble de la presencia del brujo, o sufrirá los efectos descritos en el nivel del hechizo.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Muerte', '{"conjuro":"Muerte","via":"Destrucción","nivel":72,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":250,"zeonAvanzado":300,"zeonArcano":350,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RF 120","efectoIntermedio":"RM o RF 140","efectoAvanzado":"RM o RF 160","efectoArcano":"RM o RF 180","efecto":"El brujo es capaz de producir la muerte de un ser, separando su alma y su cuerpo. El poder de este conjuro es tan grande que puede incluso matar a seres espirituales y a criaturas nigrománticas, convirtiéndolos en simples almas muertas o destruyéndolos.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Zona devoradora', '{"conjuro":"Zona devoradora","via":"Destrucción","nivel":76,"diario":"Sí","tipo":"Auto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":360,"zeonAvanzado":450,"zeonArcano":600,"mantBase":25,"mantIntermedio":40,"mantAvanzado":45,"mantArcano":55,"efectoBase":"RM o RF 140 y 500 metros de radio","efectoIntermedio":"RM o RF 195 y 6000 metros de radio","efectoAvanzado":"RM o RF 240 y 10500 metros de radio","efectoArcano":"RM o RF 270 y 13500 metros de radio","efecto":"Por cada día que un objeto o personaje pase dentro de la zona devoradora, debe superar una RF o RM, o perderá 5 puntos de presencia base. Si ésta disminuye hasta 0, se descompondrá dejando escasos rastros. Los seres vivos reciben un penalizador a toda acción igual al doble de sus puntos de presencia perdidos. El daño espiritual se recupera al ritmo de cinco puntos por día.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir capacidades', '{"conjuro":"Destruir capacidades","via":"Destrucción","nivel":78,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":250,"zeonAvanzado":350,"zeonArcano":500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"-50 PD, RM 120","efectoIntermedio":"-100 PD, RM 160","efectoAvanzado":"-150 PD, RM 200","efectoArcano":"-200 PD, RM 240","efecto":"Destruye para siempre parte de las capacidades o poderes de un individuo. El brujo puede elegir libremente como rebajar los PDs del personaje afectado. Permite también destruir poderes de monstruo, según los costes fijados en el capítulo 26, y arrebatar las ventajas elegidas con puntos de Creación, a un coste de 100 PD por punto.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sesgar la existencia', '{"conjuro":"Sesgar la existencia","via":"Destrucción","nivel":80,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":350,"zeonIntermedio":500,"zeonAvanzado":600,"zeonArcano":800,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120 / 10 metros de línea","efectoIntermedio":"RM 160 / 100 metros de línea","efectoAvanzado":"RM 200 / 250 metros de línea","efectoArcano":"RM 240 / 1 kilómetro metros de línea","efecto":"Como si enarbolara una cuchilla de vacío, el brujo es capaz de cortar la misma realidad, aniquilando todo aquello que se encuentre en su camino. Cualquier cosa que entre en contacto con el conjuro, será destruida física y animicamente, sin dejar rastro de haber existido. Puede trazar una línea o ser enfocado en un solo punto. En este último caso, la RM a superar aumenta en +20. A pesar de ser un conjuro anímico, el corte en la realidad es visible para todo el mundo.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Lluvia de destrucción', '{"conjuro":"Lluvia de destrucción","via":"Destrucción","nivel":82,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 200 / RM 140 / 50 metros de radio","efectoIntermedio":"Daño 250 / RM 180 / 150 metros de radio","efectoAvanzado":"Daño 300 / RM 220 / 500 metros de radio","efectoArcano":"Daño 400 / RM 260 / 1 kilómetro de radio","efecto":"Desencadena una tempestad de descargas selectivas en área que destrozan únicamente los blancos designados por el brujo. Este conjuro ataca en la TA de Energía.Adicionalmente, si consigue impactar a un blanco y provocarle daño, este deberá superar una RM o sufrir una perdida de puntos de vida equivalente al nivel de fracaso","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción de zeon', '{"conjuro":"Destrucción de zeon","via":"Destrucción","nivel":86,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":400,"zeonAvanzado":600,"zeonArcano":700,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"-50 al Zeon del Conjuro / Sólo afecta a conjuros de grado base","efectoIntermedio":"-150 al Zeon del Conjuro/ Afecta a conjuros hasta grado Intermedio","efectoAvanzado":"-250 al Zeon del Conjuro/ Afecta a conjuros hasta grado Avanzado","efectoArcano":"-350 al Zeon del Conjuro/ Afecta a conjuros hasta grado arcano","efecto":"Afecta directamente a la esencia de la magia y es capaz de disipar el poder de otro sortilegio activo, disminuyendo su grado y valor zeónico. Si el hechizo queda mermado hasta una cantidad menor que el coste de su grado base, desaparece.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Arrojar de los cielos', '{"conjuro":"Arrojar de los cielos","via":"Destrucción","nivel":88,"diario":"Sí","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":300,"zeonIntermedio":600,"zeonAvanzado":1000,"zeonArcano":2000,"mantBase":15,"mantIntermedio":30,"mantAvanzado":50,"mantArcano":100,"efectoBase":"-5 a su Gnosis, RM 120","efectoIntermedio":"-10 a su Gnosis, RM 160","efectoAvanzado":"-15 a su Gnosis, RM 200","efectoArcano":"-20 a su Gnosis, RM 260","efecto":"Arrebata la presencia divina a un ente. La criatura afectada reducirá su gnosis según el valor indicado. Mientras se mantenga la reducción, no podrá utilizar los poderes y capacidades que le otorgase su Gnosis original. No puede repetirse la RM mientras el conjuro siga activo.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vacío', '{"conjuro":"Vacío","via":"Destrucción","nivel":90,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":800,"mantBase":25,"mantIntermedio":40,"mantAvanzado":45,"mantArcano":55,"efectoBase":"5 metros de radio / 50 metros de succión / 120 de RM y RF","efectoIntermedio":"15 metros de radio / 500 metros de succión / 160 de RM y RF","efectoAvanzado":"25 metros de radio / 1 kilómetro de succión / 200 de RM y RF","efectoArcano":"50 metros de radio / 3 kilómetros de succión / 240 de RM y RF","efecto":"Esfera de vacío que absorbe materia física y espiritual. Se lanza en espacio abierto, y allí se queda. Tiene Fuerza 14, y quien fracase un control de características será atraído a un ritmo de 10 metros por punto. Cada turno en su interior se tira RM o perder puntos de Zeon igual al 2 veces nivel de fracaso, y RF o perderlos en Puntos de Vida. Alguien sin Zeon, pierde un punto permanente de Poder por cada 100 de Zeon. Si llega hasta cero, o muere, será engullido.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción mayor', '{"conjuro":"Destrucción mayor","via":"Destrucción","nivel":92,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":350,"zeonIntermedio":600,"zeonAvanzado":900,"zeonArcano":1500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Presencia máxima 100","efectoIntermedio":"Presencia máxima 160","efectoAvanzado":"Presencia máxima 200","efectoArcano":"Presencia máxima 240","efecto":"Otorga la capacidad de destruír parte del mundo material a gran escala, desde grandes construcciones a amplias zonas de terreno. Puede afectar automáticamente a cualquier número de cosas inorgánicas, siempre que no superen la presencia determinada por el grado de conjuro.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir almas', '{"conjuro":"Destruir almas","via":"Destrucción","nivel":96,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":13,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":19,"zeonBase":500,"zeonIntermedio":800,"zeonAvanzado":1500,"zeonArcano":2500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 100 / 5 kilómetros de radio","efectoIntermedio":"RM 140 /50 kilómetros de radio","efectoAvanzado":"RM 180 / 250 kilómetros de radio","efectoArcano":"RM 220 / 1.000 kilómetros de radio","efecto":"Arrasa la materia espiritual que se encuentre en el área determinada por el grado de conjuro, acabando con la existencia de todo aquel que no sea capaz de resistirse. Quien falle la RM morirá de inmediato.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Caos', '{"conjuro":"Caos","via":"Destrucción","nivel":98,"diario":"Sí","tipo":"Auto","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":700,"zeonIntermedio":1200,"zeonAvanzado":2000,"zeonArcano":5000,"mantBase":70,"mantIntermedio":80,"mantAvanzado":90,"mantArcano":100,"efectoBase":"100 kilómetros de radio / Afecta hasta Gnosis 10","efectoIntermedio":"1.000 kilómetros de radio / Afecta hasta Gnosis 20","efectoAvanzado":"10.000 kilómetros de radio / Afecta hasta Gnosis 30","efectoArcano":"Afecta a toda la creación / Afecta hasta Gnosis 40","efecto":"En el área, el mago puede alterar reglas existenciales.Puede designar qué aspecto de la existencia en concreto quiere alterar, o transformarla toda. El conjuro no le otorga control sobre lo que está cambiando, por lo que el resultado y devenir de los acontecimientos serán, caóticos. No existe resistencia posible, y afecta a todos aquellos seres cuyo Gnosis no sea muy elevado. La única  excepción son individuos cuyo Gnosis sea 20 puntos superior a su Natura.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descrear', '{"conjuro":"Descrear","via":"Destrucción","nivel":100,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":17,"intRIntermedio":18,"intRAvanzado":19,"intRArcano":20,"zeonBase":1000,"zeonIntermedio":2500,"zeonAvanzado":5000,"zeonArcano":10000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 140","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"El mago puede eliminar un parte de la existencia. El elemento descreado es borrado de la realidad. Nadie le recordará, y todos los sucesos en los que intervino se modificaran . Incluso volverán a la vida quienes hubieran perecido por su causa (salvo almas destruídas). Seres con Gnosis más de 40 o 20 por encima de su Natura son conscientes.Se realiza un control de RM para resistirse. Si afecta a varios, tira la mejor RM. No se pueden descrear elementos del pasado.","_seccion":"DESTRUCCION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear viento', '{"conjuro":"Crear viento","via":"Aire","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"20 Km/h / 25 metros de anchura","efectoIntermedio":"40 Km/h / 50 metros de anchura","efectoAvanzado":"80 Km/h / 75 metros de anchura","efectoArcano":"100 Km/h / 100 metros de anchura","efecto":"Levanta viento de gran velocidad. Para usar este conjuro, es necesario que el brujo se encuentre en el exterior, o en una zona en la que sea posible que sople el aire. La anchura de la corriente no deberá exceder lo determinado por el grado del conjuro, y su longitud será 10 veces su anchura","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mover', '{"conjuro":"Mover","via":"Aire","nivel":6,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Peso maximo 10 Kg","efectoIntermedio":"Peso maximo 50 Kg","efectoAvanzado":"Peso maximo 100 Kg","efectoArcano":"Peso maximo 250 Kg","efecto":"Este conjuro permite al brujo mover objetos inanimados a distancia, sin la necesidad de que exista contacto físico entre ellos, a una velocidad equivalente a un Tipo de vuelo 10. No afecta a objetos que estén directamente en contacto con seres vivos.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Reducir peso', '{"conjuro":"Reducir peso","via":"Aire","nivel":10,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":140,"zeonAvanzado":240,"zeonArcano":350,"mantBase":5,"mantIntermedio":15,"mantAvanzado":25,"mantArcano":35,"efectoBase":"-20 Kg","efectoIntermedio":"-150 Kg","efectoAvanzado":"-300  Kg","efectoArcano":"-500 Kg","efecto":"Reduce el peso de un cuerpo material orgánico o inorgánico hasta un mínimo de 1 kilogramo.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'No respirar', '{"conjuro":"No respirar","via":"Aire","nivel":12,"diario":"Si","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":110,"zeonArcano":150,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Presencia maxima 80","efectoIntermedio":"Presencia maxima 150","efectoAvanzado":"Presencia maxima 200","efectoArcano":"Presencia maxima 350","efecto":"El blanco de este conjuro deja de tener la necesidad de respirar. Puede afectar a tantos individuos como desee el lanzador, siempre que la suma de sus presencias no supere lo que determine el grado del conjuro.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Movimiento libre', '{"conjuro":"Movimiento libre","via":"Aire","nivel":16,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":110,"zeonArcano":150,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Presencia maxima 80","efectoIntermedio":"Presencia maxima 120","efectoAvanzado":"presencia maxima 160","efectoArcano":"Presencia maxima 240","efecto":"Otorga al blanco del conjuro la habilidad de moverse libremente por cualquier tipo de superficie, ignorando completamente las leyes de la gravedad. De este modo, un individuo podrá caminar por encima del agua o correr sin problemas por paredes y techos. Puede afectar a tantos blancos como desee el brujo, siempre que la suma de sus presencias no supere lo que determine el grado del conjuro.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Golpe de aire', '{"conjuro":"Golpe de aire","via":"Aire","nivel":20,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":140,"zeonArcano":200,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"5 metros de anchura / fuerza 6","efectoIntermedio":"20 metros de anchura / fuerza 9","efectoAvanzado":"30 metros de anchura / fuerza 12","efectoArcano":"50 metros de anchura / fuerza 14","efecto":"El mago lanza un golpe de viento, concentrándolo lo suficiente para impactar a un blanco lejano, o de una forma dispersa como para retener a un grupo de personas a distancia. Si se concentre sobre un solo blanco, aplica un bonificador de +2 a su Fuerza. Daño igual al doble del bono de la Fuerza del impacto en Contundente. El ataque sólo podrá ser percibido por personas capaces de ver magia o que superen un control de Advertir contra Absurdo.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Pantalla de aire', '{"conjuro":"Pantalla de aire","via":"Aire","nivel":22,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":14,"zeonBase":50,"zeonIntermedio":160,"zeonAvanzado":200,"zeonArcano":240,"mantBase":5,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"300 puntos de resistencia","efectoIntermedio":"1500 puntos de resistencia","efectoAvanzado":"2000 puntos de resistencia","efectoArcano":"3500 puntos de resistencia","efecto":"Forma una barrera de aire que protege frente a cualquier fuente de ataque, excepto aquellas basadas en electricidad o energía. Adicionalmente, los fuertes vientos que levanta perjudican a cualquier proyectil físico que sea disparado o lanzado contra el defensor, por lo que provocan un penalizador de -50 a la habilidad de ataque final del proyectil.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Transporte automático', '{"conjuro":"Transporte automático","via":"Aire","nivel":26,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"50 metros / presencia maxima 60","efectoIntermedio":"250 metros / presencia maxima 90","efectoAvanzado":"400 metros / presencia maxima 120","efectoArcano":"1 kilometro / presencia maxima 150","efecto":"El mago, u objetivo, es teletransportado a un lugar que vea o conozca. El conjuro puede pasar a través de objetos físicos, si no se encuentren basados en energía o sean de carácter sobrenatural. En caso de que el conjuro se use para teletransportar a alguien a una posición innatural (como por ejemplo, a 50 metros de altura en el aire), el blanco puede aplicar un +40 a su RM. Se puede afectar a varios, siempre que la suma de presencias no supere el grado del conjuro.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vuelo (Aire)', '{"conjuro":"Vuelo (Aire)","via":"Aire","nivel":30,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":240,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"tipo vuelo 4","efectoIntermedio":"tipo vuelo 8","efectoAvanzado":"tipo vuelo 12","efectoArcano":"tipo vuelo 15","efecto":"Otorga al afectado la capacidad de moverse con un Tipo de Vuelo místico determinado por el grado del conjuro.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Incremento de reacción', '{"conjuro":"Incremento de reacción","via":"Aire","nivel":32,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":15,"efectoBase":"+30 al turno","efectoIntermedio":"+60 al turno","efectoAvanzado":"+90 al turno","efectoArcano":"+120 al turno","efecto":"Aumenta la capacidad de reacción de un sujeto, otorgándole un bono a su turno. A partir de turno 200, este incremento se reduce a la mitad.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Electrificar', '{"conjuro":"Electrificar","via":"Aire","nivel":36,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":240,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"RF 100 / Presencia máxima 30 / 1 metro de longitud","efectoIntermedio":"RF 120 / Presencia máxima 40 / 3 metros de longitud","efectoAvanzado":"RF 140 / Presencia máxima 60 / 5 metros de longitud","efectoArcano":"RF 160 / Presencia máxima 80 / 10 metros de longitud","efecto":"Este conjuro electrifica un cuerpo físico, provocando potentes descargas a quien lo toque. Cualquier sujeto que se ponga en contacto con él, incluyendo el lanzador, deberá superar cada asalto una RF o perderá una cantidad de puntos de vida equivalente a la mitad del nivel de fracaso. El daño se considera producido por un ataque de electricidad. La máxima presencia del objeto así como su longitud máxima son determinadas por el grado del conjuro","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Tajo de aire', '{"conjuro":"Tajo de aire","via":"Aire","nivel":40,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":150,"zeonAvanzado":240,"zeonArcano":350,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"linea de 3 metros de longitud","efectoIntermedio":"linea de 12 metros de lingitud","efectoAvanzado":"linea de 25 metros de longitud","efectoArcano":"linea de 50 metros de longitud","efecto":"Produce una fuerte ráfaga de aire, capaz de cortar lo que toque como si se tratase de una afilada espada. El tajo afecta en una línea en la cual no será posible seleccionar blanco. Tiene un daño base de 80 y ataca en Filo, reduciendo en -2 la TA al defensor","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Velocidad', '{"conjuro":"Velocidad","via":"Aire","nivel":42,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"presencia maxima 50","efectoIntermedio":"presencia maxima 80","efectoAvanzado":"presencia maxima 120","efectoArcano":"presencia maxima 160","efecto":"Incrementa de un modo increíble la velocidad de desplazamiento de los individuos afectados. A efectos de juego, dobla la cantidad de metros por asalto que un personaje puede moverse gracias a su Tipo de movimiento. Puede afectar a tantos blancos como desee el brujo, siempre que la suma de sus presencias no supere lo que determine el grado del conjuro","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Rayo', '{"conjuro":"Rayo","via":"Aire","nivel":46,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":280,"zeonArcano":400,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"1 rebote o +10 al daño","efectoIntermedio":"10 rebotes o +40 al daño","efectoAvanzado":"15 rebotes o +80 al daño","efectoArcano":"25 rebotes o +150 al daño","efecto":"Relámpago con daño base 100. Antes de impactar, el mago elige si concentra todo el rayo en una sola descarga, o tras alcanzar su blanco, la electricidad rebota hacia el cuerpo más próximo realizando un nuevo ataque de idénticas características al primero. El hechicero no podrá elegir sobre quién se dirigirá el rayo después del ataque original, aunque nunca podrá volverse contra él. Un mismo blanco no puede ser afectado dos veces por el mismo rayo.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Remolino', '{"conjuro":"Remolino","via":"Aire","nivel":50,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":30,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"3 metros de radio","efectoIntermedio":"6 metros de radio","efectoAvanzado":"12 metros de radio","efectoArcano":"25 metros de radio","efecto":"Se crea un remolino. Quien se encuentre en el área recibe un ataque con habilidad de Absurdo y daño base de 40 CON. Los afectados deberán superar un control enfrentado de Fuerza o Agilidad contra el equivalente a Fuerza 12, o serán levantados en el aire. Los levantados sufren penalizador de –60 a toda acción. Todos en el area son afectados. El mago podrá desplazar el hechizo con velocidad 8. No tiene efectos sobre cuerpos inmateriales.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Forma etérea', '{"conjuro":"Forma etérea","via":"Aire","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Las habilidades descritas","efectoIntermedio":"Se puede mover por el aire a velocidadigual a Tipo de movimiento natural","efectoAvanzado":"Idem arriba, Si ve magia superar Advertir a 140 o Buscar a 80 para verle","efectoArcano":"Idem arriba, ataques de FIL o PEN basados en ENE le hacen mitad de daño","efecto":"El cuerpo objetivo se transformará en aire, volviéndose intangible ante la materia y ataque no basados en energía. En este estado será invisible ante cualquier individuo incapaz de ver magia o que no supere un control de Advertir contra Casi Imposible, o un Buscar contra Muy Difícil. Aunque no puede traspasar materia física, un cuerpo etéreo se introduce por cualquier rendija o espacio por el que pueda soplar el aire","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control del aire', '{"conjuro":"Control del aire","via":"Aire","nivel":56,"diario":"No","tipo":"Efecto, Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":150,"zeonAvanzado":240,"zeonArcano":350,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":35,"efectoBase":"radio de 50 metros / RM 120","efectoIntermedio":"radio de 300 metros / RM 140","efectoAvanzado":"radio de 500 metros / RM 180","efectoArcano":"radio de 1 kilometro / RM 220","efecto":"Otorga al hechicero el control del aire, así como el de cualquier sustancia gaseosa que se encuentre a su alrededor. El mago será capaz de manejar a su antojo las corrientes de viento y los elementos gaseosos para usarlos como desee. Podría, por ejemplo, vaciar de aire una zona o cambiar el curso de un tornado. Si se lanza sobre un ser basado naturalmente en aire, el mago podrá controlarlo si la criatura no supera una RM.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control de la electricidad', '{"conjuro":"Control de la electricidad","via":"Aire","nivel":60,"diario":"No","tipo":"Efecto, Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":150,"zeonAvanzado":240,"zeonArcano":350,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":35,"efectoBase":"RM 120 / 5 intensidades","efectoIntermedio":"RM 160 / 15 intensidades","efectoAvanzado":"RM 180 / 25 intensidades","efectoArcano":"RM 220 / 40 intensidades","efecto":"Permite controlar la forma y dirección de una fuente eléctrica. Si se trata de un ser basado naturalmente en electricidad, el mago podrá controlarlo si este no supera una RM","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Movimiento defensivo', '{"conjuro":"Movimiento defensivo","via":"Aire","nivel":62,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"3 esquivas / tipo de movimiento 8","efectoIntermedio":"9 esquivas / tipo de movimiento 12","efectoAvanzado":"15 esquivas / tipo de movimiento 16","efectoArcano":"sin limite de esquivas / tipo de movimiento 18","efecto":"Ell mago se mueve o transporta fuera del alcance de un ataque. Puede usar Proyección Mágica del mago como si se tratase de su esquiva. Podrá apartarse de un máximo de ataques por asalto, tras los cuales deberá encontrar otro método de defensa hasta el siguiente turno. El conjuro esquiva como si se dispusiera de una velocidad equivalente a un Tipo de movimiento determinado por el grado del conjuro a la hora de los penalizadores contra ataques en área.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Teletransportación', '{"conjuro":"Teletransportación","via":"Aire","nivel":66,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":180,"zeonIntermedio":300,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"presencia maxima 80 / 10 kilometros","efectoIntermedio":"presencia maxima 150 / 10000 kilometros","efectoAvanzado":"presencia maxima 240 / 100000 kilometros","efectoArcano":"presencia maxima 350 / cualquier distancia","efecto":"El objetivo es transportado a distancia. Se puede pasar a través de cuerpos físicos si no se encuentran basados en energía. Puede afectar a tantos blancos siempre que la suma de sus presencias no supere lo que determine el grado del conjuro. El objetivo tiene que conocer o ver el lugar al que va a ser transportado si quiere poder hacerlo con precisión. En caso contrario, sólo se transportará a un lugar aproximado hacia la dirección que desee","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inmaterialidad', '{"conjuro":"Inmaterialidad","via":"Aire","nivel":70,"diario":"Si","tipo":"Efecto, Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 100 / presencia maxima 80","efectoIntermedio":"RM 140 / presencia maxima 120","efectoAvanzado":"RM 160 / presencia maxima 160","efectoArcano":"RM 200 / presencia maxima 200","efecto":"El objetivo se vuelve inmaterial, haciéndose intangible ante todo lo no basado en energía. Así no podrá tocar ni ser tocado. Si el mago lanza el conjuro sobre un sujeto o cuerpo que desea resistirse a sus efectos, este deberá superar una RM para conseguirlo. Si fracasa el control y se torna inmaterial, tendrá derecho a una nueva Resistencia cada día. La máxima presencia afectable será de 80 puntos","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Huracán', '{"conjuro":"Huracán","via":"Aire","nivel":72,"diario":"No","tipo":"Efecto, Automático","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":450,"zeonArcano":600,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"500 metros de radio","efectoIntermedio":"1 kilometros de radio","efectoAvanzado":"2 kilometros de radio","efectoArcano":"5 kilometros de radio / el control de fuerza es contra 14","efecto":"Crea un huracan. Afectados superar un control contra Fuerza 12, o ser arrastrado por el viento. Construcciones con barrera de daño menos de 60 se destruyen, hasta 120, 10 puntos de daño por turno, con más de 120 no afectadas. Los cuerpos arrastrados quedarán en el aire y al caer no más de 100 metros. Quien pase el control, no tendrá que volver a tirar mientras no se mueva, pero deberá tirar por turno que se mueva por encima de movimiento pasivo.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aire sólido', '{"conjuro":"Aire sólido","via":"Aire","nivel":76,"diario":"No","tipo":"Efecto, Ataque","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":260,"zeonArcano":350,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":25,"efectoBase":"25 metros de radio","efectoIntermedio":"150 metros de radio","efectoAvanzado":"300 metros de radio","efectoArcano":"500 metros de radio / si se usa para apresar, tiene fuerza 16","efecto":"El brujo puede elegir qué forma darle y dónde ubicarla. El aire sólido sólo puede ser dañado con armas capaces de afectar energía, y cada 5 metros de material resiste 150 puntos de daño. No puede verse salvo con control de Advertir 320, o Buscar a 240. Se puede utilizarse para rodear a personas e impedirles moverse. En este caso es posible realizar un ataque con reglas de Presa, si penalizador para el mago. El aire posee Fuerza 14, afectando a todos en el area.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control del clima', '{"conjuro":"Control del clima","via":"Aire","nivel":80,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":300,"zeonAvanzado":380,"zeonArcano":500,"mantBase":50,"mantIntermedio":60,"mantAvanzado":80,"mantArcano":100,"efectoBase":"5 kilometros","efectoIntermedio":"25 kilometros","efectoAvanzado":"100 kilometros","efectoArcano":"1000 kilometros","efecto":"El hechicero obtiene un completo control sobre el clima en un radio de acción determinado por el grado del conjuro. Podrá modificar cualquier elemento meteorológico a su antojo, creando la situación climática que desee de manera gradual","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear silfo', '{"conjuro":"Crear silfo","via":"Aire","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":50,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":140,"efectoBase":"Nivel 1.","efectoIntermedio":"Nivel 3","efectoAvanzado":"Nivel 6.","efectoArcano":"Nivel 10.","efecto":"Crea una criatura de aire con apariencia de vida bajo el control absoluto del hechicero. El ente será desarrollado como un Ser Entre Mundos, usando los poderes y limitaciones de los elementales de aire del Capítulo 26. Para calcular su nivel máximo, se emplean las mismas reglas que en el conjuro Crear Ser de la vía de Creación","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Telequinesis superior', '{"conjuro":"Telequinesis superior","via":"Aire","nivel":86,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":160,"zeonIntermedio":280,"zeonAvanzado":400,"zeonArcano":550,"mantBase":35,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"RM 100 / 100 toneladas","efectoIntermedio":"RM 120 / 10000 toneladas","efectoAvanzado":"RM 140 / 250000 toneladas","efectoArcano":"RM 160 / 500000 toneladas","efecto":"Este conjuro permite al brujo mover a distancia cualquier cuerpo material, orgánico o inorgánico, sin la necesidad de que exista contacto físico con ellos y dotándoles de una velocidad equivalente a un Tipo de vuelo 10. Los seres vivos o criaturas de presencia sobrenatural excepcional podrán resistirse si superan una RM.","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ubicar magia', '{"conjuro":"Ubicar magia","via":"Aire","nivel":90,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":180,"zeonIntermedio":270,"zeonAvanzado":360,"zeonArcano":450,"mantBase":20,"mantIntermedio":30,"mantAvanzado":40,"mantArcano":45,"efectoBase":"conjuros de hasta 100 puntos de zeon","efectoIntermedio":"conjuros de hasta 200 puntos de zeon","efectoAvanzado":"conjuros de hasta 300 puntos de zeon","efectoArcano":"conjuros de hasta 400 puntos de zeon","efecto":"Mueve fuentes mágicas de un conjuro activo de un sitio a otro. Puede trasladar cualquier conjuro mantenido. Distancia máxima determinadas por reglas de Proyección Mágica. Si lo que se traslada es un conjuro Anímico de un sujeto a otro, se tratará a todos los efectos del mismo modo que si acabase de ser lanzado por el hechicero, permitiendo al nuevo blanco defenderse de él y realizar un control de Resistencia con normalidad","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Magia pasiva', '{"conjuro":"Magia pasiva","via":"Aire","nivel":92,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":300,"zeonIntermedio":400,"zeonAvanzado":550,"zeonArcano":800,"mantBase":30,"mantIntermedio":40,"mantAvanzado":55,"mantArcano":80,"efectoBase":"Afecta a conjuros de grado base","efectoIntermedio":"Afecta a conjuros Automáticos de Grado Intermedio","efectoAvanzado":"Afecta a conjuros Automáticos de Grado Avanzado","efectoArcano":"Afecta a conjuros Automáticos de Grado Arcano","efecto":"Este hechizo envuelve la esencia de su lanzador, haciendo que la magia fluya en él de un modo instintivo y manifestando automáticamente sus designios. Así pues, la magia y él responden como un solo ser ante cualquier acontecimiento. Mientras se mantenga, cualquier hechizo que ejecute el personaje se considerará una acción pasiva, incluidos los de Ataque y los Anímicos","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Señor del aire', '{"conjuro":"Señor del aire","via":"Aire","nivel":96,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":300,"zeonIntermedio":450,"zeonAvanzado":600,"zeonArcano":1000,"mantBase":30,"mantIntermedio":45,"mantAvanzado":60,"mantArcano":100,"efectoBase":"100 kilometros de radio / 140 RM","efectoIntermedio":"1000 kilometros de radio / 180 RM","efectoAvanzado":"10000 kilometros de radio / 200 RM","efectoArcano":"100000 kilometros de radio / 240 RM","efecto":"El mago controla cualquier aire y electricidad, sin importar las intensidades. Este dominio le permite también modificar el clima, como crear vendavales, tormentas o ventiscas de cualquier magnitud. Toda criatura basada en aire que se encuentre dentro del área, deberá superar una RM o será controlada. Si la pasan, ya no necesitan volver a realizar el control. Los afectados tienen derecho a una nueva tirada únicamente si alteran su Resistencia base","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Un lugar en el mundo', '{"conjuro":"Un lugar en el mundo","via":"Aire","nivel":100,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":450,"zeonIntermedio":800,"zeonAvanzado":1200,"zeonArcano":1600,"mantBase":45,"mantIntermedio":80,"mantAvanzado":120,"mantArcano":200,"efectoBase":"50 kilometros de radio / RM 140","efectoIntermedio":"250 kilometros de radio / RM 180","efectoAvanzado":"500 kilometros de radio / RM 240","efectoArcano":"1000 kilometros de radio / RM 280","efecto":"No es capaz de cambiar la esencia de las cosas ni su forma, pero puede moverlas por el mundo y situarlas en cualquier lugar. Es posible mover tantas cosas como se desee por turno, sin importar su número o condición. La única manera de resistirse a sus efectos será superar una RM en cada ocasión en la que se quiera evitar ser trasladado. El radio afecta automáticamente a cualquier ser u objeto que se encuentre en su interior","_seccion":"AIRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Manantial', '{"conjuro":"Manantial","via":"Agua","nivel":2,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":7,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":180,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"100 metros.","efectoIntermedio":"250 metros.","efectoAvanzado":"500 metros.","efectoArcano":"1 kilómetro.","efecto":"Atrae cualquier corriente o arroyo subterráneo que haya en las proximidades, haciendo brotar un manantial en el lugar designado por el brujo. El conjuro influye en los líquidos naturales que se encuentren a menos distancia del lanzador de lo que determina el grado del conjuro, aunque no es capaz de atravesar barreras de energía.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear frío', '{"conjuro":"Crear frío","via":"Agua","nivel":6,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":7,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":50,"zeonAvanzado":90,"zeonArcano":140,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":15,"efectoBase":"1 Intensidad.","efectoIntermedio":"3 Intensidades.","efectoAvanzado":"5 Intensidades.","efectoArcano":"8 Intensidades.","efecto":"Crea intensidades de frío o hielo. Mientras se mantenga el conjuro, la temperatura se conservará.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Capacidad acuática', '{"conjuro":"Capacidad acuática","via":"Agua","nivel":10,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":140,"mantBase":10,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"Presencia máxima 50.","efectoIntermedio":"Presencia máxima 100.","efectoAvanzado":"Presencia máxima 200.","efectoArcano":"Presencia máxima 350.","efecto":"Confiere la capacidad de respirar y moverse libremente por ambientes acuáticos. El personaje sobre el que se lance podrá trasladarse con su máximo Tipo de movimiento en dichos medios, respirando líquidos y resistiendo cualquier clase de presión. Puede afectar a tantos blancos como desee el brujo, siempre que la suma de sus presencias no supere lo que determine el grado del conjuro.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inmunidad al frío', '{"conjuro":"Inmunidad al frío","via":"Agua","nivel":12,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":13,"zeonBase":50,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"5 intensidades de frío.","efectoIntermedio":"12 intensidades de frío.","efectoAvanzado":"20 intensidades de frío.","efectoArcano":"30 intensidades de frío.","efecto":"Este conjuro permite al hechicero, o a las personas que designe, ser inmune a intensidades de frío. En el caso de que se reciba un ataque basado en dicho elemento, cada intensidad a la que es inmune disminuye 5 puntos el daño base del ataque y otorga un +5 a las Resistencias contra sus efectos.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Burbuja protectora', '{"conjuro":"Burbuja protectora","via":"Agua","nivel":16,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":40,"zeonIntermedio":90,"zeonAvanzado":140,"zeonArcano":220,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Hasta Daño base 40.","efectoIntermedio":"Hasta Daño base 90.","efectoAvanzado":"Hasta Daño base 120.","efectoArcano":"Hasta Daño base 160.","efecto":"Levanta una burbuja de energía mágica que funciona a modo de escudo contra cualquier clase de ataque. La barrera no sufre perjuicio alguno si detiene ataques con un daño base igual o inferior a lo que indique el grado del conjuro, pero los impactos con un daño base superior la rompen automáticamente.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Impacto de agua', '{"conjuro":"Impacto de agua","via":"Agua","nivel":20,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":140,"zeonArcano":200,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 40 / Fuerza 8.","efectoIntermedio":"Daño 60 / Fuerza 10.","efectoAvanzado":"Daño 80 / Fuerza 12.","efectoArcano":"Daño 100 / Fuerza 14.","efecto":"El brujo genera una descarga ofensiva que, aunque ataca en Contundente, es capaz de dañar energía. Si causa daño o es detenido, produce un impacto sobre el blanco del sortilegio con una fuerza determinada por el grado del conjuro.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control sobre los líquidos', '{"conjuro":"Control sobre los líquidos","via":"Agua","nivel":22,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":220,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM o RF 100 / 5 litros.","efectoIntermedio":"RM o RF 120 / 50 litros.","efectoAvanzado":"RM o RF 140 / 500 litros.","efectoArcano":"RM o RF 180 / 5.000 litros.","efecto":"El mago puede alterar forma, naturaleza, movimiento y solidez de una masa de liquido. Contra un elemental de agua, lo domina si no pasa RM. Es capaz de manejar sangre de los vivos, afectados aplican un bono de +40 a su RM o RF (se puede tirar cada 5 turnos). Al manejar sangre produce por asalto negativo a acción y un daño equivalente a la mitad del nivel de fracaso. Los elementales, control al día o si reciben una orden completamente opuesta a su naturaleza.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Congelar las emociones', '{"conjuro":"Congelar las emociones","via":"Agua","nivel":26,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Afecta a estados naturales.","efectoIntermedio":"Como en grado base, pero el afectado deja de sentir también dolor.","efectoAvanzado":"Como en Intermedio, pero también afecta a todos los estados sobrenaturales.","efectoArcano":"Como en Avanzado, pero el mago puede elegir qué sentimientos congelar.","efecto":"Este hechizo hiela los sentimientos de una persona, otorgándole inmunidad psicológica contra todos los estados emocionales.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Controlar el frío', '{"conjuro":"Controlar el frío","via":"Agua","nivel":30,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":180,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 100 / 5 intensidades.","efectoIntermedio":"RM 120 / 8 intensidades.","efectoAvanzado":"RM 140 / 12 intensidades.","efectoArcano":"RM 180 / 15 intensidades.","efecto":"Permite controlar una cantidad de frío o hielo. El dominio capacita al brujo para alterar su potencia (hasta un la mitad de su valor arriba o abajo, en caso de que se mida por intensidades) o cambiar su forma. Si lo usa contra un ser basado naturalmente en frío, el mago podrá controlarlo si este no supera una RM. La criatura tendrá derecho a un nuevo control al día, o si recibe una orden completamente opuesta a su naturaleza.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Congelar', '{"conjuro":"Congelar","via":"Agua","nivel":32,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":220,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120 / 5 metros de radio.","efectoIntermedio":"RM 140/ 10 metros de radio.","efectoAvanzado":"RM 160 / 25 metros de radio.","efectoArcano":"RM 180 / 50 metros de radio.","efecto":"Provoca un intenso frío sobre una o varias personas, congelando sus cuerpos al tiempo que los encierra en prisiones de hielo. Si se concentra sobre un único antagonista, aumenta el valor de la Resistencia 20 puntos. Dependiendo del nivel de fracaso del control, las consecuencias del conjuro son distintas. Si la diferencia es menor de 20, el efecto es parálisis menor; si es menor de 80, de parálisis normal, y si es superior, parálisis completa.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Pantalla de hielo', '{"conjuro":"Pantalla de hielo","via":"Agua","nivel":36,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"400 puntos de Resistencia.","efectoIntermedio":"1.500 puntos de Resistencia.","efectoAvanzado":"2.500 puntos de Resistencia.","efectoArcano":"4.000 puntos de Resistencia.","efecto":"Forma una barrera de hielo que protege frente a cualquier fuente de ataque. En el caso de que el escudo detenga con éxito una descarga de energía basada en luz u oscuridad, puede devolver el ataque hacia su lanzador con la misma habilidad con la que este lo proyectó.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear líquidos', '{"conjuro":"Crear líquidos","via":"Agua","nivel":40,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":16,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":240,"zeonArcano":350,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"50 litros de agua.","efectoIntermedio":"500 litros de agua.","efectoAvanzado":"5.000 litros de agua.","efectoArcano":"50.000 litros de agua.","efecto":"Crea agua o un cuerpo líquido similar. En el caso de que el compuesto tenga una presencia superior al agua, el DJ tiene la capacidad de reducir como considere necesario su cantidad. Este conjuro no permite elaborar líquidos con capacidades místicas.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ataque de hielo', '{"conjuro":"Ataque de hielo","via":"Agua","nivel":42,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 100.","efectoIntermedio":"Daño 150.","efectoAvanzado":"Daño 200.","efectoArcano":"Daño 250.","efecto":"Produce una potente descarga de hielo capaz de dañar energía. El lanzador puede elegir libremente entre atacar en Frío o en Penetrantes.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cristalización', '{"conjuro":"Cristalización","via":"Agua","nivel":46,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":150,"zeonArcano":200,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM o RF 140.","efectoIntermedio":"RM o RF 160.","efectoAvanzado":"RM o RF 180.","efectoArcano":"RM o RF 200.","efecto":"Este hechizo cristaliza un cuerpo, tornándolo frágil y quebradizo. El individuo afectado deberá superar un control de RM o RF o todo su cuerpo se congelará, quedando sometido de inmediato a paralización menor. Adicionalmente, cualquier daño que reciba se considera automáticamente crítico, sin importar cuál sea su valor. Los seres con acumulación no reciben un crítico directo, pero todo su cuerpo se torna un punto vulnerable.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control reflejo', '{"conjuro":"Control reflejo","via":"Agua","nivel":50,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":350,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 80.","efectoIntermedio":"RM 130.","efectoAvanzado":"RM 160.","efectoArcano":"RM 200.","efecto":"El hechicero ata el cuerpo de un individuo al suyo propio, obligándole a imitar todos los movimientos que haga. En cierta manera, el personaje afectado se comporta como un espejo, que copia al instante a su controlador. Para resistir el conjuro es necesario superar un control de RM. El hechizo no permite repetir la tirada, salvo si el afectado se da cuenta de que va a ejecutar una acción que jamás realizaría.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cuerpo líquido', '{"conjuro":"Cuerpo líquido","via":"Agua","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Las habilidades descritas.","efectoIntermedio":"Podrá moverse por el agua a velocidad igual a su Tipo de movimiento natural.","efectoAvanzado":"Como el Intermedio, pero la calidad de las armas es +10.","efectoArcano":"Idem arriba, pero ataques FIL o PEN basados en energía hacen mitad de daño","efecto":"El objetivo cambia a sustancia líquida, pudiendo alterar su forma. Quien lo vea, superar un control de Advertir a 140 para percatarse que es líquido. Puede convertir sus extremidades en armas físicas, de calidad +5. Entrar en cualquier lugar en el que sea capaz de filtrarse. Es invulnerable a ataques PEN y FIL que no dañen energía, CON sólo la mitad de efecto (salvo si dañan energía). Se torna vulnerable a los efectos de frío paralizantes, aplicando un  -20 a Resistencias.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Reflejar estados', '{"conjuro":"Reflejar estados","via":"Agua","nivel":56,"diario":"No","tipo":"Auto","accion":"Pasiva","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":320,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120.","efectoIntermedio":"RM 150.","efectoAvanzado":"RM 180.","efectoArcano":"RM 220.","efecto":"Crea un espejo místico, capaz de reflejar estado sobrenatural del que él o un individuo cercano sea blanco. El efecto se refleja automáticamente sobre aquel que lo haya producido, quien deberá superar una RM para evitar su propio poder. Este hechizo no tiene mantenimiento, pero el estado reflejado se mantendrá mientras perdure en el sujeto sobre el que fue lanzado originariamente. Cada efecto sólo puede tratar de reflejarse una vez.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Tormenta de hielo', '{"conjuro":"Tormenta de hielo","via":"Agua","nivel":60,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":320,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"50 metros de radio.","efectoIntermedio":"150 metros de radio.","efectoAvanzado":"500 metros de radio / La RF se incrementa hasta 160.","efectoArcano":"1 kilómetro de radio / La RF se incrementa hasta 180.","efecto":"Crea una tormenta helada que congelará todo. Quien se halle en ella, debe de superar cada cinco asaltos un control de RF contra 140, o sufrir 10 puntos de daño basado en frío y un -5 acumulativo a toda acción. Las habilidades perceptivas aumentan dos niveles su dificultad. La tormenta tendrá un radio dentro del cual no es posible designar blancos. La condición para ser afectado es estar en el área. El conjuro permanece siempre en el mismo lugar.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control de las mareas', '{"conjuro":"Control de las mareas","via":"Agua","nivel":62,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":300,"zeonAvanzado":450,"zeonArcano":600,"mantBase":15,"mantIntermedio":30,"mantAvanzado":45,"mantArcano":60,"efectoBase":"500 metros de radio.","efectoIntermedio":"1 kilómetro de radio.","efectoAvanzado":"3 kilómetros de radio.","efectoArcano":"5 kilómetros de radio.","efecto":"Otorga la capacidad de controlar limitadamente las corrientes de agua de mares y ríos, permitiendo al hechicero modificar su curso y potencia. El poder de este hechizo es tal, que el mago puede incluso producir pequeños maremotos o invertir el sentido de un río. Afecta en un radio alrededor del hechicero.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Prisión de agua', '{"conjuro":"Prisión de agua","via":"Agua","nivel":66,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":280,"zeonArcano":350,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"10 metros cúbicos.","efectoIntermedio":"50 metros cúbicos.","efectoAvanzado":"100 metros cúbicos.","efectoArcano":"150 metros cúbicos / El control es contra Fuerza 15.","efecto":"Crea masa de agua que engulle a todos los individuos que encuentre. El ser atrapado, se moverá buceando, comenzará también a ahogarse. La prisión no permite que nadie escape de ella, produciendo corrientes que empujan hacia su centro. Si se quiere huir, superar un control enfrentado contra Fuerza 14, aunque obtiene un +1 a su por cada nivel de Nadar que supere por encima de Fácil. La condición para ser afectado será encontrarse en el interior de la zona.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Glacial', '{"conjuro":"Glacial","via":"Agua","nivel":70,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":40,"mantIntermedio":60,"mantAvanzado":80,"mantArcano":100,"efectoBase":"1 Kilómetro de radio.","efectoIntermedio":"3 Kilómetros de radio.","efectoAvanzado":"5 Kilómetros de radio.","efectoArcano":"10 Kilómetros de radio.","efecto":"Como su nombre indica, crea una inmensa zona glacial alrededor del hechicero, sin importar en absoluto cuáles sean las condiciones climáticas del ambiente en el que se encuentra. Todo el entorno se cubrirá de inmediato de hielo y nieve, reduciendo la temperatura ambiental a varios grados bajo cero. Mientras el conjuro se mantenga, el frío no será afectado por los fenómenos atmosféricos naturales.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Tsunami', '{"conjuro":"Tsunami","via":"Agua","nivel":72,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":450,"zeonArcano":550,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"1 kilómetro de longitud.","efectoIntermedio":"10 kilómetros de longitud.","efectoAvanzado":"20 kilómetros de longitud.","efectoArcano":"30 kilómetros de longitud / Arrasa construcciones de hasta barrera\nde daño 90.","efecto":"Levanta un devastador tsunami capaz de arrasar completamente la costa. Las construcciones con una barrera de daño inferior a 80 serán destruidas de inmediato, mientras que el resto sufrirá enormes daños. Naturalmente, cualquier individuo dentro de la zona de impacto padecerá las consecuencias lógicas del fenómeno.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Reflejo del alma', '{"conjuro":"Reflejo del alma","via":"Agua","nivel":76,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":280,"zeonAvanzado":320,"zeonArcano":400,"mantBase":20,"mantIntermedio":30,"mantAvanzado":35,"mantArcano":40,"efectoBase":"RM 140 / Copia entidades de hasta Nivel 3.","efectoIntermedio":"RM 160 / Copia entidades de hasta Nivel 5.","efectoAvanzado":"RM 180 / Copia entidades de hasta Nivel 8 / Imita poderes de hasta Gnosis 25.","efectoArcano":"RM 200 / Copia entidades de hasta Nivel 12 / Imita poderes de hasta Gnosis 30.","efecto":"Manifiesta un reflejo de un ser. Es idéntica al objetivo, salvo que es espiritual, visible e inmune a cualquier ataque no basado en energía. Si la criatura tiene poderes que dependen de Gnosis mayor a 20, no son copiadas. El reflejo obedece órdenes del mago, pero sólo puede manifestarse mientras este el sujeto a partir del cual se ha formado. Solo puede usarse sobre una persona a la vez. Si el sujeto se resiste, superar RM. El mago no puede copiarse.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Enlentecer el tiempo', '{"conjuro":"Enlentecer el tiempo","via":"Agua","nivel":80,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":320,"zeonAvanzado":450,"zeonArcano":600,"mantBase":20,"mantIntermedio":25,"mantAvanzado":30,"mantArcano":35,"efectoBase":"100 metros de radio / RM 120 / El tiempo se reduce una décima parte.","efectoIntermedio":"200 metros de radio / RM 140 / El tiempo se reduce una centésima parte.","efectoAvanzado":"500 metros de radio / RM 160 / El tiempo se reduce una milésima parte.","efectoArcano":"1 kilómetro de radio / RM 180 / El tiempo se reduce una millonésima parte.","efecto":"Se influye en espacio tiempo de una parte de la realidad, aminorando su flujo, para todo el mundo, incluyendo al propio lanzador. La zona afectada por el hechizo se separa de la realidad, haciendo que cada instante dure más en el exterior. El área de acción se extiende a una velocidad de 10 metros por turno a partir del momento lanzado. Si alguien penetra en ella, se ve influenciado. Se puede evitar superando RM, pero si posee Gnosis más de 30.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear ondina', '{"conjuro":"Crear ondina","via":"Agua","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":50,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":140,"efectoBase":"Nivel 1.","efectoIntermedio":"Nivel 3.","efectoAvanzado":"Nivel 6.","efectoArcano":"Nivel 10.","efecto":"Crea una entidad de agua con apariencia de vida bajo el control absoluto del hechicero. El ente será desarrollado como un Ser Entre Mundos, usando los poderes y limitaciones de los elementales de agua del Capítulo 26. Para calcular su nivel máximo, se emplean las mismas reglas que en el conjuro Crear Ser de la vía de Creación.","_seccion":"AGUA"}'::jsonb)
insert into public.catalogo (paquete_id, coleccion, clave, datos) values
  ('core-exxet', 'conjuros', 'Congelar la magia', '{"conjuro":"Congelar la magia","via":"Agua","nivel":86,"diario":"Si","tipo":"Efecto","accion":"Pasiva","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":250,"zeonIntermedio":400,"zeonAvanzado":550,"zeonArcano":800,"mantBase":50,"mantIntermedio":75,"mantAvanzado":90,"mantArcano":100,"efectoBase":"Valor zeónico máximo 150.","efectoIntermedio":"Valor zeónico máximo 250.","efectoAvanzado":"Valor zeónico máximo 300.","efectoArcano":"Valor zeónico máximo 400.","efecto":"Se congela la magia, paralizando un conjuro y anulando sus efectos. Mientras permanezca helado no desaparece, pero se queda estancado sin producir consecuencias, y tampoco requiere que se pague mantenimiento. Afecta a hechizos controlados por el mago como los lanzados por otros. Cuando congelar la magia deja de mantenerse, el conjuro estancado vuelve a ser efectivo. Ya que es pasivo, puede congelar hechizos que se usan en el mismo turno.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'En el interior del espejo', '{"conjuro":"En el interior del espejo","via":"Agua","nivel":90,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":17,"zeonBase":300,"zeonIntermedio":480,"zeonAvanzado":600,"zeonArcano":800,"mantBase":30,"mantIntermedio":50,"mantAvanzado":60,"mantArcano":70,"efectoBase":"500 metros de radio máximo.","efectoIntermedio":"2 kilómetros de radio máximo.","efectoAvanzado":"5 kilómetros de radio máximo.","efectoArcano":"10 kilómetros de radio máximo / Se pueden imitar seres de hasta presencia 30.","efecto":"Se crea el reflejo de un territorio, siendo una realidad paralela a imagen y semejanza del mundo real. No podrán ser imitados seres vivos con una presencia superior a 20 y los lugares con características excepcionales. Al lanzarse, el mago debe crear distintas puertas que conecten el mundo real con su obra, que podrán ubicarse y tener la forma que desee. No hay un número máximo de aperturas, aunque por lo menos está obligado a crear una.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Señor de los hielos', '{"conjuro":"Señor de los hielos","via":"Agua","nivel":92,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":300,"zeonIntermedio":450,"zeonAvanzado":600,"zeonArcano":1000,"mantBase":30,"mantIntermedio":45,"mantAvanzado":60,"mantArcano":100,"efectoBase":"100 kilómetros de radio / 140 RM.","efectoIntermedio":"1.000 kilómetros de radio / 180 RM.","efectoAvanzado":"10.000 kilómetros de radio / 200 RM.","efectoArcano":"100.000 kilómetros de radio / 240 RM.","efecto":"Se controla cualquier frío o hielo sin importar la intensidades. Este dominio le permite disminuir la temperatura ambiental dentro de su área de acción, y cristalizar hielo allí donde desee. Cualquier criatura basada en frío que se encuentre en el interior, deberá superar una RM o será dominada de inmediato. Si la pasan, ya no necesitan volver a realizar el control. Los afectados tienen derecho a una nueva tirada únicamente si alteran sus Resistencias.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Señor de las aguas', '{"conjuro":"Señor de las aguas","via":"Agua","nivel":96,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":300,"zeonIntermedio":450,"zeonAvanzado":600,"zeonArcano":1000,"mantBase":30,"mantIntermedio":45,"mantAvanzado":60,"mantArcano":100,"efectoBase":"100 kilómetros de radio / 140 RM.","efectoIntermedio":"1.000 kilómetros de radio / 180 RM.","efectoAvanzado":"10.000 kilómetros de radio / 200 RM.","efectoArcano":"Afecta cualquier sustancia líquida existente / 240 RM.","efecto":"Otorga el control de las sustancias líquidas en un radio de 100 km. Puede alterar libremente los océanos, ríos y lagos de cualquier magnitud, moldeándolos a su antojo. Toda criatura basada en agua que se encuentre dentro del área del conjuro, deberá superar una RM o será controlada por el mago. Si la pasan, ya no necesitan volver a realizar el control. Los afectados tienen derecho a una nueva tirada únicamente si alteran su Resistencia base.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Un mundo perfecto', '{"conjuro":"Un mundo perfecto","via":"Agua","nivel":100,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":12,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":20,"zeonBase":450,"zeonIntermedio":800,"zeonAvanzado":1200,"zeonArcano":1600,"mantBase":90,"mantIntermedio":115,"mantAvanzado":130,"mantArcano":145,"efectoBase":"RM 120.","efectoIntermedio":"RM 180.","efectoAvanzado":"RM 220.","efectoArcano":"RM 260.","efecto":"Este hechizo congela toda la realidad, deteniendo completamente el paso del tiempo. Mientras duren sus efectos, la existencia permanece paralizada; únicamente el lanzador podrá moverse y alterar su entorno libremente (aunque será incapaz de regenerar Zeon). Las entidades afectadas pueden evitar las consecuencias del hechizo superando una RM, pero únicamente si poseen un Gnosis mayor de 35 o 20 puntos por encima de su Natura.","_seccion":"AGUA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear fuego', '{"conjuro":"Crear fuego","via":"Fuego","nivel":2,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"1 Intensidad de fuego","efectoIntermedio":"6 intensidades de fuego","efectoAvanzado":"8 Intensidades de fuego","efectoArcano":"10 intensidades de fuego","efecto":"Crea intensidades de fuego. Mientras se mantenga el conjuro, la temperatura se mantendrá","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mitigar fuego', '{"conjuro":"Mitigar fuego","via":"Fuego","nivel":6,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":13,"zeonBase":30,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":200,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"-1 intesidad de fuego","efectoIntermedio":"-5 Intensidades de fuego","efectoAvanzado":"-10 Intensidades fuego","efectoArcano":"-15 Intensidades de fuego","efecto":"Disminuye intensidades de fuego o de calor. Hay que tener en uenta que alguna fuentes de fuego, como volcanes o grandes incendios, se reproducen automáticamente si no se consifuen mitigar del todo. Al lanzarlo sobre un ser basado en fuego, recibira 5 puntos de daño por cada intensidad rebajada, si no supera la RM. Los seres con acumulación reciben 25 puntos de daño por cada intensidad.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inmunidad contra el fuego', '{"conjuro":"Inmunidad contra el fuego","via":"Fuego","nivel":10,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":13,"zeonBase":50,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"5 Intensidades de calor","efectoIntermedio":"12 Intensidades de calor","efectoAvanzado":"20 Intensidades de calor","efectoArcano":"30 Intensidades de calor","efecto":"Este conjuro permite al hechicero, o a las personas que designe, ser inmunes a intensidades de calor. En el caso de que se reciba un ataque basado en dicho elemento, cada intensidad a la que es inmune disminuye 5 puntos de daño base del ataque, otorgando un +5 a las Resistencias contra sus efectos","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sentir el calor', '{"conjuro":"Sentir el calor","via":"Fuego","nivel":12,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"25 metros / RM 120","efectoIntermedio":"50 metros / RM 150","efectoAvanzado":"100 metros / RM 180","efectoArcano":"250 metros / RM 220","efecto":"Detecta la localización de cualquier fuente de calor. El conjuro no dará información sobre qué lo produce, pero podrá sentir intensidades y tamaños. Es posible, incluso percibir el calor que desprende un cuerpo humano, pero no el de seres inanimados o inmateriales, como golems o no muertos. Si se desea resistir, deberá superarse una RM","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Bola de fuego', '{"conjuro":"Bola de fuego","via":"Fuego","nivel":16,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":100,"zeonAvanzado":160,"zeonArcano":250,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño Base 50 / Área de 5 metros de radio","efectoIntermedio":"Daño Base 100 / Área de 25 metros de radio","efectoAvanzado":"Daño Base 140 / Área de 80 metros de radio","efectoArcano":"Daño Base 160 / Área de 150 metros de radio","efecto":"Proyecta un ataque ígneo que estalla en un área. No es posible seleccionar blancos en el interior de la explosión. Ataca en la TA de calor","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control sobre el fuego', '{"conjuro":"Control sobre el fuego","via":"Fuego","nivel":20,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":180,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 100/ 5 intensidades","efectoIntermedio":"RM 120 / 8 intensidades","efectoAvanzado":"RM 140/ 12 intensidades","efectoArcano":"RM 180/ 15 intensidades","efecto":"Permite controlar la forma y crecimiento de un fuego. Del mismo modo, podrán modificarse distintos aspectos de las llamas, como su color, apariencia e incluso el humo que producen. Si se trata de un ser basado naturalmente en este elemento, el mago podrá controlarlo si la criatura no supera una RM. Un ser que falle la Resistencia no puede repetirla, salvo en caso de que reciba una orden opuesta a su naturaleza.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Barrera de fuego', '{"conjuro":"Barrera de fuego","via":"Fuego","nivel":22,"diario":"No","tipo":"Defensa","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Daño 80 / 2 metros de extensión / 300 puntos de Resistencia","efectoIntermedio":"Daño 90 / 5 metros de extensión / 500 puntos de Resistencia","efectoAvanzado":"Daño 100 / 10 metros / 800 puntos / Puede detener ataques basados en energía","efectoArcano":"Daño 100 /15 metros/1000 puntos/Ataque a IMP/ Puede con toda clase ataque","efecto":"Este conjuro levanta un potente muro de fuego. Cualquiera que trate de traspasarlo recibirá automáticamente un ataque contra una habilidad de Casi Imposible, en la TA de calor. Recibir daño no impide a un personaje atravesar el muro. Adicionalmente, el brujo podrá usarla a modo de escudo mágico para detener únicamente ataques basados en agua, frío o fuego","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Arma ígnea', '{"conjuro":"Arma ígnea","via":"Fuego","nivel":26,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":14,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"+10 daño base","efectoIntermedio":"+20 daño base","efectoAvanzado":"+30 daño base","efectoArcano":"+40 daño base","efecto":"Imbuye de llamas un arma, haciendo que ataque en la TA de calor como crítico primario. El fuego será tan potente que aumentará el daño base del ataque, sin afectar en absoluto a la resistencia del arma","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descarga de calor', '{"conjuro":"Descarga de calor","via":"Fuego","nivel":30,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 50","efectoIntermedio":"Daño 70","efectoAvanzado":"Daño 90","efectoArcano":"Daño 110","efecto":"Proyecta una descarga de ondas de alta temperatura, capaces de abrasar cualquier cosa. El ataque se realiza en a TA de calor. Dado que las ondas no son visibles para el ojo humano, el defensor deberá ser capaz de ver magia, tener visión térmica, o superar un control de Advertir contra Absurdo si no quiere sufrir el penalizador de Cegado contra este ataque.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ver en las cenizas', '{"conjuro":"Ver en las cenizas","via":"Fuego","nivel":32,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":140,"zeonAvanzado":220,"zeonArcano":340,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Retrocede una hora","efectoIntermedio":"Retrocede un día","efectoAvanzado":"Retrocede un mes","efectoArcano":"Retrocede un año","efecto":"Traslada los sentidos del hechicero al pasado, permitiéndole ver la causa o incidente que provocó un determinado incendio. El hechicero deberá estar presente entre los restos del incendio para ejecutar el conjuro, y mientras lo hace no será consciente de lo que ocurre a su alrededor en la realidad.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aumentar temp. ambiental', '{"conjuro":"Aumentar temp. ambiental","via":"Fuego","nivel":36,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":140,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"+5 grados/ 1 km de radio","efectoIntermedio":"+10 grados / 5 km de radio","efectoAvanzado":"+20 grados / 10km de radio","efectoArcano":"+30 grados / 15 km de  radio","efecto":"Aumenta la temperatura ambiente. Si la temperatura aumenta 10º por encima de lo que es natural en una zona en su momento más cálido, el índice de aumento se reduce a la mitad.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mina de fuego', '{"conjuro":"Mina de fuego","via":"Fuego","nivel":40,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":320,"mantBase":20,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"10 metros de radio/ Daño 80","efectoIntermedio":"50 metros de radio/ Daño 120","efectoAvanzado":"150 metros de radio/ Daño 180","efectoArcano":"250 metros de radio/ Daño 240","efecto":"Crea una mina ígnea, en radio, ataca en la TA de calor. Para defenderse defensa contra un ataque final de 240, si se esta a más de la mitad de la zona abarcada o contra 280 si es menos. A menos de un metro, ataque 320. La mina puede dejarse fija en un lugar o en un objeto determinado y permanece estática en ese lugar hasta que estalla. El mago puede activarla cuando desee, aunque hacerlo se considera una acción activa. Afecta a todos dentro del area.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aumentar el crítico', '{"conjuro":"Aumentar el crítico","via":"Fuego","nivel":42,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"+20 al nivel de Crítico","efectoIntermedio":"+40 al nivel de Crítico","efectoAvanzado":"+60 al nivel de Crítico","efectoArcano":"+80 al nivel de Crítico","efecto":"Proporciona un bonificador a la tirada para calcular el Nivel de Crítico que haya provocado un ataque determinado. A pesar de ser un conjuro pasivo deberá usarse antes de que se lancen los dados.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Secar', '{"conjuro":"Secar","via":"Fuego","nivel":46,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":240,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"5 metros de radio/ RM o RF 100","efectoIntermedio":"15 metros de radio / RM o RF 120","efectoAvanzado":"25 metros de radio / RM o RF 140","efectoArcano":"35 metros de radio / RM o RF 160","efecto":"Este conjuro seca inmediatamente cualquier cuerpo mojado que se encuentre dentro de un radio. Puede utilizarse para dañar cualquier tipo de elemental de agua, causándole un daño igual al doble de lo que no supere una RM o RF. Si se usa contra seres vivos que poseen organismos basados en agua (lo que incluye también seres humanos), sus efectos pueden ser también muy perjudiciales, aunque el daño se reduce a solo la mitad del nivel de fracaso.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Fundir', '{"conjuro":"Fundir","via":"Fuego","nivel":50,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":240,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"10 metros de radio/ RF 80","efectoIntermedio":"50 metros de radio / RF 100","efectoAvanzado":"100 metros de radio / RF 120","efectoArcano":"150 metros de radio / RF 140","efecto":"Este conjuro calienta un objeto inorgánico en un radio haciendo que alcance mucha temperatura. El calor producido será tanto que, cualquier objeto susceptible de fundirse que no supere un control de resistencia se fundirá en un número de asaltos equivalente a su entereza. Cualquier persona que esté en contacto con el cuerpo abrasado, deberá desprenderse de él o sufrirá daños. Si no lo arroja, cada turno realizará una tirada acumulativa en la Tabla 76","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cuerpo a fuego', '{"conjuro":"Cuerpo a fuego","via":"Fuego","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":12,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Las habilidades descritas","efectoIntermedio":"Se gana +30 a sus Resistencias contra efectos basados en calor","efectoAvanzado":"Idem arriba, el sujeto puede pasar por donde pueda pasar el fuego","efectoArcano":"Idem arriba, los ataques de frío o agua no sobrenatural no causan daño","efecto":"El objetivo se transforma en llamas, volviéndose inmune a ataques no basado en energía, frió o agua. Todo aquello capaz de mitigar el fuego (arena, espuma) producirá también daño. Quien se ponga en contacto con las llamas, superar una RF contra el doble de su presencia o perder puntos de vida equivalente a la mitad del nivel de fracaso (si el afectado tiene TA contra calor obtiene un bono de +5 a esta tirada)","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sacrificio vital', '{"conjuro":"Sacrificio vital","via":"Fuego","nivel":56,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Sacrificio máximo de 50 PV por asalto","efectoIntermedio":"Sacrificio máximo de 100 PV por asalto","efectoAvanzado":"Sacrificio máximo de 150 PV por asalto","efectoArcano":"Sacrificio máximo de 200 PV por asalto","efecto":"Permite al mago consumir su vida aumentando su capacidad física. Esta habilidad es pasiva. Por 5 puntos de vida se gana +5 a una acción (seres con acumulación, multiplican por multiplo). El bono se usa para acciones físicas, ataque, defensa o Proyección Mágica. Es necesario declarar el sacrificio antes de lanzar los dados. Se puede conferir esta capacidad a otro. La vida se recuperan como sacrificio (10 por día). Sus efectos no se superponen.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Incinerar', '{"conjuro":"Incinerar","via":"Fuego","nivel":60,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":12,"intRArcano":16,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":260,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 140/ +100 a la Tabla 76/ 50 metros de radio","efectoIntermedio":"RM 160/ +120 a la Tabla 76/ 100 metros de radio","efectoAvanzado":"RM 180/ +140 a la Tabla 76/ 150 metros de radio","efectoArcano":"RM 200/ +160 a la Tabla 76/ 200 metros de radio","efecto":"Prende en llamas cualquier cuerpo que designe el hechicero, orgánico o inorgánico, por la mera condición de hallarse en su presencia. A efectos del juego, el brujo realizará una tirada con un bonificador en la Tabla 76: En Llamas, por cada blanco que desee incinerar","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Consumir esencia', '{"conjuro":"Consumir esencia","via":"Fuego","nivel":62,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":14,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"10 metros de radio/ RM 120","efectoIntermedio":"25 metros de radio/ RM 160","efectoAvanzado":"50 metros de radio/ RM 200","efectoArcano":"150 metros de radio / RM 220","efecto":"Se crea aura sobrenatural alrededor del mago que destruye la esencia vital de los seres, curarse por medios naturales. Todo ser en el radio, superar RM o perder puntos de vida y Zeon igual al nivel de fracaso. La vida perdida no se recuperan de manera natural, y sólo podrán sanarse mediante conjuros de curación o medios sobrenaturales equivalentes. Los puntos de Zeon, deberán ser absorbidos de otros hechiceros o contenedores mágicos.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sacrificio de poder', '{"conjuro":"Sacrificio de poder","via":"Fuego","nivel":66,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"20 puntos de Zeon por asalto","efectoIntermedio":"50 puntos de Zeon por asalto","efectoAvanzado":"80 puntos de Zeon por asalto","efectoArcano":"120 puntos de Zeon por asalto","efecto":"Permite al hechicero consumir su propia energía mágica para incrementar su acumulación mágica. Este conjuro otorga la habilidad pasiva de gastar puntos de Zeon para obtener un bono temporal a su ACT. Cada 10 puntos que invierta con este fin, le proporcionarán un +5 a su ACT hasta el fin del turno. Sus efectos no se superponen, y sólo se puede tener un conjuro de esta clase activo sobre un individuo determinado","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crítico directo', '{"conjuro":"Crítico directo","via":"Fuego","nivel":70,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":280,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Crítico 120/ RM 140","efectoIntermedio":"Crítico 140/ RM 160","efectoAvanzado":"Crítico 180/ RM 180","efectoArcano":"Crítico 220/ RM 200","efecto":"Causa un estallido interno en un individuo, provocándole un crítico de manera automática. A efectos del juego, el blanco recibirá el equivalente a un Nivel de Crítico aunque tendrá la capacidad de contrarrestarlo con su RF empleando las reglas generales. Para evitar sus efectos es necesario superar un control de RM contra el calor determinado por el grado de conjuro.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Magia por capacidades', '{"conjuro":"Magia por capacidades","via":"Fuego","nivel":72,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"50 puntos de Zeon por asalto","efectoIntermedio":"100 puntos de Zeon por asalto","efectoAvanzado":"150 puntos de Zeon por asalto","efectoArcano":"200 puntos de Zeon por asalto","efecto":"Permite al mago usar su energía mágica, para incrementar temporalmente atributos y habilidades que dependen de ellos. Se gana habilidad pasiva de gastar puntos de Zeon para obtener un bonificador a las características. Cada 25 puntos de Zeon que gaste de esta forma le proporcionan un +1 a uno de sus atributos hasta el fin del turno. Sus efectos no se superponen.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Tormenta de fuego', '{"conjuro":"Tormenta de fuego","via":"Fuego","nivel":76,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"25 metros de radio/ HA Absurdo (180)","efectoIntermedio":"150 metros de radio/ HA CIM (240)","efectoAvanzado":"200 metros de radio/ HA IMP (280)","efectoArcano":"250 metros de radio/ HA INH (320)","efecto":"Se crea una tormenta de llamas. Los seres en ella sufren, cada asalto, un ataque automático en la TA de calor contra una habilidad determinada por el grado del conjuro y un daño base de 100 puntos. No se podrán designar blancos dentro del area, pudiendo afectar al propio lanzador. La condición para recibir el ataque será estar dentro de la tormenta en el asalto posterior. El hechizo siempre permanece estático en el lugar donde fue conjurado.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Consumir vida por magia', '{"conjuro":"Consumir vida por magia","via":"Fuego","nivel":80,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"20 PV por asalto","efectoIntermedio":"80 PV por asalto","efectoAvanzado":"140 PV por asalto","efectoArcano":"200 PV por asalto","efecto":"Otorga la habilidad pasiva de sacrificar temporalmente puntos de vida para recuperar Zeon. Cada 5 PV que se sacrifiquen, proporcionan 100 puntos de Zeon (en el caso de las criaturas con acumulación de daño, la cantidad a sacrificar aumentará dependiendo del múltiplo). La vida perdida se recupera a modo de Sacrificio. Sus efectos no se superponen, y sólo puede tener un conjuro de esta clase activo sobre un individuo determinado.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear ifreet', '{"conjuro":"Crear ifreet","via":"Fuego","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":50,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":140,"efectoBase":"Nivel 1.","efectoIntermedio":"Nivel 3","efectoAvanzado":"Nivel 6.","efectoArcano":"Nivel 10.","efecto":"Crea una criatura de fuego con apariencia de vida, bajo el control absoluto del hechicero. El ente será desarrollado como un Ser Entre Mundos, usando los poderes y las limitaciones de los elementales de Fuego del Capítulo 26. La criatura tendrá PD y, para calcular su nivel máximo se emplean las mismas reglas que en el conjuro Crear Ser de la vía de Creación","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Pira', '{"conjuro":"Pira","via":"Fuego","nivel":86,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":18,"zeonBase":250,"zeonIntermedio":300,"zeonAvanzado":350,"zeonArcano":400,"mantBase":25,"mantIntermedio":30,"mantAvanzado":30,"mantArcano":35,"efectoBase":"15 intensidades","efectoIntermedio":"25 intensidades","efectoAvanzado":"35 intensidades","efectoArcano":"45 intensidades","efecto":"Crea intensidades de fuego. Mientras se mantenga el conjuro, la llama seguirá ardiendo incluso sin nada que consumir. Si se prende en algo inflamable, arderá naturalmente tras finalizar el hechizo.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Devastación', '{"conjuro":"Devastación","via":"Fuego","nivel":90,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":16,"intRArcano":18,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"1 km de radio","efectoIntermedio":"5 km de radio","efectoAvanzado":"10 km de radio","efectoArcano":"15 km de radio","efecto":"Proyecta una explosión ígnea, que ataca en área con un daño base de 200 puntos. Ataca en la TA de calor, aunque es capaz de dañar energía. No es posible designar blancos en el interior del conjuro.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sacrificar a otros', '{"conjuro":"Sacrificar a otros","via":"Fuego","nivel":92,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":13,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":19,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":750,"mantBase":50,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":150,"efectoBase":"RM 120/ 1 km de area","efectoIntermedio":"RM 140/ 2km de area","efectoAvanzado":"RM 160/ 3km de area","efectoArcano":"RM 180/ 5 km de area","efecto":"Permite consumir la esencia de otros y utilizar sus puntos de vida y Zeon para sus hechizos de sacrificio: Sacrificio Vital, Magia por Capacidades, Sacrificio de Poder y Consumir Vida Por Magia. Este conjuro tiene un área estática de un km, donde se puede asignar tantos blancos como se quiera. La RM a superar será de 120. Los afectados podran tirar una vez por día, o cuando sus energías sean consumidas.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Señor del fuego', '{"conjuro":"Señor del fuego","via":"Fuego","nivel":96,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":300,"zeonIntermedio":450,"zeonAvanzado":600,"zeonArcano":1000,"mantBase":30,"mantIntermedio":45,"mantAvanzado":60,"mantArcano":100,"efectoBase":"100 km/ 140 RM","efectoIntermedio":"1.000 km/ 180RM","efectoAvanzado":"10.000 km / 200 RM","efectoArcano":"Afecta a cualquier fuente de calor / RM 240","efecto":"Controla núcleos de elevado calor a su alrededor lo que le permite incluso manejar las corrientes de magma del interior del planeta, pudiendo crear erupciones y volcanes. Toda criatura basa en fuego que se encuentre dentro del área del conjuro, deberá superar una RM o será controlada por el lanzador. Si la pasan, ya no necesitan volver a realizar el control. Los afectados tienen derecho a una nueva tirada únicamente si alteran su Resistencia Base.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Armagedón', '{"conjuro":"Armagedón","via":"Fuego","nivel":100,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":15,"intRIntermedio":16,"intRAvanzado":17,"intRArcano":18,"zeonBase":450,"zeonIntermedio":800,"zeonAvanzado":1200,"zeonArcano":1600,"mantBase":90,"mantIntermedio":100,"mantAvanzado":105,"mantArcano":110,"efectoBase":"10 km de radio / RM 140","efectoIntermedio":"25 km de radio / RM 150","efectoAvanzado":"50 km de radio / RM 160","efectoArcano":"150 km de radio / RM 180","efecto":"Concede al lanzador la capacidad de consumir una parte de la propia esencia del mundo, calcinando las almas que están a su alrededor. Cualquier cosa, orgánica o no, que se encuentre en el interior de su área, deberá superar cada minuto que esté dentro una RM o será calcinado física y espiritualmente. Mientras el lanzador mantenga activo el Armagedón, ninguna forma de vida podrá nacer o ser creada dentro de su zona de influencia.","_seccion":"FUEGO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detectar minerales', '{"conjuro":"Detectar minerales","via":"Tierra","nivel":2,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":20,"zeonIntermedio":60,"zeonAvanzado":100,"zeonArcano":140,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"NO","efectoBase":"10 metros de radio","efectoIntermedio":"50 metros de radio","efectoAvanzado":"150 metros de radio","efectoArcano":"500 metros de radio","efecto":"Permite detectar la ubicación de un mineral determinado, dentro del radio de acción del conjuro. No da información sobre la forma del mineral, pero si sobre su tamaño o cantidad. No es posible detectar a través de barreras basadas en energía.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control mineral', '{"conjuro":"Control mineral","via":"Tierra","nivel":6,"diario":"Si","tipo":"Efecto, Anímico","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":100,"zeonArcano":140,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Presencia máxima 30 / RM 100","efectoIntermedio":"Presencia máxima 60 / RM 120","efectoAvanzado":"Presencia máxima 90 / RM 130","efectoArcano":"Presencia máxima 120 / RM 140","efecto":"Otorga la capacidad de controlar cualquier sustancia mineral, aunque no de atribuírle propiedades que no tenga. El hechicero no puede hacer que una roca se mueva, pero si someter a su voluntad a un golem de piedra o a un elemental de tierra. Los seres conscientes pueden resistirse superando la RM establecida.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aumentar peso', '{"conjuro":"Aumentar peso","via":"Tierra","nivel":10,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":120,"zeonAvanzado":200,"zeonArcano":320,"mantBase":5,"mantIntermedio":25,"mantAvanzado":30,"mantArcano":40,"efectoBase":"+20 kilogramos","efectoIntermedio":"+120 kilogramos","efectoAvanzado":"+200 kilogramos","efectoArcano":"+300 kilogramos","efecto":"Incrementa el peso de un cuerpo, ya sea orgánico o inorgánico","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Transformar mineral', '{"conjuro":"Transformar mineral","via":"Tierra","nivel":12,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":8,"intRAvanzado":11,"intRArcano":13,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"Presencia máxima 30 / hasta 10 kilos de masa","efectoIntermedio":"Presencia máxima 50 / hasta 50 kilos de masa","efectoAvanzado":"Presencia máxima 70 / hasta 100 kilos de masa","efectoArcano":"Presencia máxima 90 / hasta 250 kilos de masa","efecto":"Transmuta un mineral determinado en otro diferente. Puede convertirse, por ejemplo, una roca en oro. El peso resultante puede variar dependiendo de aquello en lo que se transforme y de su presencia.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Firmeza', '{"conjuro":"Firmeza","via":"Tierra","nivel":16,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RF +20 / Entereza +3","efectoIntermedio":"RF +30 / Entereza +5","efectoAvanzado":"RF +45 / Entereza +7","efectoArcano":"RF +60 / Entereza +9","efecto":"Aumenta el aguante ante el daño. Si se lanza sobre un ser vivo, otorga un bonificador a cualquier tirada de RF que se realice para evitar los efectos de un crítico. Si se aplica sobre un objeto, incrementa su entereza. Sólo es posible afectar a un cuerpo a la vez con un conjuro de Firmeza.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Barrera de piedra', '{"conjuro":"Barrera de piedra","via":"Tierra","nivel":20,"diario":"No","tipo":"Defensa","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Barrera de daño 60 / 600 puntos de resistencia","efectoIntermedio":"Barrera de daño 100 / 1.600 puntos de resistencia","efectoAvanzado":"Barrera de daño 150 / 3.000 puntos de resistencia","efectoArcano":"Barrera de daño 200 / 5.000 Puntos de Resistencia","efecto":"Levanta una barrera que permite defenderse de cualquier ataque que cause daño, incluso los basados en Energía. No obstante, es incapaz de detener los efectos anímicos, o aquellos que únicamente obliguen a realizar una RM o RP.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Lentitud', '{"conjuro":"Lentitud","via":"Tierra","nivel":22,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120 / -50 al turno y -2 al Tipo de Movimiento","efectoIntermedio":"RM 140 / -70 al turno y -4 al Tipo de Movimiento","efectoAvanzado":"RM 160 / -90 al turno y -6 al Tipo de Movimiento","efectoArcano":"RM 180 / -120 al turno y -10 al Tipo de Movimiento","efecto":"Reduce la velocidad de movimiento y la capacidad de reacción de un individuo si éste no supera la RM del conjuro. Si el tipo de movimiento llega a cero, cada punto de movimiento adicional que se reduzca provoca en su lugar un -20 a todas las acciones físicas.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Coraza', '{"conjuro":"Coraza","via":"Tierra","nivel":26,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"TA 2","efectoIntermedio":"TA 4","efectoAvanzado":"TA 6","efectoArcano":"TA 8","efecto":"Forma una coraza física que protege contra todos los tipos de ataque, salvo los basados en energía. Aunque cuenta como armadura, no aplica penalizadores al turno por emplear capas adicionales.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo magnético', '{"conjuro":"Escudo magnético","via":"Tierra","nivel":30,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":8,"intRAvanzado":11,"intRArcano":14,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":160,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":20,"efectoBase":"300 puntos de resistencia","efectoIntermedio":"600 puntos de resistencia","efectoAvanzado":"900 puntos de resistencia","efectoArcano":"1.200 puntos de resistencia","efecto":"El hechicero levanta un escudo capaz de repeler cualquier ataque que se realice en su contra empleando un medio metálico. La distorsión magnética impondrá un penalizador de -50 a la habilidad ofensiva del atacante. El escudo sólo puede ser perjudicado por ataques capaces de dañar energía. Esta barrera es inútil contra ataques inmateriales o anímicos.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Atravesar lo sólido', '{"conjuro":"Atravesar lo sólido","via":"Tierra","nivel":32,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Presencia máxima 100","efectoIntermedio":"Presencia máxima 140","efectoAvanzado":"Presencia máxima 180","efectoArcano":"Presencia máxima 240","efecto":"Permite a uno o varios sujetos, atravesar cuerpos sólidos. No hace inmateriales a los blancos, viéndose influidos por los efectos de los elementos como el calor o el frío, pero pueden ignorar completamente cualquier cosa no basada en energía. De este modo, podrían atravesar voluntariamente una pared como si no existiera para ellos, o pasar a través de una espada normal sin sufrir daños. Es posible decidir qué cuerpos puede atravesar y cuáles no.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Espina de la tierra', '{"conjuro":"Espina de la tierra","via":"Tierra","nivel":36,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":150,"zeonArcano":200,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"2 espinas","efectoIntermedio":"4 espinas","efectoAvanzado":"6 espinas","efectoArcano":"8 espinas","efecto":"Levanta afiladas aristas del suelo, que utiliza para atacar. Cada espina tiene daño base 60 y ataca en TA de Penetrantes. No afectan a seres inmateriales, ni sobre los que sólo pueden ser afectados por ataques basados en energía (salvo que las espinas se combinen con un conjuro de Encantar). Cada espina puede atacar a distintos blancos o al mismo. No puede usarse para realizar choque de conjuros, ni atacar a seres volando a más de 10 metros del suelo.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Rotura', '{"conjuro":"Rotura","via":"Tierra","nivel":40,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Rotura +4","efectoIntermedio":"Rotura +8","efectoAvanzado":"Rotura +12","efectoArcano":"Rotura +15","efecto":"Mediante la magia, el brujo incrementa la capacidad de un cuerpo para romper cosas.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Telemetría', '{"conjuro":"Telemetría","via":"Tierra","nivel":42,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 80 / 1 mes","efectoIntermedio":"RM 120 / 1 año","efectoAvanzado":"RM 140 / 10 años","efectoArcano":"RM 160 / 1 siglo","efecto":"El brujo puede leer la historia de un objeto con el que se ponga en contacto, percibiendo los acontecimientos más importantes que hayan ocurrido en torno a él durante un tiempo. Puede usarse también sobre personas pero, en tal caso, el individuo afectado podrá evitarlo superando una RM.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control magnético', '{"conjuro":"Control magnético","via":"Tierra","nivel":46,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":320,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"25 metros de radio / Fuerza 10","efectoIntermedio":"150 metros de radio / Fuerza 12","efectoAvanzado":"350 metros de radio / Fuerza 13","efectoArcano":"500 metros de radio / Fuerza 14","efecto":"Controla campos magnéticos, manipula a distancia, cuerpos metálicos, con fuerza dada por el grado de conjuro. Produce un efecto automático sobre el metal y puede evitarse con un control enfrentado de Fuerza o Agilidad. esto es una acción activa, por lo que no puede emplearse como defensa. Si un cuerpo tiene metales solo en parte, o esta escudado con energía, el control tiene -4. Si se usa arma a distancia, se aplicaran las reglas de Telequinesis Menor.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Forja', '{"conjuro":"Forja","via":"Tierra","nivel":50,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":160,"zeonIntermedio":270,"zeonAvanzado":360,"zeonArcano":450,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Forja 120","efectoIntermedio":"Forja 180","efectoAvanzado":"Forja 240","efectoArcano":"Forja 280","efecto":"Emplea la magia para fraguar un objeto, empleando el equivalente a la habilidad de Forja. Dado que se utiliza puro poder sobrenatural, no aplica ninguno de los modificadores de tiempo de la Tabla 21, ni necesita herramientas o fragua. El hechizo no fabrica los materiales con los que se crea el objeto, por lo que debe ser el hechicero quien los consiga.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cuerpo sólido', '{"conjuro":"Cuerpo sólido","via":"Tierra","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Las habilidades descritas / TA natural 6 / +1 Fuerza","efectoIntermedio":"Las habilidades descritas / TA natural 8 / +2 Fuerza","efectoAvanzado":"TA natural 10 / No dañan ataques físicos no basados en energía / +3 a Fuerza","efectoArcano":"Idem arriba, TA 12 /Ataques físicos basados en ENE mitad daño /+4 a Fuerza","efecto":"El cuerpo objetivo adquirirá mucha solidez, obteniendo una resistencia similar a la de la piedra. Si se lanza contra un individuo, da una armadura natural (salvo contra energía) y barrera de daño igual al doble de su presencia. Sus músculos se fortalecerán, pero disminuirá en 2 su Tipo de movimiento. El material al que se asemeja el cuerpo transformado varía, dependiendo del grado del conjuro, entre roca, acero, diamante y malebolgia.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Resistencia', '{"conjuro":"Resistencia","via":"Tierra","nivel":56,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"500 puntos de vida","efectoIntermedio":"1.200 puntos de vida","efectoAvanzado":"2.000 puntos de vida","efectoArcano":"3.000 puntos de vida","efecto":"Le confiere a un individuo la capacidad de absorver temporalmente grandes cantidades de daño. A efectos de juego, otorga puntos de vida adicionales y permite al afectado aplicar las reglas de defensa de los seres de acumulación. Estos puntos serán los primeros que pierda el personaje, antes de restar los suyos propios. La TA depende del tamaño del personaje.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Petrificar', '{"conjuro":"Petrificar","via":"Tierra","nivel":60,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":260,"zeonArcano":320,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 120","efectoIntermedio":"RM 150","efectoAvanzado":"RM 180","efectoArcano":"RM 220","efecto":"Transforma en piedra a un ser físico. No podrá moverse, ni sabrá que ocurre a su alrededor. Cuando el conjuro finaliza, vuelve a su forma original, con la misma edad y apariencia que tenía en el momento de ser petrificado. Si la \"estatua\" sufre deterioros o se rompe, el sujeto sufre daños, o incluso muere. Un individuo afectado por petrificación tiene derecho a repetir la RM al finalizar su primer día bajo el conjuro, y luego, una vez a la semana.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Grieta', '{"conjuro":"Grieta","via":"Tierra","nivel":62,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"10 metros de longitud / 3 de anchura / Construcciones con barrera de 40","efectoIntermedio":"25 metros de longitud / 8 de anchura / Construcciones con barrera de 60","efectoAvanzado":"36 metros de longitud/ 12 de anchura/ Construcciones con barrera de 80","efectoArcano":"48 metros de longitud/ 15 de anchura/ Construcciones con barrera de 100","efecto":"El brujo es capaz de abrir grietas de gran tamaño en el suelo, capaces de engullir a personas y construcciones. Si un individuo se encuentran en la zona en la que se abre la grieta, debe superar un control de Agilidad para evitar caer al interior y sufrir una caída de entre 20 y 50 metros. Las construcciones con una barrera de daño no son afectadas por el conjuro.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Invertir la gravedad', '{"conjuro":"Invertir la gravedad","via":"Tierra","nivel":66,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"mantBase":40,"mantIntermedio":50,"mantAvanzado":60,"mantArcano":65,"efectoBase":"25 metros de radio / 50 de altura / 120 RM","efectoIntermedio":"50 metros de radio / 100 de altura / 140 RM","efectoAvanzado":"100 metros de radio / 200 de altura / 160 RM","efectoArcano":"150 metros de radio / 300 de altura / 180 RM","efecto":"Invierte la gravedad de una zona. Todo lo que se encuentre en el interior del área afectada, empezará a \"caer\" hacia el cielo hasta la distancia máxima que determine el conjuro. El lanzador puede fijar un límite, como afectar sólo a lo que se encuentre dentro de una construcción. Las cosas que se encuentren fijadas al suelo no \"caerán\". Un individuo puede quedarse \"colgando\" si puede agarrarse. Puede superarse una RM para evitar completamente los efectos.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Creación mineral', '{"conjuro":"Creación mineral","via":"Tierra","nivel":70,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Presencia Máxima 40","efectoIntermedio":"Presencia Máxima 70","efectoAvanzado":"Presencia Máxima 100","efectoArcano":"Presencia Máxima 140","efecto":"El hechicero puede utilizar este conjuro para crear cualquier cosa que desee, siempre y cuando esté compuesta por minerales o metales. El objeto creado debe aparecer ubicado de forma lógica, según su naturaleza. Es decir, no se puede crear una pequeña montaña en mitad del aire.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Erudición del terreno', '{"conjuro":"Erudición del terreno","via":"Tierra","nivel":72,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":270,"zeonAvanzado":360,"zeonArcano":450,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"500 metros de radio","efectoIntermedio":"3 kilómetros de radio","efectoAvanzado":"10 kilómetros de radio","efectoArcano":"15 kilómetros de radio","efecto":"El lanzador obtiene un conocimiento absoluto de todo lo que se haya a su alrededor en contacto con el suelo. No se trata de un hechizo de localización, sino que permite al brujo unir su conciencia con la propia tierra, y sentir todo lo que está en contacto con ella. Tanto seres vivos como construcciones son localizados de inmediatio (excepto seres inmateriales o que estén en vuelo). No permite ver a a través de lugares sellados por energía.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Terremoto', '{"conjuro":"Terremoto","via":"Tierra","nivel":76,"diario":"No","tipo":"Efcto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"500 metros de radio","efectoIntermedio":"3 kilómetros de radio","efectoAvanzado":"10 kilómetros de radio","efectoArcano":"15 kilómetros de radio","efecto":"Crea un terremoto. Cualquier construcción con barrera inferior a 40 queda destruída, mientras que el resto sufrirá 5 puntos de daño en el primer asalto, que se doblarán en cada turno posterior (10 en el segundo, 20 en el tercero, 40 en el cuarto...) Las construcciones con una barrera de daño superior a 150 no son afectadas por el terremoto. Cualquier individuo dentro de la zona del conjuro sufrirá sus efectos, dependiendo del entorno en el que se encuentre.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción gravitacional', '{"conjuro":"Destrucción gravitacional","via":"Tierra","nivel":80,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":17,"zeonBase":180,"zeonIntermedio":250,"zeonAvanzado":320,"zeonArcano":400,"mantBase":20,"mantIntermedio":25,"mantAvanzado":30,"mantArcano":40,"efectoBase":"20 metros de radio","efectoIntermedio":"50 metros de radio","efectoAvanzado":"100 metros de radio","efectoArcano":"150 metros de radio","efecto":"Crea una cúpula de alta presión. Un ser dentro, debe superar RF a 180 cada turno, o sufrir un daño equivalente a la mitad del nivel de fracaso. Por punto de TA en Contundentes +5 a la tirada de RF. La cúpula permanece estática donde se lanza, para salir superar control de Fuerza 16. Afecta a los seres inmateriales, pero aplican un bono de +40 a controles de resistencia, y +6 a los de fuerza. No hay seleccion de blancos, sólo el lanzador es inmune a sus efectos.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear golem', '{"conjuro":"Crear golem","via":"Tierra","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":50,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":140,"efectoBase":"Nivel 1","efectoIntermedio":"Nivel 3","efectoAvanzado":"Nivel 6","efectoArcano":"Nivel 10","efecto":"Crea un ser de piedra con apariencia de vida, bajo el control absoluto del hechicero. El ente será creado como un ser entre mundos, usando los poderes y limitaciones de los elementales de Tierra, según las reglas de creación de seres. La criatura tendrá PD, y se le aplican los limites descritos en el conjuro Crear Ser, de la Vía de Creación","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aumento de gravedad', '{"conjuro":"Aumento de gravedad","via":"Tierra","nivel":86,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"mantBase":20,"mantIntermedio":25,"mantAvanzado":30,"mantArcano":35,"efectoBase":"Dobla el peso / 100 metros de radio","efectoIntermedio":"Triplica el peso / 200 metros de radio","efectoAvanzado":"Quintuplica el peso / 300 metros de radio","efectoArcano":"Decuplica el peso / 400 metros de radio","efecto":"Incrementa la masa de la atmósfera de una zona determinada, aumentando con ello la fuerza de gravedad y, por lo tanto, el peso de todo lo que se halle en su interior. A efectos de juego, aumenta el peso de todo lo que determine el hechicero dentro del área de conjuro, que permanecerá estática en el lugar donde se haya lanzado.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Meteoro', '{"conjuro":"Meteoro","via":"Tierra","nivel":90,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":200,"zeonIntermedio":250,"zeonAvanzado":350,"zeonArcano":450,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"1 meteoro","efectoIntermedio":"5 meteoros","efectoAvanzado":"10 meteoros","efectoArcano":"15 meteoros","efecto":"Controla uno o varios meteoros, y los arroja desde los cielos. Cada asteroide tarda entre 1 y 10 turnos, que se determinan lanzando 1d10 por cada uno. Tienen daño base de 200 en 10 metros de radio, en la TA de Contundentes o Calor. Lo que se encuentre en una zona de 50 metros alrededor del impacto, sufre la onda expansiva, que tiene daño base 60, y produce un impacto de Fuerza 14. Este conjuro no tiene efecto si es lanzado en interiores.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control de la gravedad', '{"conjuro":"Control de la gravedad","via":"Tierra","nivel":92,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":350,"zeonIntermedio":500,"zeonAvanzado":650,"zeonArcano":800,"mantBase":70,"mantIntermedio":100,"mantAvanzado":130,"mantArcano":160,"efectoBase":"100 kilómetros de radio","efectoIntermedio":"750 kilómetros de radio","efectoAvanzado":"1.500 kilómetros de radio","efectoArcano":"5.000 kilómetros de radio","efecto":"Otorga la capacidad de controlar las fuerzas gravitacionales de una zona del planeta. Dentro de ella, el lanzador podrá anular la gravedad, incrementarla hasta diez veces su valor, o invertirla. Todo cuerpo físico que se encuentre dentro del área designada, será automáticamente influído por sus efectos.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Uno con la tierra', '{"conjuro":"Uno con la tierra","via":"Tierra","nivel":96,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":300,"zeonIntermedio":450,"zeonAvanzado":600,"zeonArcano":1000,"mantBase":30,"mantIntermedio":45,"mantAvanzado":60,"mantArcano":100,"efectoBase":"100 kilómetros de radio / 140 RM","efectoIntermedio":"1.000 kilómetros de radio / 180 RM","efectoAvanzado":"10.000 kilómetros de radio / 200 RM","efectoArcano":"Afecta cualquier elemento mineral existente / 240 RM","efecto":"El mago fusiona su esencia con el mundo, teniendo control de cualquier elemento mineral. Esto le permite alterar la apariencia del planeta dentro de su radio de acción, levantando montañas y cordilleras, o haciéndolas desaparecer. Toda criatura basada en Tierra que esté dentro del área debe superar una RM o es controlada de inmediato. Si la pasan, ya no necesitan volver a realizar el control. Los afectados pueden repetir la tirada si incrementan su presencia.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control atómico', '{"conjuro":"Control atómico","via":"Tierra","nivel":100,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":450,"zeonIntermedio":800,"zeonAvanzado":1200,"zeonArcano":1600,"mantBase":45,"mantIntermedio":80,"mantAvanzado":120,"mantArcano":160,"efectoBase":"RM o RF 140 / 100 metros de radio","efectoIntermedio":"RM o RF 160 / 250 metros de radio","efectoAvanzado":"RM o RF 200 / 500 metros de radio","efectoArcano":"RM o RF 240 / 1 kilómetro de radio","efecto":"El mago controla los atomos a su alrededor. Obtiene el dominio de toda la materia, orgánica o inorgánica, que no supere un control de RM o RF y se encuentre dentro del radio. No hay límite para lo que el brujo puede hacer con aquellos elementos que tiene controlados, desde alterar su forma, masa y apariencia, a hacerlo desaparecer por completo, dispersando sus átomos. Este conjuro sólo afecta a la materia física.","_seccion":"TIERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Afinidad natural', '{"conjuro":"Afinidad natural","via":"Esencia","nivel":2,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Afecta a animales naturales (caballos, conejos, lobos, etc)","efectoIntermedio":"Afecta a toda clase de criatura natural","efectoAvanzado":"Afecta a seres naturales y a criaturas entre mundos","efectoArcano":"Afecta a cualquier criatura, incluyendo seres sobrenaturales de alto poder","efecto":"Altera la esencia de un individuo, permitíendole volverse afín a cualquier tipo de ser vivo, y consiguiendo que estos le reconozcan como un miembro de su especie. Sólo afecta a seres que se basen en institntos.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detectar esencia', '{"conjuro":"Detectar esencia","via":"Esencia","nivel":6,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":100,"zeonArcano":140,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"RM 100 / 10 metros de radio","efectoIntermedio":"RM 140 / 25 metros de radio","efectoAvanzado":"RM 160 y 50 metros de radio","efectoArcano":"RM 200 / 100 metros de radio","efecto":"El mago ve la esencia en la que se está basado cualquier ser de su alrededor. No de información real sobre las criaturas, pero reconoce sus ataduras elementales, e identifica posteriormente seres con el mismo tipo de esencia o raza. No es un conjuro de detección, por lo que el mago debe saber que una criatura está cerca para poder sentir su esencia. Aún así, el hechizo le permite percibir a criaturas espirituales que sean invisibles al ojo humano.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Comunicación por esencia', '{"conjuro":"Comunicación por esencia","via":"Esencia","nivel":10,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":10,"intRArcano":13,"zeonBase":30,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":150,"mantBase":10,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"Permite comunicarse con animales o plantas","efectoIntermedio":"Permite comunicarte con cualquier clase de ser natural","efectoAvanzado":"Permite comunicarse con cualquier clase de ser natural o entre mundos","efectoArcano":"Permite comunicarse con cualquier clase de entidad","efecto":"El hechizo establece un enlace anímico entre el lanzador y un sujeto determinado, permitiéndoles a ambos comunicarse espiritualmente. La conversación se realizará mediante conceptos que ambos entenderán automáticamente, incluso si hablan idiomas distintos, o aunque uno de ellos no esté capacitado para hablar. Es incluso posible comunicarse con animales o plantas, que no tienen un idioma estructurado.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Conocimiento natural', '{"conjuro":"Conocimiento natural","via":"Esencia","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":10,"intRArcano":13,"zeonBase":40,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Analiza las propiedades básicas de una planta o animal","efectoIntermedio":"Analiza todas las propiedades de una planta o animal","efectoAvanzado":"Analiza todas las propiedades de una raza natural","efectoArcano":"Analiza todas las propiedades y poderes místicos de un ser natural.","efecto":"Permite analizar toda la información sobre un determinado tipo de ser natural, como animales o plantas. Un hechicero que usase este conjuro podría, por ejemplo, examinar una planta extraña y descubrir si es venenosa o si tiene algún tipo de propiedad especial.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sanación', '{"conjuro":"Sanación","via":"Esencia","nivel":16,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"20% puntos de vida","efectoIntermedio":"40% puntos de vida","efectoAvanzado":"60% puntos de vida","efectoArcano":"80% puntos de vida","efecto":"Otorga la capacidad de regenerar a un ritmo vertiginoso las heridas de un individuo, curando los puntos de vida perdidos. No permite recuperar miembros cercenados o daños similares, ni tampoco elimina los penalizadores causados por los críticos, pero sí detiene cualquier tipo de desangramiento. En caso de ser lanzado sobre un ser con acumulación de daño, sólo recupera la mitad del valor porcentual indicado.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Barrera de almas', '{"conjuro":"Barrera de almas","via":"Esencia","nivel":20,"diario":"Si","tipo":"Defensa","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":40,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Hasta 140 de Resistencia","efectoIntermedio":"Hasta 160 de Resistencia","efectoAvanzado":"Hasta 200 de Resistencia","efectoArcano":"Hasta 240 de Resistencia","efecto":"Crea una barrera espiritual para detener cualquier efecto que obligue a superar una RM o RP, aunque es inútil contra cualquier otro tipo de ataque o conjuro. Tampoco detiene ataques que provoquen daños con efectos añadidos, como Lluvia de Destrucción, por ejemplo. El escudo no tiene puntos de vida, porque no protege contra impactos que causen daños.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Compartir sentidos', '{"conjuro":"Compartir sentidos","via":"Esencia","nivel":22,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Presencia máxima 100 / RM o RP 100 / 1 kilómetro de distancia máxima","efectoIntermedio":"Presencia máxima 160 / RM o RP 160 / 10 kilómetros de distancia máxima.","efectoAvanzado":"Presencia máxima 200 / RM o RP 190 / 50 kilómetros de distancia máxima","efectoArcano":"Presencia máxima 240 / RM o RP 220 / 150 kilómetros de distancia máxima","efecto":"Conecta los sentidos del hechicero con los de otros individuos y viceversa, permitiéndoles ver y escuchar lo que otros perciban. Si el brujo lo desea, es capaz de negar el acceso a sus propios sentidos. Para resistirse, debe superarse una RM o RP. Cualquier afectado tiene derecho a una nueva resistencia cada hora. Puede afectar a varios individuos a la vez, siempre que la suma de sus Presencias (sin contar la del hechicero) no supere el máximo indicado por el conjuro.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Modificar la esencia', '{"conjuro":"Modificar la esencia","via":"Esencia","nivel":26,"diario":"No","tipo":"anímico","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":140,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"RM 140","efectoIntermedio":"RM 160","efectoAvanzado":"RM 180","efectoArcano":"RM 200","efecto":"Permite al hechicero modificar la esencia de un ser. No da habilidades especiales por el cambio en sí, pero altera temporalmente la base anímica del objetivo. De esta forma, podrá modificar la esencia de un elemental de tierra por frío, haciéndole vulnerable a efectos y ataques basados en el calor. En el caso de que la criatura posea poderes que estén cerrados al elemento al que se modifica su esencia, perderá temporalmente la capacidad de usarlos.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Veneno de almas', '{"conjuro":"Veneno de almas","via":"Esencia","nivel":30,"diario":"No","tipo":"anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Veneno de nivel 40","efectoIntermedio":"Veneno de nivel 50","efectoAvanzado":"Veneno de nivel 60","efectoArcano":"Veneno de nivel 70","efecto":"El veneno es una creación sobrenatural que se inocula en el alma del afectado y se extiende por todo su cuerpo. El mago podrá crear libremente los efectos del veneno, siguiendo la descripción del capítulo 14. También es posible desarrollar antídotos, si se tienen los conocimientos suficientes sobre el veneno original.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Analizar el alma', '{"conjuro":"Analizar el alma","via":"Esencia","nivel":32,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 180","efectoArcano":"RM 200","efecto":"Permite obtener información detallada acerca de las capacidades naturales y poderes de un individuo o criatura. No le da acceso a saber cuáles son sus conocimientos ni el nivel de las habilidades que dependan de estos, sí medir su potencial espiritual y averiguar cómo funcionan sus capacidades innatas. Este conjuro funciona automáticamente sobre la criatura designada si el hechicero la ve o conoce su verdadero nombre, aunque puede resistirse con una RM.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Adq. capacidades naturales', '{"conjuro":"Adq. capacidades naturales","via":"Esencia","nivel":36,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":200,"zeonAvanzado":280,"zeonArcano":360,"mantBase":25,"mantIntermedio":40,"mantAvanzado":60,"mantArcano":80,"efectoBase":"50 PD","efectoIntermedio":"100 PD","efectoAvanzado":"150 PD","efectoArcano":"200 PD","efecto":"Da PD adicionales al personaje, para habilidades secundarias, habilidades esenciales o poderes de la Creación de Seres. Sólo pueden escogerse secundarias de los campos físicos de Agilidad, Percepción y Fuerza, y poderes especiales con Gnosis 0. No puede aumentarse habilidades primarias, ni adquirir capacidades sobrenaturales. Estos cambios afectarán temporalmente a la forma física del personaje. Los efectos de este conjuro no se superponen.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Revitalizar', '{"conjuro":"Revitalizar","via":"Esencia","nivel":40,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"50 metros de radio","efectoIntermedio":"200 metros de radio","efectoAvanzado":"500 metros de radio","efectoArcano":"1 kilómetro de radio","efecto":"Crea una zona dentro de la cual todo ser vivo regenera sus heridas y se revitaliza. El conjuro otorga Regeneración 16 a todas las criaturas vivientes que se encuentren dentro del radio designado.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mente de vida', '{"conjuro":"Mente de vida","via":"Esencia","nivel":42,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 80 / 500 metros de radio","efectoIntermedio":"RM 120 / 1 kilómetro de radio","efectoAvanzado":"RM 140 / 2 kilómetros de radio","efectoArcano":"RM 180 / 3 kilómetros de radio","efecto":"El mago conecta su esencia con la mente de todo ser vivo con Gnosis entre 0 y 10 dentro del area. Podrá sentir lo que hay alrededor utilizando la percepción de estos. Puede lanzar conjuros con la mitad de ACT como si estuviese allí, pero los conjuros Anímicos sobre el cuerpo en que está lo afectan. Se puede evitar la posesión con RM, una vez que pasa el control, ya no puede ser afectado. Una persona no se da cuenta de que está siendo utilizada de este modo.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alterar el crecimiento', '{"conjuro":"Alterar el crecimiento","via":"Esencia","nivel":46,"diario":"Si","tipo":"anímico","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":240,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"x2 al ritmo de crecimiento / RM 100","efectoIntermedio":"X 10 al ritmo de crecimiento / RM 120","efectoAvanzado":"x50 al ritmo de crecimiento / RM 140","efectoArcano":"x100 al ritmo de crecimiento / RM 160","efecto":"Modifica el ritmo natural de desarrollo de un organismo, acelerando o retrasando su evolución. En juego, permite multiplicar o dividir el ritmo de envejecimiento de un cuerpo vivo por el valor que determina el grado de conjuro. Una vez alguien es afectado por este sortilegio, no tiene derecho a repetir la RM mientras el lanzador lo mantenga.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Imitación natural', '{"conjuro":"Imitación natural","via":"Esencia","nivel":50,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"2 niveles","efectoIntermedio":"10 niveles","efectoAvanzado":"20 niveles","efectoArcano":"50 niveles","efecto":"Crea un animal natural, imitando una especie existente. Estará bajo el control absoluto del lanzador. La criatura creada debe ser un animal con Gnosis 0 y de una raza que exista en el mundo. El conjuro permite elegir entre crear un sólo ser (de cinco niveles como máximo) o repartir los niveles que confiere entre varias criaturas. Las Creaciónes tendrán todos sus instintos y habilidades naturales. Como referencia, el hechicero debe utilizar los animales del capítulo 25.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Forma espiritual', '{"conjuro":"Forma espiritual","via":"Esencia","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"El mago se vuelve intangible.","efectoIntermedio":"Como en grado base, pero también carece de necesidades físicas.","efectoAvanzado":"Como en grado intermedio, pero obtiene invisibilidad espiritual","efectoArcano":"como avanzada, pero también obtiene el poder Interacción con el mundo.","efecto":"Transforma la forma física de un individuo en materia espiritual. Mientras se encuentre en ese estado, aplicará las reglas descritas en el grado de conjuro como si se tratase de un ser espiritual (Cap. 26)","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control natural', '{"conjuro":"Control natural","via":"Esencia","nivel":56,"diario":"Si","tipo":"anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":20,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"RM 80","efectoIntermedio":"RM 120","efectoAvanzado":"RM 150","efectoArcano":"RM 180","efecto":"Se obtiene el dominio de un miembro de una raza natural con Gnosis 0, animales, plantas o seres humanos normales. Podrá transmitir órdenes por la conexión que se crea. Para resistir el hechizo, es necesario superar RM. El individuo subyugado tendrá derecho a un control por día, y cada vez que reciba una orden totalmente contraria a su naturaleza. Ante una petición que ponga su vida en peligro, o le obligue a matar a alguien querido, podrá sumar +20 a RM.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inducción de estados', '{"conjuro":"Inducción de estados","via":"Esencia","nivel":60,"diario":"No","tipo":"anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 100","efectoIntermedio":"RM 140","efectoAvanzado":"RM 180","efectoArcano":"RM 200","efecto":"Mediante la manipulación del alma, se imbuye al objetivo del conjuro de cualquiera de los estados genéricos descritos en el Capítulo 14, con excepción de Muerte. El brujo elige cúal desea provocar en el momento de lanzar el hechizo, cuya duración dependerá de las reglas generales en cada caso. Para resistirse, es necesario superar una RM. Si los estados inducidos son Coma o Paralización Completa, el afectado puede añadir un bono de +40 a su RM.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Devolver al flujo', '{"conjuro":"Devolver al flujo","via":"Esencia","nivel":62,"diario":"No","tipo":"anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120","efectoIntermedio":"RM 180","efectoAvanzado":"RM 240","efectoArcano":"RM 300","efecto":"Afecta a un espíritu, devolviéndolo al más allá. Permite influenciar tanto a almas que esperan El Llamamiento como a criaturas de naturaleza espiritual. Salvo si la entidad tiene un Gnosis lo suficientemente elevado como para permitirle regresar al mundo, su esencia desaparecerá al llegar al más allá. En el caso de los no muertos, dado que sus almas no pertenecen al mundo, son automáticamente destruídos.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudar', '{"conjuro":"Escudar","via":"Esencia","nivel":66,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120 / 20 metros de radio","efectoIntermedio":"RM 160 / 30 metros de radio","efectoAvanzado":"RM 180 / 40 metros de radio","efectoArcano":"RM 200 / 50 metros de radio","efecto":"Hace una zona impenetrable para un determinado tipo de ser. El mago decide cuáles en el momento de lanzar el hechizo, aunque tendrá libertad absoluta para vedar el acceso a tantos como desee. La zona afectada no podrá ser mayor de lo que indique el conjuro, o el doble, si tiene forma de muro. quien tenga el paso vedado y no supere RM no podrá pasar. La tirada puede repetirse una vez por hora. Escudar permanece estático en el lugar en el que es lanzado.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control sobrenatural', '{"conjuro":"Control sobrenatural","via":"Esencia","nivel":70,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":25,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"RM 100","efectoIntermedio":"RM 120","efectoAvanzado":"RM 140","efectoArcano":"RM 180","efecto":"Se obtiene el control de un espíritu o de un Ser Entre Mundos. Se podrá transmitir las órdenes por la conexión mística que crea con la entidad. Para resistir los efectos , es necesario superar una RM (dado que se controla la esencia de la criatura, no es posible utilizar su RP). El ser tendrá derecho a una Resistencia por día, y en cada ocasión en la que las órdenes recibidas vayan completamente en contra de su comportamiento.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Compartir esencia', '{"conjuro":"Compartir esencia","via":"Esencia","nivel":72,"diario":"Sí","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Presencia máxima 100 / RM 120","efectoIntermedio":"Presencia máxima 140 / RM 140","efectoAvanzado":"Presencia máxima 200 / RM 170","efectoArcano":"Presencia máxima 260 / RM 200","efecto":"Se ata la esencia de dos individuos, formando una unidad indivisible. Cualquier daño o efecto espiritual que reciba uno de los afectados, lo sufrirá el otro. En el caso de anímicos, se usa la RM más elevada. Si se ata la esencia de un ser normal a otro con acumulación de daño, el primero sufrirá una quinta parte del daño recibido por la criatura. En el caso de que alguno de los blancos del conjuro quiera resistirse, deberá superar una RM.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Transmigrar almas', '{"conjuro":"Transmigrar almas","via":"Esencia","nivel":76,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":180,"zeonIntermedio":240,"zeonAvanzado":300,"zeonArcano":540,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 100 / Presencia máxima 60","efectoIntermedio":"RM 140 / Presencia máxima 100","efectoAvanzado":"RM 160 / Presencia máxima 140","efectoArcano":"RM 200 / Presencia máxima 180","efecto":"Transporta almas de un cuerpo a otro, conservando las capacidades intelectuales y anímicas y adquiere las limitaciones físicas del nuevo cuerpo. Un cuerpo muerto, volverá a vivir. Si el cuerpo ya tiene alma, ambas lucharan (ver libro). Tanto el alma como el cuerpo anfitrión tienen derecho a RM. Puede transmigrar cualquier clase de alma, incluso espíritus que esperan El Llamamiento. Si un espíritu es encerrado en un cuerpo físico, pierde sus poderes anímicos.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Existencia espiritual', '{"conjuro":"Existencia espiritual","via":"Esencia","nivel":80,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":500,"zeonAvanzado":1000,"zeonArcano":2500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Hasta 100 PD opcionales en desventajas","efectoIntermedio":"+100 PD / hasta 100 PD opcionales en desventajas","efectoAvanzado":"+200 PD / hasta 200 PD opcionales en desventajas","efectoArcano":"+300 PD / hasta 200 PD opcionales en desventajas","efecto":"Permite trascencer a un estado espiritual, abandonando su cuerpo. Será un ser espiritual de Gnosis 25. Obtendrá PD, para gastar en Habilidades Naturales o Poderes de Creación de Seres. Puede escoger PD en desventajas para puntos adicionales. El mago suma automáticamente un nivel (por las ventajas que otorga convertirse en un ente espiritual), más otro por cada 100 PD que obtenga sin desventajas. Sólo funciona sobre seres naturales o entre mundos.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Creación de espíritus', '{"conjuro":"Creación de espíritus","via":"Esencia","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":50,"mantIntermedio":70,"mantAvanzado":100,"mantArcano":140,"efectoBase":"Nivel 1","efectoIntermedio":"Nivel 3","efectoAvanzado":"Nivel 6","efectoArcano":"Nivel 10","efecto":"Mediante su magia, el brujo crea un ente espiritual bajo su completo control. Debe ser desarrollado como un espíritu, según las reglas del capítulo 26. La criatura tendrá PD y para calcular su nivel máximo se aplican las mismas reglas que en el conjuro Crear Ser, de la Vía de Creación.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Atar esencia vital', '{"conjuro":"Atar esencia vital","via":"Esencia","nivel":86,"diario":"No","tipo":"Activa","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 100 / 1 kilómetro de distancia","efectoIntermedio":"RM 120 / 5 kilómetros de distancia","efectoAvanzado":"RM 140 / 50 kilómetros de distancia","efectoArcano":"RM 160 / 150 kilómetros de distancia","efecto":"Esconde un alma en un contenedor físico. El alma sigue usando su cuerpo, aunque ya solo es una cáscara. Es incapaz de morir por pérdida de PV''s. Si éstos se reducen hasta la Muerte, el cuerpo quedará inutilzado y sólo se curará mediante habilidades sobrenaturales. La carcasa sin alma será inmune a los efectos místicos de carácter anímico. La distancia máxima de separación con el contenedor es el grado de conjuro. El efecto puede resisitirse con RM.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Verdor', '{"conjuro":"Verdor","via":"Esencia","nivel":90,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":13,"intRArcano":16,"zeonBase":250,"zeonIntermedio":450,"zeonAvanzado":600,"zeonArcano":750,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"10 kilómetros de radio","efectoIntermedio":"150 kilómetros de radio","efectoAvanzado":"350 kilómetros de radio","efectoArcano":"600 kilómetros de radio","efecto":"Verdor crea vida vegetal y animal al antojo del lanzador. Animales y plantas aparecerán en el instante en el que se lance el hechizo, sin importar las condiciones climatológicas de la zona. El brujo podrá crear una selva incluso en mitad de un desierto (aunque eso no significa que sobreviviese durante un período prolongado en esas condiciones). Fauna y flora deben pertenecer a especies naturales existentes.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Dominio de la vida', '{"conjuro":"Dominio de la vida","via":"Esencia","nivel":92,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":18,"zeonBase":300,"zeonIntermedio":500,"zeonAvanzado":750,"zeonArcano":1000,"mantBase":60,"mantIntermedio":75,"mantAvanzado":85,"mantArcano":100,"efectoBase":"RM 100 / 100 kilómetros de radio","efectoIntermedio":"RM 130 / 500 kilómetros de radio","efectoAvanzado":"RM 160 / 1.500 kilómetros de radio","efectoArcano":"RM 200 / 2.500 kilómetros de radio","efecto":"El mago controla parte de la esencia del mundo, obteniendo el dominio de todos los Seres Naturales a su alrededor. Podrá transmitir órdenes directamente por la conexión mística, sin la necesidad de estar junto a ellos. Para resistirse, es necesario superar una RM. Los afectados tendrán derecho a una nueva Resistencia por día, y en cada ocasión en la que las órdenes recibidas vayan completamente en contra de su comportamiento.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Resurrección', '{"conjuro":"Resurrección","via":"Esencia","nivel":96,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":18,"zeonBase":400,"zeonIntermedio":500,"zeonAvanzado":600,"zeonArcano":700,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Presencia máxima 30 / 1 mes","efectoIntermedio":"Presencia máxima 60 / 1 año","efectoAvanzado":"Presencia máxima 120 / 1 década","efectoArcano":"Presencia máxima 150 / 1 siglo","efecto":"Este conjuro trae del más allá un alma muerta. La dificultad depende del tiempo que transcurra desde que murio. Sólo permite traer el alma, pero no podrá atarla a un cuerpo ni sanarlo. Para hacer una resurrección, debe trasladarse el alma a un cuerpo apropiado mediante Transmigrar el Alma. No es posible resucitar un alma que ya se haya reencarnado o que fuese destruida. Máxima presencia igual a grado del conjuro.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Señor de las almas', '{"conjuro":"Señor de las almas","via":"Esencia","nivel":100,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":600,"zeonIntermedio":800,"zeonAvanzado":1200,"zeonArcano":1500,"mantBase":120,"mantIntermedio":160,"mantAvanzado":240,"mantArcano":300,"efectoBase":"RM 120 / 100 kilómetros","efectoIntermedio":"RM 140 / 1.000 kilómetros","efectoAvanzado":"RM 180 / 2.500 kilómetros","efectoArcano":"RM 200 / 5.000 kilómetros","efecto":"El mago controla parte del flujo de almas. Tiene autoridad sobre cualquier alma, lo que incluye Seres Espirituales y otras criaturas. Tendrá control total sobre ellas y las maneja como desee. También podrá arrancarlas de un cuerpo y reintroducirlas en otro, incluso en niños que aún no han nacido. El Señor de las Almas puede transmitir sus órdenes a las almas que se encuentren bajo su control directamente. Su efecto se resiste con RM a una tirada por día.","_seccion":"ESENCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ilusión sonora', '{"conjuro":"Ilusión sonora","via":"Ilusión","nivel":2,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":50,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 100 / radio de 20 metros","efectoIntermedio":"RM 120 / radio de 50 metros","efectoAvanzado":"RM 140 / radio de 100 metros","efectoArcano":"RM 160 / radio de 250 metros","efecto":"Forma un sonido ilusorio, que el hechicero compondrá con completa libertad. Podría crear, por ejemplo, voces humanas o el ruido de un arroyo. El conjuro afectará a aquellos sujetos que no superen una RM. El hechicero puede elegir quién escucha el sonido dentro del área y quién no.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ilusión olfativa', '{"conjuro":"Ilusión olfativa","via":"Ilusión","nivel":6,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":50,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 100 / radio de 20 metros","efectoIntermedio":"RM 120 / radio de 50 metros","efectoAvanzado":"RM 140 / radio de 100 metros","efectoArcano":"RM 160 / radio de 250 metros","efecto":"Crea un olor ilusorio. El conjuro afectará en radio a aquellos sujetos que no superen una RM. El hechicero puede elegir quién huele el aroma dentro del área y quién no.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ilusión táctil', '{"conjuro":"Ilusión táctil","via":"Ilusión","nivel":10,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":50,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 100 / radio de 20 metros","efectoIntermedio":"RM 120 / radio de 50 metros","efectoAvanzado":"RM 140 / radio de 100 metros","efectoArcano":"RM 160 / radio de 250 metros","efecto":"Falsea el tacto o el gusto de un elemento concreto. El Ilusiónista decidirá qué nueva sensación o gusto adquiere, y quién la notará, dentro del área, El conjuro afectará a aquellos sujetos que no superen una RM.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ilusión visual', '{"conjuro":"Ilusión visual","via":"Ilusión","nivel":12,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 100 / radio de 10 metros","efectoIntermedio":"RM 120 / radio de 25 metros","efectoAvanzado":"RM 140 / radio de 50 metros","efectoArcano":"RM 160 / radio de 100 metros","efecto":"Crea una imagen ilusoria inmóvil que engaña al sentido de la vista. El conjuro afectará a cualquier persona dentro del radio de efecto que vea la imagen y no supere una RM. El hechicero puede elegir qué sujetos la verán y cuáles no.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detectar ilusiones', '{"conjuro":"Detectar ilusiones","via":"Ilusión","nivel":16,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":60,"zeonIntermedio":160,"zeonAvanzado":200,"zeonArcano":240,"mantBase":10,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"Afecta a conjuros de grado base.","efectoIntermedio":"Afecta a conjuros de grado intermedio.","efectoAvanzado":"Afecta a conjuros de grado avanzado.","efectoArcano":"Afecta a conjuros de grado arcano.","efecto":"Otorga al brujo la capacidad de sentir las Ilusiónes en un radio. Mientras esté activa la detección, cualquier conjuro de esta via será automáticamente revelado al hechicero.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Engatusar', '{"conjuro":"Engatusar","via":"Ilusión","nivel":20,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":13,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"+50 a Liderazgo y Persuasión.","efectoIntermedio":"+80 a Liderazgo y Persuasión.","efectoAvanzado":"+100 a Liderazgo y Persuasión.","efectoArcano":"+120 a Liderazgo y Persuasión.","efecto":"El individuo objeto del conjuro ve aumentado, mediante la magia, su carisma y su encanto. Mientras esté activo, el personaje recibirá un bono a sus habilidades secundarias Liderazgo y Persuasión.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alterar apariencia', '{"conjuro":"Alterar apariencia","via":"Ilusión","nivel":22,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"Altera a la vista el aspecto fisico de un individuo u objeto. Sólo podrá aumentar o reducir en tres grados las características de Tamaño y Apariencia del afectado. Cualquier sujeto que mire, debe superar una RM para ver la realidad que esconde. Una vez que alguien es afectado,sólo tendrá derecho a un control de Resistencia cuando posea algún motivo para sospechar que hay algo raro en la identidad o apariencia del sujeto.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Invisibilidad ilusoria', '{"conjuro":"Invisibilidad ilusoria","via":"Ilusión","nivel":26,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 120 / Presencia máxima 140.","efectoIntermedio":"RM 150 / Presencia máxima 200.","efectoAvanzado":"RM 180 / Presencia máxima 260.","efectoArcano":"RM 210 / Presencia máxima 320.","efecto":"Utilizando este conjuro, un Ilusiónista puede hacer desaparecer de la vista cualquier ser u objeto. Afectará a tantos como desee, mientras la suma de sus presencias no supere lo que determina el grado del conjuro. Cualquier individuo que mire hacia los cuerpos invisibles deberá superar automáticamente una RM o no será capaz de detectarlos usando su sentido de la vista.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Imagen espejo', '{"conjuro":"Imagen espejo","via":"Ilusión","nivel":30,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120 / 5 imágenes.","efectoIntermedio":"RM 140 / 10 imágenes.","efectoAvanzado":"RM 160 / 20 imágenes.","efectoArcano":"RM 180 / 50 imágenes.","efecto":"Realiza copias de un blanco determinado. Se trata sólo de imágenes ilusorias, que no podrán estar separadas a más de 10 metros de distancia entre ellas. Como si se tratase de espejos, realizarán los mismos movimientos que el blanco del conjuro. Si algona de ellas es alcanzada por algún impacto que dañe energía, será inmediatamente destruida. Para ver la ilusión, es necesario pasar una RM.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ilusión total', '{"conjuro":"Ilusión total","via":"Ilusión","nivel":32,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"120 RM.","efectoIntermedio":"160 RM.","efectoAvanzado":"200 RM.","efectoArcano":"240 RM.","efecto":"Forma una ilusión completa, que engaña a los cinco sentido de los afectados. El brujo podrá crear cualquier cosa inanimada. La ilusión será destruida si es alcanzada por ataques que dañen en energía. El conjuro afectará a cualquiera capaz de ver, oír o sentir la ilusión y que no supere una RM.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Confusión', '{"conjuro":"Confusión","via":"Ilusión","nivel":36,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":70,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"140 RM.","efectoIntermedio":"160 RM.","efectoAvanzado":"180 RM.","efectoArcano":"200 RM.","efecto":"Confunde los sentidos de un individuo, provocando un penalizador a todas las habilidades secundarias del campo perceptivo equivalnete al nivel de fracaso. Si la difrecncia es mayor de 40, el afectado sufrirá un negativo adicional de -20 a toda acción a causa de los mareos. Un individuo afectado no tiene derecho a un nuevo control  salvo si aumentan sus Resistencias.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear ser ilusorio', '{"conjuro":"Crear ser ilusorio","via":"Ilusión","nivel":40,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 120 / Nivel 2 / 20 metros de radio.","efectoIntermedio":"RM 140 / Nivel 4 / 50 metros de radio.","efectoAvanzado":"RM 160 / Nivel 7 / 100 metros de radio.","efectoArcano":"RM 180 / Nivel 10 / 250 metros de radio.","efecto":"Crea un ser ilusorio que actúa dentro de la zona. Es Ser Entre Mundos. La criatura es ficticia a todos los efectos y no podrá producir daños ni alterar la realidad, y cualquier ataque no basado en energía la atravesará sin producirle daños. Cualquiera que entre en ella tira RM y, si la supera, no verá o sentirá a la criatura, la cual no verá al personaje. La ilusión pude tener como máximo dos niveles por encima del lanzador.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Resistencia a las ilusiones', '{"conjuro":"Resistencia a las ilusiones","via":"Ilusión","nivel":42,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"+20 al RM","efectoIntermedio":"+40 al RM","efectoAvanzado":"+60 al RM","efectoArcano":"+80 al RM","efecto":"Aumenta la Resistencia mágica de un sujeto contra los efectos ilusorios. El conjuro otorga un bonificador a todos a RM contra cualquier conjuro de la via ilusión (o conjuros de naturaleza similar). Los efectos de este hechizo no se superponen, y solo se puede afectar con él una vez a cada sujeto.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detectar mentira', '{"conjuro":"Detectar mentira","via":"Ilusión","nivel":46,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":20,"efectoBase":"RM o RP 120.","efectoIntermedio":"RM o RP 140.","efectoAvanzado":"RM o RP 160.","efectoArcano":"RM o RP 180.","efecto":"Detecta automáticamente cualquier mentira que se diga en presencia del hechicero. Cada vez que alguien mienta conscientemente ante el brujo, deberá superar un contra de RM o RP, o el lanzador se dará cuenta de que no ha dicho la verdad. Si alguien no sabe que esta mintiendo, no es afectado por el hechizo.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ilusión fantasmal', '{"conjuro":"Ilusión fantasmal","via":"Ilusión","nivel":50,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120 / Presencia máxima 60","efectoIntermedio":"RM 150 / Presencia máxima 80","efectoAvanzado":"RM 180 / Presencia máxima 100","efectoArcano":"RM 210 / Presencia máxima 120","efecto":"Crea uno o varios objetos, que se verán sometidos a las reglas de conjuro Fantasmal. Podrá crearse cualquier cosa inanimada que decida el hechicero, desde una espada a un muro siempre y cuando la supuesta presencia del objeto no supere lo que determina el grado del conjuro. Una vez fallada la resistencia, los afectados sólo tendrán derecho a una nueva tirada si encuentran algún motivo o sospecha para dudar de la realidad de la ilusión.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Falsear detección', '{"conjuro":"Falsear detección","via":"Ilusión","nivel":52,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120 / 10 metros de radio.","efectoIntermedio":"RM 140 / 50 metros de radio.","efectoAvanzado":"RM 180 / 250 metros de radio.","efectoArcano":"RM 220 / 500 metros de radio.","efecto":"Puede alterar toda detección de carácter sobrenatural realizada a su alrededor. Podrá falsear la información como desee.  El ser que lanza la detección debe superar RM o es engañado. No funciona contra los individuos que están en de su área de efecto, sino contra la detección. Si alguien intenta detectar algo que está en el radio de acción del sortilegio, incluso si se encuentra fuera del radio del conjuro, deberá superar igualmente la RM.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mentira', '{"conjuro":"Mentira","via":"Ilusión","nivel":56,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 100","efectoIntermedio":"RM 120","efectoAvanzado":"RM 140","efectoArcano":"RM 160","efecto":"Se induce a todo aquel que escuche al mago a creer sus mentiras, por absurdas o ilógicas que sean. Eso no significa que los afectados deban obedecerle, pero sí lo creerán. Cada vez que el Ilusiónista diga una mentira, quienes le escuchen deben de superar una RM o le creerán. En el caso de que la mentira sea excepcionalmente increíble o un individuo esté prevenido hacia esta habilidad, puede aplicar una bono de +40 a su tirada.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir ilusiones', '{"conjuro":"Destruir ilusiones","via":"Ilusión","nivel":60,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":300,"zeonArcano":500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Zeón máximo 80.","efectoIntermedio":"Zeón máximo 140.","efectoAvanzado":"Zeón máximo 200.","efectoArcano":"Zeón máximo 300.","efecto":"Destruye un conjruo activo que pertenezca a la vía de ilusión.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ser fantasmal', '{"conjuro":"Ser fantasmal","via":"Ilusión","nivel":62,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":150,"zeonArcano":200,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 120 / Nivel 2 / 20 metros de radio.","efectoIntermedio":"RM 140 / Nivel 4 / 50 metros de radio.","efectoAvanzado":"RM 160 / Nivel 7 / 100 metros de radio.","efectoArcano":"RM 180 / Nivel 10 / 250 metros de radio.","efecto":"Crea ser ilusorio como Ser Entre Mundos, usando las reglas de creación de seres. Funciona igual que el sortilegio Crear Ser Ilusorio (Ilusión nivel 40) salvo por el hecho de que quien fracase una RM se ve sometido a las reglas de conjuros fantasmales. Es posible realizar un nuevo control sólo si un personjae encuentra duda o  motivo para sospechar de la autenticidad del ser. El fantasma puede tener como máximo tres niveles por encima del lanzador.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Credulidad', '{"conjuro":"Credulidad","via":"Ilusión","nivel":66,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 140","efectoIntermedio":"RM 160","efectoAvanzado":"RM 180","efectoArcano":"RM 200","efecto":"Debilita las Resistencias sobrenaturales de un blanco contra los conjruos ilusorios. El afectado deberá superar una RM o sufrirá un negativo a su RM y RP, equivalente a la cifra por la que falló el contro, aunque únicamente contra hechizos de ilusión.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ataque fantasmal', '{"conjuro":"Ataque fantasmal","via":"Ilusión","nivel":70,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":220,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 140 / Daño 100","efectoIntermedio":"RM 160 / Daño 180","efectoAvanzado":"RM 180 / Daño 250","efectoArcano":"RM 200 / Daño 350","efecto":"Proyecta una descarga de enería fantasmal. El daño se someterá a las reglas de conjuros fantasmales. Dado que el ataque no es real, no puede usarse para chocar contra otras descargas. Puede atacar en cualquier tipología de ataque que desee el lanzador.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'El don de la mentira', '{"conjuro":"El don de la mentira","via":"Ilusión","nivel":72,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":320,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":35,"efectoBase":"RM o RP 140","efectoIntermedio":"RM o RP 160","efectoAvanzado":"RM o RP 180","efectoArcano":"RM o RP 200","efecto":"El Ilusiónista tiene la capacidad de obligar a un individuo a mentir. Puede constreñirle a hacerlo en absolutamente todo lo que diga, o únicamente en un tema determinado. El afectado no podrá indicar a otros que está mintiendo, ni tampoco dar información veraz sobre el tema (o temas) de ningún modo. Si alguien falla la RM o RP, sólo puede repetir el control una vez al día.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vida ilusoria', '{"conjuro":"Vida ilusoria","via":"Ilusión","nivel":76,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":260,"zeonArcano":320,"mantBase":15,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":35,"efectoBase":"RM o RP 140","efectoIntermedio":"RM o RP 160","efectoAvanzado":"RM o RP 180","efectoArcano":"RM o RP 200","efecto":"Introduce recuerdos falsos en la mente de un individuo. El Ilusiónista puede alterar sus recuerdos, incluyendo todos los datos nuevos que desee. Una persona influida por este hechizo no es capaz de diferenciar los recuerdos ilusorios de los suyos propios. Una vez fallado el control, el personaje no tendrá derecho a una nueva tirada, salvo si encuentra motivos para pensar que esos recuerdos son falsos.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ilusión mayor', '{"conjuro":"Ilusión mayor","via":"Ilusión","nivel":80,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":25,"mantIntermedio":35,"mantAvanzado":50,"mantArcano":70,"efectoBase":"RM 120 / 1kilómetro de radio","efectoIntermedio":"RM 160 / 5 kilómetros de radio","efectoAvanzado":"RM 200 / 10 kilómetros de radio","efectoArcano":"RM 240 / 20 kilómetros de radio","efecto":"Crea una gran ilusión que afecta a los cinco sentidos. Se manifiesta en una zona dentro de la cual las personas verán y sentirán todo lo que el hechicero desee. Cualquiera que entre en la zona se verá afectado automáticamente por la ilusión si no supera una RM. Si falla el control, sus sentidos se adaptarán a la mentira, y sólo podrán repetir la Resistencia si encuentran algún motivo de sospecha sobre la autenticidad de lo que hay a su alrededor.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Fijar ilusión', '{"conjuro":"Fijar ilusión","via":"Ilusión","nivel":82,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":250,"zeonIntermedio":360,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"+ 1.000 puntos de Zeón al mantenimiento.","efectoIntermedio":"+ 1.500 puntos de Zeón al mantenimiento.","efectoAvanzado":"+ 3.000 puntos de Zeón al mantenimiento.","efectoArcano":"+ 5.000 puntos de Zeón al mantenimiento.","efecto":"Fija una ilusión a la realidad de forma permanente. A efectos de juego añade puntos de Zeon al mantenimiento de un conjuro de la vía de ilusión. Ten en cuenta que esta cantidad no se suma al poder del hechizo, sino que añade Zeon sólo para pagar su mantenimiento. No puede utilizarse sobe conjuros de Libre Acceso, incluso si pertenecen a la vía de ilusión.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ilusión de sentidos', '{"conjuro":"Ilusión de sentidos","via":"Ilusión","nivel":86,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":250,"zeonAvanzado":300,"zeonArcano":350,"mantBase":20,"mantIntermedio":25,"mantAvanzado":30,"mantArcano":35,"efectoBase":"RM o RP 120.","efectoIntermedio":"RM o RP 150","efectoAvanzado":"RM o RP 190","efectoArcano":"RM o RP 220","efecto":"El mago puede hacer creer cualquier cosa a alguien.Si, por ejemplo, utiliza el conjuro para hacerle pensar que no tiene brazos ni piernas, deja de sentir sus extremidades y cae al suelo pensando que las ha perdido. Si se le dice que está muerto, caerá inconsciente automáticamente. El personaje afectado no tendrá derecho a una nueva Resistencia, salvo si tiene la convicción de que es víctima de un engaño.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inexistencia', '{"conjuro":"Inexistencia","via":"Ilusión","nivel":90,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":25,"mantIntermedio":30,"mantAvanzado":40,"mantArcano":50,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"El objetivo no podrá percibirse per sentidos naturales, aunque sigue siendo material y físico. Tampoco deja rastros o huellas.Solo es percibido por detecciones sobrenaturales; ya sea mágica, psíquica o de Ki. Cualquiera que pueda sentirle mediante algún sentido natural debe superar una RM. Si la falla, sólo tendrá la oportunidad de repetirlo cada vez que tenga una causa para pensar que hay alguien a su alrededor.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Engañar a la muerte', '{"conjuro":"Engañar a la muerte","via":"Ilusión","nivel":92,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":13,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":19,"zeonBase":500,"zeonIntermedio":800,"zeonAvanzado":1200,"zeonArcano":1500,"mantBase":100,"mantIntermedio":160,"mantAvanzado":240,"mantArcano":300,"efectoBase":"Nivel 5.","efectoIntermedio":"Nivel 10.","efectoAvanzado":"Nivel 15.","efectoArcano":"Nivel 20.","efecto":"Se engaña a la muerte. Mientras se encuentre activo, el individuo afectado por él no morirá de ningún modo, puesto que el flujo de almas ignora su presencia y será incapaz dereclamarlo. Aunque su espíritu no saldrá del cuerpo, su forma física puede ser destrozada, y el personaje seguirá sufriendo cualquier efecto perjudicial que le produzca el daño. Este conjuro no protege de un efecto que destruya el alma.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mundo de mentiras', '{"conjuro":"Mundo de mentiras","via":"Ilusión","nivel":96,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":13,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":19,"zeonBase":500,"zeonIntermedio":900,"zeonAvanzado":1400,"zeonArcano":2000,"mantBase":50,"mantIntermedio":90,"mantAvanzado":140,"mantArcano":200,"efectoBase":"RM 140 / 10 Km de radio / 100 niveles a repartir entre seres.","efectoIntermedio":"RM 180 / 100 Km de radio / 500 niveles a repartir entre seres.","efectoAvanzado":"RM 220 / 1000 Km de radio/ 1.500 niveles a repartir entre seres.","efectoArcano":"RM 260 / 10.000 Km de radio / 5.000 niveles a repartir entre seres","efecto":"Crea una realidad de mentiras, todas las Ilusiónes serán fantasmales, y cualquiera que entre debe superar RM para no verse influido. Permite crear criaturas irreales. El mago podrá dar niveles a esas entidades, ninguna de ellas, podrá tener más de la mitad de su nivel (redondeando hacia arriba). Los fantasmas son creados como Seres Entre Mundos. Los personajes que entren en el área y fallen el control de resistencia sólo podrán repetirlo cuando tengan alguna duda.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'La falsa realidad', '{"conjuro":"La falsa realidad","via":"Ilusión","nivel":100,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":19,"zeonBase":600,"zeonIntermedio":1000,"zeonAvanzado":2000,"zeonArcano":3000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 140","efectoIntermedio":"RM 180","efectoAvanzado":"RM 220","efectoArcano":"RM 240","efecto":"Hace realidad algo que no ocurrio. Permite inventar acontecimientos y que repercutan en el presente. No puede realizar imposibles, sólo alterar acontecimientos posibles. La RM es la mayor de lo afectado en la mentira. En el caso de que se cambiara algún acontecimiento que implicase que un difunto volviese a la vida, lo haría sin alma y sin personalidad. No afecta a características o nivel de seres. Tampoco involucrar a un ser con Gnosis mayor al mago.","_seccion":"ILUSION"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sentir la muerte', '{"conjuro":"Sentir la muerte","via":"Nigromancia","nivel":2,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"100 metros de radio / RM 120","efectoIntermedio":"250 metros de radio / RM 140","efectoAvanzado":"500 metros de radio / RM 160","efectoArcano":"1 kilometro de radio / RM 180","efecto":"El nigromante detecta, automáticamente, cualquier fallecimiento que ocurra en un radio a su alrededor. Este hechizo es también capaz de revelar criaturas no muertas, aunque estas tendrán derecho a una RM para evitar ser encontradas.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ver el mas allá', '{"conjuro":"Ver el mas allá","via":"Nigromancia","nivel":6,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Permite ver seres espectrales","efectoIntermedio":"Permite ver seres espectrales y almas que esperan El Llamamiento.","efectoAvanzado":"Permite ver toda clase de ser espiritual","efectoArcano":"Permite ver toda clase de ser espiritual o sobrenatural","efecto":"Permite ver ciertas clases de seres espirituales invisibles al ojo humano.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Dominar a los carroñeros', '{"conjuro":"Dominar a los carroñeros","via":"Nigromancia","nivel":8,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":11,"intRArcano":13,"zeonBase":40,"zeonIntermedio":120,"zeonAvanzado":200,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"10 metros de radio","efectoIntermedio":"150 metros de radio","efectoAvanzado":"500 metros de radio","efectoArcano":"2 kilometros de radio","efecto":"Otorga al brujo un control absoluto sobre cualquier alimaña carroñera. La consideración de alimaña carroñera es la de toda criatura de naturaleza inferior, es decir, con presencia 20 o inferior, que se alimente generalmente de los muertos. Cuervos, gusanos y otros muchos insectos encajan perfectamente dentro de esta descripción.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo espectral', '{"conjuro":"Escudo espectral","via":"Nigromancia","nivel":10,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":40,"zeonIntermedio":60,"zeonAvanzado":80,"zeonArcano":100,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Detiene Resistencias de hasta 140","efectoIntermedio":"Detiene Resistencias de hasta 180","efectoAvanzado":"Detiene Resistencias de hasta 220","efectoArcano":"Detiene Resistencias de hasta 260","efecto":"Forma un escudo de energía nigromántica, capaz de detener cualquier asalto anímico que afecte a las Resistencias sobrenaturales del personaje, aunque no así de acometidas de carácter físico o ataques que produzcan daños. Permite detener efectos místicos, siempre que estos no obliguen a lanzar una Resistencia contra más de lo que determine el grado del conjuro.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Drenar vida', '{"conjuro":"Drenar vida","via":"Nigromancia","nivel":12,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":14,"zeonBase":50,"zeonIntermedio":140,"zeonAvanzado":230,"zeonArcano":320,"efectoBase":"RM 100","efectoIntermedio":"RM 140","efectoAvanzado":"RM 180","efectoArcano":"RM 240","efecto":"Permite absorber parte de la vida de otro ser, dañándolo a la vez que el mago se fortalece. El objetivo debe tirar RM o perderá una cantidad de puntos de vida equivalente al nivel de fracaso, los cuales curanrán al mago. Los seres de acumulación pierden cinco veces esa cantidad, pero el brujo, sólo recupera una quinta parte (es decir, si un ser con acumulación de daño falla el control por 20 puntos, perdería 100 PV, aunque el nigromante solo absorbería 20).","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detección nigromántica', '{"conjuro":"Detección nigromántica","via":"Nigromancia","nivel":16,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"RM 120 / 20 metros de radio","efectoIntermedio":"RM 160 / 50 metros de radio","efectoAvanzado":"RM 200 / 100 metros de radio","efectoArcano":"RM 240 / 150 metros de radio","efecto":"Permite al nigromante detectar la presencia de cualquier criatura viva o muerta que se encuentre cerca de él. Para resistirse a sus efectos, hay que superar una RM.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Hablar con los muertos', '{"conjuro":"Hablar con los muertos","via":"Nigromancia","nivel":18,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":5,"efectoBase":"Nivel 4","efectoIntermedio":"Nivel 8","efectoAvanzado":"Nivel 12","efectoArcano":"Nivel 16","efecto":"Este hechizo confiere al nigromante la capacidad de comunicarse con almas y espíritus de seres muertos que se encuentren a su alrededor, incluso si no es consciente de su posición exacta. El nivel del espíritu es el que determina si este puede o no escucharle.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Paralización Nigromántica', '{"conjuro":"Paralización Nigromántica","via":"Nigromancia","nivel":20,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"10 metros de radio / RM 120","efectoIntermedio":"25 metros de radio / RM 140","efectoAvanzado":"50 metros de radio / RM 160","efectoArcano":"100 metros de radio / RM 180","efecto":"Este conjuro congela la esencia sobrenatural de las criaturas no muertas, conteniéndolas y haciendo que sean incapaces de moverse. Cualquier ser nigromántico, en un radio respecto al brujo, queda automáticamente sometido a paralización completa si no es capaz de superar un control de RM.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Necromitud', '{"conjuro":"Necromitud","via":"Nigromancia","nivel":22,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"efectoBase":"50 puntos de vida","efectoIntermedio":"100 puntos de vida","efectoAvanzado":"150 puntos de vida","efectoArcano":"250 puntos de vida","efecto":"Hace recuperar puntos de vida a una criatura nigromántica. No tiene ningún efecto sobre seres vivos.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descarga de muerte', '{"conjuro":"Descarga de muerte","via":"Nigromancia","nivel":26,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"efectoBase":"Daño 80","efectoIntermedio":"Daño 100","efectoAvanzado":"Daño 140","efectoArcano":"Daño 180","efecto":"Proyecta una potente descarga nigromántica. El ataque se realiza en la TA de energía.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Levantar cadáveres', '{"conjuro":"Levantar cadáveres","via":"Nigromancia","nivel":28,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":300,"zeonArcano":450,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"100 puntos de presencia (Nivel máximo 0)","efectoIntermedio":"300 puntos de presencia (Nivel máximo 1)","efectoAvanzado":"600 puntos de presencia (Nivel máximo 2)","efectoArcano":"1.000 puntos de presencia (Nivel máximo 3)","efecto":"Se puede animar cadáveres y convertirlos en zombis o esqueletos bajo su control. No conservan nada de su vida, pero si capacidades básicas, armas naturales. El poder y resistencia del ser varía dependiendo de su cuerpo. Puede animar entre una o varias criaturas hasta un valor de presencia, siempre que ninguno de los no muertos levantados supere el nivel que determina el grado del conjuro.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cuerpo muerto', '{"conjuro":"Cuerpo muerto","via":"Nigromancia","nivel":30,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Personajes de Nivel 3","efectoIntermedio":"Personajes de Nivel 6","efectoAvanzado":"Personajes de Nivel 12","efectoArcano":"Personajes de Nivel 18","efecto":"Detiene temporalmente las funciones corporales de un individuo sin matarlo, aunque puede moverse y actuar con normalidad. Mientras permanezca activo, el ser será extremadamente resistente a los efectos del daño y sus consecuencias, los penalizadores físicos quedan reducidos a la mitad. Se mantiene consciente y sin negativos (salvo por críticos) en el estado de entre la vida y la muerte. No se puede saber que no se trata de un verdadero cadáver.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Drenar magia', '{"conjuro":"Drenar magia","via":"Nigromancia","nivel":32,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":140,"zeonAvanzado":220,"zeonArcano":300,"efectoBase":"RM 140","efectoIntermedio":"RM 180","efectoAvanzado":"RM 220","efectoArcano":"RM 260","efecto":"Permite drenar la energía mágica de un individuo u objeto y otorgársela al nigromante. Quienquiera que sea afectado por el conjuro, deberá realizar un control de RM, o perderá una cantidad de puntos de Zeon equivalente al doble del nivel de fracaso, que será inmediatamente absorbida por el brujo.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destruir no muertos', '{"conjuro":"Destruir no muertos","via":"Nigromancia","nivel":36,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":320,"efectoBase":"RM 140","efectoIntermedio":"RM 180","efectoAvanzado":"RM 220","efectoArcano":"RM 260","efecto":"Este conjuro destruye completamente la esencia de los no muertos. Cualquier ser nigromántico que sea su blanco deberá superar un control de RM o sufrir un daño equivalente al doble de su nivel de fracaso. Si tiene acumulación, sufre diez veces dicha cantidad.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Drenar características', '{"conjuro":"Drenar características","via":"Nigromancia","nivel":38,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":150,"zeonAvanzado":240,"zeonArcano":320,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 140","efectoIntermedio":"RM 180","efectoAvanzado":"RM 220","efectoArcano":"RM 260","efecto":"Roba capacidades de seres, aumentando las suyas. El mago decide que característica drenar, antes de tirar. El objetivo perderá un punto de ese atributo por cada 10 que no supere RM. Si el valor natural de las características drenadas es mayor a las del mago, cada punto aumenta en uno la suya. Si es menor, necesita tres para sumar uno. Mientras se mantenga, se conserva los atributos incrementados. se recupera un punto por hora, una vez que termina el hechizo.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Controlar a los muertos', '{"conjuro":"Controlar a los muertos","via":"Nigromancia","nivel":40,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":250,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"20 metros de radio / RM 120","efectoIntermedio":"50 metros de radio / RM 140","efectoAvanzado":"100 metros de radio / RM 160","efectoArcano":"150 metros de radio / RM 180","efecto":"Obtiene el control de todo no muerto en el área. El dominio permanece activo mientras el hechizo se mantenga, pero no afecta a otras criaturas que se acerquen con posterioridad. Los no muertos pueden evitar el control, superando una RM. Las entidades sólo tienen derecho a repetir la tirada si reciben una orden que vaya en contra de su naturaleza, por lo que las criaturas sin voluntad, como los cadáveres animados, nunca pueden liberarse.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Marchitar la vida', '{"conjuro":"Marchitar la vida","via":"Nigromancia","nivel":42,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":220,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"10 metros de radio","efectoIntermedio":"20 metros de radio","efectoAvanzado":"30 metros de radio","efectoArcano":"50 metros de radio","efecto":"Este conjuro crea un área de energía nigromántica que mata de inmediato cualquier forma de vida inferior que se encuentre alrededor del brujo, como pequeños animales y plantas. Todo ser vivo con una presencia 20 o inferior se pudre o marchita a gran velocidad sin derecho a ningún control de Resistencia.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo nigromántico', '{"conjuro":"Escudo nigromántico","via":"Nigromancia","nivel":46,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"1.000 puntos de Resistencia","efectoIntermedio":"2.000 puntos de Resistencia","efectoAvanzado":"3.500 puntos de Resistencia","efectoArcano":"5.000 puntos de Resistencia","efecto":"Empleando la esencia de almas muertas, forma un escudo de energía que protege frente a cualquier clase de ataque.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Dominar la vida', '{"conjuro":"Dominar la vida","via":"Nigromancia","nivel":48,"diario":"Si","tipo":"Anímico","accion":"Pasiva","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":30,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"RM 100","efectoIntermedio":"RM 120","efectoAvanzado":"RM 140","efectoArcano":"RM 160","efecto":"Permite al brujo esclavizar el alma de un ser vivo, sometiéndolo a un control similar al que tiene sobre sus criaturas no muertas. El personaje podrá resistirse superando un control de RM. El individuo tendrá derecho a una nueva Resistencia por día, y en cada ocasión en la que las órdenes recibidas vayan completamente en contra de su comportamiento.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Estigma vampírico', '{"conjuro":"Estigma vampírico","via":"Nigromancia","nivel":50,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"20% de absorción","efectoIntermedio":"40% de absorción","efectoAvanzado":"60% de absorción","efectoArcano":"100% de absorción","efecto":"El personaje sobre el que se lance este conjuro obtiene la capacidad de absorber, automáticamente, un porcentaje del daño que produzca personalmente a sus adversarios. Funciona tanto con ataques físicos como con conjuros de daño directo o poderes equivalentes. En el caso de los seres con acumulación, la cantidad absorbida se divide por el múltiplo de acumulación de la criatura.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Forma espectral', '{"conjuro":"Forma espectral","via":"Nigromancia","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"El brujo es inmaterial y sólo puede ser dañado por ataques que afecten energia","efectoIntermedio":"si lo tocan, RF o RM (PREx2) o negativo acción y vida = ½ fracaso","efectoAvanzado":"pero gana vida = a la cantidad que pierde ser que lo toco.","efectoArcano":"Si falla la RM o RF por más de 40 puntos muere","efecto":"El cuerpo físico del nigromante se convierte en una crepitante masa espectral, que daña la esencia de cualquier ser vivo que se ponga en contacto con ella.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Modificación nigromántica', '{"conjuro":"Modificación nigromántica","via":"Nigromancia","nivel":56,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":10,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"100 PD","efectoIntermedio":"200 PD","efectoAvanzado":"300 PD","efectoArcano":"400 PD","efecto":"La entidad no muerta blanco de este hechizo se alimenta de su energía, adquiriendo temporalmente nuevos poderes y habilidades. Un no muerto obtiene PD adicionales para obtener Poderes Especiales detallados en el Capítulo 26, como si se tratase de una criatura con Gnosis 25. No puede usarse sobre seres vivos. Los efectos de este hechizo no se superponen, y sólo puede afectar uno de ellos a la vez a un mismo sujeto.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Llamar a los muertos', '{"conjuro":"Llamar a los muertos","via":"Nigromancia","nivel":58,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":160,"zeonArcano":180,"efectoBase":"Nivel máximo 3","efectoIntermedio":"Nivel máximo 6","efectoAvanzado":"Nivel máximo 9","efectoArcano":"Nivel máximo 12","efecto":"Este conjuro atrae hasta el nigromante las almas de personas fallecidas o de espectros. El brujo es quien elige a qué espíritu llama, aunque en el caso de que este no pueda responderle, es posible que se presente alguna otra alma en su lugar. Llamar a los Muertos sólo funciona con espíritus que permanecen atados al mundo o con criaturas espectrales, por lo que no tiene poder sobre almas que ya hayan transmigrado.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Levantar espectros', '{"conjuro":"Levantar espectros","via":"Nigromancia","nivel":60,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"mantBase":20,"mantIntermedio":25,"mantAvanzado":30,"mantArcano":35,"efectoBase":"Nivel máximo del espíritu 1 / Suma total de presencias 100","efectoIntermedio":"Nivel máximo del espíritu 2 / Suma total de presencias 160","efectoAvanzado":"Nivel máximo del espíritu 4 / Suma total de presencias 220","efectoArcano":"Nivel máximo del espíritu 6 / Suma total de presencias 280","efecto":"Convierte almas de muertos en espectros a su servicio. Conservan parte de sus capacidades en vida. Un espectro, reduce a la mitad el nivel de vivo (redondeado hacia arriba), y tiene 100 PD más que el mago usa para darle los poderes como ser con Gnosis 20. Sólo funciona sobre almas recién fallecidas y que esperen el llamamiento. Puede afectar a varios espectros a la vez, siempre que la suma de sus presencias no supere lo que determine el grado del conjuro.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Drenar fuerza vital', '{"conjuro":"Drenar fuerza vital","via":"Nigromancia","nivel":62,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":180,"zeonIntermedio":240,"zeonAvanzado":300,"zeonArcano":360,"efectoBase":"RM 100","efectoIntermedio":"RM 130","efectoAvanzado":"RM 160","efectoArcano":"RM 190","efecto":"Absorbe la fuerza vital de un ser y se pasa al objetivo. El blanco debe superar RM o perder un punto de Constitución y de Poder por cada 10 que falle. Si se quiere, el objetivo envejece tantos años como nivel de fracaso. Los puntos absorbidos permiten al mago o al sujeto que los reciba, recuperar atributos perdidos hasta sus niveles iniciales o rejuvenecer. El personaje al que se le arranca la fuerza vital no la recupera, salvo con habilidades sobrenaturales.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Matar', '{"conjuro":"Matar","via":"Nigromancia","nivel":66,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":220,"efectoBase":"RM o RF 80","efectoIntermedio":"RM o RF 100","efectoAvanzado":"RM o RF 120","efectoArcano":"RM o RF 140","efecto":"Este conjuro detiene las funciones vitales de una persona, produciéndole de inmediato la muerte. Este hechizo sólo funciona sobre seres vivos, por lo que resulta virtualmente inútil contra espíritus o Seres Entre Mundos inanimados. Cualquier afectado deberá superar un control de RM o RF si quiere sobrevivir.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descarga de almas', '{"conjuro":"Descarga de almas","via":"Nigromancia","nivel":68,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":140,"zeonIntermedio":260,"zeonAvanzado":380,"zeonArcano":500,"efectoBase":"Daño 100","efectoIntermedio":"Daño 200","efectoAvanzado":"Daño 300","efectoArcano":"Daño 400","efecto":"Proyecta una descarga de energía mágica compuesta por almas marchitas. Este conjuro ataca en Energía. Sólo afecta a seres con alma, por lo que ignora los cuerpos físicos sin vida, como paredes o golems. Dada la naturaleza de la descarga, únicamente aquellos con la capacidad de ver espíritus son capaces de percibirla.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Quimera nigromántica', '{"conjuro":"Quimera nigromántica","via":"Nigromancia","nivel":70,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":360,"zeonAvanzado":500,"zeonArcano":800,"mantBase":50,"mantIntermedio":80,"mantAvanzado":100,"mantArcano":160,"efectoBase":"Nivel 2","efectoIntermedio":"Nivel 6","efectoAvanzado":"Nivel 10","efectoArcano":"Nivel 13","efecto":"Se crea una criatura no muerta sometida al mago desarrollada como Ser Entre Mundos de Gnosis 25. No se puede crear a la criatura de la nada, hay que reunir partes de cadáveres con los que darle forma. Para otorgarle cualquier poder o habilidad esencial que desee, ha de conseguir cuerpos de seres que los tuvieran. Puesto que la existencia de la quimera se encuentra directamente atada al mago, para calcular su nivel máximo es igual que el conjuro Crear Ser.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Perversion de vida', '{"conjuro":"Perversion de vida","via":"Nigromancia","nivel":72,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":18,"zeonBase":180,"zeonIntermedio":240,"zeonAvanzado":300,"zeonArcano":360,"efectoBase":"RM o RF 100","efectoIntermedio":"RM o RF 140","efectoAvanzado":"RM o RF 180","efectoArcano":"RM o RF 220","efecto":"Este conjuro corrompe la esencia de un ser vivo y detiene sus funciones físicas, transformándolo de inmediato en un ente no muerto. El personaje afectado mantendrá las mismas características y habilidades que tenía en vida, aunque en su estado de cadáver animado conseguirá, naturalmente, la ventaja de exención física. Para evitar la transformación, es necesario superar una RM o RF.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vasallaje', '{"conjuro":"Vasallaje","via":"Nigromancia","nivel":76,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":18,"zeonBase":250,"zeonIntermedio":360,"zeonAvanzado":450,"zeonArcano":540,"efectoBase":"RM o RF 100","efectoIntermedio":"RM o RF 140","efectoAvanzado":"RM o RF 180","efectoArcano":"RM o RF 220","efecto":"Ata eternamente la esencia de una criatura no muerta al mago, convirtiendolo en su superior jerárquico, y haciendo que la existencia de la entidad dependa de este. Aunque no otorga al nigromante control sobre la criatura, la vida del vasallo está unida a la de su maestro, conllevando que si el “amo” es destruido, también perezca el “súbdito”. Un no muerto puede resistirse al vasallaje superando una RM o RF, pero una vez fallada la unión no puede romperse.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Drenar almas', '{"conjuro":"Drenar almas","via":"Nigromancia","nivel":78,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"Se drena el alma del objetivo que o supera una RM o pierde presencia igual a la mitad de nivel de fracaso. Por 5 puntos perdidos resta un nivel  y cualquier capacidad o poder que dependiera de este. Si llega a cero muere. Por cada 10 puntos que sume, incrementa temporalmente una característica en +1, u obtiene 10 PD para poderes o habilidades esenciales de monstruos de Gnosis 30. Se pierde cada día un punto de característica o 20 de los PD incrementados.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Superar la muerte', '{"conjuro":"Superar la muerte","via":"Nigromancia","nivel":80,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":500,"zeonAvanzado":1000,"zeonArcano":2500,"mantArcano":".","efectoBase":"Mas 100 PD / hasta 100 PD opcionales en desventajas","efectoIntermedio":"Mas 200 PD / hasta 100 PD opcionales en desventajas","efectoAvanzado":"Mas 300 PD / hasta 200 PD opcionales en desventajas","efectoArcano":"Mas 400 PD / hasta 200 PD opcionales en desventajas","efecto":"El Blanco se convierte en no muerto. Lanzado en el instante en el que el personaje fallece o escasos segundos antes. El mago decide si será un Ser Entre Mundos o  un Espíritu, tendrá Gnosis 25. Gana PD para elegir habilidades esenciales o poderes, si opta por ser espectro, deberá invertir 100 PD. Puede escoger PD en desventajas y penalizadores, que dan más puntos. El exceso de PD aumenta su nivel.  Sólo funciona sobre seres vivos en el momento de morir.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alzamiento', '{"conjuro":"Alzamiento","via":"Nigromancia","nivel":82,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":350,"zeonIntermedio":500,"zeonAvanzado":800,"zeonArcano":1200,"efectoBase":"Nivel máximo 3","efectoIntermedio":"Nivel máximo 6","efectoAvanzado":"Nivel máximo 9","efectoArcano":"Nivel máximo 12","efecto":"Alza un cadáver conservando todos los poderes, conocimientos y habilidades que tenía en vida. Carece de alma. Afecta a cualquier individuo o criatura fallecida cuyo cadáver esté al alcance del mago, siempre y cuando su nivel no sea mayor de lo que diga el grado del conjuro. Si el cuerpo se encuentra en mal estado, sus habilidades físicas pueden perjudicarse. Alguien levantado no puede volver a ser alzado. El cadaver no está controlado por el mago.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Pozo de vida', '{"conjuro":"Pozo de vida","via":"Nigromancia","nivel":86,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":300,"zeonIntermedio":400,"zeonAvanzado":500,"zeonArcano":600,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"50 metros de radio","efectoIntermedio":"250 metros de radio","efectoAvanzado":"500 metros de radio","efectoArcano":"1 kilometro de radio","efecto":"Como un vacío que se alimenta del daño que sufren los demás, el nigromante absorbe la mitad de los puntos de vida perdidos por los seres vivos que se encuentren a su alrededor, sin posible resistencia alguna. Estos PV le sirven para restituir cualquier clase de herida que haya sufrido.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Tierra maldita', '{"conjuro":"Tierra maldita","via":"Nigromancia","nivel":88,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":350,"zeonIntermedio":600,"zeonAvanzado":900,"zeonArcano":1500,"mantBase":35,"mantIntermedio":60,"mantAvanzado":90,"mantArcano":150,"efectoBase":"1 kilómetro de radio","efectoIntermedio":"10 kilómetros de radio","efectoAvanzado":"100 kilómetros de radio","efectoArcano":"1.000 kilómetros de radio","efecto":"El mago encanta una zona, todo ser que fallezca dentro se levanta como un no muerto bajo su control. Los difuntos se convierten en cadáveres animados, los seres naturales cuyo Gnosis sea al menos 5 puntos superior a su natura, se levantan como un espectro. Las criaturas sólo pueden actuar dentro de la tierra maldita. Si salen de ella, la magia que los sustenta desaparece. El conjuro afecta una zona de terreno que permanece estática en el lugar donde fue lanzada.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sostenimiento', '{"conjuro":"Sostenimiento","via":"Nigromancia","nivel":90,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":16,"intRArcano":18,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"efectoBase":"Hasta 60 de presencia","efectoIntermedio":"Hasta 120 de presencia","efectoAvanzado":"Hasta 240 de presencia","efectoArcano":"Hasta 480 de presencia","efecto":"Afecta a la esencia de una o varias criaturas no muertas que se hallen sostenidas por un conjuro, permitiéndoles seguir existiendo incluso después de que el nigromante deje de pagar su mantenimiento. Afecta a tantos no muertos como desee el nigromante, siempre y cuando la suma de sus presencias no sea superior a lo que determine el grado del conjuro.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Materia prima', '{"conjuro":"Materia prima","via":"Nigromancia","nivel":92,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":350,"zeonIntermedio":500,"zeonAvanzado":900,"zeonArcano":1500,"efectoBase":"1.000 cuerpos humanos","efectoIntermedio":"10.000 cuerpos humanos","efectoAvanzado":"100.000 cuerpos humanos","efectoArcano":"1.000.000 cuerpos humanos","efecto":"Este hechizo genera las energías corruptas que utiliza la magia nigromántica para alzar cadáveres y espectros, permitiendo al lanzador crear de la nada materia prima con la que levantar cadáveres posteriormente. El conjuro forma material nigromántico equivalente a cierta cantidad de cuerpos humanos muertos o, en su defecto, a una cantidad menor de otras criaturas más poderosas.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Señor de los muertos', '{"conjuro":"Señor de los muertos","via":"Nigromancia","nivel":96,"diario":"Si","tipo":"Auto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":300,"zeonIntermedio":600,"zeonAvanzado":1000,"zeonArcano":2000,"mantBase":30,"mantIntermedio":60,"mantAvanzado":100,"mantArcano":200,"efectoBase":"100 kilómetros de radio / 140 RM","efectoIntermedio":"1.000 kilómetros de radio / 160 RM","efectoAvanzado":"10.000 kilómetros de radio / 180 RM","efectoArcano":"100.000 kilómetros de radio / 200 RM","efecto":"El Señor de los Muertos extiende su presencia por el mundo, obteniendo el control absoluto de todas las criaturas no muertas que se encuentren a su alrededor. Cualquiera de estos seres que esté dentro del área del conjuro deberá superar una RM o será completamente controlado por el lanzador. Si pasa la Resistencia, ya no tiene que volver a realizarla. Los afectados tienen derecho a un nuevo control únicamente si alteran sus Resistencias.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Regresar de entre los muertos', '{"conjuro":"Regresar de entre los muertos","via":"Nigromancia","nivel":98,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":16,"intRIntermedio":17,"intRAvanzado":18,"intRArcano":19,"zeonBase":400,"zeonIntermedio":800,"zeonAvanzado":1600,"zeonArcano":3200,"mantArcano":".","efectoBase":"Nivel 4 máximo / Un mes como máximo desde su muerte","efectoIntermedio":"Nivel 8 máximo / Un año como máximo desde su muerte","efectoAvanzado":"Nivel 12 máximo / Una decada como máximo desde su muerte","efectoArcano":"Nivel 16 máximo / Un siglo como máximo desde su muerte","efecto":"Devuelve al mundo el espíritu de una criatura difunta, incluso si ha regresado al flujo de almas o su esencia ha sido dispersada. El ser vuelve como no muerto, pero conservando su alma y su esencia. Si el cuerpo del fallecido aún sigue existiendo, regresará a él. Puede encarnar uno nuevo o convertirse en un espectro. El tiempo que haya transcurrido entre la muerte y su regreso condicionan el conjuro. No es posible resucitar un alma reencarnada o destruida.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'El despertar', '{"conjuro":"El despertar","via":"Nigromancia","nivel":100,"diario":"No","tipo":"Auto","accion":"Activa","intRBase":17,"intRIntermedio":18,"intRAvanzado":19,"intRArcano":20,"zeonBase":900,"zeonIntermedio":2000,"zeonAvanzado":3500,"zeonArcano":5000,"mantBase":45,"mantIntermedio":100,"mantAvanzado":175,"mantArcano":250,"efectoBase":"Nivel 4","efectoIntermedio":"Nivel 8","efectoAvanzado":"Nivel 12","efectoArcano":"Nivel 15","efecto":"El mago devuelve la vida a los muertos y los somete a su dominio. El Despertar no tiene un radio de acción determinado; afecta por igual a cualquier difunto cuyo nivel no fuese superior a lo que determine el grado del conjuro. Si sus espíritus esperan aún el llamamiento, se levantan como espectros o, en caso contrario, como cadáveres animados. Aquellos seres cuyo gnosis sea al menos 15 puntos superior a su Natura, regresa como no muerto con sus facultades plenas.","_seccion":"NIGROMANCIA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Apertura', '{"conjuro":"Apertura","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":140,"efectoBase":"80 en Cerrajería","efectoIntermedio":"140 en Cerrajería","efectoAvanzado":"240 en Cerrajería","efectoArcano":"280 en Cerrajería","efecto":"Permite abrir cualquier puerta cerrada utilizando una habilidad final en Cerrajería determinada por el grado del conjuro.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mover objetos', '{"conjuro":"Mover objetos","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":70,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"10 kilogramos","efectoIntermedio":"50 kilogramos","efectoAvanzado":"100 kilogramos","efectoArcano":"150 kilogramos","efecto":"Este conjuro mueve artefactos inorgánicos sin la necesidad de que exista contacto físico con ellos, otorgándoles un Tipo de Vuelo 10. El peso máximo es determinado por el grado del conjuro.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aseamiento', '{"conjuro":"Aseamiento","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":100,"zeonArcano":140,"efectoBase":"Presencia máxima 40","efectoIntermedio":"Presencia máxima 80","efectoAvanzado":"Presencia máxima 120","efectoArcano":"Presencia máxima 140","efecto":"Elimina cualquier impureza física menor (como suciedad, mal olor…), en el cuerpo y ropas del objetivo del conjuro. También puede ser utilizado sobre lugares u objetos para sanearlos, siempre que la presencia de estos no supere a lo que determina el grado del conjuro.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detección mágica', '{"conjuro":"Detección mágica","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"25 metros de radio / 140 Valoración mágica","efectoIntermedio":"100 metros de radio / 180 Valoración mágica","efectoAvanzado":"200 metros de radio / 200 Valoración mágica","efectoArcano":"300 metros de radio / 240 Valoración mágica","efecto":"El hechicero detecta automáticamente cualquier fuente de magia a su alrededor. Si está oculta, emplea una habilidad de Valoración Mágica final determinada por el grado del conjuro para detectarla.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear música', '{"conjuro":"Crear música","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"10 metros de radio / 80 en Música","efectoIntermedio":"50 metros de radio / 120 en Música","efectoAvanzado":"150 metros de radio / 180 en Música","efectoArcano":"250 metros de radio / 240 en Música","efecto":"Crea una melodía audible para todos aquellos que se encuentren en el radio de acción del hechizo. La calidad musical de la composición será realizada con el equivalente a una habilidad final en Música determinada por el grado del conjuro. Sólo puede reproducir temas que el lanzador conozca, aunque sea de un modo vago.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Atar', '{"conjuro":"Atar","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"efectoBase":"120 en Trucos de Manos","efectoIntermedio":"140 en Trucos de Manos","efectoAvanzado":"180 en Trucos de Manos","efectoArcano":"240 en Trucos de Manos","efecto":"Hace que cuerdas, cadenas o cualquier tipo de filamento, se anuden con una habilidad final en Trucos de Manos determinada por el grado del conjuro. Se puede ordenar que aten a un sujeto, el blanco se defendera contra un ataque de Habilidad final igual a Trucos de Manos del conjuro. La Fuerza de la sujeción dependerá del material. Una cuerda muy gruesa tendría una Fuerza 10, unas cadenas tendrian 12. Las cuerdas no son creadas por el hechizo.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear llamas', '{"conjuro":"Crear llamas","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":110,"zeonArcano":130,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"1 intensidad","efectoIntermedio":"3 intensidades","efectoAvanzado":"6 intensidades","efectoArcano":"9 intensidades","efecto":"Crea intensidades de fuego en una materia que sea naturalmente inflamable. Si prende, no será necesario mantener el conjuro.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Deshacer escritura', '{"conjuro":"Deshacer escritura","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantArcano":".","efectoBase":"Presencia máxima del objeto 30 / Hace desaparecer 500 caracteres","efectoIntermedio":"Presencia máxima del objeto 60 / Hace desaparecer 5.000 caracteres","efectoAvanzado":"Presencia máxima del objeto 90 / Hace desaparecer 50.000 caracteres","efectoArcano":"Presencia máxima del objeto 120 / Hace desaparecer 250.000 caracteres","efecto":"El conjuro hace desaparecer cierta cantidad de caracteres de texto sobre un objeto o superficie. No destruye la materia sobre la que se haya escrito, sino que elimina las letras o caracteres. Por ejemplo, en una hoja de papel desaparecería la tinta, mientras que en un grabado se rellenaría la piedra.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detener caída', '{"conjuro":"Detener caída","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":160,"zeonArcano":240,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"50 metros de caída / Presencia máxima 60","efectoIntermedio":"150 metros de caída / Presencia máxima 160","efectoAvanzado":"500 metros de caída / Presencia máxima 240","efectoArcano":"Cualquier distancia de caída / Presencia máxima 320","efecto":"Anula los efectos de una caída desde gran altura. En juego, suprime completamente el impacto sufrido al caer de una distancia elevada, o lo reduce equivalentemente en mayores distancias. Puede afectar a varios blancos, siempre que la suma de sus presencias no superen lo que determina el grado del conjuro.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mensaje estático', '{"conjuro":"Mensaje estático","via":"Libre acceso","nivel":2,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":70,"zeonAvanzado":120,"zeonArcano":180,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Máximo de 50 palabras","efectoIntermedio":"Máximo de 150 palabras","efectoAvanzado":"Máximo de 250 palabras","efectoArcano":"Máximo de 500 palabras","efecto":"Marca un lugar u objeto con un mensaje escrito. El hechicero podrá hacer que aparezca y desaparezca a voluntad, incluso si no está presente (aunque no por ello sabe si hay alguien allí para leerlo).","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Saltar', '{"conjuro":"Saltar","via":"Libre acceso","nivel":2,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":140,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"+50 a Saltar","efectoIntermedio":"+100 a Saltar","efectoAvanzado":"+150  a Saltar / Pernite alcanzar la dificultad de Inhumano en los controles","efectoArcano":"+200 a Saltar/ Permite alcanzar la dificultad de Zen en los controles","efecto":"El individuo afectado por este hechizo aumenta sobrenaturalmente su capacidad de saltar. El conjuro añade un bono a la base de la habilidad secundaria Saltar.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cambiar de color', '{"conjuro":"Cambiar de color","via":"Libre acceso","nivel":2,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"Presencia máxima 40 / RM 100","efectoIntermedio":"Presencia máxima 60 / RM 120","efectoAvanzado":"Presencia máxima 80 / RM 140","efectoArcano":"Presencia máxima 100 / RM 160","efecto":"Este conjuro cambia el color de una materia, objeto o incluso persona cuya presencia no sea superior a lo que determina el grado del conjuro. Para resistirse, hace falta superar una RM. Alguien afectado no tiene derecho a una nueva resistencia mientras el conjuro se mantenga.","_seccion":"LIBRE ACCESO 1-10"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear sonidos', '{"conjuro":"Crear sonidos","via":"Libre acceso","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"A 50 metros","efectoIntermedio":"A 200 metros","efectoAvanzado":"A 500 metros","efectoArcano":"A 1 kilometro","efecto":"Crea un sonido en un lugar determinado","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Recrear imagen', '{"conjuro":"Recrear imagen","via":"Libre acceso","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":40,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":130,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Imagen de 1 metro cuadrado","efectoIntermedio":"Imagen de 5 metros cuadrados","efectoAvanzado":"Imagen de 10 metros cuadrados","efectoArcano":"15 metros² /Imagen realista, Advertir a 140 o Buscar a 80 para darse cuenta","efecto":"Recrea la imagen de algo que el hechicero ha visto con anterioridad. La aparición se trata de un holograma translúcido y sin sustancia, que permanece inmóvil en el lugar donde es creado.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Encantar', '{"conjuro":"Encantar","via":"Libre acceso","nivel":12,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":110,"zeonArcano":130,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Presencia máxima 40","efectoIntermedio":"Presencia máxima 60","efectoAvanzado":"Presencia máxima 90","efectoArcano":"Presencia máxima 120","efecto":"Otorga a un objeto o lugar el carácter de cuerpo sobrenatural. La sustancia afectada será material para seres intangibles y conjuros. Si es lanzado sobre un arma, será capaz de dañar a seres inmateriales (empleando la presencia del objeto), y una pared encantada no podrá ser traspasada por seres etéreos o efectos místicos. Permite afectar a multitud de objetos, siempre y cuando la suma de sus presencias no supere el valor indicado por el conjuro.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Zona resbaladiza', '{"conjuro":"Zona resbaladiza","via":"Libre acceso","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":100,"zeonAvanzado":160,"zeonArcano":240,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"5 metros de radio","efectoIntermedio":"25 metros de radio","efectoAvanzado":"50 metros de radio","efectoArcano":"100 metros de radio / Pasar lentamente control contra 140, y corriendo a 280","efecto":"Encanta un área estática sobre la cual es tan fácil resbalar como sobre una zona de hielo mojado. Pasar lentamente por ella sin caer requiere una tirada de Atletismo o Acrobacias de Difícil, mientras que corriendo la dificultad aumenta a Absurdo.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Reparación', '{"conjuro":"Reparación","via":"Libre acceso","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"efectoBase":"Presencia máxima 30","efectoIntermedio":"Presencia máxima 50","efectoAvanzado":"Presencia máxima 70","efectoArcano":"Presencia máxima 90","efecto":"Repara completamente un objeto inorgánico. No recrea partes perdidas, por lo que es necesario conservar los fragmentos o tener la materia prima necesaria para su reparación. Puede lanzarse sobre cualquier cosa, desde armas a edificios, mientras su presencia no sea superior a lo que determine el grado del conjuro.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Trepar', '{"conjuro":"Trepar","via":"Libre acceso","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Más 50 a Trepar","efectoIntermedio":"Más 100 a Trepar","efectoAvanzado":"Más 150  a Trepar / Pernite alcanzar la dificultad de Inhumano en los controles","efectoArcano":"Más 200 a Trepar/ Permite alcanzar la dificultad de Zen en los controles","efecto":"Este conjuro aumenta sobrenaturalmente la capacidad de escalar de un individuo, añadiendo un bono a la base de su habilidad secundaria Trepar.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Bolsa infinita', '{"conjuro":"Bolsa infinita","via":"Libre acceso","nivel":12,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"x10 su capacidad","efectoIntermedio":"x30 su capacidad","efectoAvanzado":"x40 su capacidad","efectoArcano":"x50 su capacidad","efecto":"Permite a una envoltura, bolsa o baúl, cargar materiales que excedan su capacidad de contención, sin aumentar su peso. El mago siempre es capaz de extraer lo que quiere, aunque los demás sacarán las cosas al azar. No se pueden introducir objetos que no entren físicamente en el interior, como una lanza en una pequeña bolsa. Si el conjuro finaliza, la carga reaparecerá, pudiendo incluso reventar el contenedor.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Atraer alimañas menores', '{"conjuro":"Atraer alimañas menores","via":"Libre acceso","nivel":12,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":30,"zeonIntermedio":80,"zeonAvanzado":140,"zeonArcano":180,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Atrae hasta a quinientos seres","efectoIntermedio":"Atrae hasta diez mil seres","efectoAvanzado":"Atrae hasta cien mil seres","efectoArcano":"Atrae a varios millones de seres","efecto":"Invoca una masa de alimañas (sapos, lagartijas, avispas, insectos…) hasta el lugar que designe el hechicero. Su aparición no es automática, pero son atraídas de inmediato desde la zona más cercana a donde se encuentran. El sortilegio no otorga ningún control sobre los seres. El lanzador determina que clase de alimañas son las que atrae.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Respirar líquidos', '{"conjuro":"Respirar líquidos","via":"Libre acceso","nivel":12,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Presencia máxima 60","efectoIntermedio":"Presencia máxima 100","efectoAvanzado":"Presencia máxima 200","efectoArcano":"Presencia máxima 320","efecto":"Confiere la capacidad de respirar en el interior de cualquier líquido, como si se tratase de aire. Se puede afectar a varios sujetos, siempre que la suma de sus presencias no supere el valor indicado por el conjuro.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inhumanidad', '{"conjuro":"Inhumanidad","via":"Libre acceso","nivel":12,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":110,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Permite alcanzar Inhumanidad en una habilidad determinada","efectoIntermedio":"Permite alcanzar Inhumanidad en cualquier habilidad","efectoAvanzado":"Permite alcanzar Inhumanidad en cualquier habilidad y Zen en una habilidad","efectoArcano":"Permite alcanzar Zen en cualquier habilidad","efecto":"Los afectados por este conjuro podrán alcanzar la dificultad de Inhumano en cualquier campo o materia. Ten en cuenta que ello no quiere decir que las acciones realizadas por dichos sujetos sean automáticamente inhumanas, sino que podrán lograrlas si sus tiradas de habilidad o sus atributos se lo permiten.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Pasar sin dejar marca', '{"conjuro":"Pasar sin dejar marca","via":"Libre acceso","nivel":12,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":140,"zeonAvanzado":220,"zeonArcano":340,"mantBase":10,"mantIntermedio":15,"mantAvanzado":25,"mantArcano":35,"efectoBase":"Presencia máxima 120","efectoIntermedio":"Presencia máxima 180","efectoAvanzado":"Presencia máxima 240 / La dificultad para rastrearle aumenta a Inhumano","efectoArcano":"Presencia máxima 320 / La dificultad para rastrearle aumenta a Zen","efecto":"Elimina los rastros físicos que deja tras de sí una persona. Para seguir las huellas de alguien sobre quien está activo este conjuro, será necesario alcanzar una dificultad de Imposible en Rastrear. Puede afectar a tantos blancos como se desee, mientras la suma de sus presencias no supere el valor determinado por el grado del conjuro.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Niebla', '{"conjuro":"Niebla","via":"Libre acceso","nivel":12,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":240,"mantBase":10,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"100 metros de radio","efectoIntermedio":"250 metros de radio","efectoAvanzado":"500 metros de radio","efectoArcano":"1 kilómetro de radio","efecto":"Forma niebla con una intensidad a discreción del lanzador. Permanecerá estática donde fue lanzada.","_seccion":"LIBRE ACCESO 11-20"}'::jsonb),
  ('core-exxet', 'conjuros', 'Causar miedo', '{"conjuro":"Causar miedo","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"5 metros de radio / RM 100","efectoIntermedio":"15 metros de radio / RM 120","efectoAvanzado":"25 metros de radio / RM 140","efectoArcano":"50 metros de radio / RM 160","efecto":"Los afectados que se encuentren en un radio alrededor del hechicero serán presos de un terrible miedo mágico si no superan una RM. Aquellos que fallen el control temerán al lanzador, quedando sometidos al estado de Miedo","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Serenidad', '{"conjuro":"Serenidad","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":130,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"Causa una sensación de tranquilidad y paz sobre el blanco del conjuro, haciéndolo propenso a calmarse incluso si se encuentra lleno de ira o aterrorizado. Este conjuro anula cualquier estado de miedo, terror o ira que padezca el sujeto afectado, salvo si son de origen sobrenatural","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cerrar mágicamente', '{"conjuro":"Cerrar mágicamente","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"efectoBase":"Más 1 nivel de dificultad","efectoIntermedio":"Más 2 niveles de dificultad","efectoAvanzado":"Más 3 niveles de dificultad","efectoArcano":"Más 4 niveles de dificultad","efecto":"Cierra automáticamente cualquier puerta o cerradura, aumentando varios grados la dificultad necesaria para abrirla. Aunque el cerrojo queda encantado, no es necesario pagar un mantenimiento, ya que el hechizo se mantendrá hasta que sea abierta. Un conjuro de Cerrar Mágicamente sólo puede afectar a la vez a una cerradura","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo mágico', '{"conjuro":"Escudo mágico","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":240,"mantBase":10,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"300 puntos de resistencia","efectoIntermedio":"1.000 puntos de resistencia","efectoAvanzado":"2.000 puntos de resistencia","efectoArcano":"3.000 puntos de resistencia","efecto":"Crea un escudo mágico que protege al hechicero frente a cualquier tipo de ataque, incluyendo los de carácter sobrenatural","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Protección mágica', '{"conjuro":"Protección mágica","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"TA 2","efectoIntermedio":"TA 4","efectoAvanzado":"TA 6","efectoArcano":"TA 8","efecto":"Otorga una armadura contra todos los tipos de ataques, salvo energía. Puede combinarse con cualquier otra protección como capa adicional, pero no causa penalizadores especiales al turno","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Comprensión de idiomas', '{"conjuro":"Comprensión de idiomas","via":"Libre acceso","nivel":22,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":160,"zeonAvanzado":200,"zeonArcano":240,"mantBase":20,"mantIntermedio":35,"mantAvanzado":40,"mantArcano":50,"efectoBase":"Afecta a idiomas básicos, conocidos y hablados comúnmente","efectoIntermedio":"Idiomas extraños, hablados por pocos grupos o que no se usan en sociedad","efectoAvanzado":"Afecta a idiomas únicos y olvidados","efectoArcano":"Afecta a cualquier idioma","efecto":"Este conjuro permite comprender temporalmente un lenguaje desconocido, tanto si es escrito como oral","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Nubes', '{"conjuro":"Nubes","via":"Libre acceso","nivel":22,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":260,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":30,"efectoBase":"100 metros de radio","efectoIntermedio":"250 metros de radio","efectoAvanzado":"500 metros de radio","efectoArcano":"1 kilómetro de radio","efecto":"Forma una espesa capa de nubes. El hechicero tiene completo control sobre ellas, pudiendo moverlas o darles la forma que desee.","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Red', '{"conjuro":"Red","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Efec. / Ataq.","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"3 metros cuadrados / 500 Puntos de vida","efectoIntermedio":"6 metros cuadrados / 750 Puntos de vida","efectoAvanzado":"9 metros cuadrados / 1.000 Puntos de vida","efectoArcano":"12 metros cuadrados / 1.500 Puntos de vida / Presa con Fuerza 12","efecto":"Este sortilegio crea unas fibras mágicas de gran densidad, que actúan como una red muy pegajosa. Sus usos quedan a disposición del hechicero: bloquear una zona, lanzarla directamente sobre individuos… Presa con Fuerza 10 a cualquier individuo que la toque y aguanta como un ser con acumulación empleando TA 4. Al ser una sustancia de naturaleza mística, será dañada únicamente por ataques sobrenaturales o calor","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Enviar mensaje', '{"conjuro":"Enviar mensaje","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"efectoBase":"10 kilómetros / Hasta 500 palabras","efectoIntermedio":"100 kilómetros / Hasta 1.000 palabras","efectoAvanzado":"150 kilómetros / Hasta 2.500 palabras","efectoArcano":"1.000 kilómetros / Hasta 5.000 palabras","efecto":"Envía un mensaje oral o escrito a una persona o lugar conocido, que se encuentre dentro de los límites espaciales del conjuro","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Celeridad', '{"conjuro":"Celeridad","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Más 1 al Tipo de movimiento / +20 al turno","efectoIntermedio":"Más 2 al tipo de movimiento / +40 al turno","efectoAvanzado":"Más 4 al Tipo de movimiento / +60 al turno","efectoArcano":"Más 6 al Tipo de movimiento / +80 al turno","efecto":"Eleva el movimiento de un sujeto, al igual que le proporciona un bono a su turno. Los valores que hagan aumentar el Tipo de Movimiento por encima de 12 quedan reducidos a la mitad","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Levitación', '{"conjuro":"Levitación","via":"Libre acceso","nivel":22,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Tipo de vuelo 4","efectoIntermedio":"Tipo de vuelo 6","efectoAvanzado":"Tipo de vuelo 8","efectoArcano":"Tipo de vuelo 10","efecto":"El blanco de este conjuro podrá elevarse o descender verticalmente a voluntad por el aire, aunque no hacer movimientos horizontales","_seccion":"LIBRE ACCESO 21-30"}'::jsonb)
insert into public.catalogo (paquete_id, coleccion, clave, datos) values
  ('core-exxet', 'conjuros', 'Protección anticonceptiva', '{"conjuro":"Protección anticonceptiva","via":"Libre acceso","nivel":22,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Presencia máxima 80","efectoIntermedio":"Presencia máxima 180","efectoAvanzado":"Presencia máxima 260","efectoArcano":"Presencia máxima 380","efecto":"Evita al personaje contraer enfermedades de transmisión sexual o concebir descendencia. Puede afectar a varios individuos siempre que la suma de sus presencias no supere lo que determine el grado del conjuro","_seccion":"LIBRE ACCESO 21-30"}'::jsonb),
  ('core-exxet', 'conjuros', 'Resistencia al dolor', '{"conjuro":"Resistencia al dolor","via":"Libre acceso","nivel":32,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":14,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Más 50 a Resistir el dolor","efectoIntermedio":"Más 100 a Resistir el dolor","efectoAvanzado":"Más 150 a Resistir el dolor / Permite alcanzar Inhumanidad","efectoArcano":"Más 200 a Resistir el dolor / Permite alcanzar Zen","efecto":"Aumenta el aguante de un ser vivo, otorgando un bonificador a la habilidad secundaria Resistir el Dolor","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Eliminar conjuros', '{"conjuro":"Eliminar conjuros","via":"Libre acceso","nivel":32,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantArcano":".","efectoBase":"Valor zeónico máximo 60","efectoIntermedio":"Valor zeónico máximo 80","efectoAvanzado":"Valor zeónico máximo 100","efectoArcano":"Valor zeónico máximo 120","efecto":"Destruye un conjuro activo cuyo valor zeónico no supere el indicado por el grado del conjuro","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Extender la presencia', '{"conjuro":"Extender la presencia","via":"Libre acceso","nivel":32,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"5 metros","efectoIntermedio":"25 metros","efectoAvanzado":"50 metros","efectoArcano":"100 metros / Crea copias de la presencia de los objetos que lleve encima","efecto":"El mago puede separar su presencia de su cuerpo pudiendo actuar a distancia. Mientras esté separada el hechicero no podrá moverse, pero puede regresar a su cuerpo cuando quiera. La presencia puede tocar objetos físicos y atacar, pero es invisible; sólo se puede ver con el uso de detecciones de Ki, ver espíritus, o algún otro medio de ver cuerpos etéreos. La presencia es intangible y sólo podrá ser dañada por ataques basados en energía.","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Invocar agresividad', '{"conjuro":"Invocar agresividad","via":"Libre acceso","nivel":32,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"20 metros de radio / RM 80","efectoIntermedio":"40 metros de radio / RM 100","efectoAvanzado":"60 metros de radio / RM 120","efectoArcano":"80 metros de radio / RM 140","efecto":"Aumenta automáticamente la agresividad de todos los seres vivos que se encuentren cerca del hechicero, siempre y cuando no superen una RM. Los afectados actuarán de una forma violenta sobre cualquier individuo o cosa que pueda ser blanco de su ira","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Purificación', '{"conjuro":"Purificación","via":"Libre acceso","nivel":32,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantArcano":".","efectoBase":"Nivel máximo del veneno 30","efectoIntermedio":"Nivel máximo del veneno 50","efectoAvanzado":"Nivel máximo del veneno 70","efectoArcano":"Nivel máximo del veneno 90","efecto":"Purifica un cuerpo eliminando cualquier elemento nocivo para el sistema, como venenos o toxinas. La purificación sólo afectará a los elementos de un cuerpo que resulten dañinos y que no pertenezcan a él. De este modo, el veneno que posee una serpiente no se verá alterado, dado que es algo natural para ella, pero podría eliminarse cuando se inocule en una víctima","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Curar enfermedades', '{"conjuro":"Curar enfermedades","via":"Libre acceso","nivel":32,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":300,"mantArcano":".","efectoBase":"Nivel máximo de la enfermedad 30 / Presencia máxima 80","efectoIntermedio":"Nivel máximo de la enfermedad 50 / Presencia máxima 120","efectoAvanzado":"Nivel máximo de la enfermedad 70 / Presencia máxima 180","efectoArcano":"Nivel máximo de la enfermedad 100 / Presencia máxima 240","efecto":"Elimina automáticamente cualquier enfermedad. Puede emplearse sobre varios individuos, siempre y cuando la suma de sus presencias no supere lo que determina el grado del conjuro","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Descarga de magia', '{"conjuro":"Descarga de magia","via":"Libre acceso","nivel":32,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":14,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"efectoBase":"Daño 40","efectoIntermedio":"Daño 60","efectoAvanzado":"Daño 80","efectoArcano":"Daño 100","efecto":"Proyecta una descarga de energía mágica, que ataca en la TA de Energía","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cerrar realmente', '{"conjuro":"Cerrar realmente","via":"Libre acceso","nivel":32,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":160,"zeonAvanzado":200,"zeonArcano":240,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Presencia máxima 20","efectoIntermedio":"Presencia máxima 40","efectoAvanzado":"Presencia máxima 60","efectoArcano":"Presencia máxima 80","efecto":"Mediante este hechizo, el mago obstruye automáticamente cualquier tipo de puerta, postigo o ventana. Si, por ejemplo, se lanza sobre una puerta abierta, esta se cerrará sola, o si se usa sobre un rastrillo, bajará taponando la salida. Mientras se mantenga el conjuro, no es posible abrir la puerta físicamente, salvo por medios mágicos o destrozándola. La máxima presencia de la puerta viene determinada por el grado del conjuro","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Eliminar sueños', '{"conjuro":"Eliminar sueños","via":"Libre acceso","nivel":32,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":14,"zeonBase":50,"zeonIntermedio":100,"zeonAvanzado":150,"zeonArcano":200,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"Suprime la capacidad de soñar de un individuo. En caso de que sea lanzado sobre un individuo que se encuentre en la Vigilia, este será expulsado de inmediato al mundo real. El objetivo del conjuro puede resistirse superando una RM, aunque en caso de fallarla, sólo podrá repetir el control una vez al día","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Percibir sentimientos', '{"conjuro":"Percibir sentimientos","via":"Libre acceso","nivel":32,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"50 metros de radio / RM o RP 120","efectoIntermedio":"100 metros de radio / RM o RP 140","efectoAvanzado":"250 metros de radio / RM o RP 160","efectoArcano":"500 metros de radio / RM o RP 180","efecto":"Detecta un sentimiento determinado en aquellos individuos que se encuentren en un radio cercano al brujo. El hechicero debe elegir qué emoción desea percibir. Los sujetos afectados podrán escudarse superando una RM o RP","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Modificar el tamaño', '{"conjuro":"Modificar el tamaño","via":"Libre acceso","nivel":32,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":180,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Altera 2 puntos de Tamaño/ RM 100","efectoIntermedio":"Altera 4 puntos de Tamaño/ RM 120","efectoAvanzado":"Altera 6 puntos de Tamaño/ RM 140","efectoArcano":"Altera 8 puntos de Tamaño/ RM 160","efecto":"Incrementa o disminuye el Tamaño de la persona u objeto sobre el que es lanzado. Por muchos añadidos que se empleen, nunca podrá disminuirse por debajo de 1. Puede resistirse sus efectos superando una RM","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cambio de aspecto', '{"conjuro":"Cambio de aspecto","via":"Libre acceso","nivel":32,"diario":"Si","tipo":"Efec. /Aním.","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 100","efectoIntermedio":"RM 110","efectoAvanzado":"RM 120","efectoArcano":"RM 130","efecto":"Modifica la apariencia facial y corporal del sujeto sobre el que es lanzado. Puede alterar su color de piel o su fisonomía, pero no variar su altura o peso más allá de los límites impuestos por su Tamaño. Para resistir la alteración, es necesario superar una RM. Una vez fallada, sólo es posible repetir el control una vez por día","_seccion":"LIBRE ACCESO 31-40"}'::jsonb),
  ('core-exxet', 'conjuros', 'Transporte rápido', '{"conjuro":"Transporte rápido","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"efectoBase":"25 metros","efectoIntermedio":"100 metros","efectoAvanzado":"200 metros","efectoArcano":"350 metros","efecto":"Transporta al blanco del conjuro a distancia. Este conjuro permite pasar a través de cuerpos físicos, siempre que no se encuentren basados en energía, pero no situar a sus objetivos en una superficie de naturaleza diferente a aquella en la que se encontrara (por ejemplo, haciendo aparecer a alguien en el aire)","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Enviar sueños', '{"conjuro":"Enviar sueños","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"efectoBase":"Sueños vagos,poco claros,imágenes fragmentadas,frases inconexas y sonidos","efectoIntermedio":"Los Sueños son vagos, pero permiten mostrar secuencias y lugares al soñador","efectoAvanzado":"Sueños claros con mensaje comprensible, imágenes ideadas por el mago","efectoArcano":"Sueños claros, permitiendo al soñador preguntar o interactuar con lo que ve","efecto":"Permite enviar imágenes y palabras al subconsciente de un durmiente. El conjuro no funciona como un sistema de comunicación, ya que el brujo no tendrá constancia de lo que el soñador diga o haga. El mensaje puede mandarse a cualquier sujeto que el hechicero designe, sin importar la distancia a la que esté. La condición para ser afectado por el conjuro es estar durmiendo, y ser el individuo elegido por el lanzador","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Maldición', '{"conjuro":"Maldición","via":"Libre acceso","nivel":42,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":200,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":700,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":35,"efectoBase":"actos concretos y crea infortunio, que no pueda lograr sus objetivos /RM 120","efectoIntermedio":"Actos genéricos, mala suerte, maldecir una habilidad (–60 por uso) / RM 140","efectoAvanzado":"acto o condición, toda clase de efectos negativos, habilidad (–80) / RM 160","efectoArcano":"Complejidad imaginable y produce efectos mayores, incluso muerte / RM 180","efecto":"Este conjuro provoca una serie de condiciones negativas sobre el objetivo. Su cometido es causar infortunio sobre ciertas acciones que realice el objetivo. El mago decide a qué exactamente, así como sus consecuencias, dentro de los límites por el grado del conjuro. Otros vinculados a la maldicion pueden tirar su RM para evitar sus efectos. Sólo se puede realizar un nuevo control cuando sus efectos vuelvan a activarse.","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mostrar lo invisible', '{"conjuro":"Mostrar lo invisible","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Radio de 25 metros / RM 120","efectoIntermedio":"Radio de 50 metros / RM 160","efectoAvanzado":"Radio de 100 metros / RM 200","efectoArcano":"Radio de 250 metros / RM 240","efecto":"Muestra cualquier fuerza o presencia invisible, exhibiéndola a la vista de todo el mundo. Este conjuro revela tanto efectos sobrenaturales como seres de naturaleza espiritual o completamente invisibles. Las criaturas afectadas podrán evitar manifestarse superando una RM. La condición consiste, simplemente, en encontrarse dentro del área del hechizo","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Deshacer', '{"conjuro":"Deshacer","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":240,"mantArcano":".","efectoBase":"50 kilos / Resistencia 80","efectoIntermedio":"100 kilos / Resistencia 100","efectoAvanzado":"250 kilos / Resistencia 100","efectoArcano":"500 kilos / Resistencia 140","efecto":"Destruye kilogramos de cualquier material inorgánico, siempre que no supere una Resistencia","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Causar enfermedad', '{"conjuro":"Causar enfermedad","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":200,"efectoBase":"Enfermedad de Nivel 30.","efectoIntermedio":"Enfermedad de Nivel 50.","efectoAvanzado":"Enfermedad de Nivel 70.","efectoArcano":"Enfermedad de Nivel 90.","efecto":"Hace enfermar a un individuo que falle la RE requerida","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Anulación de magia', '{"conjuro":"Anulación de magia","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Valor zeónico máximo 60 / 10 metros de radio","efectoIntermedio":"Valor zeónico máximo 100 / 25 metros de radio","efectoAvanzado":"Valor zeónico máximo 140 / 50 metros de radio","efectoArcano":"Valor zeónico máximo 180 / 100 metros de radio","efecto":"Anula los efectos de todos los conjuros (incluidos los del lanzador) que se encuentren en un radio alrededor del hechicero y cuyo valor zeónico no supere lo que determine el grado del conjuro. Ten en cuenta que no los destruye, sino simplemente neutraliza sus efectos mientras estén dentro del área","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Leer la mente', '{"conjuro":"Leer la mente","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":160,"zeonAvanzado":200,"zeonArcano":240,"mantBase":10,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"RM o RP 80","efectoIntermedio":"RM o RP 120","efectoAvanzado":"RM o RP 140","efectoArcano":"RM o RP 180","efecto":"Permite al hechicero indagar en los pensamientos o recuerdos de un individuo. Queda a discreción del DJ decidir la cantidad de asaltos que necesita para obtener la información deseada, dependiendo de lo oculto que esté en la memoria del personaje. El afectado puede resistirse superando una RP o una RM. Mientras pueda leer las intenciones de su adversario, el brujo aplica un bonificador de +30 a las acciones enfrentadas en su contra.","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Enlentecer', '{"conjuro":"Enlentecer","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Menos 2 al Tipo de movimiento / RM 120","efectoIntermedio":"Menos 4 al Tipo de movimiento / RM 140","efectoAvanzado":"Menos 8 al Tipo de movimiento / RM 160","efectoArcano":"Menos 12 al Tipo de movimiento / RM 180","efecto":"Disminuye la velocidad de reacción y movimiento del sujeto sobre el que se lance el conjuro, provocando un penalizador a su movimiento si no supera una RM","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Amistad', '{"conjuro":"Amistad","via":"Libre acceso","nivel":42,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":220,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"RM o RP 120","efectoIntermedio":"RM o RP 140","efectoAvanzado":"RM o RP 160","efectoArcano":"RM o RP 180","efecto":"Crea en un individuo un vínculo de amistad hacia otra persona designada por el hechicero. El afectado no se vuelve estúpido, por lo que no obedecerá de manera ciega a su “amigo”, actuando siempre conforme a su ética y personalidad. Para superar este conjuro, es necesario pasar una RM o RP. Posteriormente, sólo se repite el control una vez al día, o cuando algo pueda poner en duda la relación de compañerismo que mantiene el hechizado.","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Absorber información', '{"conjuro":"Absorber información","via":"Libre acceso","nivel":42,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":16,"zeonBase":80,"zeonIntermedio":180,"zeonAvanzado":320,"zeonArcano":500,"mantArcano":".","efectoBase":"Un libro corto y no muy complejo","efectoIntermedio":"Un grueso volumen de gran complejidad","efectoAvanzado":"El equivalente a una enciclopedia","efectoArcano":"El conocimiento de una biblioteca entera","efecto":"El hechicero absorbe conocimientos escritos o gráficos, que se encuentren a su vista o al alcance de su mano. Así pues, le es posible, por ejemplo, leer un libro en escasos segundos tocando su cubierta y recordar los detalles como si lo hubiera hecho con detenimiento. Un personaje que trate de recordar información que ha memorizado usando este conjuro disminuye dos grados la dificultad de cualquier control de Memorizar.","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alterar energia', '{"conjuro":"Alterar energia","via":"Libre acceso","nivel":42,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":100,"zeonIntermedio":160,"zeonAvanzado":200,"zeonArcano":240,"mantBase":10,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"10 intensidades / RM 120","efectoIntermedio":"15 intensidades / RM 140","efectoAvanzado":"20 intensidades / RM 160","efectoArcano":"25 intensidades / RM 180","efecto":"El hechicero puede transformar intensidades de cualquier tipo de energía elemental en otro, como convertir fuego en electricidad. Si estas intensidades son mágicas o tienen presencia propia, podrán resistirse superando una RM. Este conjuro no causa daños a los seres elementales, pero sí altera su naturaleza","_seccion":"LIBRE ACCESO 41-50"}'::jsonb),
  ('core-exxet', 'conjuros', 'Dormir', '{"conjuro":"Dormir","via":"Libre acceso","nivel":52,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"10 metros de radio / RM 80","efectoIntermedio":"25 metros de radio / RM 100","efectoAvanzado":"50 metros de radio / RM 120","efectoArcano":"100 metros de radio / RM 140","efecto":"Provoca Sueños sobre la gente en la zona. Los afectados deben superar una RM o quedan sumidos en un profundo Sueños en poco más de un minuto. Si fallan por una diferencia mayor a 20 puntos, los efectos del conjuro son inmediatos. Mientras se mantenga el sortilegio, los afectados no podrán despertarse. Cualquier causa que permitiría al hechizado despertar mientras sigue preso del conjuro, le dará la oportunidad de realizar una nueva RM.","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ceguera', '{"conjuro":"Ceguera","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":20,"efectoBase":"Radio de 5 metros / RM 100","efectoIntermedio":"Radio de 25 metros / RM 120","efectoAvanzado":"Radio de 50 metros / RM 140","efectoArcano":"Radio de 100 metros / RM 160","efecto":"Los sujetos dentro del radio del conjuro que fallen la RM perderán el sentido de la vista","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sordera', '{"conjuro":"Sordera","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Radio de 5 metros / RM 120","efectoIntermedio":"Radio de 25 metros / RM 140","efectoAvanzado":"Radio de 50 metros / RM 160","efectoArcano":"Radio de 100 metros / RM 180","efecto":"Los sujetos dentro del radio del conjuro que fallen la RM perderán el sentido del oído","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mudez', '{"conjuro":"Mudez","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Radio de 5 metros / RM 120","efectoIntermedio":"Radio de 25 metros / RM 150","efectoAvanzado":"Radio de 50 metros / RM 190","efectoArcano":"Radio de 100 metros / RM 220","efecto":"Los sujetos dentro del radio del conjuro que fallen la RM perderán la capacidad de hablar","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Curar heridas', '{"conjuro":"Curar heridas","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":220,"efectoBase":"40 Puntos de vida","efectoIntermedio":"80 Puntos de vida","efectoAvanzado":"160 Puntos de vida","efectoArcano":"320 Puntos de vida","efecto":"Sana cualquier clase de herida recuperando Puntos de Vida. Este tipo de curación no permite recobrar miembros perdidos o daños similares, pero sí evita los efectos del desangramiento","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Visualizar cartografía', '{"conjuro":"Visualizar cartografía","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"efectoBase":"25 kilómetros de radio","efectoIntermedio":"100 kilómetros de radio","efectoAvanzado":"250 kilómetros de radio","efectoArcano":"1.000 kilómetros de radio","efecto":"Permite al hechicero visualizar los elementos del terreno que se encuentren cercanos al sitio en el que está. No se puede localizar a individuos concretos o construcciones con exactitud, pero sí la ubicación de ciudades, ríos, montañas...","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Fusionar con el cuerpo', '{"conjuro":"Fusionar con el cuerpo","via":"Libre acceso","nivel":52,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Presencia máxima 80","efectoIntermedio":"Presencia máxima 180","efectoAvanzado":"Presencia máxima 280","efectoArcano":"Presencia máxima 320","efecto":"Fusiona objetos, como armas, armaduras, con el objetivo. El objeto quedará oculto bajo alguna forma visible, como icatriz o tatuaje, hasta el que se extraiga. Mientras se encuentren ocultos, aquel que los porte no tendrá ningún penalizador por peso o por tamaño, tampoco sus beneficios. No se puede fusionar algo que exceda en más de diez veces el tamaño del contenedor. Separar un objeto del cuerpo, requiere un asalto completo.","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Andar por las paredes', '{"conjuro":"Andar por las paredes","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"A una cuarta parte del Tipo de Movimiento como máximo","efectoIntermedio":"A mitad de Tipo de Movimiento como máximo","efectoAvanzado":"Tipo de Movimiento pleno","efectoArcano":"Puede moverse o quedarse quieto por superficies completamente imposibles.","efecto":"Permite a un individuo moverse por paredes o techos como si se tratase del suelo, anulando absolutamente cualquier regla de la gravedad","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Eliminar cansancio', '{"conjuro":"Eliminar cansancio","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"efectoBase":"1 Punto de Cansancio","efectoIntermedio":"3 Puntos de Cansancio","efectoAvanzado":"5 Puntos de Cansancio","efectoArcano":"7 Puntos de Cansancio","efecto":"Este conjuro recupera el agotamiento físico que haya sufrido una persona, permitiendo recobrar sus puntos de Cansancio perdidos","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Montura mágica', '{"conjuro":"Montura mágica","via":"Libre acceso","nivel":52,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":220,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Tipo de movimiento 10, 500 PV, Fuerza 10, Tamaño máximo 20","efectoIntermedio":"Tipo de movimiento 12, 1.000 PV, Fuerza 12, Tamaño máximo 22","efectoAvanzado":"Tipo de movimiento 14, 1.500 PV, Fuerza 14, Tamaño máximo 24","efectoArcano":"Tipo de movimiento 15, 2.000 PV, Fuerza 15, Tamaño máximo 28","efecto":"Crea un ser sobrenatural, con el único objetivo de servir como montura. No tendrá ninguna habilidad de ataque y se defenderá usando las reglas de acumulación de daño. Para moverse, la montura mágica utiliza las reglas de la habilidad del Ki Eliminación de Peso y Atletismo 200","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Nube ácida', '{"conjuro":"Nube ácida","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":320,"mantBase":10,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":35,"efectoBase":"RF 120 / 5 metros de radio / Tipo de Vuelo 6","efectoIntermedio":"RF 140 / 10 metros de radio / Tipo de Vuelo 8","efectoAvanzado":"RF 160 / 20 metros de radio / Tipo de Vuelo 10","efectoArcano":"RF 180 / 50 metros de radio / Tipo de Vuelo 12","efecto":"Forma una nube corrosiva. Superar RF o perder vida equivalente al nivel de fracaso. Si un objeto no supera RF por 50 puntos, perderá un nivel de calidad. Cada turno que un cuerpo esté expuesto y falle la tirada, aplica un negativo acumulativo a su RF de -10 para el control en el siguiente turno. La nube se mueve a voluntad del mago a una velocidad determinada por el grado del conjuro. No es posible designar blancos, y afectará incluso al mago.","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Desproteger', '{"conjuro":"Desproteger","via":"Libre acceso","nivel":52,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"-2 a la TA / RM 140","efectoIntermedio":"-4 a la TA / RM 160","efectoAvanzado":"-6 a la TA / RM 180","efectoArcano":"-8 a la TA / RM 200","efecto":"Reduce la TA de un defensor, si este (o su armadura) no superan una RM. La única condición para ser afectado por este conjuro es ser designado como blanco por el lanzador y fallar la RM","_seccion":"LIBRE ACCESO 51-60"}'::jsonb),
  ('core-exxet', 'conjuros', 'Paralizar', '{"conjuro":"Paralizar","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":9,"intRAvanzado":13,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"10 metros de Radio / RM 80","efectoIntermedio":"25 metros de Radio / RM 100","efectoAvanzado":"50 metros de Radio / RM 120","efectoArcano":"100 metros de Radio / RM 140","efecto":"Somete al efecto de Paralización Completa a cualquier sujeto que se encuentre en el área de acción del conjuro y falle la RM","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Debilidad', '{"conjuro":"Debilidad","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"El blanco de este conjuro se verá sometido temporalmente al efecto de Debilidad tal y como se explica en el Capítulo 14","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Arma mágica', '{"conjuro":"Arma mágica","via":"Libre acceso","nivel":62,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Calidad +5","efectoIntermedio":"Calidad +10","efectoAvanzado":"Calidad +15","efectoArcano":"Calidad +20","efecto":"El brujo elabora con su magia un arma sobrenatural. La creación será considerada un objeto de la calidad determinada por el grado del sortilegio con la habilidad de dañar energía","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Resistir', '{"conjuro":"Resistir","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":20,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"+20 a una Resistencia","efectoIntermedio":"+40 a una Resistencia","efectoAvanzado":"+60 a una Resistencia","efectoArcano":"+80 a una Resistencia","efecto":"Potencia una de las Resistencias de un sujeto. Sólo se mejora un único tipo, como la RM o RF; no en su totalidad","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alteración menor', '{"conjuro":"Alteración menor","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":80,"zeonIntermedio":160,"zeonAvanzado":240,"zeonArcano":320,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Presencia máxima 30.","efectoIntermedio":"Presencia máxima 50.","efectoAvanzado":"Presencia máxima 70.","efectoArcano":"Presencia máxima 100.","efecto":"Permite al hechicero moldear la forma de la materia inorgánica, transmutando un objeto en otro similar de idéntica presencia. Por ejemplo, es posible convertir un arpón en una lanza, ya que ambos tienen una forma similar y la misma presencia, pero no en un mandoble, ya que su presencia es mayor y sus formas difieren considerablemente","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Rechazo', '{"conjuro":"Rechazo","via":"Libre acceso","nivel":62,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":220,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Presencia máxima 30 / Fuerza 8","efectoIntermedio":"Presencia máxima 40 / Fuerza 10","efectoAvanzado":"Presencia máxima 50 / Fuerza 12","efectoArcano":"Presencia máxima 60 / Fuerza 14","efecto":"Encanta un cuerpo físico con energía mágica, produciendo un fuerte rechazo a cualquiera que lo toque. El conjuro provoca un impacto sobre todo aquel con el que se ponga en contacto. Como en todos los golpes similares, el DJ deberá considerar el daño que sufre el afectado, dependiendo de la diferencia con un control enfrentado de Agilidad o Fuerza, y los elementos que haya en el entorno.","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Plaga', '{"conjuro":"Plaga","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantArcano":".","efectoBase":"1 Kilómetro de radio / Nivel máximo de enfermedad 20","efectoIntermedio":"5 Kilómetros de radio / Nivel máximo de enfermedad 40","efectoAvanzado":"10 Kilómetros de radio / Nivel máximo de enfermedad 60","efectoArcano":"25 Km de radio / Nivel máximo de enfermedad 80 / La RE es más 10 puntos","efecto":"Este conjuro debe de lanzarse sobre un sujeto o un lugar que esté infectado con una enfermedad. Al hacerlo, extiende la infección de manera automática sobre todos los individuos que se encuentren en el radio. Estas personas tendrán derecho a una RE contra la enfermedad expandida, para evitar el contagio. La condición para ser afectado será encontrarse, simplemente, en el área del conjuro","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cuerpo a magia', '{"conjuro":"Cuerpo a magia","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"El objetivo es inmune a todos los ataques no basados en energía","efectoIntermedio":"el objetivo puede atravesar cualquier materia física no basada en energía","efectoAvanzado":"el objetivo obtiene un +10 a su ACT","efectoArcano":"todo daño basado en habilidad mágica o conjuro queda reducido a la mitad","efecto":"El cuerpo designado por el hechicero se transformará en energía mágica","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aumentar car. físicas', '{"conjuro":"Aumentar car. físicas","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"+1 a la característica","efectoIntermedio":"+3 a la característica","efectoAvanzado":"+5 a la característica","efectoArcano":"+7 a la característica","efecto":"Aumenta una de las cuatro características físicas de un personaje: Destreza, Agilidad, Fuerza o Constitución. En el caso de que el atributo se incremente por encima de 12, el índice de progresión se reduce a la mitad. Sólo uno de estos conjuros puede afectar a la vez a una característica concreta","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Olvido', '{"conjuro":"Olvido","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":120,"zeonIntermedio":160,"zeonAvanzado":200,"zeonArcano":240,"efectoBase":"RM o RP 120","efectoIntermedio":"RM o RP 140","efectoAvanzado":"RM o RP 160","efectoArcano":"RM o RP 180","efecto":"Afecta a la memoria de un sujeto, haciéndole olvidar todo lo que desee. Si los recuerdos están muy arraigados en el afectado, podrá aplicar un bono de +40 a su tirada de RM o RP. A pesar de no tener mantenimiento, el blanco tendrá una oportunidad de volver a realizar un control de Resistencia si encuentra algo que pueda hacerle recordar. Este conjuro no afecta a las habilidades del personaje, sólo a la memoria consciente.","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Crear emociones', '{"conjuro":"Crear emociones","via":"Libre acceso","nivel":62,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":220,"zeonArcano":280,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM o RP 120","efectoIntermedio":"RM o RP 140","efectoAvanzado":"RM o RP 160","efectoArcano":"RM o RP 180","efecto":"Introduce algún tipo de sentimiento o emoción en el individuo designado por el hechicero que falle una RM o RP contra la dificultad del conjuro. El afectado puede hacer un nuevo control cada día que transcurra, o cuando tenga una seria sospecha de que está siendo influido sobrenaturalmente","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aumentar car. mentales', '{"conjuro":"Aumentar car. mentales","via":"Libre acceso","nivel":62,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"+1 a la característica","efectoIntermedio":"+3 a la característica","efectoAvanzado":"+5 a la característica","efectoArcano":"+7 a la característica","efecto":"Aumenta una de las cuatro características mentales de un personaje: Inteligencia, Poder, Voluntad y Percepción. En el caso de que el atributo se incremente por encima de 12, el índice de progresión se reduce a la mitad. El aumento de Inteligencia no permite al brujo incrementar el potencial máximo de sus hechizos. Uno de estos conjuros tan sólo puede afectar a una característica concreta a la vez","_seccion":"LIBRE ACCESO 61-70"}'::jsonb),
  ('core-exxet', 'conjuros', 'Esfera de levitación', '{"conjuro":"Esfera de levitación","via":"Libre acceso","nivel":72,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 80 / 25 metros de radio","efectoIntermedio":"RM 100 / 150 metros de radio","efectoAvanzado":"RM 120 / 250 metros de radio","efectoArcano":"RM 140 / 350 metros de radio","efecto":"Hace levitar todo lo que se esté en un radio respecto al hechicero. El lanzador decide qué es lo que se eleva y qué no, sin importar el peso o el tamaño de lo que levanta. Los objetos o personas que se encuentren en el aire son movidos por el mago, con un Tipo de vuelo 6 si no superan una RM. Sólo los seres vivos o animados tienen derecho a un control de Resistencia, al igual que las construcciones que estén dotadas de características sobrenaturales","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Estancar conjuro', '{"conjuro":"Estancar conjuro","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"efectoBase":"Zeón máximo 80","efectoIntermedio":"Zeón máximo 120","efectoAvanzado":"Zeón máximo 180","efectoArcano":"Zeón máximo 240","efecto":"Permite almacenar un segundo conjuro en un objeto. Se lanza con el otro hechizo, de modo que el segundo sortilegio, en lugar de funcionar con normalidad, quedará en el interior de algo. El conjuro estancado podrá activarse, otro mago que introduzca en el contenedor el coste zeónico exacto conque fue lanzado. El mago que posea el objeto tendrá el control del conjuro. El hechizo estancado podrá volver a ser usado mientras se vuelva a pagar el coste de Zeon.","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inutilidad', '{"conjuro":"Inutilidad","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 180","efectoArcano":"RM 220","efecto":"El sujeto afectado por el conjuro de Inutilidad se volverá torpe e incapaz de ejecutar maniobras físicas. Deberá superar una RM o sufrir un penalizador a equivalente a su nivel de fracaso. Este hechizo no afecta a las habilidades mágicas, psíquicas o perceptivas","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Desviar trayectoria', '{"conjuro":"Desviar trayectoria","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Efec. Defen.","accion":"Pasiva","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":160,"zeonAvanzado":220,"zeonArcano":300,"efectoBase":"RM 140","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"El mago modifica trayectoria de un cuerpo en movimiento, redirigiéndolo. No permite mover un cuerpo estático. Puede ser utilizado como defensa contra ataques materiales, como espadazos o proyectiles. En el caso de que el mago consiga una defensa con éxito con su Proyección Mágica, podrá redirigirlo hacia otro adversario. Este conjuro puede evitarse, superando una RM (en caso de usarse como defensa, será el atacante quien deba superar la Resistencia)","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Invisibilidad', '{"conjuro":"Invisibilidad","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":160,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantBase":20,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Advertir contra Imposible y Buscar contra Absurdo","efectoIntermedio":"Advertir contra Inhumano y Buscar contra Casi Imposible","efectoAvanzado":"Advertir contra Zen y Buscar contra Imposible","efectoArcano":"El blanco no puede ser percibido por el sentido de la vista","efecto":"Este conjuro vuelve invisible uno o varios cuerpos designados por el hechicero. Un individuo puede percibir las alteraciones que produce un cuerpo invisible superando un control de Advertir o Buscar contra la Dificultad determinada por el grado del conjuro","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Dominio', '{"conjuro":"Dominio","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":160,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantBase":20,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM o RP 100","efectoIntermedio":"RM o RP 120","efectoAvanzado":"RM o RP 140","efectoArcano":"RM o RP 160","efecto":"Permite dominar la voluntad de cualquiera que no supere una RM o RP. El afectado sólo tiene derecho a un nuevo control cada vez que se le ordene realizar un acto que va completamente en contra de su naturaleza. Si la orden es excepcionalmente opuesta, puede aplicar un +20 a su tirada","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Marca de detección', '{"conjuro":"Marca de detección","via":"Libre acceso","nivel":72,"diario":"Si","tipo":"Efec. Anim.","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"10 kilómetros / RM 120","efectoIntermedio":"100 kilómetros / RM 140","efectoAvanzado":"1.000 kilómetros / RM 160","efectoArcano":"Cualquier distancia / RM 180","efecto":"Encanta una persona, objeto o lugar, permitiendo al hechicero unir con él sus sentidos. De este modo, el brujo puede utilizar sus habilidades de percepción como si estuviera presente hasta la distancia máxima precisada por el grado del conjuro. Además, tendrá siempre constancia de dónde se encuentra su marca con respecto a su posición. En el caso de tratarse de un ser vivo o un objeto sobrenatural, podrá evitar ser afectado superando una RM","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vuelo (Libre Acceso)', '{"conjuro":"Vuelo (Libre Acceso)","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Tipo de Vuelo Místico 8","efectoIntermedio":"Tipo de Vuelo Místico 10","efectoAvanzado":"Tipo de Vuelo Místico 12","efectoArcano":"Tipo de Vuelo Místico 14","efecto":"Otorga al afectado la capacidad de moverse por el aire a voluntad","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Erudición ofensiva', '{"conjuro":"Erudición ofensiva","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"+20 a la Proyección Mágica Ofensiva","efectoIntermedio":"+30 a la Proyección Mágica Ofensiva","efectoAvanzado":"+40 a la Proyección mágica ofensiva","efectoArcano":"+50 a la Proyección mágica ofensiva","efecto":"Empleando este conjuro, el hechicero aumenta su Proyección Mágica ofensiva. Sólo puede emplearse a la vez un conjuro de Erudición Ofensiva sobre un sujeto concreto","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Erudición defensiva', '{"conjuro":"Erudición defensiva","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"+20 a la Proyección mágica defensiva","efectoIntermedio":"+30 a la Proyección mágica defensiva","efectoAvanzado":"+40 a la Proyección mágica defensiva","efectoArcano":"+50 a la Proyección mágica defensiva","efecto":"Empleando este conjuro, el hechicero aumenta su Proyección Mágica defensiva. Sólo puede emplearse a la vez un conjuro de Erudición Defensiva sobre un sujeto concreto","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Contención', '{"conjuro":"Contención","via":"Libre acceso","nivel":72,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"mantBase":40,"mantIntermedio":50,"mantAvanzado":60,"mantArcano":65,"efectoBase":"10 metros de radio / RM 120","efectoIntermedio":"25 metros de radio / RM 140","efectoAvanzado":"50 metros de radio / RM 160","efectoArcano":"100 metros de radio / RM 180","efecto":"Encanta una zona haciendo que todo el que entre (o que ya se encuentre en su interior) no pueda salir si no supera RM. Una vez que se ha fallado la Resistencia, un sujeto afectado no tiene derecho a un nuevo control mientras se mantenga el conjuro, salvo si por alguna causa sus Resistencias aumentan. El mago no podrá elegir blancos en su interior, e incluso podrá quedar él mismo encerrado","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Blanco perfecto', '{"conjuro":"Blanco perfecto","via":"Libre acceso","nivel":72,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":16,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"efectoBase":"Bono de Habilidad +40","efectoIntermedio":"Bono de Habilidad +60","efectoAvanzado":"Bono de Habilidad +80","efectoArcano":"Bono de Habilidad +100","efecto":"Encanta un proyectil convencional haciendo que alcance su blanco de modo ineludible. El proyectil utiliza la habilidad de su lanzador, y en el caso de que se emplee para atacar a un adversario, este se defiende utilizando las reglas convencionales. Se confiere un bono a su tirada, permitiéndole ignorar las dificultades de disparo de la Tabla 48 y la distancia que le separa del blanco. Se debe lanzar en el mismo asalto en que se realiza el disparo","_seccion":"LIBRE ACCESO 71-80"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inmortalidad', '{"conjuro":"Inmortalidad","via":"Libre acceso","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":300,"zeonIntermedio":400,"zeonAvanzado":500,"zeonArcano":600,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Las habilidades descritas","efectoIntermedio":"Idem base, invulnerable a venenos o enfermedades que no sean sobrenaturales","efectoAvanzado":"Idem intermedio, invulnerable a desangramiento o daños físicos sobrenaturales","efectoArcano":"Idem avanzado, invulnerable a todo daño físico, si no es crítico mortal","efecto":"Mientras este conjuro siga activo, el hechicero o quien este designe no envejece ni sufre los efectos del paso del tiempo. Así, se volverá un ser inmortal, salvo ante una muerte de carácter violento. Si este conjuro deja de mantenerse o es destruido, el individuo recuperará la edad que le corresponde a un ritmo muy acelerado","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Localización', '{"conjuro":"Localización","via":"Libre acceso","nivel":82,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":300,"zeonIntermedio":360,"zeonAvanzado":420,"zeonArcano":480,"efectoBase":"100 kilómetros / RM 120","efectoIntermedio":"1.000 kilómetros / RM 140","efectoAvanzado":"10.000 kilómetros / RM 180","efectoArcano":"Cualquier distancia / RM 220","efecto":"Localización permite encontrar una persona, objeto o lugar, y conocer su ubicación exacta en ese momento. El brujo puede buscar cualquier cosa concreta, pero no cualidades subjetivas, como por ejemplo localizar a la persona que ha matado a su hermano si no sabe quién es exactamente. Para evitar ser encontrados, las personas u objetos deberán superar una RM. Los lugares de gran tamaño aplicarán un penalizador de –40 a dicha tirada","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Desencantamiento', '{"conjuro":"Desencantamiento","via":"Libre acceso","nivel":82,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":200,"zeonIntermedio":250,"zeonAvanzado":320,"zeonArcano":400,"efectoBase":"Presencia máxima 80","efectoIntermedio":"Presencia máxima 100","efectoAvanzado":"Presencia máxima 120","efectoArcano":"Presencia máxima 140","efecto":"Destruye automáticamente un objeto mágico. El hechicero puede elegir si destruir completamente el objeto o, por el contrario, despojarle simplemente de sus cualidades sobrenaturales","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Eliminar necesidades', '{"conjuro":"Eliminar necesidades","via":"Libre acceso","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":300,"zeonIntermedio":360,"zeonAvanzado":420,"zeonArcano":480,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":25,"efectoBase":"Las habilidades descritas","efectoIntermedio":"ignora los penalizadores por efectos climáticos naturales como calor o frío","efectoAvanzado":"ignorará penalizador natural no provocado por efectos sobrenaturales","efectoArcano":"pero el personaje recupera un punto de Cansancio por asalto","efecto":"Hace desaparecer completamente cualquier necesidad física de un individuo. Mientras se mantenga el conjuro, no se verá afectado por los efectos del hambre, el cansancio o el Sueños, ignorando por completo cualquier penalizador causado por estos. El personaje puede seguir gastando puntos de Cansancio para mejorar sus acciones físicas (que se recuperan a un ritmo de un punto por hora), aunque no sufre negativos por alcanzar valores muy bajos","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Inmunidad física', '{"conjuro":"Inmunidad física","via":"Libre acceso","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"mantBase":10,"mantIntermedio":15,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Presencia máxima 60","efectoIntermedio":"Presencia máxima 80","efectoAvanzado":"Presencia máxima 100","efectoArcano":"Presencia máxima 120","efecto":"El individuo u objeto designado se vuelve completamente invulnerable a cualquier daño que no sea capaz de afectar energía. Es posible elegir tantos blancos como se desee, mientras la suma de sus presencias no supere lo que determine el máximo del conjuro","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Preparar conjuro', '{"conjuro":"Preparar conjuro","via":"Libre acceso","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":360,"zeonArcano":420,"mantBase":20,"mantIntermedio":30,"mantAvanzado":40,"mantArcano":45,"efectoBase":"Zeon máximo del conjuro 100","efectoIntermedio":"Zeon máximo del conjuro 200","efectoAvanzado":"Zeon máximo del conjuro 300","efectoArcano":"Zeon máximo del conjuro 400","efecto":"Introduce otro conjuro en un objeto o individuo, para lanzarlo posteriormente automáticamente. Quien tiene el conjuro decide como lanzarlo. Utiliza la Proyección Mágica del mago original, salvo si quien lo posee en la actualidad decide utilizar la suya propia. Una vez lanzado, el hechizo preparado desaparece. Sólo un conjuro lanzado por asalto. Un objeto o persona puede contener hasta 4 veces su presencia en valor zeónico.","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Robar conjuro', '{"conjuro":"Robar conjuro","via":"Libre acceso","nivel":82,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":280,"zeonAvanzado":340,"zeonArcano":400,"mantArcano":".","efectoBase":"Valor zeónico máximo 120 / RM 120","efectoIntermedio":"Valor zeónico máximo 180 / RM 140","efectoAvanzado":"Valor zeónico máximo 240 / RM 160","efectoArcano":"Valor zeónico máximo 300 / RM 180","efecto":"Sustrae la esencia mágica de un hechizo, cortando sus lazos con el mago que lo ha lanzado y ligándolo a otro. El mago toma un conjuro que no es suyo, dominándolo a partir de ese momento como si él mismo fuese el lanzadorSólo es posible robar aquellos que tengan mantenimiento; nunca los de acción automática. El hechicero que controla el conjuro podrá evitar que le sea robado superando una RM","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Conjuro natural', '{"conjuro":"Conjuro natural","via":"Libre acceso","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":350,"zeonIntermedio":420,"zeonAvanzado":480,"zeonArcano":540,"mantBase":70,"mantIntermedio":85,"mantAvanzado":100,"mantArcano":110,"efectoBase":"Valor zeónico máximo 100","efectoIntermedio":"Valor zeónico máximo 140","efectoAvanzado":"Valor zeónico máximo 180","efectoArcano":"Valor zeónico máximo 220","efecto":"Otorga la capacidad de lanzar sortilegios tantas veces como desee como si fueran conjuros innatos, sin que tengan coste zeónico. El mago puede ejecutar innatamente uno de dichos hechizos cada asalto. En el momento del lanzamiento de este conjuro, el brujo debe ejecutar todos los sortilegios que pretende preparar gastando el Zeon con el que pretende usarlos. Sólo es posible mantener activo un conjuro natural a la vez","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Prisma de magia', '{"conjuro":"Prisma de magia","via":"Libre acceso","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":20,"efectoBase":"400 puntos de Zeon","efectoIntermedio":"800 puntos de Zeon","efectoAvanzado":"1.500 puntos de Zeon","efectoArcano":"3.000 puntos de Zeon","efecto":"Solidifica la magia, creando un recipiente sobrenatural para el Zeon. Aplicado a reglas de juego, conforma un contenedor de magia que aparece vacío. Sólo es posible mantener activo un conjuro de Prisma de Magia a la vez","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Devolución de conjuro', '{"conjuro":"Devolución de conjuro","via":"Libre acceso","nivel":82,"diario":"No","tipo":"Automático","accion":"Pasiva","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":240,"zeonArcano":280,"mantArcano":".","efectoBase":"Zeón máximo del conjuro 100","efectoIntermedio":"Zeón máximo del conjuro 120","efectoAvanzado":"Zeón máximo del conjuro 140","efectoArcano":"Zeón máximo del conjuro 160","efecto":"Devuelve un conjuro activo contra su lanzador, o sobre cualquier otro blanco que se elija. El sortilegio rechazado utiliza la misma Proyección Mágica de quien lo ejecutó. La devolución es un efecto automático","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Teletransporte', '{"conjuro":"Teletransporte","via":"Libre acceso","nivel":82,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":300,"zeonIntermedio":480,"zeonAvanzado":560,"zeonArcano":640,"mantArcano":".","efectoBase":"50 kilómetros / Presencia máxima 80","efectoIntermedio":"1.000 kilómetros / Presencia máxima 180","efectoAvanzado":"5.000 kilómetros / Presencia máxima 240","efectoArcano":"10.000 kilómetros / Presencia máxima 320","efecto":"El hechicero, o quien este designe, es teletransportado a otra posición. Este conjuro permite pasar a través de cuerpos físicos, mientras no se encuentren basados en energía. Puede afectar a tantos blancos como se desee, mientras la suma de su presencias no supere lo que determina el grado del conjuro","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Portal', '{"conjuro":"Portal","via":"Libre acceso","nivel":82,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":500,"zeonIntermedio":600,"zeonAvanzado":700,"zeonArcano":800,"mantBase":25,"mantIntermedio":30,"mantAvanzado":35,"mantArcano":40,"efectoBase":"5 metros de abertura / 1.000 kilómetros de distancia / 500 presencias al día","efectoIntermedio":"15 metros de abertura / 5.000 kilómetros de distancia / 1.000 presencias al día","efectoAvanzado":"25 metros de abertura / 25.000 kilómetros de distancia / 2.000 presencias al día","efectoArcano":"50 metros de abertura/cualquier distancia /Sin límite de presencias","efecto":"Crea una puerta mágica de tránsito entre dos lugares. Cualquiera que la atraviese se trasladará, instantáneamente, hasta la otra abertura. El conjuro queda fijado en el lugar donde es lanzado y en el sitio donde se designe la salida. El mago puede decidir, si funciona en ambas direcciones o sólo transporta en una.","_seccion":"LIBRE ACCESO 81-90"}'::jsonb),
  ('core-exxet', 'conjuros', 'Imitar conjuro', '{"conjuro":"Imitar conjuro","via":"Libre acceso","nivel":92,"diario":"No","tipo":"Efecto (variab)","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":360,"zeonArcano":420,"mantArcano":".","efectoBase":"Valor zeónico máximo 100","efectoIntermedio":"Valor zeónico máximo 150","efectoAvanzado":"Valor zeónico máximo 200","efectoArcano":"Valor zeónico máximo 250","efecto":"Permite al brujo imitar un conjuro que se encuentre en su presencia. Pueden copiarse tanto hechizos automáticos, si se lanzan en el mismo asalto que se utiliza la imitación, como conjuros mantenidos. Este hechizo imita incluso conjuros de Alta Magia o Divinos, sin necesidad de que el brujo tenga el Gnosis necesario para lanzarlos. El brujo elige si emplea su propia Proyección Mágica o la de quien lanza el conjuro original.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Condicionamiento', '{"conjuro":"Condicionamiento","via":"Libre acceso","nivel":92,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":300,"zeonIntermedio":400,"zeonAvanzado":500,"zeonArcano":600,"mantBase":30,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"Zeón máximo 100","efectoIntermedio":"Zeón máximo 150","efectoAvanzado":"Zeón máximo 200","efectoArcano":"Zeón máximo 250","efecto":"Afecta a otros conjuros del mago, estancándolos hasta darse una circunstancia. Debe lanzarse a la vez que los hechizos adicionales. El conjuro se activará automáticamente en el momento dé la circunstancia, incluso si el mago no es consciente. La acción del conjuro es activa o pasiva, dependiendo de este. Puede tener varios conjuros pero sin exceder el Zeon máximo determinado por Grado del conjuro. Sólo es posible mantener activo un condicionar a la vez.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ojo del tiempo', '{"conjuro":"Ojo del tiempo","via":"Libre acceso","nivel":92,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"Una década","efectoIntermedio":"Un siglo","efectoAvanzado":"Una milenio","efectoArcano":"Cualquier periodo de tiempo","efecto":"El brujo puede enviar sus sentidos al pasado, para observar cualquier acontecimiento que haya ocurrido tiempo atrás en el lugar donde se encuentra como si estuviera presente. El lanzador puede avanzar y retroceder libremente al momento que desee dentro del periodo que le permite el grado del conjuro","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sellar', '{"conjuro":"Sellar","via":"Libre acceso","nivel":92,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":200,"zeonIntermedio":360,"zeonAvanzado":420,"zeonArcano":480,"mantArcano":".","efectoBase":"Estanca un conjuro de grado base","efectoIntermedio":"Estanca un conjuro de grado intermedio","efectoAvanzado":"Estanca un conjuro de grado avanzado","efectoArcano":"Estanca un conjuro de grado arcano","efecto":"Estanca un conjuro anímico activo en una persona, haciendo imposible que se libre de sus efectos. El conjuro se utiliza sobre un conjuro Anímico lanzado anteriormente sobre un individuo que falló la Resistencia. Hasta que el conjuro Anímico no deje de mantenerse o sea destruido, el sujeto pierde la capacidad de realizar una RM. No tiene efectos sobre hechizos sin mantenimiento, o aquellos que influyan sólo en un área determinada.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vincular mantenimiento', '{"conjuro":"Vincular mantenimiento","via":"Libre acceso","nivel":92,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"El mago vincula el mantenimiento de un conjuro a otro mago u objeto mágico. Para evitalo superar RM, si no se da cuenta, no puede realizar un nuevo control de RM. Si se da cuenta, podrá repetir tirada, dependiendo del tipo de hechizo, cada día si es diario, o cada 5 asaltos si no. En el momento en que supere la RM o no le queden suficientes puntos de Zeon, los efectos de la vinculación desaparecerán para siempre.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Fortalecer la magia', '{"conjuro":"Fortalecer la magia","via":"Libre acceso","nivel":92,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":200,"zeonIntermedio":360,"zeonAvanzado":480,"zeonArcano":600,"mantBase":20,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"+50 al valor zeónico falso de los conjuros","efectoIntermedio":"+100 al valor zeónico falso de los conjuros","efectoAvanzado":"+150 al valor zeónico falso de los conjuros","efectoArcano":"+250 al valor zeónico falso de los conjuros","efecto":"Potencia la magía del mago. Fortalece los conjuros contra efectos que pudieran ser perjudiciales. Añade puntos de Zeon “falsos” al valor zeónico de los conjuros que utilice. Este incremento no es real, por lo que estos puntos no otorgan ningún efecto añadido pero aumentan su potencial contra habilidades que afecten a hechizos.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'El don del conocimiento', '{"conjuro":"El don del conocimiento","via":"Libre acceso","nivel":92,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":30,"mantIntermedio":45,"mantAvanzado":60,"mantArcano":75,"efectoBase":"+100 de bono","efectoIntermedio":"+250 de bono","efectoAvanzado":"+400 de bono","efectoArcano":"+600 de bono","efecto":"El hechicero obtiene conocimientos intelectuales que desconoce. Otorga al brujo, o a quien este designe, un bono a las secundarias del campo Intelectual, que podrá repartir como considere apropiado (hasta un tope de 340). Por ejemplo si obtuviera 100 puntos, puede aumentar 40 puntos su habilidad de Historia, más 30 en Ciencia y Animales, respectivamente. Sólo un conjuro de El Don del Conocimiento puede estar activo en un sujeto a la vez.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Posesión', '{"conjuro":"Posesión","via":"Libre acceso","nivel":92,"diario":"Si","tipo":"Animico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":300,"zeonIntermedio":400,"zeonAvanzado":500,"zeonArcano":600,"mantBase":30,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 180","efectoArcano":"RM 220","efecto":"Controla el cuerpo de otro. Permite usar habilidades del poseído o las suyas. Si usa habilidades del poseído, las características físicas son las del poseído. Si el ser es diferente al mago aplica un  –20 a –40. El mago permanece en estado de coma. Los ataques que no dañan energía afectan al cuerpo poseído, pero si son sobrenaturales, restan vida a ambos. En el caso de que el cuerpo muera, pero no el mago, regresa de a su forma original. Para evitar, superar RM.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudar contra poderes', '{"conjuro":"Escudar contra poderes","via":"Libre acceso","nivel":92,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":300,"zeonIntermedio":360,"zeonAvanzado":420,"zeonArcano":480,"mantBase":30,"mantIntermedio":40,"mantAvanzado":45,"mantArcano":50,"efectoBase":"50m radio / Zeon 100 / Potencial Psí. 140 / Ki 8 / Convocación inferior a 180","efectoIntermedio":"150m radio / Zeon 150 / Potencial Psíquico 180 / Ki 14 / Convocación 240","efectoAvanzado":"300m radio / Zeon 200 / Potencial Psíquico 240 / Ki 22 / Convocación 280","efectoArcano":"500m de radio / Zeon 250 / Potencial Psíquico 280 / Ki 30 / Convocación 320","efecto":"Afecta un lugar dentro del cual el hechicero crea un área que impide utilizar poderes sobrenaturales de cualquier tipo. En su interior, no funcionará ningún conjuro, convocación, poder psíquico o Técnica de Ki cuyo valor zeónico, potencial o coste no supere lo que indique el grado del conjuro. El área permanece siempre estática donde fue creada y afecta automáticamente a todos los que estén en su interior, incluyendo al propio lanzador","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'El magistrado', '{"conjuro":"El magistrado","via":"Libre acceso","nivel":92,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":450,"zeonIntermedio":600,"zeonAvanzado":800,"zeonArcano":1000,"mantBase":45,"mantIntermedio":60,"mantAvanzado":80,"mantArcano":100,"efectoBase":"50 metros de radio / RM 140","efectoIntermedio":"100 metros de radio / RM 180","efectoAvanzado":"500 metros de radio / RM 220","efectoArcano":"1 kilómetro de radio / RM 260","efecto":"El mago es juez dentro del area. Puede vetar acción activa de gente, evitando lo que no quiera. No es capaz de someter a nadie a su voluntad. La prohibición es una acción pasiva. El mago debe ser consciente de lo que desea vetar. Cada vez que se quiera hacer algo prohíbido superar RM. Si  alguien consigue superar RM, no se verá totalmente libre, ya que en el siguiente asalto volverá a someterse si no supera otro control. El área permanece estática.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Magia innata', '{"conjuro":"Magia innata","via":"Libre acceso","nivel":92,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":50,"mantIntermedio":60,"mantAvanzado":70,"mantArcano":80,"efectoBase":"25 metros de radio / +10 al valor zeónico de la magia innata","efectoIntermedio":"100 metros de radio/ +20 al valor zeónico de la magia innata","efectoAvanzado":"250 metros de radio / +30 al valor zeónico de la magia innata","efectoArcano":"500 metros de radio / +40 al valor zeónico de la magia innata","efecto":"Este hechizo incrementa exponencialmente el potencial mágico ambiental, aumentando la capacidad de los brujos para dominar innatamente su magia. En reglas de juego, encanta una zona estática dentro de la cual los conjuros innatos tienen un potencial adicional de lo que indique el ACT del brujo. El lanzador posee la capacidad de elegir si este incremento favorece a todo el mundo, o si sólo él se beneficia de sus efectos","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Predestinación', '{"conjuro":"Predestinación","via":"Libre acceso","nivel":92,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":12,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":19,"zeonBase":600,"zeonIntermedio":900,"zeonAvanzado":1200,"zeonArcano":1500,"efectoBase":"RM 140","efectoIntermedio":"RM 170","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"El mago puede modificar sucesos venideros. El mago designa la complejidad de estos como desee. Es posible que predestine un único evento, dejando a casualidad los sucesos que permitan que pase, o determinar los aspectos hasta el fin deseado. No puede causar eventos imposibles. Los sucesos determinados pueden fijarse para una fecha concreta o para que se repitan eternamente a lo largo del tiempo. No crea un futuro absoluto e ineludible.","_seccion":"LIBRE ACCESO 91-100"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sentir el caos', '{"conjuro":"Sentir el caos","via":"Caos","nivel":4,"diario":"Sí","tipo":"Efecto (Det)","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":12,"efectoBase":"50 metros de radio","efectoIntermedio":"100 metros de radio","efectoAvanzado":"250 metros de radio","efectoArcano":"500 metros de radio/Percibe gnosis > 20 o Natura > 10, si no superan RM 160","efecto":"El hechicero es capaz de notar las fluctuaciones provocadas por el caos en el ambiente, permitiéndole sentir cualquier cosa innatural para la realidad que ocurra dentro del área del conjuro. No determina la localización exacta, pero si es consciente del nivel de influencia del caos.","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aura de caos', '{"conjuro":"Aura de caos","via":"Caos","nivel":14,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM 80 / 10 metros de radio / Presencia máxima 100","efectoIntermedio":"RM 100 / 20 metros de radio / Presencia máxima 120","efectoAvanzado":"RM 120 / 40 metros de radio / Presencia máxima 140","efectoArcano":"RM 140 / 60 metros de radio / Presencia máxima 160","efecto":"Mientras este sortilegio se encuentre activo, todas las personas se comportan como si tuvieran Natura 10 (aunque, a efectos de su importancia en la realidad, mantienen su valor original) y todo tipo de sucesos inusuales e imposibles ocurren sin parar. En el momento de lanzar este conjuro, el hechicero debe decidir si lo deja fijo en una zona determinada o hace que el aura se mueva consigo","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alteración de la probabilidad', '{"conjuro":"Alteración de la probabilidad","via":"Caos","nivel":24,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":20,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"+2 al rango de pifia / -5 al rango de tirada abierta","efectoIntermedio":"+4 al rango de pifia / -10 al rango de tirada abierta","efectoAvanzado":"+6 al rango de pifia / -15 al rango de tirada abierta","efectoArcano":"+8 al rango de pifia / -20 al rango de tirada abierta","efecto":"El hechicero o el personaje que este elija sufre una alteración temporal de su naturaleza, siendo capaz de realizar con mucha más facilidad acciones extremas, tanto para bien como para mal. En consecuencia, incrementa su rango de pifia y tirada abierta, en los valores indicados por el grado del conjuro. Por ejemplo, alguien sin maestría que fuera afectado por este conjuro en grado base, pifiaría con un resultado de 5 y obtendría una tirada abierta con un 85","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alterar la suerte', '{"conjuro":"Alterar la suerte","via":"Caos","nivel":34,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":250,"zeonArcano":400,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160 / La suerte concedida es algo desproporcionado, rozando lo absurdo","efectoArcano":"RM 180","efecto":"El blanco de este conjuro ven incrementados los resultados producidos por el azar y la suerte del modo deseado por el hechicero, de manera que cualquier situación que se vea determinada por el azar obtiene siempre resultados desmesurados, ya sea para bien o para mal.  Los personajes con la Ventajas y Desventaja Afortunado y Desafortunado ven incrementados exponencialmente sus efectos.","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Caminos del caos', '{"conjuro":"Caminos del caos","via":"Caos","nivel":44,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":14,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":280,"zeonArcano":400,"mantBase":20,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Una tirada por asalto","efectoIntermedio":"Dos tiradas por asalto","efectoAvanzado":"Tres tiradas por asalto","efectoArcano":"Cuatro tiradas por asalto o una que sea pifia","efecto":"El hechicero puede repetir cierta cantidad de tiradas por asalto, siempre y cuando ninguna de ellas sea un resultado de pifia. No es posible afectar dos veces la misma tirada","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aberración caótica', '{"conjuro":"Aberración caótica","via":"Caos","nivel":54,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":700,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Nivel 2","efectoIntermedio":"Nivel 4","efectoAvanzado":"Nivel 8","efectoArcano":"Nivel 12","efecto":"Crea un engendro solidificando el caos, que se comportará de un modo impredecible (aunque por regla general, siempre violento). El lanzador solamente puede elegir gastar voluntariamente la mitad de los PD de la criatura, mientras que la otra mitad serán determinados al azar por el Director de Juego.No permite crear criaturas de un nivel superior al del hechicero, ya que estas se basan en la presencia espiritual del mismo.","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Manipulación del caos', '{"conjuro":"Manipulación del caos","via":"Caos","nivel":64,"diario":"No","tipo":"Automático","accion":"Pasiva","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":200,"zeonAvanzado":300,"zeonArcano":400,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 140","efectoIntermedio":"RM 180 / puede obligar a repetir la tirada dos veces","efectoAvanzado":"RM 220 /  Puede obligar a repetir la tirada tres veces","efectoArcano":"RM 260/ Puede obligar a repetir la tirada cuatro veces","efecto":"El conjuro debe ser lanzado inmediatamente después de que se realice una acción; el personaje que la haya realizado deberá repetir inmediatamente su tirada de dados. Este conjuro es automático, y la condición para obligar a realizar la RM es estar ante el brujo y haber realizado una acción en ese momento. Los seres con Gnosis 35 o Natura elevada son conscientes del cambio, mientras que los demás no pueden percibirlo","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mutación caótica', '{"conjuro":"Mutación caótica","via":"Caos","nivel":74,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":200,"zeonIntermedio":400,"zeonAvanzado":800,"zeonArcano":1200,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"100 PD / 100 RM","efectoIntermedio":"200 PD / 120 RM","efectoAvanzado":"300 PD / 140 RM","efectoArcano":"400 PD / Gnosis 30 / 160 RM","efecto":"El hechicero o el individuo que éste determine consigue PD adicionales para obtener Poderes de monstruo como si fuera un Ser Entre Mundos con Gnosis 25. No obstante, únicamente puede elegir gastar voluntariamente la mitad de dichos PD, mientras que la otra mitad serán determinados al azar por el Director de Juego. Por regla general, los poderes que provoca este conjuro siempre dejan visibles cambios físicos.","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Control del caos', '{"conjuro":"Control del caos","via":"Caos","nivel":84,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":300,"zeonIntermedio":500,"zeonAvanzado":800,"zeonArcano":1200,"mantBase":50,"mantIntermedio":60,"mantAvanzado":67,"mantArcano":75,"efectoBase":"Hasta Gnosis 30 / RM 120","efectoIntermedio":"Hasta Gnosis 35 / RM 160.","efectoAvanzado":"Hasta Gnosis 40 / RM 200","efectoArcano":"Hasta Gnosis 45 / RM 260","efecto":"El hechicero tiene la capacidad de doblegar la naturaleza del caos a su antojo, pudiendo usarlo para obtener los resultados que desee. De ese modo, puede hacer desde cosas tan simples como que una silla se rompa hasta que el espacio se pliegue creando portales. El brujo obtiene los poderes Gnosticos Influir en la Realidad y Auspice. En el caso de que un ser basado en caos se encuentre en presencia del hechicero, este puede dominarlo si no supera una RM.","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Caos primario', '{"conjuro":"Caos primario","via":"Caos","nivel":94,"diario":"Sí","tipo":"Automático","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":500,"zeonIntermedio":900,"zeonAvanzado":1500,"zeonArcano":2400,"mantBase":100,"mantIntermedio":180,"mantAvanzado":300,"mantArcano":480,"efectoBase":"500 metros","efectoIntermedio":"1 kilómetro","efectoAvanzado":"5 kilómetro / Tras un minuto, cualquiera es afectado por  Mutación Caótica","efectoArcano":"25 kilómetros/ A menos de un kilómetro del núcleo, RM 150 o descreación","efecto":"Alterando completamente las leyes de la realidad, el hechicero crea caos en su estado más puro, una zona donde todo cuanto contiene deja de responder a ninguna regla de la razón. Alguien normal puede volverse loco en pocos minutos, mientras que todo poder sobrenatural puede salir fuera de control. La zona de acción de este conjuro es determinada por su grado, y permanece estática donde fue lanzada","_seccion":"CAOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Moral', '{"conjuro":"Moral","via":"Guerra","nivel":4,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":11,"intRArcano":13,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Da +40 a Frialdad / 10m radio","efectoIntermedio":"Da +80 a Frialdad / 50m radio","efectoAvanzado":"Da +120 a Frialdad / 250m radio","efectoArcano":"Da +180 a Frialdad / 500m radio","efecto":"Este grito provoca que los aliados del hechicero aumenten su espíritu combativo y se vuelvan inmunes a los efectos del Miedo o Dolor. A efectos de juego, se obtiene un Bono a Frialdad hasta que finalice el combate en el que se encuentran trabados o transcurran más de 10 min.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ira ancestral', '{"conjuro":"Ira ancestral","via":"Guerra","nivel":14,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":40,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":130,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"10m radio","efectoIntermedio":"50m radio","efectoAvanzado":"250m radio","efectoArcano":"500m radio","efecto":"Despierta en los aliados del brujo un ansia de lucha que los convierte en guerreros imparables, bestias humanas llenas de furia sin par. El hechizo confiere un Bono de +10 al Ataque y provoca el estado de Ira (impidiendo a los afectados perder el control o atacarse unos a otros) en todo aquel aliado dentro del radio de acción.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Velocidad en la batalla', '{"conjuro":"Velocidad en la batalla","via":"Guerra","nivel":24,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Da +10 Turno / 10m radio","efectoIntermedio":"Da +10 Turno / 50m radio","efectoAvanzado":"Da +20 Turno / 250m radio","efectoArcano":"Da +20 Turno / 500m radio","efecto":"Canaliza el espíritu de batalla de los aliados, haciéndolos trabajar como un solo hombre y permitiéndoles anticiparse a las acciones de sus enemigos.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Destrucción desencadenada', '{"conjuro":"Destrucción desencadenada","via":"Guerra","nivel":34,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":20,"efectoBase":"Da +20 Daño / 10m radio","efectoIntermedio":"Da +20 Daño / 50m radio","efectoAvanzado":"Da +30 Daño / 250m radio","efectoArcano":"Da +40 Daño / 500m radio","efecto":"Incrementa la potencia destructiva de los aliados cercanos al PJ, otorgándoles a estos un Bono al Daño de todos sus ataques.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Protección final', '{"conjuro":"Protección final","via":"Guerra","nivel":44,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":20,"efectoBase":"Da +10 a Todas las Resistencias / +1 TA / 10m radio","efectoIntermedio":"Da +10 a Todas las Resistencias / +2 TA / 50m radio","efectoAvanzado":"Da +20 a Todas las Resistencias / +2 TA / 250m radio","efectoArcano":"Da +30 a Todas las Resistencias / +3 TA / 500m radio","efecto":"Incrementa la protección y resistencia de los aliados cercanos al brujo, otorgándoles a estos un Bono a sus Resistencias y Tipo de Armadura.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Marcha implacable', '{"conjuro":"Marcha implacable","via":"Guerra","nivel":54,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":30,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":100,"efectoBase":"10m radio","efectoIntermedio":"50m radio","efectoAvanzado":"100m radio","efectoArcano":"500m radio","efecto":"Este hechizo permite a los compañeros del brujo marchar de forma incesante, resistiendo la fatiga y la furia de los elementos. A efectos de juego, proporciona a todos los aliados dentro del área de efecto del conjuro las Habilidades del Ki: Uso de la Energía Necesaria y Eliminación de Necesidades.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Campeón', '{"conjuro":"Campeón","via":"Guerra","nivel":64,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":140,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":15,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":30,"efectoBase":"Da +10 a Toda Acción / +10 Daño / +10 Turno / +2 TA","efectoIntermedio":"Da +10 a Toda Acción / +20 Daño / +20 Turno / +3 TA","efectoAvanzado":"Da +20 a Toda Acción / +20 Daño / +20 Turno / +4 TA","efectoArcano":"Da +30 a Toda Acción / +30 Daño / +30 Turno / +5 TA","efecto":"Canaliza el espíritu combativo del grupo en uno de sus guerreros, creando como resultado un luchador implacable e invencible. El hechizo otorga diferentes bonos a las habilidades de combate, siempre y cuando combata junto a sus compañeros. Sólo un individuo por cada 10 que compongan un grupo de batalla puede ser afectado por este sortilegio.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Órdenes precisas', '{"conjuro":"Órdenes precisas","via":"Guerra","nivel":74,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"25m radio","efectoIntermedio":"100m radio","efectoAvanzado":"250m radio","efectoArcano":"500m radio","efecto":"Permite al hechicero o a aquel sobre el que se lance el conjuro trasmitir órdenes directamente a la mente de sus compañeros. Estos mensajes son automáticos, sin la necesidad de hablar con ellos o de formular largas frases o indicaciones que pueden ser escuchadas por personas indeseadas. El elegido puede seleccionar quienes les escuchan y quienes no, o incluso transmitir varias órdenes a la vez con un simple pensamiento.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Maestro de la guerra', '{"conjuro":"Maestro de la guerra","via":"Guerra","nivel":84,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":10,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"200 Habilidad","efectoIntermedio":"250 Habilidad","efectoAvanzado":"300 Habilidad","efectoArcano":"Sin Límite","efecto":"El hechicero puede combatir físicamente con cualquier arma usando su habilidad de Proyección Mágica ofensiva y defensiva como si fuera habilidad de ataque y defensa. El límite máximo que puede alcanzar está determinado por el Grado del conjuro.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Hasta más allá del fin', '{"conjuro":"Hasta más allá del fin","via":"Guerra","nivel":94,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":250,"zeonIntermedio":500,"zeonAvanzado":750,"zeonArcano":1000,"mantBase":25,"mantIntermedio":50,"mantAvanzado":75,"mantArcano":100,"efectoBase":"25m radio","efectoIntermedio":"50m radio","efectoAvanzado":"250m radio","efectoArcano":"500m radio / Puede seguir luchando  hasta 2 asaltos después de muerto","efecto":"Este hechizo lleva más allá del poder de los mortales el espíritu combativo de los aliados del brujo, permitiéndoles seguir adelante incluso en el umbral de la muerte. Todos sus aliados que se encuentren dentro del radio de acción del sortilegio duplican su aguante en puntos de vida negativos (en caso de usar las reglas opcionales Entre la Vida y la Muerte, aplican un +40 a sus controles de RF), y no sufren ningún negativo por combatir en dicho estado.","_seccion":"GUERRA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Pluma de la realidad', '{"conjuro":"Pluma de la realidad","via":"Literae","nivel":4,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Afecta a conjuros Literae de grado base.","efectoIntermedio":"Afecta a conjuros Literae de grado intermedio.","efectoAvanzado":"Afecta a conjuros Literae de grado avanzado.","efectoArcano":"Afecta a conjuros Literae de grado arcano.","efecto":"Crea una pluma sobrenatural que escribe sobre cualquier superficie sin la necesidad de tinta. Usándola durante el lanzamiento de un conjuro de la sub-vía Literae, el hechicero puede potenciar monumentalmente los efectos de dicho sortilegio, haciendo que el coste de Zeon requerido se reduzca a la mitad. Por ejemplo, un conjuro de Misiva en grado base pasaría a costar 40 en lugar de 80.","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Misiva', '{"conjuro":"Misiva","via":"Literae","nivel":14,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":280,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"10 kilómetros","efectoIntermedio":"100 kilómetros","efectoAvanzado":"1000 kilómetros","efectoArcano":"Cualquier Lugar","efecto":"Tras escribir una carta es posible utilizar este hechizo para enviar su contenido a un individuo a quien el hechicero conozca personalmente. Puede traspasar estructuras encantadas e menor poder siempre y cuando haya suficiente espacio para, por ejemplo “colar” la carta por debajo de la puerta.","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Diario de viaje', '{"conjuro":"Diario de viaje","via":"Literae","nivel":24,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"1 día","efectoIntermedio":"1 semana","efectoAvanzado":"1 mes","efectoArcano":"1 año","efecto":"Encanta un libro para que recoja todas las experiencias que afecten al mago para poder revisarlas posteriormente, como si a efectos de juego estuviera escribiendo un detallado diario. El grado del conjuro determina el máximo periodo de tiempo que dicho libro cubre retrospectivamente desde el momento del lanzamiento","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Orden escrita', '{"conjuro":"Orden escrita","via":"Literae","nivel":34,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":240,"zeonAvanzado":360,"zeonArcano":480,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 120","efectoIntermedio":"RM o RP 140","efectoAvanzado":"RM o RP 160","efectoArcano":"RM o RP 180","efecto":"La orden funcionará incluso si está oculta entre otras frases, aunque el personaje afectado obtiene entre un +20 y +60 al control si el mandato va directamente en contra de su naturaleza. Este conjuro puede repetirse de manera encadenada en varias ocasiones para crear una orden compleja, como “abre la puerta y luego olvida lo ocurrido”. El poder de las palabras pierde su poder después de haber imbuido a una persona con la orden.","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo de palabras', '{"conjuro":"Escudo de palabras","via":"Literae","nivel":44,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"200 puntos de resistencia","efectoIntermedio":"500 puntos de resistencia","efectoAvanzado":"800 puntos de resistencia","efectoArcano":"1.200 puntos de resistencia","efecto":"Usando la Pluma Mágica para trazar caracteres en el aire, el hechicero crea un escudo de palabras que le defienden tanto de ataques físicos como sobrenaturales. El escudo regenera cada asalto tantos Puntos de Resistencia como la habilidad base del mago en Arte (Literatura).","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Teatro de la vida', '{"conjuro":"Teatro de la vida","via":"Literae","nivel":54,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":240,"zeonIntermedio":360,"zeonAvanzado":480,"zeonArcano":600,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"RM o RP 120/ Límite de Presencia 100/ 20 metros de radio.","efectoIntermedio":"RM o RP 140/ Límite de Presencia 180/ 40 metros de radio.","efectoAvanzado":"RM o RP 160/ Límite de Presencia 240/ 80 metros de radio.","efectoArcano":"RM o RP 180/ Límite de Presencia 320/ 150 metros de radio.","efecto":"Permite al hechicero modificar el comportamiento de las personas que se encuentran a su alrededor escribiendo sobre una superficie las acciones que quiere que dichos individuos realicen.  Puede afectar a varias personas, siempre que su presencia combinada no supere el límite. La condición para verse afectado es estar dentro del área de efecto del conjuro y que el lanzador conozca el nombre real de las personas sobre las que quiere influir.","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Compendio', '{"conjuro":"Compendio","via":"Literae","nivel":64,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":260,"zeonAvanzado":380,"zeonArcano":500,"mantBase":10,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"120 puntos de habilidad intelectual","efectoIntermedio":"240 puntos de habilidad intelectual","efectoAvanzado":"320 puntos de habilidad intelectual","efectoArcano":"440 puntos de habilidad intelectual","efecto":"Encanta un libro para que responda las preguntas que se le dirijan de manera que, cuando alguien haga una pregunta ante él, se escribirá en sus páginas una contestación. Lamentablemente, el libro no es capaz de responder a cualquier duda; al lanzar Compendio, el manuscrito afectado recibe una cantidad de puntos de una habilidad intelectual, y dará una respuesta apropiada basada en lo que sabría un experto con la misma puntuación sobre el tema.","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Dramaturgo', '{"conjuro":"Dramaturgo","via":"Literae","nivel":74,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":280,"zeonIntermedio":320,"zeonAvanzado":480,"zeonArcano":700,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Presencia máxima 40","efectoIntermedio":"Presencia máxima 80","efectoAvanzado":"Presencia máxima 120","efectoArcano":"Presencia máxima 160","efecto":"Este hechizo modifica la realidad siempre que sea algo plausible y no afecte directamente a otro ser vivo. Las posibilidades de este hechizo son casi infinitas, siempre y cuando los elementos y objetos empleados sean simples y con una presencia que no supere lo que determine el grado del conjuro.","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Secundario', '{"conjuro":"Secundario","via":"Literae","nivel":84,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":17,"zeonBase":400,"zeonIntermedio":600,"zeonAvanzado":800,"zeonArcano":1200,"mantBase":40,"mantIntermedio":60,"mantAvanzado":80,"mantArcano":120,"efectoBase":"Nivel 2","efectoIntermedio":"Nivel 5","efectoAvanzado":"Nivel 7","efectoArcano":"Nivel 10","efecto":"Crea un “personaje” con la personalidad y habilidades que desee el hechicero. Para hacerlo, el lanzador debe de describir en un libro la personalidad, historia y naturaleza de dicho individuo, quien creerá realmente ser lo que el brujo ha descrito para él. Si el libro es destruído, el Secundario desaparecerá. El nivel del Secundario no puede superar el indicado por el grado del sortilegio ni tampoco el nivel del propio hechicero.","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Tragedia', '{"conjuro":"Tragedia","via":"Literae","nivel":94,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":12,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":19,"zeonBase":500,"zeonIntermedio":900,"zeonAvanzado":1400,"zeonArcano":2500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"El lanzador puede escribir cualquier desenlace que desee para la vida de una persona. La condición para verse afectado por este sortilegio es haber sido visto por el brujo al menos una vez y que este conozca su nombre verdadero. Para evitar sus efectos, tanto el blanco de Tragedia como cualquier persona involucrada han de superar la RM del sortilegio. De conseguirlo, se vuelven inmunes a este hechizo (lanzado por el mismo brujo) durante el resto de su vida.","_seccion":"LITERAE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Autopsia', '{"conjuro":"Autopsia","via":"Muerte","nivel":4,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":4,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"1 hora","efectoIntermedio":"1 día","efectoAvanzado":"1 semana","efectoArcano":"1 mes","efecto":"Determina la causa de la muerte y el momento en el que ocurrió. No espeficica si el blanco del conjuro murió asesinado, ni tampoco el responsable, pero sí si alguien ha fallecido por contusión masiva, o el tipo de enfermedad que lo mató.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Resistencia a la muerte', '{"conjuro":"Resistencia a la muerte","via":"Muerte","nivel":14,"diario":"Sí","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":14,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"+20 a resistencias","efectoIntermedio":"+40 a resistencias","efectoAvanzado":"+60 a resistencias","efectoArcano":"+80 a resistencias","efecto":"Protege contra cualquier efecto que pueda provocar la muerte de manera automática, otorgando un bono a todas las resistencias del objetivo.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Exterminio menor', '{"conjuro":"Exterminio menor","via":"Muerte","nivel":24,"diario":"No","tipo":"Efecto, Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 60 / 10 metros de radio","efectoIntermedio":"RM 80 / 25 metros de radio","efectoAvanzado":"RM 100 / 50 metros de radio","efectoArcano":"RM 120 / 75 metros de radio","efecto":"Mata a las criaturas con Presencia 20 determinadas por el lanzador en un área, si no superan la RM determinada por el grado de conjuro.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Golpe de gracia', '{"conjuro":"Golpe de gracia","via":"Muerte","nivel":34,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 140","efectoIntermedio":"RM 160","efectoAvanzado":"RM 180","efectoArcano":"RM 200","efecto":"Remata a alguien que esté a punto de morir. La condición para ser afectado es que el objetivo debe encontrarse en el estado entre la vida y la muerte , y fallecerá de manera automática si no supera la RM.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Poner en reposo', '{"conjuro":"Poner en reposo","via":"Muerte","nivel":44,"diario":"No","tipo":"Animico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120 / 10 m. de radio","efectoIntermedio":"RM 140 / 25 m. de radio","efectoAvanzado":"RM 160 / 50 m. de radio","efectoArcano":"RM 180 / 75 m. de radio","efecto":"Destruye automáticamente a criaturas no muertas sin alma en el radio de acción del conjuro. Las criaturas pueden resistirse superando la RM.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sentir la muerte (Muerte)', '{"conjuro":"Sentir la muerte (Muerte)","via":"Muerte","nivel":54,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"En 100 m detecta muertes hace < 1 hora, o moribundo morirá < 1 minuto","efectoIntermedio":"150 m, muertes hace < 6 horas, o si alguien  va a morir en diez minutos.","efectoAvanzado":"Percibe tiempo de vida de una persona, y si alguien ha muerto en la zona","efectoArcano":"Percibe las causas de muertes pasadas y futuras","efecto":"El lanzador es capaz de presentir la muerte en las cercanías.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Memento mori', '{"conjuro":"Memento mori","via":"Muerte","nivel":64,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":260,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 80 / 5 m. radio","efectoIntermedio":"RM 100 / 10 m. radio","efectoAvanzado":"RM 120 / 25 m. radio","efectoArcano":"RM 140 / 50 m. radio","efecto":"Este hechizo mata a cualquier criatura dentro de su área que pueda ser considerada un ser vivo, sin importar su naturaleza o condición.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Maldición mortal', '{"conjuro":"Maldición mortal","via":"Muerte","nivel":74,"diario":"Sí","tipo":"Anímico, Automático","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":150,"zeonIntermedio":250,"zeonAvanzado":350,"zeonArcano":500,"mantBase":15,"mantIntermedio":25,"mantAvanzado":35,"mantArcano":50,"efectoBase":"RM 120","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"El lanzador puede hacer que un individuo muera en un momento determinado por él, y de la forma que él elija. El objetivo, y todos aquellos implicados en las circunstancias de su muerte, tienen derecho a una RM para resistir los efectos.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detener la muerte', '{"conjuro":"Detener la muerte","via":"Muerte","nivel":84,"diario":"No","tipo":"Efecto, Anímico","accion":"Pasiva","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":350,"zeonIntermedio":500,"zeonAvanzado":800,"zeonArcano":1200,"mantBase":15,"mantIntermedio":25,"mantAvanzado":40,"mantArcano":60,"efectoBase":"El personaje ignora  cualquier efecto de muerte automática","efectoIntermedio":"El personaje se vuelve inmortal ante el daño físico.","efectoAvanzado":"El afectado no puede morir a consecuencia de críticos.","efectoArcano":"Inmune a cualquier negativo a la acción derivado del deterioro físico.","efecto":"El blanco de este conjuro se vuelve temporalmente inmortal. No se le conisidera un No Muerto. No tiene efecto sobre poderes que exterminen directamente el alma, o efectos similares.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'La muerte', '{"conjuro":"La muerte","via":"Muerte","nivel":94,"diario":"Sí","tipo":"Efecto, Automático","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":400,"zeonIntermedio":750,"zeonAvanzado":1200,"zeonArcano":2000,"mantBase":40,"mantIntermedio":75,"mantAvanzado":120,"mantArcano":200,"efectoBase":"500 m. de radio / RF o RM 80","efectoIntermedio":"1 km. de radio / RF o RM 100","efectoAvanzado":"5 km. de radio / RF o RM 120","efectoArcano":"10 km. de radio / RF o RM 140","efecto":"El brujo puede decidir a voluntad quien fallece en el radio de acción del conjuro. Como efecto automático, el lanzador puede elegir que cualquier ser vivo muera si no supera una RM o RF contra el valor determinado. Alguien que supere la resistencia una vez, no puede volver a ser afectado por este poder, si es lanzado por el mismo hechicero.","_seccion":"MUERTE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Tempo', '{"conjuro":"Tempo","via":"Musical","nivel":4,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":50,"zeonAvanzado":70,"zeonArcano":100,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Da + 40 a buscar","efectoIntermedio":"Da +60 a buscar","efectoAvanzado":"Da +80 a buscar","efectoArcano":"Da +100 a buscar","efecto":"Controlando el ritmo del mundo, este conjuro aísla al hechicero de las distracciones exteriores permitiéndole discernir de manera intuitiva todos los sonidos que le rodean. En conscuencia, obtiene un bono a su habilidad secundaria Buscar para todos aquellos controles que estén relacionados con el sonido.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Cantábile', '{"conjuro":"Cantábile","via":"Musical","nivel":14,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":60,"zeonAvanzado":80,"zeonArcano":100,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"100 metros","efectoIntermedio":"250 metros","efectoAvanzado":"500 metros","efectoArcano":"1 kilometro","efecto":"Este conjuro permite al personaje hacer sonar su voz o una melodía interpretada por este en cualquier lugar que desee hasta una distancia máxima determinada por el grado del conjuro.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Plagio', '{"conjuro":"Plagio","via":"Musical","nivel":24,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":70,"zeonAvanzado":80,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"120 Música","efectoIntermedio":"180 Música","efectoAvanzado":"240 Música","efectoArcano":"280 Música","efecto":"Proporciona al mago la capacidad artística necesaria para efectuar una interpretación de algún tipo de composición musical, ya sea tocando un instrumento o cantando. El hechicero deberá conocer o haber escuchado, aunque sea de forma incompleta, la pieza que desea representar. Al hacerlo, el personaje tiene el equivalente a una habilidad de Música determinado por el grado del conjuro.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Mezzo forte', '{"conjuro":"Mezzo forte","via":"Musical","nivel":34,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 10","efectoIntermedio":"Daño 20","efectoAvanzado":"Daño 30","efectoArcano":"Daño 40","efecto":"Creando una nota musical discordante, el brujo desencadena una destructiva onda de sonido que destroza cualquier cosa sólida con la que se ponga en contacto. El ataque tiene daño base muy bajo pero, en caso de causar daño, el defensor debe realizar un control de RF contra una dificultad igual a 10 veces la perdida de puntos de vida recibida (hasta un máximo de 240) o sufrir un daño adicional equivalente al nivel de fracaso.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Adagio', '{"conjuro":"Adagio","via":"Musical","nivel":44,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":100,"zeonIntermedio":160,"zeonAvanzado":220,"zeonArcano":280,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"120 RM/ 20 metros de radio","efectoIntermedio":"140 RM/ 50 metros de radio","efectoAvanzado":"160 RM/ 100 metros de radio","efectoArcano":"180 RM 150 metros de radio","efecto":"Este conjuro crea una melodía cargada con fuertes emociones que penetran en todo aquel que las escucha al menos en un asalto. Cualquiera que cumpla tal requisito, debe superar un control de RM o verse  imbuido por la emoción elegida. Si alguien escucha Adagio de manera parcial obtiene un + 40 a su tirada de resistencia. No se pueden escoger blancos.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Allegro', '{"conjuro":"Allegro","via":"Musical","nivel":54,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":100,"zeonIntermedio":160,"zeonAvanzado":220,"zeonArcano":280,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"120 RM/ 10 metros de radio","efectoIntermedio":"140 RM/ 25 metros de radio","efectoAvanzado":"160 RM/ 50 metros de radio","efectoArcano":"180 RM/ 100 metros de radio","efecto":"Crea la más hermosa melodía imaginable, que atonta y embelesa a quienes la escuchar.  Todo aquel que se encuentre alrededor del hechicero debe superar cada dos asaltos un control de RM o quedará fascinado, siendo incapaz de realizar acciones activas por su propia voluntad. Los objetivos incapaces de oír son inmunes a este hechizo y si alguien esccha parcialmente la melodía obtiene un +40 a la tirada de resistencia.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Presstisimo', '{"conjuro":"Presstisimo","via":"Musical","nivel":64,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"10 metros de radio/ +1 al tipo de movimiento/ +30 al Turno","efectoIntermedio":"20 metros de radio/ +2 al turno/ +30 al Turno","efectoAvanzado":"30 metros de radio/ +2 al tipo de movimiento/ +40 al Turno","efectoArcano":"40 metros de radio/ +3 al tipo de movimiento/ +50 al Turno","efecto":"Este conjuro crea una frenética melodía que incrementa la velocidad de reacción de todo aquel que la escuche y sea designado por el lanzador. Los afectados que se encuentren cerca del hechicero obtienen de inmediato un bono a su turno e incrementan su velodiad.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Fortísimo', '{"conjuro":"Fortísimo","via":"Musical","nivel":74,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":30,"efectoBase":"10 metros de radio","efectoIntermedio":"25 metros de radio","efectoAvanzado":"50 metros de radio","efectoArcano":"100 metros de radio","efecto":"El hechicero obtiene un control absoluto sobre cualquier sonido que sea producido en el área de influencia determinada por el grado del conjuro, pudiendo alterarlo, incrementar su potencia o hacerlo competamente imperceptible. Salvo si el sonido como tal tiene presencia propia o es producido por un ser con Gnosis 40 o superior, no es posible de ningún modo evitar los efectos de este sortilegio.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Marziale', '{"conjuro":"Marziale","via":"Musical","nivel":84,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"10 metros radio/ +2 a la TA/ +20 RM","efectoIntermedio":"25 metros de radio/ +3 a la TA/ +20 RM y RF","efectoAvanzado":"50 metros de radio/ +5 a la TA/ +20 a la RM, RF y RP/ Barrera de daño 50","efectoArcano":"100 metros de radio/ +5 a la TA/ +30 RM, RF y RP/ Barrera de daño 100","efecto":"Crea una potente melodía que refuerza el aguante innato de aquellos que la escuchen  y sean designados por el lanzador. Aquellos afectados que se encuentren alrededor del brujo obtienen diferentes bonos, descritos en los grados del conjuro. Los beneficios de este conjuro no se superponen, por lo que un individuo que se encuentre detro de la zona de influencia de dos Marzialle diferentes no aplica dos veces sus beneficios.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Anima', '{"conjuro":"Anima","via":"Musical","nivel":94,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":300,"zeonIntermedio":450,"zeonAvanzado":600,"zeonArcano":800,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Afecta a conjuros de grado base","efectoIntermedio":"Afecta a conjuros de grado intermedio","efectoAvanzado":"Afecta a conjuros de grado avanzado","efectoArcano":"Afecta a conjuros de grado arcano","efecto":"Debe de ser lanzado en combinación con otro conjuro de clase Anímico, haciendo que dicho sortilegio se convierta en Automático y funcione sobre cualquiera que esté a menos de 50 metros del hechicero y escuche la melodia mas de un asalto. La RM a superar es la misma de la del conjuro afectado por Anima, pero si alguien percibe la melodia de manera parcial , obtiene un bono de +40 a su control.","_seccion":"MUSICAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Rostro', '{"conjuro":"Rostro","via":"Nobleza","nivel":4,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":50,"zeonAvanzado":80,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"Las habilidades descritas","efectoIntermedio":"El personaje incrementa un punto su apariencia (hasta un máximo de 9)","efectoAvanzado":"El personaje incrementa dos puntos su apariencia (hasta un máximo de 10)","efectoArcano":"El personaje incrementa tres puntos su apariencia (hasta un máximo de 10)","efecto":"Elimina las imperfecciones externas que puedan afectar al rostro del blanco del conjuro, cubriendo dichos defectos con una suave capa de maquillaje sobrenatural.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Perfume', '{"conjuro":"Perfume","via":"Nobleza","nivel":14,"diario":"Si","tipo":"Efecto/ Automático","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"Las habilidades descritas/ 20 metros radio","efectoIntermedio":"Incrementa un grado la dif alcanzada por Estilo/ 30 metros radio","efectoAvanzado":"Incrementa dos grados el nivel de dificultad alcanzado/ 40m radio","efectoArcano":"Quien huela el perfume durante +5 asaltos, RM 100 o fascinación/ 50m de radio","efecto":"Este conjuro modifica el olor corporal del blanco designado por el hechicero, transformandolo en un fragante aroma, suave y agradable al olfato, que evoca placenteras sensaciones a quienes lo aspiran en un área determinada por le grado del conjuro.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Musa', '{"conjuro":"Musa","via":"Nobleza","nivel":24,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"120 de habilidad","efectoIntermedio":"180 de habilidad","efectoAvanzado":"240 de habilidad","efectoArcano":"280 de habilidad","efecto":"Proporciona al lanzador la inspiración necesaria para efectuar una magistral interpretación de alguna forma de arte tradicional. Da al hechicero la habilidad secundaria base que pone a prueba (Música, Baile o Arte) o bien la mitad de dicho valor como bono a su propia habilidad.  Aunque no tenga mantenimiento el hechizo perdura el tiempo suficiente para realizar la interpretación siempre que no sea superior a un dia.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Guardarropa', '{"conjuro":"Guardarropa","via":"Nobleza","nivel":34,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"Las habilidades descritas","efectoIntermedio":"Mientras lleve las ropas, bono de +50 a su habilidad de estilo.","efectoAvanzado":"Las ropas varían de forma y color dependiendo de la situación y el momento.","efectoArcano":"Las ropas otorgan una TA 4 contra toda clase de ataque, y se reparan solas","efecto":"Transforma temporalmente las ropas del blanco del conjuro en otras de calidad exquisita con la capacidad de permanecer limpias y planchadas en todo momento. Las manchas y salpicaduras resbalarán por la tela y los desgarros se zurcirán mágicamente en cuestión de segundos.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Conversación agradable', '{"conjuro":"Conversación agradable","via":"Nobleza","nivel":44,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"120 de RM o RP","efectoIntermedio":"160 de RM o RP","efectoAvanzado":"200 de RM o RP","efectoArcano":"240 de RM o RP","efecto":"Permite percibir los pensamientos superficiales e intereses más comunes de un individuo para poder mantener una conversación que sea agradable o entretenida para él. El afectado puede realizar una tirada de RM o RP. En caso de fallar el mago obtiene un +200 a sus tiradas de estilo y persuasión destinadas a embaucar al objetivo. Para que el conjuro funcione se debe estar conversando mas de medio minuto y acaba cuando finalize la conversación.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Grandeza', '{"conjuro":"Grandeza","via":"Nobleza","nivel":54,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":150,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"120 de RM o RP","efectoIntermedio":"160 de RM o RP","efectoAvanzado":"200 de RM o RP","efectoArcano":"240 de RM o RP","efecto":"Cualquiera que se encuentre en un área de 5 metros alrededor del mago deberá realizar una tirada de RM o RP, o se sentirán a impelidos a complacerle. Este conjuro no tiene efecto con personas que conozcan al hechicero o sean abiertamente hostiles. Los hechizados pueden repetir la tirada de resistencia cuando el lanzado haga una acción tan contraria a la razón que estos puedan replantearse su sumisión hacia él.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Conquistar corazones', '{"conjuro":"Conquistar corazones","via":"Nobleza","nivel":64,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"120 de RM o RP","efectoIntermedio":"160 de RM o RP","efectoAvanzado":"200 de RM o RP","efectoArcano":"240 de RM o RP","efecto":"Cualquiera sexualmente compatible con el personaje que se beneficia de sus efectos deberá superar un control de RM o RP, o quedará automáticamente embelesado. Además, el individuo en el que recae obtiene un +200 a sus tiradas de persuasión (Seducción) contra cualquiera que no haya podido superar el control. La condición para ser afectado por el sortilégio es dedicar verdadera atención a la apariencia del individuo que se beneficia del conjuro.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Presencia absoluta', '{"conjuro":"Presencia absoluta","via":"Nobleza","nivel":74,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":120,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"120 de RM o RP/ 20 metros radio","efectoIntermedio":"160 de RM o RP/ 50 metros radio","efectoAvanzado":"200 de RM o RP/ 100 metros radio","efectoArcano":"240 de RM o RP/ 150 metros radio","efecto":"Quienquiera que intente realizar una actividad que no esté centrada en el hechicero recibe automaticamente un penalizador de -40 a toda acción (-120 en caso de estar relacionadas con habilidades perceptivas). La condición para ser afectado por este conjuro es simplemente estar en el interior del área designada y no superar un control de RM o RP.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Perfección', '{"conjuro":"Perfección","via":"Nobleza","nivel":84,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":120,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":15,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"Apariencia 10 y bono de +100 a Estilo, Persuasión, Intimidar y Liderazgo.","efectoIntermedio":"+3 al nivel de regeneración base.","efectoAvanzado":"El bono aumenta a +200","efectoArcano":"+1 a todos los atributos.","efecto":"El blanco del conjuro altera su complexión física adquiriendo automáticamente una apariencia perfecta.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'El rey del mundo', '{"conjuro":"El rey del mundo","via":"Nobleza","nivel":94,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":120,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"500 metros de radio/ 120 RM","efectoIntermedio":"1 Km de radio/ 160 de RM","efectoAvanzado":"2 km de radio/ 200 RM","efectoArcano":"5 Km de radio/ 240 RM","efecto":"El hechicero emplea la magia para divinizar sus capacidades sociales, convirtiendose en el centro de atencción y veneración de todos cuantos le rodean. Cualquiera que se encuentre en un radio de él debe superar automaticamente un control de RM o RP o considerará al hechicero como su maestro e ideal. El brujo no tendrá el control de los afectados pero intentaran satisfacerle y buscar su aprobación.","_seccion":"NOBLEZA"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo salvador', '{"conjuro":"Escudo salvador","via":"Paz","nivel":4,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":14,"zeonBase":50,"zeonIntermedio":100,"zeonAvanzado":160,"zeonArcano":240,"mantBase":5,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"300 puntos de Resistencia / Protege hasta 2 personas sin penalizador","efectoIntermedio":"900 puntos de Resistencia / Protege hasta 5 personas sin penalizador","efectoAvanzado":"1.500 puntos de Resistencia / Hasta 8 personas sin penalizador","efectoArcano":"3.000 puntos de Resistencia / Hasta 12 personas sin penalizador","efecto":"Crea una barrera protectora que protege contra cualquier tipo de ataque. En el caso de que se utilice para cubrir a varios individuos contra un ataque en área, el conjuro permite proteger a tantos blancos como indique el Grado del conjuro sin sufrir por ello daño adicional o aplicar un penalizador a la habilidad defensiva del lanzador.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Equilibrio interior', '{"conjuro":"Equilibrio interior","via":"Paz","nivel":14,"diario":"Si","tipo":"Efecto","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"El PJ se vuelve inmune a los estados psicológicos negativos","efectoIntermedio":"Obtiene un +40 a sus Resistencias contra efectos desequilibrantes","efectoAvanzado":"Como Grado Intermedio pero el Bono es de +80","efectoArcano":"Bloquea todo efecto que altere negativamente la conducta","efecto":"El hechicero o el objetivo designado por éste alcanza un nivel de paz interior que le hace inmune cualquier efecto que pueda desequilibrar su estado de ánimo.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Defensor', '{"conjuro":"Defensor","via":"Paz","nivel":24,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":200,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Da +20 a la Defensa / Pres. máx. 60","efectoIntermedio":"Da +20 a la Defensa / Pres. máx. 100","efectoAvanzado":"Da +30 a la Defensa / Pres. máx. 150","efectoArcano":"Da +40 a la Defensa / Pres. máx. 250","efecto":"Otorga un bono a la habilidad defensiva de un individuo al utilizar la maniobra de defensa total. Afecta a tantas personas como determine el lanzador, siempre y cuando la suma de sus presencias no supere lo que determine el Grado del conjuro.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detectar armonía', '{"conjuro":"Detectar armonía","via":"Paz","nivel":34,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"10m radio / 100 RM","efectoIntermedio":"25m rad / 120 RM","efectoAvanzado":"50m rad / 140 RM","efectoArcano":"100m rad / 160 RM","efecto":"El hechicero percibe las personas en el interior del radio del conjuro que tiene sentimientos pacíficos o violentos si estos no superan la RM determinada por el Grado del sortilegio.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Remanso de paz', '{"conjuro":"Remanso de paz","via":"Paz","nivel":44,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":160,"zeonIntermedio":220,"zeonAvanzado":280,"zeonArcano":300,"mantBase":20,"mantIntermedio":25,"mantAvanzado":30,"mantArcano":30,"efectoBase":"10m radio / 100 RM","efectoIntermedio":"25m rad / 120 RM","efectoAvanzado":"50m rad / 140 RM","efectoArcano":"100m rad / 160 RM","efecto":"Este hechizo genera una zona en cuyo interior se pierde todo instinto agresivo. Cualquiera que penetre dentro debe superar automáticamente un control de RM o perderá toda actitud violenta. Alguien que supere el control no vuelve a verse afectado por los efectos de Remanso de Paz mientras no salga de su zona de influencia. El área permanece estática en el lugar en que fue lanzada.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Signo de paz', '{"conjuro":"Signo de paz","via":"Paz","nivel":54,"diario":"No","tipo":"Automático","accion":"Pasiva","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":100,"zeonIntermedio":180,"zeonAvanzado":260,"zeonArcano":340,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120","efectoIntermedio":"RM 160","efectoAvanzado":"RM 200","efectoArcano":"RM 240","efecto":"El hechicero cancela una acción de ataque dirigida contra él. La condición para ser afectado es realizar un ataque que tenga como blanco al lanzador (incluso si hay otros individuos afectados por el ataque). Para evitar sus efectos, es necesario superar una RM contra la dificultad indicada por el Grado del conjuro. Un mismo ataque sólo puede ser afectado una vez por un conjuro de Signo de Paz.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Defensa absoluta', '{"conjuro":"Defensa absoluta","via":"Paz","nivel":64,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":110,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Da +20 a la Proyección Mágica Defensiva","efectoIntermedio":"Da +30 a la Proyección Mágica Defensiva","efectoAvanzado":"Da +40 a la Proyección Mágica Defensiva","efectoArcano":"Da +50 a la Proyección Mágica Defensiva","efecto":"Mientras el hechicero no realice ninguna acción ofensiva durante un asalto puede aplicar un bono a su Proyección Mágica Defensiva.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alas de salvación', '{"conjuro":"Alas de salvación","via":"Paz","nivel":74,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":150,"zeonIntermedio":250,"zeonAvanzado":350,"zeonArcano":450,"mantBase":15,"mantIntermedio":25,"mantAvanzado":35,"mantArcano":45,"efectoBase":"El Escudo tiene 500 puntos de Resistencia / 5m radio","efectoIntermedio":"El Escudo tiene 1.200 puntos de Resistencia / 15m radio","efectoAvanzado":"El Escudo tiene 2.200 puntos de Resistencia / 25m radio","efectoArcano":"El Escudo tiene 5.000 puntos de Resistencia / 50m radio","efecto":"Crea una barrera protectora que protege contra cualquier tipo de ataque. El conjuro permite cubrir todos los individuos que estén dentro del radio de acción del sortilegio sin sufrir por ello daño adicional o aplicar un penalizador a la habilidad defensiva del lanzador.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Paz absoluta', '{"conjuro":"Paz absoluta","via":"Paz","nivel":84,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"El objetivo de este conjuro queda imbuido por una energía de la paz más pura, que le impedirá volver a entablar actos violentos de ningún tipo. Alguien que falle la RM determinada por el Grado del sortilegio deja de poder realizar acciones ofensivas contra nadie de un modo consciente. Dado que su propia esencia violenta desaparece por completo, este conjuro no tiene mantenimiento.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Pax in terrax', '{"conjuro":"Pax in terrax","via":"Paz","nivel":94,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":350,"zeonIntermedio":600,"zeonAvanzado":1000,"zeonArcano":1600,"mantBase":35,"mantIntermedio":60,"mantAvanzado":100,"mantArcano":160,"efectoBase":"1 Km radio / RM 120","efectoIntermedio":"5 Km radio / RM 140","efectoAvanzado":"15 Km radio / RM 160","efectoArcano":"50 Km radio / RM 180","efecto":"Todo individuo que entre en la zona debe superar automáticamente una RM o será incapaz de realizar acciones violentas. Una persona que falle la resistencia no tiene derecho a repetirla mientras siga dentro del área de acción del conjuro, mientras que aquellos que la superen deberán volver a realizar el control cada vez que traten de realizar una acción violenta en el interior de la zona.","_seccion":"PAZ"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sentir pecado', '{"conjuro":"Sentir pecado","via":"Pecado","nivel":4,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"Mediante este conjuro el hechicero podrá ver los pecados que ha cometido alguien. No obtendrá información específica de ellos (sabrá el tipo de pecado aunque no sepa exactamente que hizo), pero sentirá más o menos su gravedad y en qué momento aproximado fueron cometidos. El lanzador puede sentir un pecado por cada 10 puntos por los que el blanco del conjuro falle un control de RM.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Imbuir pecado', '{"conjuro":"Imbuir pecado","via":"Pecado","nivel":14,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":50,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":140,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"El objetivo del conjuro es incitado a cometer su pecado capital más afín. Alguien con enorme gula sentirá la necesidad de comer insaciablemente, mientras que un individuo lujurioso se lanzará a los brazos de cualquier persona cercana que considere atractiva. Aquel que falle la RM del conjuro se verá afectado por él y sólo tendrá derecho a repetir el control cada vez que encuentre algo que le haga volver a tener la necesidad de pecar.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Gula', '{"conjuro":"Gula","via":"Pecado","nivel":24,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":180,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"Absorbe un 10% / 10m radio","efectoIntermedio":"Absorbe un 20% / 20m radio","efectoAvanzado":"Absorbe un 30% / 40m radio","efectoArcano":"Absorbe un 50% / 60m radio","efecto":"El hechicero recupera automáticamente una parte de todos los Puntos de Zeon (redondeado hacia arriba en grupos de 5) y de Ki que se gasten en un radio a su alrededor. Gula no tiene efectos sobre conjuros innatos o poderes mágicos que no consuman propiamente Zeon, ni tampoco aquellos conjuros o Técnicas de Ki que utilice el lanzador.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Lujuria', '{"conjuro":"Lujuria","via":"Pecado","nivel":34,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 140","efectoIntermedio":"RM 160","efectoAvanzado":"RM 180","efectoArcano":"RM 200","efecto":"El blanco del conjuro se convertirá en un imán para cualquiera que se sienta atraído por el sexo del blanco. Cualquiera que lo vea y no supere la RM se sentirá inmensamente atraído por el afectado, mientras que quien falle el control por más de 40 puntos sentirá una atracción obsesiva y enfermiza.. Cualquier individuo afectado puede repetir el control cada hora.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Avaricia', '{"conjuro":"Avaricia","via":"Pecado","nivel":44,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":50,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":260,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120 / Pres. 50","efectoIntermedio":"RM 140 / Pres. 80","efectoAvanzado":"RM 160 / Pres. 100","efectoArcano":"RM 180 / Pres. 120","efecto":"Arrebata automáticamente algo que esté en posesión del blanco del conjuro, haciéndolo aparecer ante el hechicero. No es ni siquiera necesario que dicho objeto pueda \"moverse\" hacia el lanzador. Alguien que sea consciente de que puede ser blanco de este conjuro puede tratar de resistirse a sus efectos superando una RM.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Pereza', '{"conjuro":"Pereza","via":"Pecado","nivel":54,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 100","efectoIntermedio":"RM 120","efectoAvanzado":"RM 140","efectoArcano":"RM 160","efecto":"El objetivo se ve sumido en un profundo estado de pereza. En consecuencia, mientras dure el efecto del sortilegio sólo podrá realizar acciones pasivas. Para resistir los efectos de este conjuro es necesario superar un control de RM contra la dificultad determinada por el Grado del conjuro.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Soberbia', '{"conjuro":"Soberbia","via":"Pecado","nivel":64,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 120 / +10 a Toda Acción / +50 Estilo","efectoIntermedio":"RM 140 / +20 a Toda Acción / +100 Estilo","efectoAvanzado":"RM 160 / +20 a Toda Acción / +150 Estilo / +100 Resistir el Dolor","efectoArcano":"RM 180 / +30 a Toda Acción / +200 Estilo / +150 Resistir el Dolor","efecto":"Cualquier persona incrementa automáticamente sus habilidades, obteniendo bonos especiales determinados por el Grado del conjuro. No obstante, será incapaz de usar Técnicas de Ki o Magnus, Poderes Psíquicos de Nivel 2 o 3, o Conjuros de Nivel superior a 40. Para resistirse a sus efectos, es necesario superar una RM contra la dificultad determinada por el Grado del conjuro.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ira', '{"conjuro":"Ira","via":"Pecado","nivel":74,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":220,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"El objetivo del hechizo entra en un estado de ira berserker que no puede controlar, atacando de inmediato a todo aquel que sea objeto de su furia. El hechicero podrá, en el momento del lanzamiento, enfocar sobre quién irá dirigida toda esa rabia. Para resistir los efectos de este conjuro es necesario superar un control de RM contra la dificultad determinada por el Grado del conjuro.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Envidia', '{"conjuro":"Envidia","via":"Pecado","nivel":84,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":9,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"Si el objetivo falla la RM determinada por el Grado del conjuro, sufrirá todo lo que el hechicero sufra, tanto positivo como negativo. Por ejemplo, si dañan al lanzador el personaje afectado también sufrirá el mismo daño, o si el brujo recibe cualquier efecto místico, de la naturaleza que sea, también será traspasado.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'La semilla del mal', '{"conjuro":"La semilla del mal","via":"Pecado","nivel":94,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":260,"zeonArcano":320,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 120","efectoIntermedio":"RM 140","efectoAvanzado":"RM 160","efectoArcano":"RM 180","efecto":"Un individuo afectado por este sortilegio se torna intrínsecamente malvado, perdiendo cualquier concepto de moralidad. El personaje adquirirá una maldad extrema automáticamente. Una persona realmente pura, sin concepto alguno de la maldad, es inmune a este conjuro. Para resistirse a sus efectos es necesario superar un control de RM contra la dificultad determinada por el Grado del conjuro.","_seccion":"PECADO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Categorizar', '{"conjuro":"Categorizar","via":"Conocimiento","nivel":4,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":7,"intRAvanzado":9,"intRArcano":11,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Sabrá a qué campo de estudio pertenece (mecánica, herrería…) sin más datos.","efectoIntermedio":"Obtiene información de los materiales de los que está compuesto.","efectoAvanzado":"Obtiene una vaga idea de cómo funciona, aunque no para que sirve.","efectoArcano":"El lanzador obtiene una vaga idea de cómo se creó, aunque no podrá recrearlo.","efecto":"El lanzador del conjuro obtiene conocimiento sobre la naturaleza de una creación. No otorga al lanzador conocimientos de cómo realizar tal cosa pero al menos le guía en que materia ha de buscar o que elementos ha de utilizar. Objetos de naturaleza elevada o especialmente complejos son inmunes a Categorizar","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Conocimiento', '{"conjuro":"Conocimiento","via":"Conocimiento","nivel":14,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"40 en una habilidad","efectoIntermedio":"60 en una habilidad","efectoAvanzado":"80 en una habilidad","efectoArcano":"100 en una hablilidad","efecto":"Otorga al lanzador un conocimiento innato en una materia. El hechicero obtiene un valor en la habilidad de conocimiento que desee, sustituyendo la que tuviese de por si. Un personaje puede lanzar varias veces este hechizo pero cada vez ha de escoger una materia diferente.","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Saber debilidad', '{"conjuro":"Saber debilidad","via":"Conocimiento","nivel":24,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":180,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"120 RM","efectoIntermedio":"140 RM","efectoAvanzado":"160 RM","efectoArcano":"180 RM","efecto":"Permite al hechicero ver las imperfecciones y debilidades de algo o alguien. Si se lanza sobre un ser sabra sus debilidades y si se lanza sobre un objeto sabra si es débil hacia algo o cual es su punto de fisura. La única condición para ser afectado por el conjuro es estar en presencia del lanzador aunque el objetivo puede resistirse a sus efectos superarando una RM:","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Saber la verdad', '{"conjuro":"Saber la verdad","via":"Conocimiento","nivel":34,"diario":"Si","tipo":"Detección","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":20,"efectoBase":"80 RM","efectoIntermedio":"100 RM","efectoAvanzado":"120 RM","efectoArcano":"140 RM","efecto":"El hechicero sabrá cuando alguien esta mintiendo ante él. El hechizado puede no ser afectado por el conjuro si supera una tirada de RM, si falla el mago sabrá que el objetivo esta mintiendo en algo, aunque no especificamente en que.","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Conocimiento mágico', '{"conjuro":"Conocimiento mágico","via":"Conocimiento","nivel":44,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Un conjuro de hasta nivel 20","efectoIntermedio":"Un conjuro de hasta nivel 30","efectoAvanzado":"Un conjuro de hasta nivel 40","efectoArcano":"Un conjuro de hasta nivel 50","efecto":"El lanzador obtiene el conocimiento de lanzar un conjuro de una vía que no conoce siempre y cuando el hechizo sea del nivel estipulado por el conjuro. Una vez ejecutado Conocimiento Mágico, el brujo tiene un máximo de 5 asaltos para ejecutar el sortilegio elegido. Este conjuro no funciona con hechizos de la via contraria a la via en la que esté integrada esta subvía.","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Conocimiento de combate', '{"conjuro":"Conocimiento de combate","via":"Conocimiento","nivel":54,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":5,"mantIntermedio":10,"mantAvanzado":20,"mantArcano":20,"efectoBase":"140 RM/ + 20 a toda acción","efectoIntermedio":"160 RM/ +30 a toda acción","efectoAvanzado":"180 RM/ +30 a toda acción","efectoArcano":"200 RM/ + 40 a toda acción","efecto":"El hechicero percibe y entiende las habilidades de una adversario, así como su metodología de combate y como anticiparse a sus movimientos. Por tanto, si el objetivo no supera la RM del conjuro, el lanzador obtiene un bono a todas las habilidades enfrentadas a dicho enemigo. La condición para verse afectado por este sortilegio es simplemente estar en presencia del hechicero.","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aprendizaje', '{"conjuro":"Aprendizaje","via":"Conocimiento","nivel":64,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":10,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"Disminuye en uno la dificultad del grado de aprendizaje.","efectoIntermedio":"Disminuye en dos la dificultad del grado de aprendizaje.","efectoAvanzado":"Disminuye en tres la dificultad del grado de aprendizaje.","efectoArcano":"Disminuye en cuatro la dificultad del grado de aprendizaje.","efecto":"El blanco del hechizo mejora su capacidad de aprender a niveles imposibles, disminuyendo el tiempo de estudio o practica para dominar el conocimiento que desea alcanzar.","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Consejero', '{"conjuro":"Consejero","via":"Conocimiento","nivel":74,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":140,"zeonArcano":200,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"Un consejo aproximado sobre cual es la mejor decision que ha de tomar.","efectoIntermedio":"Mostrará el espectro de de posibilidades y sus posibles consecuencias.","efectoAvanzado":"El lanzador obtiene un consejo con índice de acierto elevado.","efectoArcano":"Obtiene un consejo detallado con todas las posibilidades y consecuencias.","efecto":"Como su nombre indica, este hechizo aconseja sabiamente al lanzador respecto a una cuestión o duda. El conjuro no adivinará ni tendrá conocimientos mayores a los que posea el lanzador, pero usando sus conocimientos base aconsejará lo mejor posible al lanzador.","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Otorgar conocimiento', '{"conjuro":"Otorgar conocimiento","via":"Conocimiento","nivel":84,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":14,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 120/ Habilidad intelectual hasta 50 o Nivel de magia 20.","efectoIntermedio":"RM 140/ Habilidad intelectual hasta 100 o Nivel de magia 40.","efectoAvanzado":"RM 160/ Habilidad intelectual hasta 150 o Nivel de magia 60.","efectoArcano":"RM 180/ Habilidad intelectual hasta 200 o Nivel de magia 80.","efecto":"Permite transpasar el conocimiento de un individuo a otro. Este hechizo no otorga el Don, por lo tanto si alguien trasmite sus conocimientos de vías de magia a otro sin el Don no podrá usar los conjuros. Resistirse a los efectos de este conjuro requiere superar una RM determinada por el grado del conjuro. Alguien afectado sólo puede repetir el control una vez al día","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vida', '{"conjuro":"Vida","via":"Conocimiento","nivel":94,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":400,"zeonIntermedio":600,"zeonAvanzado":800,"zeonArcano":1000,"mantBase":40,"mantIntermedio":60,"mantAvanzado":80,"mantArcano":100,"efectoBase":"+1 Niveles","efectoIntermedio":"+2 Niveles","efectoAvanzado":"+3 Niveles","efectoArcano":"+4 Niveles","efecto":"Este conjuro otorga temporalmente experiencias vitales al personaje, permitiéndole incrementar unos instantes sus habilidades y conocimientos. A efectos de juego, otorga niveles adicionales al lanzador, dándole momentáneamente la capacidad de usar los PD obtenidos para mejorar con absoluta normalidad. Los efectos de este conjuro no se supeerponen, y el hechicero sólo puede beneficiarse de un conjuro de vida a la vez.","_seccion":"CONOCIMIENTO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Relentizar pulso', '{"conjuro":"Relentizar pulso","via":"Sangre","nivel":4,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":13,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":100,"zeonArcano":150,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 80","efectoIntermedio":"RM 100","efectoAvanzado":"RM 120","efectoArcano":"RM 160","efecto":"El afectado se siente relajado, siendo eliminada cualquier emoción extrema en que esté sumido, sea de origen natural o no. La sensación de tranquilidad será tan grande, que durante el siguiente minuto el blanco del conjuro sufre un -10 a Toda Acción de carácter físico. Para tratar de resistirse a sus efectos es necesario superar una RM contra la dificultad determinada por el Grado del conjuro.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Coagular', '{"conjuro":"Coagular","via":"Sangre","nivel":14,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":13,"zeonBase":40,"zeonIntermedio":80,"zeonAvanzado":120,"zeonArcano":160,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Elimina automáticamente cualquier desangramiento.","efectoIntermedio":"Recupera un 20% de los PV perdidos por cortes o hemorragias.","efectoAvanzado":"Recupera un 40% de los Puntos de Vida perdidos por cortes o hemorragias.","efectoArcano":"Recupera un 60% de los Puntos de Vida perdidos por cortes o hemorragias.","efecto":"Restaña las heridas mágicamente, impidiendo la pérdida de sangre y cerrando las heridas. Sólo es posible afectar a alguien una vez al día con este conjuro.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sangre fría', '{"conjuro":"Sangre fría","via":"Sangre","nivel":24,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"Pres. máxima 60","efectoIntermedio":"Pres. máxima 100","efectoAvanzado":"Pres. máxima 180","efectoArcano":"Pres. máxima 300","efecto":"Cambia la temperatura corporal de los objetivos del conjuro, permitiendo regularla de forma acorde a las condiciones externas. Así, no se verán afectados por la meteorología adversa, pudiendo sobrevivir en yermos gélidos o desiertos ardientes. Puede afectar a tantos blancos como se desee, siempre y cuando la suma de sus presencias no supere lo que determine el Grado del conjuro.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Creación de sangre', '{"conjuro":"Creación de sangre","via":"Sangre","nivel":34,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":160,"zeonArcano":200,"mantBase":10,"mantIntermedio":40,"mantAvanzado":50,"mantArcano":60,"efectoBase":"Pérdida de -10 PV / Calidad +0 / Objetos de hasta 2 Kg","efectoIntermedio":"Pérdida de -20 PV / Calidad +5 / Objetos de hasta 5 Kg","efectoAvanzado":"Pérdida de -40 PV / Calidad +10 / Objetos de hasta 15 Kg","efectoArcano":"Pérdida de -60 PV / Calidad +15 / Objetos de hasta 25 Kg","efecto":"Crea un objeto u arma a partir de la propia sangre del hechicero, cristalizándola hasta convertirla en un material de una dureza extrema. Lamentablemente, esto hace que el brujo deba de sacrificar necesariamente parte de su propia sangre, perdiendo puntos de vida en el proceso.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Transfusión', '{"conjuro":"Transfusión","via":"Sangre","nivel":44,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":60,"zeonAvanzado":80,"zeonArcano":100,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"x2 a los PV Sacrificados","efectoIntermedio":"x5 a los PV Sacrificados","efectoAvanzado":"x10 a los PV Sacrificados","efectoArcano":"x20 a los PV Sacrificados","efecto":"Permite que el brujo transfiera parte de sus Puntos de Vida a otra persona. La cantidad de PV que sacrifique el lanzador se multiplica por la cantidad que determine el Grado del conjuro. Este conjuro no permite restaurar miembros cercenados o pérdidas permanentes, pero si elimina los penalizadores causados por los críticos en una cantidad equivalente a los PV sacrificados.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Desangrar', '{"conjuro":"Desangrar","via":"Sangre","nivel":54,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"Incrementa el Daño Recibido un 50% / RM 120","efectoIntermedio":"Dobla el Daño Recibido / RM 140","efectoAvanzado":"Triplica el Daño Recibido / RM 160","efectoArcano":"Cuadruplica el Daño Recibido / RM 180","efecto":"Mientras se mantenga activo, el afectado incrementa el daño que sufra en una cantidad determinada por el Grado del conjuro. Para que Desangrar tenga efecto el daño resultante debe provenir de contusiones, hemorragias y cortes, mientras que las heridas provocadas por calor, frío o energía no se benefician de esta regla. Puede repetirse la RM cada vez que se reciba un impacto cuyo daño sea incrementado por este sortilegio.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vampirismo', '{"conjuro":"Vampirismo","via":"Sangre","nivel":64,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":250,"zeonArcano":300,"mantBase":10,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":15,"efectoBase":"Drena el 10% de las heridas causadas","efectoIntermedio":"Drena el 20% de las heridas causadas","efectoAvanzado":"Drena el 30% de las heridas causadas","efectoArcano":"Drena el 40% de las heridas causadas","efecto":"Este conjuro provoca que un arma beba parte de la sangre de aquellos a los que hiera, canalizando sus energías vitales y otorgándoselas al portador para que recupere sus PV perdidos. En el caso de que se ataque a un ser con acumulación de daño, la cantidad drenada debe dividirse por diez.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Lágrimas de sangre', '{"conjuro":"Lágrimas de sangre","via":"Sangre","nivel":74,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":280,"zeonIntermedio":320,"zeonAvanzado":360,"zeonArcano":400,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RF 140 / Daño 50","efectoIntermedio":"RM o RF 180 / Daño 100","efectoAvanzado":"RM o RF 220 / Daño 150","efectoArcano":"RM o RF 260 / Daño 200","efecto":"Este terrorífico conjuro provoca que la sangre del corazón de un objetivo se expanda y lo reviente desde dentro a causa de la presión. Si el personaje falla el control por más de 40 puntos muere de manera automática, mientras que si el nivel de fracaso no es superior a 40, recibe el daño determinado en la descripción del Grado del conjuro.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Corriente sanguínea', '{"conjuro":"Corriente sanguínea","via":"Sangre","nivel":84,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":10,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":17,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":300,"zeonArcano":340,"mantBase":40,"mantIntermedio":50,"mantAvanzado":60,"mantArcano":70,"efectoBase":"Da +10 a Toda Acción / -5 PV por Turno","efectoIntermedio":"Da +20 a Toda Acción / -15 PV por Turno","efectoAvanzado":"Da +40 a Toda Acción / -30 PV por Turno","efectoArcano":"Da +60 a Toda Acción / -50 PV por Turno","efecto":"Incrementa la velocidad del torrente sanguíneo del hechicero y aquellos aliados que designe, incrementado notablemente sus capacidades. Sin embargo, la presión a la que se somete el corazón de los beneficiarios del hechizo les provoca daños internos que pueden llegar a matarlos si se mantiene demasiado tiempo.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Un mundo de sangre', '{"conjuro":"Un mundo de sangre","via":"Sangre","nivel":94,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":280,"zeonIntermedio":320,"zeonAvanzado":360,"zeonArcano":400,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RF 120 / Daño 60 / 500 Puntos de Resistencia","efectoIntermedio":"RM o RF 140 / Daño 90 / 1.200 Puntos de Resistencia","efectoAvanzado":"RM o RF 160 / Daño 120 / 2.400 Puntos de Resistencia","efectoArcano":"RM o RF 180 / Daño 150 / 3.600 Puntos de Resistencia","efecto":"El hechicero obtiene un control absoluto sobre toda la sangre que se encuentre dentro del radio de acción del sortilegio. Cualquier individuo que se vea afectado por el conjuro debe superar un control de RM o RF para no verse controlado por el brujo como una marioneta, o sufrir un daño equivalente al doble del nivel de fracaso. Puede usar la sangre como medio de ataque o defensa (creando cuchillas, espinas o escudos), con su Proyección Mágica.","_seccion":"SANGRE"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sentir los sueños', '{"conjuro":"Sentir los sueños","via":"Sueños","nivel":4,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":40,"zeonIntermedio":60,"zeonAvanzado":80,"zeonArcano":100,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"50 metros / RM 120","efectoIntermedio":"150 metros / RM 160","efectoAvanzado":"200 metros / RM 200","efectoArcano":"500 metros / RM 240","efecto":"Mediante este conjuro el hechicero es capaz de localizar las energías oníricas de todos los seres que estén soñando cerca de él. Además, mediante la energía que desprenden podrá saber si están teniendo Sueños plácidos o por el contrario, terribles pesadillas. Para resistirse a la detección, los durmientes deben superar una RM.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sueño imperturbable', '{"conjuro":"Sueño imperturbable","via":"Sueños","nivel":14,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":60,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"+40 RM o RP.","efectoIntermedio":"+60 RM o RP.","efectoAvanzado":"+80 RM o RP.","efectoArcano":"+100 RM o RP.","efecto":"Este hechizo protege a un personaje de ser asaltado por conjuros o efectos de cualquier tipo relacionado con los Sueños, otorgándole un bono a la RM y RP contra tales menesteres. De igual forma, este conjuro evita que el personaje sea transportado involuntariamente hasta la vigilia, otorgándole el mismo bono a sus resistencias en caso de que alguien trate de forzarle a ir en contra de su voluntad.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Espiar los sueños', '{"conjuro":"Espiar los sueños","via":"Sueños","nivel":24,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":8,"intRAvanzado":10,"intRArcano":12,"zeonBase":60,"zeonIntermedio":80,"zeonAvanzado":100,"zeonArcano":120,"mantBase":10,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"RM 140","efectoIntermedio":"RM 160","efectoAvanzado":"RM 180","efectoArcano":"RM 200 / el lanzador puede  manifestar una imagen  de los Sueños","efecto":"Este hechizo permite observar que está ocurriendo en los Sueños de un durmiente, tanto si son tranquilos como pesadillas. No es posible intervenir en ellos de ninguna manera, pero sí verlos detalladamente. Una persona puede resistirse superando un control de RM, pero si lo falla, solo tiene derecho a un nuevo control cada día, siempre y cuando sea consciente o sospeche que puede estar siendo afectado por un conjuro de estas características.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Alterar los sueños', '{"conjuro":"Alterar los sueños","via":"Sueños","nivel":34,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":10,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"RM 100 / 50 metros de radio.","efectoIntermedio":"RM 120 / 150 metros de radio.","efectoAvanzado":"RM 140 / 250 metros de radio.","efectoArcano":"RM 160 / 500 metros de radio.","efecto":"Mediante este conjuro el hechicero tiene la capacidad de alterar los Sueños (ya sean tranquilos o pesadillas) que tengan todas las personas que estén dentro del radio de acción. Este conjuro solo funciona si el hechicero está “fuera” del Sueños, y no permite usarlo si está introducido en el propio Sueños o en la vigilia. Este hechizo solo afecta a personas que estén durmiendo en esos momentos y desaparece en el instante en que despiertan.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Caminante noctámbulo', '{"conjuro":"Caminante noctámbulo","via":"Sueños","nivel":44,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":30,"mantIntermedio":30,"mantAvanzado":40,"mantArcano":40,"efectoBase":"1 km de distancia máxima","efectoIntermedio":"2km de distancia / el afectado puede tornarse visible a voluntad y hablar","efectoAvanzado":"5 km de distancia máxima / El mago puede alterar su aspecto físico a voluntad","efectoArcano":"Cualquier distancia / puede entrar en los Sueños de cualquiera, con RM de 150","efecto":"El objetivo puede traer al mundo su yo onirico, la forma más habitual que toma su conciencia al soñar. Mientras su cuerpo físico duerme puede moverse por el mundo en forma de Sueños. Es invisible (salvo por quien pueda ver espíritus) y no hace ruido. Es intangible y no puede tocar nada material. Distancia máxima igual a grado de conjuro. Si recibe algún daño el conjuro se interrumpe.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sueño eterno', '{"conjuro":"Sueño eterno","via":"Sueños","nivel":54,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":9,"intRAvanzado":11,"intRArcano":13,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":240,"mantBase":10,"mantIntermedio":20,"mantAvanzado":20,"mantArcano":25,"efectoBase":"RM 80","efectoIntermedio":"RM 100","efectoAvanzado":"RM 120","efectoArcano":"RM 140","efecto":"Este terrible conjuro sume a su víctima en un Sueños del que no puede despertar hasta que el hechicero no lo desee, sin importar lo que le pase a su cuerpo. Alguien afectado por este conjuro tiene derecho a una resistencia al día, aunque aplica un -40 a sus resistencias para despertarse si ya ha sido afectado por el conjuro.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Rasgar la membrana', '{"conjuro":"Rasgar la membrana","via":"Sueños","nivel":64,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":240,"zeonAvanzado":280,"zeonArcano":320,"mantBase":40,"mantIntermedio":50,"mantAvanzado":60,"mantArcano":70,"efectoBase":"El portal sólo permite pasar al hechicero, y es sólo de una dirección.","efectoIntermedio":"Cualquier clase de ser puede cruzar, pero sólo en una dirección.","efectoAvanzado":"El portal puede ser usado en ambas direcciones.","efectoArcano":"Puede escogerse quienes pueden cruzar el portal, y como abrirlo.","efecto":"El hechicero crea un vórtice en la realidad permitiéndole crear un portal a la vigilia.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Desterrar a la Vigilia', '{"conjuro":"Desterrar a la Vigilia","via":"Sueños","nivel":74,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":100,"zeonIntermedio":120,"zeonAvanzado":140,"zeonArcano":160,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 100","efectoIntermedio":"RM 120","efectoAvanzado":"RM 140","efectoArcano":"RM 160","efecto":"Este hechizo permite arrancar del mundo terrenal a un individuo o ser y lanzarlo hasta un lugar al azar de la Vigilia. El lanzador puede elegir si sólo envía el subconsciente onírico del afectado (es decir, que su cuerpo permanece durmiendo mientras su mente va a la Vigilia). También puede afectar a criaturas propias de la Vigilia que serán arrastradas por completo. Para resistirse deberá superar una RM.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Entre sueños y realidad', '{"conjuro":"Entre sueños y realidad","via":"Sueños","nivel":84,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":13,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":19,"zeonBase":400,"zeonIntermedio":500,"zeonAvanzado":700,"zeonArcano":900,"mantBase":80,"mantIntermedio":100,"mantAvanzado":140,"mantArcano":180,"efectoBase":"100m de radio","efectoIntermedio":"500m de radio","efectoAvanzado":"1km de radio","efectoArcano":"3km de radio","efecto":"Permite al hechicero  fundir temporalmente en mundo real y la Vigilia. Los seres que entren en dicha zona seguirán siendo “de su lado”, por lo que si salen de la zona afectada lo seguirán haciendo “por su lado” (es decir, un ser de la Vigilia seguirá en su plano de existencia al cruzar el área afectada por el conjuro). No obstante, las criaturas que tienen poderes especiales en la Vigilia los mantendrán en dicha zona.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Hacer los sueños realidad', '{"conjuro":"Hacer los sueños realidad","via":"Sueños","nivel":94,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":300,"zeonIntermedio":600,"zeonAvanzado":900,"zeonArcano":1200,"mantBase":50,"mantIntermedio":60,"mantAvanzado":65,"mantArcano":75,"efectoBase":"Presencia máxima 80/ Nivel 3.","efectoIntermedio":"Presencia máxima 120/ Nivel 6.","efectoAvanzado":"Presencia máxima 160/ Nivel 9.","efectoArcano":"Presencia máxima 200/ Nivel 12.","efecto":"Permite al hechicero traer al mundo real cualquier ser u objeto que se encuentre en los Sueños de algún durmiente. En el caso de que se traiga un ser “vivo”, la criatura es aparentemente real, pero no podrá tener poderes superiores a Gnosis 25 ni un nivel superior a lo que determine el grado del conjuro. Si por el contrario es un objeto, su presencia máxima será determinada por el grado del sortilegio.","_seccion":"SUEÑOS"}'::jsonb),
  ('core-exxet', 'conjuros', 'Conocimiento temporal', '{"conjuro":"Conocimiento temporal","via":"Tiempo","nivel":4,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":5,"intRIntermedio":7,"intRAvanzado":10,"intRArcano":12,"zeonBase":30,"zeonIntermedio":50,"zeonAvanzado":70,"zeonArcano":90,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Permite percibir sobrenaturalmente la hora y la fecha.","efectoIntermedio":"Siente las milésimas de segundo, y toda alternación del fluir del tiempo.","efectoAvanzado":"Ell personaje puede fijar una alarma, que sonará cuando lo desee.","efectoArcano":"Ell lanzador puede calcular el tiempo que va a tardar algo en concluir.","efecto":"El personaje puede percibir sobrenaturalmente el paso del tiempo.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aceleración temporal', '{"conjuro":"Aceleración temporal","via":"Tiempo","nivel":14,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":240,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"+1 Tipo de Movimiento / +20 Turno / +10 Toda Acción","efectoIntermedio":"+2 Tipo de Movimiento / +30 Turno / +15 Toda Acción","efectoAvanzado":"+2 Tipo de Movimiento / +40 Turno / +20 Toda Acción","efectoArcano":"+3 Tipo de Movimiento / +50 Turno / +25 Toda Acción","efecto":"El brujo acelera su esencia ante el fluir del tiempo. Mientras que él percibe el mundo a cámara lenta, el resto sólo ve un borrón en movimiento. A efectos de juego, otorga diferentes bonos al lanzador o al individuo designado por este indicados por el Grado del Conjuro.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Lentitud temporal', '{"conjuro":"Lentitud temporal","via":"Tiempo","nivel":24,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"-2 Tipos Movimiento / -40 Turno / 10m radio / 100RM","efectoIntermedio":"-4 Tipos Movimiento / -60 Turno / -10 Toda Acción / 25m radio / 120RM","efectoAvanzado":"-6 Tipos Movimiento / -80 Turno / -20 Toda Acción / 50m radio / 140RM","efectoArcano":"-8 Tipos Movimiento / -100 Turno / -30 Toda Acción / 100m radio / 160RM","efecto":"Este conjuro afecta un área determinada de terreno dentro de la cual todo aquel individuo designado por el lanzador es arrastrado a un flujo temporal retardado y sufre los penalizadores indicados. El área afectada por Lentitud Temporal permanece estática en el lugar donde es lanzada. Es necesario superar una RM, pero alguien que haya fallado el control no podrá repetirlo hasta que salga de la influencia del conjuro.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Estancar el tiempo', '{"conjuro":"Estancar el tiempo","via":"Tiempo","nivel":34,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":11,"intRAvanzado":13,"intRArcano":15,"zeonBase":150,"zeonIntermedio":200,"zeonAvanzado":280,"zeonArcano":380,"mantBase":15,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"5m","efectoIntermedio":"10m","efectoAvanzado":"25m","efectoArcano":"50m","efecto":"Este hechizo memoriza el estado y condición actual de todo cuanto se encuentra en su radio de acción, pero sólo puede retrasar los efectos de lo sucedido, por lo que todo perjuicio que un individuo o cosa haya sufrido durante el lapso de tiempo estancado aparecerá de inmediato en cuanto el conjuro finalice o salgan de su zona de influencia.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Detener el tiempo', '{"conjuro":"Detener el tiempo","via":"Tiempo","nivel":44,"diario":"Si","tipo":"Automático","accion":"Activa","intRBase":9,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":40,"mantIntermedio":60,"mantAvanzado":80,"mantArcano":100,"efectoBase":"120RM / 10m","efectoIntermedio":"140RM / 25m","efectoAvanzado":"160RM / 50m","efectoArcano":"180RM / 100m","efecto":"Todo aquel individuo o cosa que, a partir del asalto posterior al lanzamiento del conjuro, se encuentre en el interior de la zona de efecto quedará congelado en el tiempo si no supera una RM. Las personas o cosas congeladas son completamente sólidas, por lo que nada puede tocarlas o dañarlas (excepto seres con Gnosis 40 o superior). Puede repetirse el control de RM una vez al día. El área afectada permanece estática y no es posible elegir blancos.","_seccion":"TIEMPO"}'::jsonb)
insert into public.catalogo (paquete_id, coleccion, clave, datos) values
  ('core-exxet', 'conjuros', 'Retroevolucionar', '{"conjuro":"Retroevolucionar","via":"Tiempo","nivel":54,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":10,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"120RM / Retrocede hasta 1 día","efectoIntermedio":"140RM / Retrocede hasta 1 semana","efectoAvanzado":"160RM / Retrocede hasta 1 año","efectoArcano":"180RM / Retrocede hasta 1 década","efecto":"Este sortilegio afecta la esencia de un objetivo, haciendo que su \"existencia\" retroceda en el tiempo. De ese modo, un anciano volvería a ser joven o un hombre adulto podría llegar a convertirse en un simple niño (o incluso un bebe). El tiempo retrocedido se borra de la vida del individuo, pudiendo llegar a alterar incluso su nivel.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Deshacer el tiempo', '{"conjuro":"Deshacer el tiempo","via":"Tiempo","nivel":64,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":11,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":200,"zeonIntermedio":350,"zeonAvanzado":500,"zeonArcano":800,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"15 segundos (5 asaltos) / 50m","efectoIntermedio":"30 segundos (10 asaltos) / 150m","efectoAvanzado":"1 minuto / 250m","efectoArcano":"1 hora / 1 Km","efecto":"Este conjuro permite hacer que las fibras del tiempo retrocedan unos instantes en una zona determinada, deshaciendo cualquier suceso que haya acontecido en dicho periodo. Sólo el lanzador, los seres con Gnosis 15 puntos superior a su Natura o criaturas de naturaleza divina serán conscientes de lo que ha pasado en el periodo de tiempo deshecho. Los seres con Gnosis 40 o superior son inmunes. No hay Tirada de Resistencia posible.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Salto temporal', '{"conjuro":"Salto temporal","via":"Tiempo","nivel":74,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":11,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Hasta 10 minutos / 120RM","efectoIntermedio":"Hasta 1 día / 160RM","efectoAvanzado":"Hasta 1 mes / 200RM","efectoArcano":"Hasta 1 año / 240RM","efecto":"Este conjuro afecta a un individuo o cosa haciendo que dé un salto temporal al futuro. A efectos de juego, el blanco del conjuro desaparece de donde está, apareciendo en el mismo sitio cierto periodo de tiempo después. El lanzador es quien elige cuanto tiempo adelanta el afectado. No obstante, hay un límite a sus efectos; existen ciertos momentos en la historia que marcan acontecimientos tan importantes existencialmente que son imposibles de evitar.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Bucle temporal', '{"conjuro":"Bucle temporal","via":"Tiempo","nivel":84,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":11,"intRIntermedio":14,"intRAvanzado":16,"intRArcano":18,"zeonBase":400,"zeonIntermedio":600,"zeonAvanzado":900,"zeonArcano":1400,"mantBase":40,"mantIntermedio":60,"mantAvanzado":90,"mantArcano":140,"efectoBase":"250m radio / Hasta 1 día","efectoIntermedio":"500m radio / Hasta 1 semana","efectoAvanzado":"1 Km radio / Hasta 1 mes","efectoArcano":"5 Km radio / Hasta 1 año","efecto":"Al llegar el final del periodo determinado por el lanzador el tiempo se reinicia, repitiendo los mismos acontecimientos.Los seres con Gnosis 40 o mayor son conscientes de inmediato del lugar y posicionamiento de todos los bucles temporales existentes en ese instante. Limitación Especial: En contra de las reglas generales, Bucle Temporal se considera un conjuro de Alta Magia.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Solapar el tiempo', '{"conjuro":"Solapar el tiempo","via":"Tiempo","nivel":94,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":12,"intRIntermedio":15,"intRAvanzado":17,"intRArcano":19,"zeonBase":500,"zeonIntermedio":800,"zeonAvanzado":1250,"zeonArcano":2500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"5m radio / Hasta 1 año en el pasado","efectoIntermedio":"25m radio / Hasta 1 década en el pasado","efectoAvanzado":"500m radio / Hasta 1 siglo en el pasado","efectoArcano":"1 Km radio / Hasta mil años en el pasado","efecto":"Este hechizo permite al lanzador crear un punto de unión entre el presente y el pasado. Todo lo que hubiera en el momento designado por el hechicero dentro de la zona que determine el Grado del Conjuro se manifiesta en el presente, como si siempre hubiera estado ahí. No se puede \"traer\" del pasado a alguien o algo que haya sido descreado o cuya alma fuese destruida. En contra de las reglas generales, este conjuro se considera un conjuro de Magia Divina.","_seccion":"TIEMPO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Ojos del otro lado', '{"conjuro":"Ojos del otro lado","via":"Umbral","nivel":4,"diario":"No","tipo":"Detección","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":11,"intRArcano":14,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":5,"mantIntermedio":5,"mantAvanzado":5,"mantArcano":10,"efectoBase":"El personaje puede sentir si una persona está asustada o no / RM o RP 120.","efectoIntermedio":"Percibe cual es el origen del miedo que siente una persona / RM o RP 140","efectoAvanzado":"El mago percibe los miedos de alguien, aunque no esté asustada /RM o RP 160.","efectoArcano":"El personaje percibe representacion visual de los miedos / RM o RP 180.","efecto":"Los ojos del hechicero le permiten ver los miedos intrínsecos de la gente, así como sus trastornos y locuras. Mientras este conjuro está activo, cualquiera capaz de percibir espíritus verá como los ojos del personaje se tornan completamente negros, como si una oscuridad interna los devorase. Para evitar sus efectos, un individuo puede superar un control de RM o RP contra la dificultad determinada por el grado del conjuro.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sombra del miedo', '{"conjuro":"Sombra del miedo","via":"Umbral","nivel":14,"diario":"No","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":40,"zeonIntermedio":70,"zeonAvanzado":100,"zeonArcano":130,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"50 metros de radio.","efectoIntermedio":"250 metros de radio.","efectoAvanzado":"500 metros de radio.","efectoArcano":"1 kilómetro de radio.","efecto":"Este conjuro afecta una zona de terreno, volviéndola lúgubre y tenebrosa a la vista de los demás. Es importante puntualizar que diferentes personas pueden percibir la misma zona de un modo distinto, dependiendo de lo que estos consideren un lugar lúgubre.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Susurros del otro lado', '{"conjuro":"Susurros del otro lado","via":"Umbral","nivel":24,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":60,"zeonIntermedio":100,"zeonAvanzado":160,"zeonArcano":200,"mantBase":5,"mantIntermedio":5,"mantAvanzado":10,"mantArcano":10,"efectoBase":"RM o RP 80 / 10 metros de radio.","efectoIntermedio":"RM o RP 100 / 25 metros de radio.","efectoAvanzado":"RM o RP 120 / 50 metros de radio.","efectoArcano":"RM o RP 140 / 100 metros de radio.","efecto":"Provoca la aparición de voces susurrantes en un área determinada, sonidos que inundan el corazón de sus víctimas de un miedo primordial. Cualquier persona dentro del radio de acción del conjuro que escuche más de cinco asaltos las voces debe superar automáticamente un control de RM o RP contra la dificultad determinada por el grado del conjuro o quedará sometido al estado de miedo.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Senda de la locura', '{"conjuro":"Senda de la locura","via":"Umbral","nivel":34,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":100,"zeonAvanzado":120,"zeonArcano":140,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM o RP 120.","efectoIntermedio":"RM o RP 140.","efectoAvanzado":"RM o RP 160.","efectoArcano":"RM o RP 180.","efecto":"El brujo altera la mente de una persona con ideas y conceptos demenciales, trastornando su percepción del mundo y sumiéndolo temporalmente en la locura. El blanco de este conjuro debe de superar un control de RM o RP contra la dificultad determinada por el blanco del conjuro o se verá sometido a una locura transitoria. El personaje afectado sólo podrá repetir el control de resistencia una vez al día.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Acechar en los sueños', '{"conjuro":"Acechar en los sueños","via":"Umbral","nivel":44,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":100,"zeonIntermedio":140,"zeonAvanzado":180,"zeonArcano":240,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"RM o RP 120.","efectoIntermedio":"RM o RP 160.","efectoAvanzado":"RM o RP 200.","efectoArcano":"RM o RP 240.","efecto":"El objetivo queda sumido en un Sueños eterno en el que constantemente será acosado por monstruosidades y otras criaturas innombrables que le darán caza hasta acabar con él. Este conjuro debe de ser lanzado sobre un individuo que está soñando. El blanco no podrá despertar hasta que no supere una RM o RP, y sólo tendrá derecho a un nuevo control cada vez que su mente considere que ha ganado a las pesadillas que le acechan.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Agudizar', '{"conjuro":"Agudizar","via":"Umbral","nivel":54,"diario":"Si","tipo":"Anímico","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":300,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"50 metros / RM o RP 120.","efectoIntermedio":"100 metros / RM o RP 140.","efectoAvanzado":"250 metros / RM o RP 160.","efectoArcano":"500 metros / RM o RP 180.","efecto":"El personaje agudiza los temores y locuras de aquellos individuos que se encuentre dentro del área de efecto del conjuro. Toda aquella persona que no supere la RM o RP pasará de tener miedo a tener terror de aquellas cosas que le asustaban, y la locura transitoria se convertirá en una profunda demencia. Sólo es posible repetir el control una vez al día o cuando aumenten las Resistencias del personaje.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Terror', '{"conjuro":"Terror","via":"Umbral","nivel":64,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":80,"zeonIntermedio":140,"zeonAvanzado":200,"zeonArcano":240,"mantBase":10,"mantIntermedio":15,"mantAvanzado":20,"mantArcano":25,"efectoBase":"RM o PR 120 / 10 metros de radio.","efectoIntermedio":"RM o PR 140 / 50 metros de radio.","efectoAvanzado":"RM o PR 180 / 100 metros de radio.","efectoArcano":"RM o PR 200 / 250 metros de radio.","efecto":"Provoca temporalmente el estado de Terror a todos los sujetos que se encuentren alrededor del lanzador. El hechicero es quien decide cual es la fuente de terror para los afectados.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Señor de los locos', '{"conjuro":"Señor de los locos","via":"Umbral","nivel":74,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":200,"zeonIntermedio":300,"zeonAvanzado":400,"zeonArcano":500,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 140 / 100 metros de radio.","efectoIntermedio":"RM o RP 160 / 250 metros de radio.","efectoAvanzado":"RM o RP 180 / 1 kilómetro de radio.","efectoArcano":"RM o RP 200 / 5 kilómetros de radio.","efecto":"El brujo puede controlar a cualquier persona demente alterando su demencia y percepción de la realidad. La condición para ser afectado es estar dentro de la zona de influencia del conjuro y estar sumido en una demencia grave. Aquellos que sólo tengan una locura transitoria pueden aplicar un +40 a sus Resistencias contra los efectos de este conjuro. Los afectados sólo tienen derecho a repetir el control una vez al día o cuando aumenten sus Resistencias.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Encarnación del miedo', '{"conjuro":"Encarnación del miedo","via":"Umbral","nivel":84,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":15,"intRArcano":18,"zeonBase":150,"zeonIntermedio":250,"zeonAvanzado":500,"zeonArcano":700,"mantBase":15,"mantIntermedio":25,"mantAvanzado":50,"mantArcano":70,"efectoBase":"Nivel 4 / RM 140.","efectoIntermedio":"Nivel 8 / RM 160.","efectoAvanzado":"Nivel 12 / RM 180.","efectoArcano":"Nivel 15 / RM 200.","efecto":"Se crea un ser entre mundos nacido a partir de los terrores más profundos del objetivo. La criatura es real en todos los aspectos, pero únicamente el individuo o individuos que la temen son capaces de verla o interactuar con ella (del mismo modo, la criatura sólo siente o puede tocar a aquellas personas que la temen). La criatura puede tener cualquier nivel o poder, siempre que no tenga un Gnosis superior a 30 o supere los límites impuestos por el grado del sortilegio.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'El miedo hecho carne', '{"conjuro":"El miedo hecho carne","via":"Umbral","nivel":94,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":17,"zeonBase":250,"zeonIntermedio":350,"zeonAvanzado":450,"zeonArcano":600,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM o RP 120","efectoIntermedio":"RM o RP 140","efectoAvanzado":"RM o RP 200","efectoArcano":"RM o RP 240","efecto":"El personaje se torna una fuente de miedo, provocando temor a todo tipo de criatura, incluso a aquellas que son inmunes a psicología. Todo aquel que esté en su presencia es sometido automáticamente a miedo, sin resistencia posible, y debe superar un control de RM o RP para no verse sometido además a Terror.","_seccion":"UMBRAL"}'::jsonb),
  ('core-exxet', 'conjuros', 'Sombra de vacío', '{"conjuro":"Sombra de vacío","via":"Vacío","nivel":4,"diario":"No","tipo":"Anímico","accion":"Activa","intRBase":5,"intRIntermedio":8,"intRAvanzado":11,"intRArcano":14,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"RM 80 / Área 5 metros","efectoIntermedio":"RM 100 / Área 10 metros.","efectoAvanzado":"RM 120 / Área 15 metros","efectoArcano":"RM 150 / Área 30 metros.","efecto":"Trae a la existencia un fragmento del vacío, una mera sombra de la nada primordial que durante unos instantes absorbe parcialmente la luz, reduce la cantidad de oxígeno en la zona, y arrebata energía vital a cuanto la rodea. Todo aquel que se encuentren en la zona afectada por este conjuro deberá realizar un control de RM o perderá o bien un punto de Cansancio en los seres vivos, dos intensidades en el caso de elementales.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Onda vacua', '{"conjuro":"Onda vacua","via":"Vacío","nivel":14,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":30,"zeonIntermedio":60,"zeonAvanzado":90,"zeonArcano":120,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 120 contra escudos.","efectoIntermedio":"Daño 250 contra escudos.","efectoAvanzado":"Daño 400 contra escudos.","efectoArcano":"Daño 600 contra escudos.","efecto":"Este hechizo manda una leve onda de vacío capaz de desestructurar las fibras sobrenaturales de cualquier protección. Este conjuro en si no provoca daños a sus adversarios, pero dirigido contra un escudo sobrenatural, provoca demoledoras consecuencias. La Onda Vacua es invisible al ojo humano, salvo para aquellos capaces de ver magia.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Escudo de vacío', '{"conjuro":"Escudo de vacío","via":"Vacío","nivel":24,"diario":"No","tipo":"Defensa","accion":"Pasiva","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":50,"zeonIntermedio":90,"zeonAvanzado":120,"zeonArcano":150,"mantBase":5,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":30,"efectoBase":"200 Puntos de Resistencia / Dificultad 14 / RF 100.","efectoIntermedio":"300 Puntos de Resistencia / Dificultad 16 / RF 120.","efectoAvanzado":"400 Puntos de Resistencia / Dificultad 18 / RF 140.","efectoArcano":"500 Puntos de Resistencia / Dificultad 20 / RF 160.","efecto":"Crea un escudo que detiene los ataques de forma convencional y que anula cualquier poder sobrenatural del que se defienda con éxito si el atacante no logra superar un control de Voluntad o Poder. De igual forma, cualquier objeto físico que logre parar el escudo debe superar una RF o será destruido de inmediato.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Vórtice de realidad', '{"conjuro":"Vórtice de realidad","via":"Vacío","nivel":34,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":7,"intRIntermedio":10,"intRAvanzado":13,"intRArcano":15,"zeonBase":80,"zeonIntermedio":120,"zeonAvanzado":180,"zeonArcano":240,"mantBase":5,"mantIntermedio":10,"mantAvanzado":15,"mantArcano":20,"efectoBase":"RM 100 / 5 metros de radio.","efectoIntermedio":"RM 120 / 10 metros de radio.","efectoAvanzado":"RM 140 / 20 metros de radio.","efectoArcano":"RM 160 / 40 metros de radio.","efecto":"Crea una zona repleta de millones de microscópicas partículas de vacío. Todo individuo que esté en ella más de un asalto deberá hacer automáticamente una RM cada turno o sufrir un daño y una pérdida de puntos de Ki equivalente a la mitad del nivel de fracaso, así como una pérdida de puntos de Zeon equivalente al nivel de fracaso pleno. Este hechizo no permite elegir blancos, y afecta a todos por igual, inclusive el propio lanzador.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Negra hoja de perdición', '{"conjuro":"Negra hoja de perdición","via":"Vacío","nivel":44,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":100,"zeonIntermedio":150,"zeonAvanzado":200,"zeonArcano":250,"mantBase":5,"mantIntermedio":10,"mantAvanzado":10,"mantArcano":15,"efectoBase":"Daño 80","efectoIntermedio":"Daño 120.","efectoAvanzado":"Daño 160.","efectoArcano":"Daño 200.","efecto":"Crea un arma que atacar en Filo con la Proyección Mágica del mago o con su Habilidad de Ataque e ignora toda clase de Armadura. El mago puede mantener activa la hoja para realizar nuevos ataques en asaltos posteriores, pero debe de realizar un control de Voluntad contra 12. Cada vez que consiga supera el control incrementa un punto su dificultad en el siguiente turno. Si llegase a fallarlo, la espada se vuelve contra el brujo, atacándole con su habilidad plena.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Aura de vacío', '{"conjuro":"Aura de vacío","via":"Vacío","nivel":54,"diario":"Si","tipo":"Efecto","accion":"Activa","intRBase":6,"intRIntermedio":9,"intRAvanzado":12,"intRArcano":15,"zeonBase":120,"zeonIntermedio":180,"zeonAvanzado":240,"zeonArcano":350,"mantBase":15,"mantIntermedio":20,"mantAvanzado":25,"mantArcano":35,"efectoBase":"TA 4 / Valor Zeónico 60 / Potencial Psíquico 80.","efectoIntermedio":"TA 6 / Valor Zeónico 90/ Potencial Psíquico 120.","efectoAvanzado":"TA 8 / Valor Zeónico 120/ Potencial Psíquico 140.","efectoArcano":"TA 10 / Valor Zeónico 160/ Potencial Psíquico 180.","efecto":"Cubre al hechicero con un aura de vacío que le protege de los efectos de los ataques sobrenaturales, proporcionándole una TA de Energía a la vez que devora cualquier hechizo o poder psíquico de valor inferior al indicado. Lamentablemente, este conjuro no discrimina entre poderes amigos o enemigos, y los devora todos sin distinción. La capa de vacío es invisible, aunque todo lo que rodea al hechicero parece verse mas tenue y apagado.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Puntos negros', '{"conjuro":"Puntos negros","via":"Vacío","nivel":64,"diario":"No","tipo":"Automático","accion":"Activa","intRBase":8,"intRIntermedio":10,"intRAvanzado":12,"intRArcano":15,"zeonBase":150,"zeonIntermedio":250,"zeonAvanzado":350,"zeonArcano":500,"mantBase":15,"mantIntermedio":25,"mantAvanzado":35,"mantArcano":50,"efectoBase":"Dificultad 120 / 10 metros de radio / RM o RF 120.","efectoIntermedio":"Dificultad 140 / 20 metros de radio / RM o RF 140.","efectoAvanzado":"Dificultad 180 / 50 metros de radio / RM o RF 160","efectoArcano":"Dificultad 240 / 100 metros de radio / RM o RF 180.","efecto":"Cualquiera que entre en el área designada debe superar cada asalto un control de Atletismo, Acrobacias o Defensa, o de lo contrario chocará con unos de puntos negros. Si se diera el caso, el personaje debe de superar un control de RF o RM o sufrir un daño y una pérdida de puntos de Ki equivalente a la mitad del nivel de fracaso, así como una pérdida de Zeon equivalente al nivel de fracaso pleno. No es posible designar blancos en el interior del sortilegio.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Protección contra el vacío', '{"conjuro":"Protección contra el vacío","via":"Vacío","nivel":74,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":10,"intRIntermedio":12,"intRAvanzado":14,"intRArcano":16,"zeonBase":140,"zeonIntermedio":200,"zeonAvanzado":280,"zeonArcano":400,"mantBase":15,"mantIntermedio":20,"mantAvanzado":30,"mantArcano":40,"efectoBase":"Protege contra conjuros de esta sub-vía.","efectoIntermedio":"El personaje es  inmune a los efectos y ataques de seres basados en el vacío.","efectoAvanzado":"Inmune a cualquier efecto relaciona con el vacío, salvo la nada primordial.","efectoArcano":"El personaje es capaz de sobrevivir incluso en la nada primordial.","efecto":"Cubre al hechicero de una energía sobrenatural que repele los efectos del vacío. Cualquier conjuro o poder relacionado con la nada no tiene efecto sobre él ni puede causarle daño.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Implosión', '{"conjuro":"Implosión","via":"Vacío","nivel":84,"diario":"No","tipo":"Ataque","accion":"Activa","intRBase":14,"intRIntermedio":16,"intRAvanzado":18,"intRArcano":20,"zeonBase":250,"zeonIntermedio":500,"zeonAvanzado":750,"zeonArcano":1000,"mantBase":"No","mantIntermedio":"No","mantAvanzado":"No","mantArcano":"No","efectoBase":"Daño 200 / Crítico +20.","efectoIntermedio":"Daño 400 / Crítico +40.","efectoAvanzado":"Daño 500 / Crítico +60.","efectoArcano":"Daño 800 / Crítico +100.","efecto":"Este terrorífico conjuro crea un punto de vacío en el interior de algo que atrae toda la masa del mismo a su interior, provocando que su estructura implosione y desaparezca completamente. Al absorber la carne, huesos y órganos, en caso de causar daño provoca además un crítico automático con un bonificador determinado por el grado del conjuro.","_seccion":"VACIO"}'::jsonb),
  ('core-exxet', 'conjuros', 'Puerta a ninguna parte', '{"conjuro":"Puerta a ninguna parte","via":"Vacío","nivel":94,"diario":"No","tipo":"Efecto","accion":"Pasiva","intRBase":11,"intRIntermedio":13,"intRAvanzado":15,"intRArcano":18,"zeonBase":300,"zeonIntermedio":500,"zeonAvanzado":800,"zeonArcano":1200,"mantBase":30,"mantIntermedio":50,"mantAvanzado":80,"mantArcano":120,"efectoBase":"2 metros de diámetro.","efectoIntermedio":"5 metros de diámetro.","efectoAvanzado":"15 metros de diámetro","efectoArcano":"50 metros de diámetro.","efecto":"Abre un portal unidireccional al vacío. Cualquiera que cruce la puerta dejará de existir automáticamente, sin control de resistencia. Sólo los seres con Gnosis 35 o superior, objetos de presencia equivalente, o individuos protegidos modo contra el Vacío pueden sobrevivir allí, pero van perdiendo poco a poco puntos de su atributo de Poder, que se recupera a un ritmo de uno al día. Naturalmente, algo que permanezca en el interior es  inmune a cualquier clase de ataque.","_seccion":"VACIO"}'::jsonb),
