  ('core-exxet', 'elan', 'Luz de esperanza', '{"patron":"Mikael","nombre":"Luz de esperanza","elan":10,"requisito":1,"coste":5,"descripcion":"El PJ se convierte en un foco de esperanza para los demás."}'::jsonb),
  ('core-exxet', 'elan', 'Extirpar enfermedades', '{"patron":"Mikael","nombre":"Extirpar enfermedades","elan":20,"requisito":1,"coste":10,"descripcion":"Permite extripar cualquier enfermedad de nivel igual o inferior a 0."}'::jsonb),
  ('core-exxet', 'elan', 'Mantener en el mundo', '{"patron":"Mikael","nombre":"Mantener en el mundo","elan":30,"requisito":1,"coste":5,"descripcion":"Permite sacar a cualquiera de el estado \"Entre la vida y la muerte\"."}'::jsonb),
  ('core-exxet', 'elan', 'Resistencia celestial', '{"patron":"Mikael","nombre":"Resistencia celestial","elan":40,"requisito":1,"coste":20,"descripcion":"Otorga un bonificador especial a todas las resistencias de 0."}'::jsonb),
  ('core-exxet', 'elan', 'Exorcizar el mal', '{"patron":"Mikael","nombre":"Exorcizar el mal","elan":50,"requisito":1,"coste":15,"descripcion":"Permite desconvocar a un ser sobrenatural maligno si no supera un control de RM de 0."}'::jsonb),
