  ('core-exxet', 'elan', 'Milagro', '{"patron":"Mikael","nombre":"Milagro","elan":60,"requisito":1,"coste":10,"descripcion":"Permite recrear cualquier milagro menor producido por Cristo o sus Santos."}'::jsonb)
insert into public.catalogo (paquete_id, coleccion, clave, datos) values
  ('core-exxet', 'elan', 'Deshacer estados negativos', '{"patron":"Mikael","nombre":"Deshacer estados negativos","elan":70,"requisito":1,"coste":10,"descripcion":"Permite anular cualquier estado perjudicial."}'::jsonb),
  ('core-exxet', 'elan', 'Salvador', '{"patron":"Mikael","nombre":"Salvador","elan":70,"requisito":1,"coste":10,"descripcion":"Reduce un nivel de dificultad cualquier acción que tenga como fin salvar una vida, u otorga un +40 a controles enfrentados."}'::jsonb),
  ('core-exxet', 'elan', 'Ayuda celestial', '{"patron":"Mikael","nombre":"Ayuda celestial","elan":80,"requisito":1,"coste":15,"descripcion":"Puede invocar una vez al mes un ángel de Mikael, habitualmente una Doncella de Luz. Puede invocar antes de un mes si sacrifica un punto de Elan."}'::jsonb),
  ('core-exxet', 'elan', 'Levántate y anda', '{"patron":"Mikael","nombre":"Levántate y anda","elan":90,"requisito":1,"coste":20,"descripcion":"Permite devolver la vida a coste de 1 punto de Elan por cada mes que haya pasado desde haber recibido El Llamamiento."}'::jsonb),
  ('core-exxet', 'elan', 'Y al tercer día resucitó', '{"patron":"Mikael","nombre":"Y al tercer día resucitó","elan":100,"requisito":1,"coste":10,"descripcion":"El PJ puede regresar de entre los muertos, recreandose con todas sus facultades intactas, mientras tenga algo que hacer en el mundo."}'::jsonb),
  ('core-exxet', 'elan', 'Asalto espiritual', '{"patron":"Zemial","nombre":"Asalto espiritual","elan":10,"requisito":1,"coste":5,"descripcion":"Permite dañar energía como si tuviese la habilidad del Ki Extensión del aura al arma."}'::jsonb),
  ('core-exxet', 'elan', 'Ansia demencial', '{"patron":"Zemial","nombre":"Ansia demencial","elan":20,"requisito":1,"coste":5,"descripcion":"El PJ puede entrar en un estado de ira obteniendo un bono de +10 a cualquier acción ofensiva encaminada a matar a alguien."}'::jsonb),
  ('core-exxet', 'elan', 'Daño incrementado', '{"patron":"Zemial","nombre":"Daño incrementado","elan":30,"requisito":1,"coste":10,"descripcion":"Incrementa el daño base de sus ataques en 0."}'::jsonb),
  ('core-exxet', 'elan', 'Daño anímico', '{"patron":"Zemial","nombre":"Daño anímico","elan":40,"requisito":0,"coste":10,"descripcion":"Las heridas que cause sólo pueden ser sanadas mediante conjuros o habilidades místicas."}'::jsonb),
  ('core-exxet', 'elan', 'Destructor', '{"patron":"Zemial","nombre":"Destructor","elan":50,"requisito":1,"coste":15,"descripcion":"Desintegra cualquier objeto que toque cuya presencia sea inferior a 10."}'::jsonb),
  ('core-exxet', 'elan', 'Señor de la destrucción (Tacto)', '{"patron":"Zemial","nombre":"Señor de la destrucción (Tacto)","elan":50,"requisito":1,"coste":10,"descripcion":"A quien toque debe superar un control de RM o RF contra 80, o sufrir una pérdida de puntos de vida equivalente a su nivel de fracaso."}'::jsonb),
  ('core-exxet', 'elan', 'Presencia exterminadora', '{"patron":"Zemial","nombre":"Presencia exterminadora","elan":60,"requisito":1,"coste":10,"descripcion":"Cualquier cosa que se halle a pocos metros de él muere o se debilita lentamente; las plantas se marchitan a su paso, las personas enferman, etc."}'::jsonb),
  ('core-exxet', 'elan', 'Señor de la destrucción (Vista)', '{"patron":"Zemial","nombre":"Señor de la destrucción (Vista)","elan":60,"requisito":0,"coste":10,"descripcion":"A quien mire debe superar un control de RM o RF contra 60, o sufrir una pérdida de puntos de vida equivalente a su nivel de fracaso."}'::jsonb),
  ('core-exxet', 'elan', 'Señor de la destrucción (Aura)', '{"patron":"Zemial","nombre":"Señor de la destrucción (Aura)","elan":70,"requisito":0,"coste":10,"descripcion":"Quien se encuentre a menos de 10 metros debe superar un control de RM o RF contra 40, o sufrir una pérdida de puntos de vida equivalente a su nivel de fracaso."}'::jsonb),
  ('core-exxet', 'elan', 'Asalto destructor', '{"patron":"Zemial","nombre":"Asalto destructor","elan":80,"requisito":1,"coste":15,"descripcion":"El PJ obtiene la capacidad de dañar a cualquier clase de criatura, sin importar su poder, presencia sobrenatural o inmunidades especiales."}'::jsonb),
  ('core-exxet', 'elan', 'La sangre de la locura', '{"patron":"Zemial","nombre":"La sangre de la locura","elan":90,"requisito":1,"coste":20,"descripcion":"Su sangre actúa como un  veneno sobrenatural de nivel 80, con efecto instantáneo y una RV de 140. Quien falle la resistencia obtiene 50 de Elan de Zemial pero pierde la cordura."}'::jsonb),
  ('core-exxet', 'elan', 'Portador de catástrofes', '{"patron":"Zemial","nombre":"Portador de catástrofes","elan":100,"requisito":1,"coste":10,"descripcion":"El PJ trae consigo todo tipo de cataclismos naturales y catástrofes que acarrearán siempre terribles consecuencias."}'::jsonb),
  ('core-exxet', 'elan', 'Instinto de libertad', '{"patron":"Uriel","nombre":"Instinto de libertad","elan":10,"requisito":1,"coste":5,"descripcion":"El PJ tiene una enorme facilidad para encontrar la salida de cualquier lugar donde se encuentre."}'::jsonb),
  ('core-exxet', 'elan', 'Inadvertido', '{"patron":"Uriel","nombre":"Inadvertido","elan":20,"requisito":1,"coste":5,"descripcion":"El PJ puede pasar desapercibido entre la gente normal si lo desea, llamando muy poco la atención."}'::jsonb),
  ('core-exxet', 'elan', 'Espíritu indomable', '{"patron":"Uriel","nombre":"Espíritu indomable","elan":20,"requisito":1,"coste":10,"descripcion":"El PJ añade un bono especial a sus controles de Resistencias contra cualquier clase de dominación de +0."}'::jsonb),
  ('core-exxet', 'elan', 'Alma libre', '{"patron":"Uriel","nombre":"Alma libre","elan":30,"requisito":1,"coste":5,"descripcion":"Las personas con las que se relacione el PJ descubrirán un renovado deseo de ser libres y actuar conforme les dicten sus impulsos."}'::jsonb),
  ('core-exxet', 'elan', 'Visionario', '{"patron":"Uriel","nombre":"Visionario","elan":40,"requisito":1,"coste":10,"descripcion":"El PJ empieza a tener visiones sobre posibles acontecimientos del futuro. Cuanto mayor sea su nivel de Elan, las visiones se tornarán más claras y acertadas."}'::jsonb),
  ('core-exxet', 'elan', 'Medio de transporte', '{"patron":"Uriel","nombre":"Medio de transporte","elan":40,"requisito":1,"coste":5,"descripcion":"Siempre que lo necesite, el PJ puede recurrir a un transporte para viajar de un lugar a otro, que aparecerá como por arte de magia."}'::jsonb),
  ('core-exxet', 'elan', 'Romper las cadenas', '{"patron":"Uriel","nombre":"Romper las cadenas","elan":50,"requisito":1,"coste":10,"descripcion":"Permite obligar una vez por individuo a liberar los esclavos que tenga bajo su control si no supera una RM de 0."}'::jsonb),
  ('core-exxet', 'elan', 'Ojos del futuro', '{"patron":"Uriel","nombre":"Ojos del futuro","elan":60,"requisito":0,"coste":20,"descripcion":"Obtiene un bono de +30 en un control enfrentado que puede usarse 1 vez al día. Se puede utilizar para eliminar una sorpresa pero cuenta como dos usos."}'::jsonb),
  ('core-exxet', 'elan', 'Paso libre', '{"patron":"Uriel","nombre":"Paso libre","elan":60,"requisito":1,"coste":15,"descripcion":"El PJ puede atravesar cualquier barrera física como si no existiera, aunque no permite ignorar muros o barreras sobrenaturales."}'::jsonb),
  ('core-exxet', 'elan', 'Comunión con Uriel', '{"patron":"Uriel","nombre":"Comunión con Uriel","elan":70,"requisito":1,"coste":10,"descripcion":"El PJ obtiene un punto adicional en las características de Poder, Voluntad y Destreza."}'::jsonb),
  ('core-exxet', 'elan', 'Esencia sobrenatural (Uriel)', '{"patron":"Uriel","nombre":"Esencia sobrenatural (Uriel)","elan":80,"requisito":1,"coste":10,"descripcion":"El PJ obtiene Gnosis 30 y todas las ventajas que ello supone."}'::jsonb),
  ('core-exxet', 'elan', 'Una segunda oportunidad', '{"patron":"Uriel","nombre":"Una segunda oportunidad","elan":90,"requisito":1,"coste":20,"descripcion":"Siempre que fracase un control de Resistencia que lo someta a un estado negativo, el PJ es capaz de repetir la tirada una segunda vez."}'::jsonb),
  ('core-exxet', 'elan', 'El viajero', '{"patron":"Uriel","nombre":"El viajero","elan":100,"requisito":1,"coste":10,"descripcion":"Una vez por asalto, como acción activa el PJ puede transportarse de inmediato hasta el sitio que quiera, ignorando cualquier protección o barrera que haya en medio."}'::jsonb),
  ('core-exxet', 'elan', 'Don de la política', '{"patron":"Jedah","nombre":"Don de la política","elan":10,"requisito":1,"coste":5,"descripcion":"Otorga un bono especial a Persuasión y Liderazgo de +0."}'::jsonb),
  ('core-exxet', 'elan', 'Dominación incrementada', '{"patron":"Jedah","nombre":"Dominación incrementada","elan":20,"requisito":1,"coste":10,"descripcion":"Aplica un bono especial a su habilidad de convocatoria Dominación de +0. Este don no funciona contra seres basados en luz."}'::jsonb),
  ('core-exxet', 'elan', 'Sombra', '{"patron":"Jedah","nombre":"Sombra","elan":30,"requisito":1,"coste":5,"descripcion":"De un modo sobrenatural, el PJ obtiene la capacidad de alterar la apariencia de su sombra, dándole el aspecto o forma que desee."}'::jsonb),
  ('core-exxet', 'elan', 'Afinidad oscura', '{"patron":"Jedah","nombre":"Afinidad oscura","elan":40,"requisito":1,"coste":5,"descripcion":"El PJ obtiene afinidad hacia todos los seres sobrenaturales oscuros, quienes lo reconocerán como uno de los suyos."}'::jsonb),
  ('core-exxet', 'elan', 'El poder del conocimiento', '{"patron":"Jedah","nombre":"El poder del conocimiento","elan":50,"requisito":1,"coste":10,"descripcion":"Obtiene un bono especial en todas las habilidades secundarias intelecuales de +0."}'::jsonb),
  ('core-exxet', 'elan', 'El dominador (Habla)', '{"patron":"Jedah","nombre":"El dominador (Habla)","elan":50,"requisito":1,"coste":10,"descripcion":"Todo aquel que le escuche hablar durante más de cinco asaltos debe de realizar un control de RM o RP contra 60, o será controlado."}'::jsonb),
  ('core-exxet', 'elan', 'Cadena de mando', '{"patron":"Jedah","nombre":"Cadena de mando","elan":60,"requisito":1,"coste":10,"descripcion":"Permite conferir parte de su poder a un solo subordinado, quien actúa como si tuviese -20 puntos de Elan."}'::jsonb),
  ('core-exxet', 'elan', 'Señor de las sombras', '{"patron":"Jedah","nombre":"Señor de las sombras","elan":65,"requisito":0,"coste":15,"descripcion":"Permite invocar y mantener el control sobre hasta 0 criaturas oscuras. Si alguna de ellas es destruida debe esperar un día para que aparezca otra."}'::jsonb),
  ('core-exxet', 'elan', 'Poder oscuro', '{"patron":"Jedah","nombre":"Poder oscuro","elan":70,"requisito":1,"coste":15,"descripcion":"El PJ obtiene un punto adicional en las características de Poder, Voluntad e Inteligencia."}'::jsonb),
  ('core-exxet', 'elan', 'El dominador (Vista)', '{"patron":"Jedah","nombre":"El dominador (Vista)","elan":70,"requisito":0,"coste":10,"descripcion":"Todo aquel a quien mire a los ojos durante más de dos asaltos debe de realizar un control de RM o RP contra 40, o será controlado."}'::jsonb),
