  ('core-exxet', 'elan', 'Gracia', '{"patron":"Gabriel","nombre":"Gracia","elan":20,"requisito":1,"coste":5,"descripcion":"El PJ tiene la capacidad de resultar hermoso a los ojos de los demás, sin que por ello altere su apariencia."}'::jsonb),
